INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24604, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "提问", "is_correct": true, "explanation": "“提问”与“回答”一问一答，是反义关系。"}, {"text": "洗澡", "is_correct": false, "explanation": "与“回答”在任何义项上都没有反义或近义关系。"}, {"text": "打扫", "is_correct": false, "explanation": "与“回答”在任何义项上都没有反义或近义关系。"}, {"text": "旅行", "is_correct": false, "explanation": "与“回答”在任何义项上都没有反义或近义关系。"}], "correct_answer": "提问", "explanations": {"提问": "“提问”与“回答”一问一答，是反义关系。", "洗澡": "与“回答”在任何义项上都没有反义或近义关系。", "打扫": "与“回答”在任何义项上都没有反义或近义关系。", "旅行": "与“回答”在任何义项上都没有反义或近义关系。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '70be7a17-cd0a-4913-9080-5d7b3005c701') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24604, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "别人问你问题，你说话告诉他。", "primary_collocate": null, "pronunciation": "huí dá", "ipa": "xu̯eɪ˧˥ ta˧˥", "syllable_count": 2, "sentences": [{"text": "老师问我一个问题，我回答了。", "target_word": "回答", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "请你回答这个问题。", "target_word": "回答", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "他没有回答我的话。", "target_word": "回答", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "小明大声回答：“我知道！”", "target_word": "回答", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "面试时，经理问了很多问题，他都回答得很好。", "target_word": "回答", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你为什么不回答我的问题？", "target_word": "回答", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "她想了一会儿才回答。", "target_word": "回答", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "学生们都举手回答老师的问题。", "target_word": "回答", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "朋友问我去不去，我回答说去。", "target_word": "回答", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他回答得又快又对。", "target_word": "回答", "complexity_tier": "T1", "sentence_source": "generated"}], "morphological_forms": [{"form": "回答了", "label": "体标"}, {"form": "回答过", "label": "体标"}], "register": "中性", "sense_fingerprint": "对别人提出的问题用话语作出回应", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '22aa5821-43c2-4f1a-bd68-eccc7ce09b8e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24604, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "回答", "is_correct": true, "explanation": "“回答”是对提问的应对，与“老师问我一个问题”相合。"}, {"text": "散步", "is_correct": false, "explanation": "语义：“散步”与“老师问我一个问题”的应答语境不符。"}, {"text": "跳舞", "is_correct": false, "explanation": "语义：“跳舞”不是对问题的回应，与上下文不合。"}, {"text": "帮助", "is_correct": false, "explanation": "配价：“帮助”后面必须带受助的对象，“我帮助了”语义不完整。"}], "explanations": {"回答": "“回答”是对提问的应对，与“老师问我一个问题”相合。", "散步": "语义：“散步”与“老师问我一个问题”的应答语境不符。", "跳舞": "语义：“跳舞”不是对问题的回应，与上下文不合。", "帮助": "配价：“帮助”后面必须带受助的对象，“我帮助了”语义不完整。"}, "sentence_index": 0, "correct_answer": "回答"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他回答了不公平的待遇。", "explanation": "这里应该用〈抗议〉。“回答”针对别人提出的问题，不能用于对待遇表示反对。"}, {"text": "我们要回答大家的帮助。", "explanation": "这里应该用〈答谢〉。“回答”是对问题的应对，不能用来表示感谢。"}, {"text": "他回答了我一拳。", "explanation": "这里应该用〈回击〉。“回答”只用于言语上的应对，不指动作上的还击。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '70be7a17-cd0a-4913-9080-5d7b3005c701') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24604, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "回答", "is_correct": true, "explanation": "“回答”指对问题作出应对，与“她想了一会儿才”相合。"}, {"text": "下雨", "is_correct": false, "explanation": "语义：“下雨”的主语是天气，不能由“她”发出。"}, {"text": "发烧", "is_correct": false, "explanation": "语义：“发烧”是身体状况，与“想了一会儿”的思考过程不符。"}, {"text": "给", "is_correct": false, "explanation": "配价：“给”需要接双宾语，“才给”后面缺少成分，句子不完整。"}], "explanations": {"回答": "“回答”指对问题作出应对，与“她想了一会儿才”相合。", "下雨": "语义：“下雨”的主语是天气，不能由“她”发出。", "发烧": "语义：“发烧”是身体状况，与“想了一会儿”的思考过程不符。", "给": "配价：“给”需要接双宾语，“才给”后面缺少成分，句子不完整。"}, "sentence_index": 6, "correct_answer": "回答"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他回答了我的感情。", "explanation": "这里应该用〈回应〉。“回答”的对象是别人提出的问题，对感情作出反应要说“回应”。"}, {"text": "这盘菜回答得很好。", "explanation": "这里应该用〈做〉。“回答”的主语要能开口应对，菜是做出来的，应说“做得很好”。"}, {"text": "妈妈回答了我一件新衣服。", "explanation": "这里应该用〈送〉。“回答”是用话语应对问题，给人东西要说“送”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '70be7a17-cd0a-4913-9080-5d7b3005c701') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24604, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他回答了老师得问题。", "corrected_sentence": "他回答了老师的问题。", "error_description": "结构助词误用：定语“老师”与中心语“问题”之间应用“的”，不能用“得”（“得”用于补语）。正确：“回答了老师的问题”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '70be7a17-cd0a-4913-9080-5d7b3005c701') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24604, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他没回答了老师的问题。", "corrected_sentence": "他没回答老师的问题。", "error_description": "错误：否定句用“没”时，动词后面不能再加“了”。正确：“没回答老师的问题”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '70be7a17-cd0a-4913-9080-5d7b3005c701') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
