INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24606, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "一个东西代表另一个东西的意思。", "primary_collocate": null, "pronunciation": "xiàng zhēng yì yì", "ipa": "ɕjɑŋ˥˩ ʈʂɤŋ˥ i˥˩ i˥˩", "syllable_count": 4, "sentences": [{"text": "红色在中国有幸福的象征意义。", "target_word": "象征意义", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这朵花有什么象征意义？", "target_word": "象征意义", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "白鸽的象征意义是和平。", "target_word": "象征意义", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个故事有很深的象征意义。", "target_word": "象征意义", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "龙在中国文化里有特别的象征意义。", "target_word": "象征意义", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个礼物没有什么象征意义。", "target_word": "象征意义", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师问我们这幅画的象征意义。", "target_word": "象征意义", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "圆圆的月亮有团圆的象征意义。", "target_word": "象征意义", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "每个国家的国旗都有象征意义。", "target_word": "象征意义", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这棵树对我们有重要的象征意义。", "target_word": "象征意义", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "个", "label": "量词"}], "register": "通用", "sense_fingerprint": "事物所代表的另一层意思", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '17259789-fe49-4308-9f94-df080a361105') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24606, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "象征意义", "is_correct": true, "explanation": "“象征意义”指事物代表另一层意思，与“红色有幸福的……”相符，正确。"}, {"text": "面积", "is_correct": false, "explanation": "搭配：“面积”指平面的大小，不能与“幸福的”搭配。"}, {"text": "体积", "is_correct": false, "explanation": "搭配：“体积”指立体空间的大小，不能用来修饰“幸福的”。"}, {"text": "年龄", "is_correct": false, "explanation": "语义：“年龄”指存在的年数，与“幸福的”无法构成合理的说法。"}], "explanations": {"象征意义": "“象征意义”指事物代表另一层意思，与“红色有幸福的……”相符，正确。", "面积": "搭配：“面积”指平面的大小，不能与“幸福的”搭配。", "体积": "搭配：“体积”指立体空间的大小，不能用来修饰“幸福的”。", "年龄": "语义：“年龄”指存在的年数，与“幸福的”无法构成合理的说法。"}, "sentence_index": 0, "correct_answer": "象征意义"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这件衣服的象征意义很贵。", "explanation": "这里应该用〈价格〉。象征意义指事物代表的另一层意思，不能用来说东西的价钱。"}, {"text": "这种药有治病的象征意义。", "explanation": "这里应该用〈作用〉。象征意义指事物代表的另一层意思，不指药物的功效。"}, {"text": "这面旗子的象征意义很鲜艳。", "explanation": "这里应该用〈颜色〉。象征意义指事物代表的另一层意思，不指外观颜色，说“鲜艳”要用“颜色”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a73fe963-f640-4930-8c6d-59e02e87f32c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24606, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "象征意义", "is_correct": true, "explanation": "“象征意义”指画所代表的另一层意思，与“老师问我们这幅画的……”相符，正确。"}, {"text": "心跳", "is_correct": false, "explanation": "语义：“心跳”指心脏的搏动，画没有心跳，与“这幅画的”不合。"}, {"text": "脾气", "is_correct": false, "explanation": "语义：“脾气”指性情，画没有性情，不能说这幅画的脾气。"}, {"text": "体重", "is_correct": false, "explanation": "搭配：“体重”多用于人和动物，不能说画的体重。"}], "explanations": {"象征意义": "“象征意义”指画所代表的另一层意思，与“老师问我们这幅画的……”相符，正确。", "心跳": "语义：“心跳”指心脏的搏动，画没有心跳，与“这幅画的”不合。", "脾气": "语义：“脾气”指性情，画没有性情，不能说这幅画的脾气。", "体重": "搭配：“体重”多用于人和动物，不能说画的体重。"}, "sentence_index": 6, "correct_answer": "象征意义"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这台机器的象征意义是切菜。", "explanation": "这里应该用〈用途〉。象征意义指事物代表的另一层意思，不指器物的用处。"}, {"text": "这辆车的象征意义很快。", "explanation": "这里应该用〈速度〉。象征意义指事物代表的另一层意思，不指车辆的快慢。"}, {"text": "这杯水的象征意义很低。", "explanation": "这里应该用〈温度〉。象征意义指事物代表的另一层意思，不指水的冷热。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a73fe963-f640-4930-8c6d-59e02e87f32c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24606, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这朵花有一朵特别的象征意义。", "corrected_sentence": "这朵花有一种特别的象征意义。", "error_description": "量词错误：“象征意义”应用“种”或“个”，“朵”用于花等具体的东西，不能数抽象名词。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a73fe963-f640-4930-8c6d-59e02e87f32c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24606, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "校徽对学校有一颗重要的象征意义。", "corrected_sentence": "校徽对学校有重要的象征意义。", "error_description": "量词错误：“颗”用于小而圆的东西，不能数“象征意义”，应直接说“有重要的象征意义”或“有一种重要的象征意义”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a73fe963-f640-4930-8c6d-59e02e87f32c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
