INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24608, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "箭头是箭的头，像尖尖的标记。", "primary_collocate": null, "pronunciation": "jiàn tóu", "ipa": "tɕjɛn˥˩ tʰoʊ˧˥", "syllable_count": 2, "sentences": [{"text": "地上的箭头告诉我们往右走。", "target_word": "箭头", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请点一下屏幕上的箭头。", "target_word": "箭头", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他在纸上画了一个红色的箭头。", "target_word": "箭头", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个箭头指向出口。", "target_word": "箭头", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "路牌上的箭头是向左的。", "target_word": "箭头", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "猎人的箭头很尖，也很亮。", "target_word": "箭头", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "按键盘上的箭头，可以往上翻。", "target_word": "箭头", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "地图上的箭头代表我们的路线。", "target_word": "箭头", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师用箭头把两个词连起来。", "target_word": "箭头", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小心，这个箭头很尖，别碰它。", "target_word": "箭头", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "个", "label": "量词"}, {"form": "箭頭", "label": "繁体"}], "register": "中性", "sense_fingerprint": "箭的尖头，或表示方向的箭形标记", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a6c53470-eab2-4aaa-a8c7-536b79bbc5b7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24608, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "箭头", "is_correct": true, "explanation": "箭头 jiàntóu 指箭的尖头或表示方向的箭形标记。"}, {"text": "肩头", "is_correct": false, "explanation": "jiān（第一声）与 jiàn（第四声）声调不同，肩头指肩膀的上部。"}, {"text": "线头", "is_correct": false, "explanation": "xiàn（第四声）与 jiàn（第四声）只差声母，线头指线的断头或末端。"}, {"text": "片头", "is_correct": false, "explanation": "piàn（第四声）与 jiàn（第四声）只差声母，片头指影视或节目开头的部分。"}], "explanations": {"箭头": "箭头 jiàntóu 指箭的尖头或表示方向的箭形标记。", "肩头": "jiān（第一声）与 jiàn（第四声）声调不同，肩头指肩膀的上部。", "线头": "xiàn（第四声）与 jiàn（第四声）只差声母，线头指线的断头或末端。", "片头": "piàn（第四声）与 jiàn（第四声）只差声母，片头指影视或节目开头的部分。"}, "sentence_index": null, "correct_answer": "箭头"}, "level_3": {"options": [{"text": "箭头", "is_correct": true, "explanation": "箭头能指示方向，符合「地上的箭头告诉我们往右走」的语境。"}, {"text": "石头", "is_correct": false, "explanation": "语义：石头不能像箭头一样指示方向。"}, {"text": "车轮", "is_correct": false, "explanation": "语义：车轮是车的部件，不起指示方向的作用。"}, {"text": "钥匙", "is_correct": false, "explanation": "语义：钥匙是开锁的工具，不能告诉人往哪里走。"}], "explanations": {"箭头": "箭头能指示方向，符合「地上的箭头告诉我们往右走」的语境。", "石头": "语义：石头不能像箭头一样指示方向。", "车轮": "语义：车轮是车的部件，不起指示方向的作用。", "钥匙": "语义：钥匙是开锁的工具，不能告诉人往哪里走。"}, "sentence_index": 0, "correct_answer": "箭头"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这把刀的箭头很锋利。", "explanation": "这里应该用〈尖端〉。箭头指箭的尖头或方向标记，刀的尖端不叫箭头。"}, {"text": "他用箭头在纸上扎了个孔。", "explanation": "这里应该用〈锥子〉。箭头是箭的尖端，不是用来钻孔的工具，在纸上扎孔要用锥子。"}, {"text": "他用箭头削苹果。", "explanation": "这里应该用〈刀〉。箭头是箭的尖端，不能用来削东西，削苹果要用刀。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'aa29b907-5038-4975-9c83-47b668cb4b9b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24608, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "箭头", "is_correct": true, "explanation": "箭头 jiàntóu 指箭的尖头或表示方向的箭形标记。"}, {"text": "念头", "is_correct": false, "explanation": "niàn（第四声）与 jiàn（第四声）只差声母，念头指心里的想法。"}, {"text": "肩头", "is_correct": false, "explanation": "jiān（第一声）与 jiàn（第四声）声调不同，肩头指肩膀的上部。"}, {"text": "尖头", "is_correct": false, "explanation": "jiān（第一声）与 jiàn（第四声）只差声调，尖头指物体尖的一端。"}], "explanations": {"箭头": "箭头 jiàntóu 指箭的尖头或表示方向的箭形标记。", "念头": "niàn（第四声）与 jiàn（第四声）只差声母，念头指心里的想法。", "肩头": "jiān（第一声）与 jiàn（第四声）声调不同，肩头指肩膀的上部。", "尖头": "jiān（第一声）与 jiàn（第四声）只差声调，尖头指物体尖的一端。"}, "sentence_index": null, "correct_answer": "箭头"}, "level_3": {"options": [{"text": "箭头", "is_correct": true, "explanation": "箭头是屏幕上可以按键移动的标记，符合「按键盘上的箭头，可以往上翻」的语境。"}, {"text": "字母", "is_correct": false, "explanation": "语义：字母是字形符号，不能通过按键往上翻。"}, {"text": "图标", "is_correct": false, "explanation": "语义：图标是界面上的小图形，不是能被按键往上翻的对象。"}, {"text": "旋钮", "is_correct": false, "explanation": "搭配：旋钮要用「转」，不能说「按旋钮往上翻」。"}], "explanations": {"箭头": "箭头是屏幕上可以按键移动的标记，符合「按键盘上的箭头，可以往上翻」的语境。", "字母": "语义：字母是字形符号，不能通过按键往上翻。", "图标": "语义：图标是界面上的小图形，不是能被按键往上翻的对象。", "旋钮": "搭配：旋钮要用「转」，不能说「按旋钮往上翻」。"}, "sentence_index": 6, "correct_answer": "箭头"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "仙人掌的箭头很扎手，别碰它。", "explanation": "这里应该用〈尖刺〉。箭头指箭的尖头或方向标记，仙人掌身上的刺不叫箭头。"}, {"text": "这支笔的箭头很细，写字很方便。", "explanation": "这里应该用〈笔尖〉。箭头不用来指笔的书写端，笔尖才是这个意思。"}, {"text": "这支矛的箭头很锋利，士兵们都很小心。", "explanation": "这里应该用〈矛尖〉。箭头指箭的尖头，矛的尖端应说矛尖。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'aa29b907-5038-4975-9c83-47b668cb4b9b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24608, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "路口的箭头指向在右边。", "corrected_sentence": "路口的箭头指向右边。", "error_description": "错误形式：指向在右边。正确形式：指向右边。「指向」后直接接方向词，不能加「在」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'aa29b907-5038-4975-9c83-47b668cb4b9b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24608, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "屏幕上的箭头们很醒目。", "corrected_sentence": "屏幕上的箭头很醒目。", "error_description": "错误形式：箭头们。正确形式：箭头。「们」一般只用于指人或某些有生命的名词，「箭头」是无生命的物体，不能加「们」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'aa29b907-5038-4975-9c83-47b668cb4b9b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
