INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24610, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "把东西分开，放到不同的地方。", "primary_collocate": null, "pronunciation": "fēn lèi", "ipa": "fən˥˥ leɪ̯˥˩", "syllable_count": 2, "sentences": [{"text": "我们按颜色分类。", "target_word": "分类", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "老师教我们怎么分类。", "target_word": "分类", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "他在整理衣服，先分类再放好。", "target_word": "分类", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这些书太乱了，我想分类放好。", "target_word": "分类", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "请按大小给这些水果分类。", "target_word": "分类", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "小朋友们正在把玩具分类。", "target_word": "分类", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "图书馆的员工每天给新书分类，再放到书架上。", "target_word": "分类", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "妈妈让我把衣服按季节分类。", "target_word": "分类", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "学生们用不同的颜色给卡片分类。", "target_word": "分类", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "她先给旧东西分类，再送给朋友。", "target_word": "分类", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "分类整理", "label": "复合词"}, {"form": "分类放好", "label": "结果补语形式"}, {"form": "分类法", "label": "复合词"}], "register": "中性", "sense_fingerprint": "按种类把东西分开放", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ed69058d-24aa-4c07-bc40-36884250d128') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24610, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "分类", "is_correct": true, "explanation": "正确答案：分类（fēn lèi）指按种类把东西分开放"}, {"text": "分离", "is_correct": false, "explanation": "lí（第二声）与 lèi（第四声）韵母和声调都不同，意思是分开、离开"}, {"text": "分立", "is_correct": false, "explanation": "lì（第四声）与 lèi 韵母不同（i 与 ei），意思是各自独立地存在"}, {"text": "分贝", "is_correct": false, "explanation": "分贝 fēn bèi：bèi（第四声）与 lèi（第四声）声母不同（b 与 l），意思是声音强度的单位。"}], "explanations": {"分类": "正确答案：分类（fēn lèi）指按种类把东西分开放", "分离": "lí（第二声）与 lèi（第四声）韵母和声调都不同，意思是分开、离开", "分立": "lì（第四声）与 lèi 韵母不同（i 与 ei），意思是各自独立地存在", "分贝": "分贝 fēn bèi：bèi（第四声）与 lèi（第四声）声母不同（b 与 l），意思是声音强度的单位。"}, "sentence_index": null, "correct_answer": "分类"}, "level_3": {"options": [{"text": "切割", "is_correct": false, "explanation": "语义：切割指把物体切断，“按颜色切割”不成立"}, {"text": "分类", "is_correct": true, "explanation": "正确答案：分类指按种类分开，“我们按颜色分类”符合句意"}, {"text": "讨论", "is_correct": false, "explanation": "搭配：讨论的对象是问题或意见，“按颜色讨论”搭配不当"}, {"text": "浇灌", "is_correct": false, "explanation": "语义：浇灌指给植物浇水，与按颜色整理无关"}], "explanations": {"切割": "语义：切割指把物体切断，“按颜色切割”不成立", "分类": "正确答案：分类指按种类分开，“我们按颜色分类”符合句意", "讨论": "搭配：讨论的对象是问题或意见，“按颜色讨论”搭配不当", "浇灌": "语义：浇灌指给植物浇水，与按颜色整理无关"}, "sentence_index": 0, "correct_answer": "分类"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "老板把任务分类给每个员工。", "explanation": "这里应该用〈分配〉。分配指把任务、名额派给人，分类是按种类分开，不能用于派发任务"}, {"text": "打架的两个人被老师分类了。", "explanation": "这里应该用〈分开〉。分开指把人或物隔开，分类强调按种类归组，不能用来说把打架的人分开"}, {"text": "这块蛋糕被分类成了三份。", "explanation": "这里应该用〈分割〉。分割指把整体切成几部分，分类是按种类归组，不能用于切蛋糕"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b40bdfe4-ba79-4ecd-b88f-4c9a825bd20a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24610, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "播放", "is_correct": false, "explanation": "语义：播放指影音内容的放映，书不能播放"}, {"text": "喂养", "is_correct": false, "explanation": "语义：喂养指给动物或人提供食物，与整理新书无关"}, {"text": "修剪", "is_correct": false, "explanation": "搭配：修剪用于枝叶、头发等，不能说修剪新书"}, {"text": "分类", "is_correct": true, "explanation": "正确答案：分类指按种类分开，“给新书分类，再放到书架上”符合句意"}], "explanations": {"播放": "语义：播放指影音内容的放映，书不能播放", "喂养": "语义：喂养指给动物或人提供食物，与整理新书无关", "修剪": "搭配：修剪用于枝叶、头发等，不能说修剪新书", "分类": "正确答案：分类指按种类分开，“给新书分类，再放到书架上”符合句意"}, "sentence_index": 6, "correct_answer": "分类"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这个消息我们要和大家分类。", "explanation": "这里应该用〈分享〉。分享指和别人一同享有或告知，分类是按种类归组，不能和大家分类消息"}, {"text": "我们班按小组分类合作。", "explanation": "这里应该用〈分工〉。分工指按职责分派任务，分类不能用于合作的分派"}, {"text": "这台电脑可以分类付款。", "explanation": "这里应该用〈分期〉。分期指分几次付款，分类是按种类归组，不能用于付款方式"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b40bdfe4-ba79-4ecd-b88f-4c9a825bd20a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24610, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这些零件要从大小分类。", "corrected_sentence": "这些零件要按大小分类。", "error_description": "错误：“从大小分类”；正确：“按大小分类”。表示分类的标准要用介词“按”，不能用“从”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b40bdfe4-ba79-4ecd-b88f-4c9a825bd20a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24610, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这些卡片我还没有分类了。", "corrected_sentence": "这些卡片我还没有分类。", "error_description": "错误：“还没有分类了”；正确：“还没有分类”。否定词“没有”之后不能再用“了”", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b40bdfe4-ba79-4ecd-b88f-4c9a825bd20a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
