INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24612, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "瓶子是一种容器，可以装水或饮料。", "primary_collocate": null, "pronunciation": "píng zi", "ipa": "pʰiŋ˧˥ tsɨ", "syllable_count": 2, "sentences": [{"text": "桌子上有一个空瓶子。", "target_word": "瓶子", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他把瓶子里的水喝完了。", "target_word": "瓶子", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个瓶子是玻璃做的。", "target_word": "瓶子", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "妈妈买了两个新瓶子。", "target_word": "瓶子", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小心，别打破那个瓶子。", "target_word": "瓶子", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我用旧瓶子种了一朵花。", "target_word": "瓶子", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "瓶子太滑，他没拿住。", "target_word": "瓶子", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请把瓶子放在冰箱里。", "target_word": "瓶子", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "瓶子里装着半瓶牛奶。", "target_word": "瓶子", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他手里拿着一个红瓶子。", "target_word": "瓶子", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "个", "label": "量词"}], "register": "中性", "sense_fingerprint": "装水或饮料的容器", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '842fb074-b13a-42dd-9ece-3ecc7134eb5d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24612, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "瓶子", "is_correct": true, "explanation": "正确：“桌子上有一个空……”中，“瓶子”是可以放在桌上的空容器。"}, {"text": "人", "is_correct": false, "explanation": "语义：“桌子上”放的东西不能是人，且“空”的人说不通，句意不通。"}, {"text": "房间", "is_correct": false, "explanation": "搭配：“桌子上”不能放下房间，“房间”与“桌子上”不搭配。"}, {"text": "雨", "is_correct": false, "explanation": "语义：雨不是可以盛放的东西，“空”的雨说不通。"}], "explanations": {"瓶子": "正确：“桌子上有一个空……”中，“瓶子”是可以放在桌上的空容器。", "人": "语义：“桌子上”放的东西不能是人，且“空”的人说不通，句意不通。", "房间": "搭配：“桌子上”不能放下房间，“房间”与“桌子上”不搭配。", "雨": "语义：雨不是可以盛放的东西，“空”的雨说不通。"}, "sentence_index": 0, "correct_answer": "瓶子"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "妈妈把两个新瓶子穿在脚上。", "explanation": "这里应该用〈拖鞋〉。瓶子不能穿在脚上，穿在脚上的要用〈拖鞋〉这类鞋子。"}, {"text": "妈妈用新瓶子煮了两碗粥。", "explanation": "这里应该用〈锅〉。粥要用锅煮，瓶子口小，不能加热煮粥。"}, {"text": "妈妈用新瓶子切菜。", "explanation": "这里应该用〈菜刀〉。瓶子没有刃，不能切菜，切菜要用菜刀。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'db5df177-4ea5-4b7f-9975-32ce13f139fa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24612, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "瓶子", "is_correct": true, "explanation": "正确：“瓶子太滑，他没拿住”中，“瓶子”是可以拿在手里的东西。"}, {"text": "房子", "is_correct": false, "explanation": "搭配：“拿住”不能搭配“房子”，房子拿不住，不能说“太滑”。"}, {"text": "天空", "is_correct": false, "explanation": "语义：天空不能太滑，也拿不住，句意不通。"}, {"text": "心情", "is_correct": false, "explanation": "语义：心情不能被“拿住”，与“太滑”搭配不通。"}], "explanations": {"瓶子": "正确：“瓶子太滑，他没拿住”中，“瓶子”是可以拿在手里的东西。", "房子": "搭配：“拿住”不能搭配“房子”，房子拿不住，不能说“太滑”。", "天空": "语义：天空不能太滑，也拿不住，句意不通。", "心情": "语义：心情不能被“拿住”，与“太滑”搭配不通。"}, "sentence_index": 6, "correct_answer": "瓶子"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他把衣服装进瓶子里了。", "explanation": "这里应该用〈箱子〉。衣服体积大，瓶子口小，装不进去。"}, {"text": "她用瓶子洗衣服。", "explanation": "这里应该用〈盆〉。洗衣服要用能盛水的盆，瓶子口小，不便洗衣服。"}, {"text": "我们在瓶子里游泳。", "explanation": "这里应该用〈游泳池〉。人不能在瓶子里游泳，游泳要在能容纳人的水池里。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'db5df177-4ea5-4b7f-9975-32ce13f139fa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24612, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他不小心打破了一条瓶子。", "corrected_sentence": "他不小心打破了一个瓶子。", "error_description": "量词错误：“条”用于细长的东西，如鱼、路、裤子，不能用于瓶子。应说“一个瓶子”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'db5df177-4ea5-4b7f-9975-32ce13f139fa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24612, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他把一张脏瓶子洗干净了。", "corrected_sentence": "他把脏瓶子洗干净了。", "error_description": "量词错误：“瓶子”前用了量词“张”，“张”用于纸张、桌子等扁平物品，不能用于瓶子。应去掉“一张”，说“脏瓶子”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'db5df177-4ea5-4b7f-9975-32ce13f139fa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
