INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24614, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "纸做的小盒子。", "primary_collocate": null, "pronunciation": "zhǐ hé", "ipa": "ʈʂɻ̩˨˩˦ xɤ˧˥", "syllable_count": 2, "sentences": [{"text": "我有一个红色的小纸盒。", "target_word": "纸盒", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他从纸盒里拿出一支笔。", "target_word": "纸盒", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子们把玩具放进纸盒里。", "target_word": "纸盒", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个纸盒是我自己做的。", "target_word": "纸盒", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "桌上的纸盒里有几块饼干。", "target_word": "纸盒", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她用漂亮的纸盒装礼物。", "target_word": "纸盒", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "纸盒太小，放不下这本书。", "target_word": "纸盒", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师给每人发了一个纸盒。", "target_word": "纸盒", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我找到了一个旧纸盒。", "target_word": "纸盒", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他把纸盒打开了，里面是糖。", "target_word": "纸盒", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "个", "label": "量词"}], "register": "中性", "sense_fingerprint": "纸做的小盒子", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '842fb074-b13a-42dd-9ece-3ecc7134eb5d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24614, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "纸盒", "is_correct": true, "explanation": "正确。“纸盒”是纸做的小盒子，与“红色的小”的描述相符。"}, {"text": "大厦", "is_correct": false, "explanation": "语义：“小”与“大厦”的大体积相矛盾，“小大厦”不成立。"}, {"text": "太阳", "is_correct": false, "explanation": "语义：太阳在天上，不能被人拥有，也不是“红色的小”物品，句意不通。"}, {"text": "时间", "is_correct": false, "explanation": "语义：“时间”是抽象概念，不能是“红色的小”的实物，句意不通。"}], "explanations": {"纸盒": "正确。“纸盒”是纸做的小盒子，与“红色的小”的描述相符。", "大厦": "语义：“小”与“大厦”的大体积相矛盾，“小大厦”不成立。", "太阳": "语义：太阳在天上，不能被人拥有，也不是“红色的小”物品，句意不通。", "时间": "语义：“时间”是抽象概念，不能是“红色的小”的实物，句意不通。"}, "sentence_index": 0, "correct_answer": "纸盒"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "她用纸盒烧开了一壶水。", "explanation": "这里应该用〈水壶〉。纸盒不能加热，烧水要用能耐热的水壶。"}, {"text": "下雨了，他把纸盒当伞打着出门。", "explanation": "这里应该用〈伞〉。纸盒遇水会湿软，不能挡雨，下雨要打伞。"}, {"text": "她用纸盒装了一大碗热汤。", "explanation": "这里应该用〈碗〉。纸盒会被汤泡软漏水，盛汤要用碗。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'db5df177-4ea5-4b7f-9975-32ce13f139fa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24614, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "纸盒", "is_correct": true, "explanation": "正确。“纸盒”是能装东西的容器，“太小，放不下这本书”符合它的特点。"}, {"text": "天空", "is_correct": false, "explanation": "语义：天空不能被装进或放下东西，“放不下这本书”与它无关，句子荒谬。"}, {"text": "大海", "is_correct": false, "explanation": "语义：大海无法被放在某处，“太小”也与大海的特点相矛盾。"}, {"text": "月亮", "is_correct": false, "explanation": "语义：月亮挂在天上，不能用来放书，“太小，放不下这本书”说不通。"}], "explanations": {"纸盒": "正确。“纸盒”是能装东西的容器，“太小，放不下这本书”符合它的特点。", "天空": "语义：天空不能被装进或放下东西，“放不下这本书”与它无关，句子荒谬。", "大海": "语义：大海无法被放在某处，“太小”也与大海的特点相矛盾。", "月亮": "语义：月亮挂在天上，不能用来放书，“太小，放不下这本书”说不通。"}, "sentence_index": 6, "correct_answer": "纸盒"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他把纸盒吃掉了。", "explanation": "语义：这里把“纸盒”误当成了〈食物〉。纸盒是纸做的器物，不能用“吃”。"}, {"text": "那个纸盒在草地上散步。", "explanation": "语义：这里把“纸盒”误当成了〈有生命的行动者〉。纸盒是器物，不会自己“散步”。"}, {"text": "我的纸盒昨天参加了期末考试。", "explanation": "语义：这里把“纸盒”误当成了〈学生〉。纸盒是器物，不能“参加考试”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'db5df177-4ea5-4b7f-9975-32ce13f139fa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24614, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我把剪刀放进了那张纸盒里。", "corrected_sentence": "我把剪刀放进了那个纸盒里。", "error_description": "量词错误：纸盒是立体容器，应用量词“个”。“张”用于纸张、桌子等扁平物品，“那张纸盒”应改为“那个纸盒”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'db5df177-4ea5-4b7f-9975-32ce13f139fa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24614, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "桌上有两纸盒。", "corrected_sentence": "桌上有两个纸盒。", "error_description": "量词缺失：数词“两”后面要加量词，“纸盒”应说“两个纸盒”，不能省去“个”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'db5df177-4ea5-4b7f-9975-32ce13f139fa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
