INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24616, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "让别人知道这是什么的东西。", "primary_collocate": null, "pronunciation": "biāo zhì", "ipa": "pjɑʊ˥˥ ʈʂʐ̩˥˩", "syllable_count": 2, "sentences": [{"text": "路边有一个红色的标志。", "target_word": "标志", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这个标志是什么意思？", "target_word": "标志", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "看到这个标志，就知道是医院。", "target_word": "标志", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "门口的标志写着“禁止吸烟”。", "target_word": "标志", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们公司的标志是一只小鸟。", "target_word": "标志", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "请看清楚地上的安全标志。", "target_word": "标志", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他把新标志挂在门口。", "target_word": "标志", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个蓝色标志表示这里可以停车。", "target_word": "标志", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我不认识这个标志，你认识吗？", "target_word": "标志", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "车头上的标志很大，一看就知道是什么车。", "target_word": "标志", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "一个标志", "label": "量词"}, {"form": "标志性", "label": "复合"}], "register": "中性", "sense_fingerprint": "用来表示事物特征、让人辨认的记号或图案", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c158727a-e2ac-46d3-b271-c699b7ec501e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24616, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "标志", "is_correct": true, "explanation": "正确：“标志”指让人辨认的记号，放在“路边有一个红色的”之后语义通顺。"}, {"text": "颜色", "is_correct": false, "explanation": "搭配：“红色的颜色”同义重复，且“颜色”不是能放在路边的具体物件。"}, {"text": "情绪", "is_correct": false, "explanation": "语义：“情绪”是抽象的心理状态，不能放在路边，也不能说是红色的。"}, {"text": "语言", "is_correct": false, "explanation": "语义：“语言”是交流的工具，不是路边可见的具体物体，与“红色的”不搭。"}], "explanations": {"标志": "正确：“标志”指让人辨认的记号，放在“路边有一个红色的”之后语义通顺。", "颜色": "搭配：“红色的颜色”同义重复，且“颜色”不是能放在路边的具体物件。", "情绪": "语义：“情绪”是抽象的心理状态，不能放在路边，也不能说是红色的。", "语言": "语义：“语言”是交流的工具，不是路边可见的具体物体，与“红色的”不搭。"}, "sentence_index": 0, "correct_answer": "标志"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他的新标志是成为一名医生。", "explanation": "这里应该用〈目标〉。“目标”指想要达到的结果，“标志”指让人辨认的记号，不能指想要做成的事。"}, {"text": "博物馆的展厅里摆着很多动物标志的骨架。", "explanation": "这里应该用〈标本〉。“标本”指经过处理保存的动植物实物，“标志”指让人辨认的记号，不能指动物的骨架。"}, {"text": "这件衣服的标志是两百元。", "explanation": "这里应该用〈标价〉。“标价”指商品上标明的价钱，“标志”指让人辨认的记号，不能指价格。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bd75a825-1ba1-4d13-af2f-d6021369ff4b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24616, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "标志", "is_correct": true, "explanation": "正确：“标志”可以用手挂在门口，符合“他把新……挂在门口”的语境。"}, {"text": "心情", "is_correct": false, "explanation": "语义：“心情”是内在感受，不能用手拿着挂在门口。"}, {"text": "时间", "is_correct": false, "explanation": "配价：“挂”的对象必须是可以悬挂的具体物件，“时间”是抽象概念。"}, {"text": "建议", "is_correct": false, "explanation": "语义：“建议”是言语或想法，不能被挂在门口，句意不通。"}], "explanations": {"标志": "正确：“标志”可以用手挂在门口，符合“他把新……挂在门口”的语境。", "心情": "语义：“心情”是内在感受，不能用手拿着挂在门口。", "时间": "配价：“挂”的对象必须是可以悬挂的具体物件，“时间”是抽象概念。", "建议": "语义：“建议”是言语或想法，不能被挂在门口，句意不通。"}, "sentence_index": 6, "correct_answer": "标志"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他的发音很标志。", "explanation": "这里应该用〈标准〉。形容发音规范要用“标准”，“标志”没有这种用法。"}, {"text": "这篇文章的标志是三千字。", "explanation": "这里应该用〈字数〉。“标志”指让人辨认的记号，不能指文章的字数。"}, {"text": "他的标志很高，篮球打得很好。", "explanation": "这里应该用〈个子〉。“标志”指让人辨认的记号，不能用来形容身高。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bd75a825-1ba1-4d13-af2f-d6021369ff4b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24616, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "地图上那位小标志代表医院。", "corrected_sentence": "地图上那个小标志代表医院。", "error_description": "错误在量词：“位”只用于人，标志是物件，应用“个”，“那位小标志”不通，应改为“那个小标志”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bd75a825-1ba1-4d13-af2f-d6021369ff4b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24616, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "路口立着一本新标志。", "corrected_sentence": "路口立着一个新标志。", "error_description": "错误在量词：“本”用于书本，标志不是书，应用“个”，应改为“一个新标志”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bd75a825-1ba1-4d13-af2f-d6021369ff4b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24618, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "恨", "is_correct": true, "explanation": "恨与爱意思相反，表示强烈的厌恶，是「爱」在喜欢这一义项上的反义词。"}, {"text": "吃", "is_correct": false, "explanation": "吃是动作动词，与「爱」不构成反义关系。"}, {"text": "读", "is_correct": false, "explanation": "读是动作动词，与「爱」不构成反义关系。"}, {"text": "跑", "is_correct": false, "explanation": "跑是动作动词，与「爱」不构成反义关系。"}], "correct_answer": "恨", "explanations": {"恨": "恨与爱意思相反，表示强烈的厌恶，是「爱」在喜欢这一义项上的反义词。", "吃": "吃是动作动词，与「爱」不构成反义关系。", "读": "读是动作动词，与「爱」不构成反义关系。", "跑": "跑是动作动词，与「爱」不构成反义关系。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'aa29b907-5038-4975-9c83-47b668cb4b9b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
