INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24618, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "爱是心里很喜欢一个人或一样东西。", "primary_collocate": null, "pronunciation": "ài", "ipa": "aɪ˥˩", "syllable_count": 1, "sentences": [{"text": "我爱我的家人。", "target_word": "爱", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "妈妈很爱我。", "target_word": "爱", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "他爱吃面条，天天都吃。", "target_word": "爱", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "小孩子都爱玩水。", "target_word": "爱", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "我爱这个城市的春天。", "target_word": "爱", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "爷爷爱喝茶，每天早上都喝一杯。", "target_word": "爱", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "你爱看电影吗？", "target_word": "爱", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "我们都爱我们的老师。", "target_word": "爱", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "弟弟爱小狗，常常和它玩。", "target_word": "爱", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "她很爱自己的故乡，常常回去看看。", "target_word": "爱", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "爱上", "label": "复合"}], "register": "中性", "sense_fingerprint": "心里很喜欢某人或某物", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a6c53470-eab2-4aaa-a8c7-536b79bbc5b7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24618, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "爱", "is_correct": true, "explanation": "爱 ài 表示心里很喜欢一个人或一样东西。"}, {"text": "矮", "is_correct": false, "explanation": "ǎi（第三声）与 ài（第四声）声调不同，矮表示身高不足或高度低。"}, {"text": "癌", "is_correct": false, "explanation": "ái（第二声）与 ài（第四声）声调不同，癌指一种恶性肿瘤。"}, {"text": "埃", "is_correct": false, "explanation": "āi（第一声）与 ài（第四声）声调不同，埃指尘土。"}], "explanations": {"爱": "爱 ài 表示心里很喜欢一个人或一样东西。", "矮": "ǎi（第三声）与 ài（第四声）声调不同，矮表示身高不足或高度低。", "癌": "ái（第二声）与 ài（第四声）声调不同，癌指一种恶性肿瘤。", "埃": "āi（第一声）与 ài（第四声）声调不同，埃指尘土。"}, "sentence_index": null, "correct_answer": "爱"}, "level_3": {"options": [{"text": "爱", "is_correct": true, "explanation": "爱表示喜欢、疼爱，符合「我爱我的家人」的语境。"}, {"text": "扔", "is_correct": false, "explanation": "语义：扔表示抛掉，「扔我的家人」与语境完全不符。"}, {"text": "借", "is_correct": false, "explanation": "配价：借要说「向某人借某物」，「借我的家人」不成立。"}, {"text": "咬", "is_correct": false, "explanation": "语义：咬表示用牙齿夹住，与「我的家人」的情感语境不合。"}], "explanations": {"爱": "爱表示喜欢、疼爱，符合「我爱我的家人」的语境。", "扔": "语义：扔表示抛掉，「扔我的家人」与语境完全不符。", "借": "配价：借要说「向某人借某物」，「借我的家人」不成立。", "咬": "语义：咬表示用牙齿夹住，与「我的家人」的情感语境不合。"}, "sentence_index": 0, "correct_answer": "爱"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这个孩子很爱黑，一个人不敢出门。", "explanation": "这里应该用〈怕〉。「爱」表示喜欢，而句中「不敢出门」表示害怕。"}, {"text": "他爱这个房间太小，所以搬走了。", "explanation": "这里应该用〈嫌〉。「爱」不能用来评价房间的大小，「嫌……太小」才符合语境。"}, {"text": "大家都很爱这次失败。", "explanation": "这里应该用〈惋惜〉。「爱」表示喜欢或爱护，不能用来表达对失败的遗憾，这里应说惋惜。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'aa29b907-5038-4975-9c83-47b668cb4b9b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24618, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "爱", "is_correct": true, "explanation": "爱 ài 表示心里很喜欢一个人或一样东西。"}, {"text": "挨", "is_correct": false, "explanation": "āi（第一声）与 ài（第四声）声调不同，挨表示遭受或靠近。"}, {"text": "傲", "is_correct": false, "explanation": "ào 与 ài 韵母不同，傲表示自以为了不起。"}, {"text": "哀", "is_correct": false, "explanation": "āi（第一声）与 ài（第四声）声调不同，哀表示悲伤。"}], "explanations": {"爱": "爱 ài 表示心里很喜欢一个人或一样东西。", "挨": "āi（第一声）与 ài（第四声）声调不同，挨表示遭受或靠近。", "傲": "ào 与 ài 韵母不同，傲表示自以为了不起。", "哀": "āi（第一声）与 ài（第四声）声调不同，哀表示悲伤。"}, "sentence_index": null, "correct_answer": "爱"}, "level_3": {"options": [{"text": "爱", "is_correct": true, "explanation": "「爱看电影」表示喜欢看电影，符合「你爱看电影吗」的语境。"}, {"text": "删", "is_correct": false, "explanation": "语义：删表示去掉，「删看电影」与语境不符。"}, {"text": "写", "is_correct": false, "explanation": "语义：写表示书写文字，「写看电影」不成立。"}, {"text": "买", "is_correct": false, "explanation": "配价：买后直接接宾语，「看电影」不能作买的宾语。"}], "explanations": {"爱": "「爱看电影」表示喜欢看电影，符合「你爱看电影吗」的语境。", "删": "语义：删表示去掉，「删看电影」与语境不符。", "写": "语义：写表示书写文字，「写看电影」不成立。", "买": "配价：买后直接接宾语，「看电影」不能作买的宾语。"}, "sentence_index": 6, "correct_answer": "爱"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他对这种噪音很爱。", "explanation": "这里应该用〈厌烦〉。「爱」表示喜欢，句中是噪音让人烦躁，不能用「爱」，应说厌烦。"}, {"text": "他爱这种不公平。", "explanation": "这里应该用〈痛恨〉。「爱」表示喜欢或爱护，不能用来表达对不公平的憎恨，应说痛恨。"}, {"text": "他爱这次考试的分数，于是把它扔进了垃圾桶。", "explanation": "这里应该用〈厌恶〉。「爱」表示喜欢，与“扔进垃圾桶”的态度矛盾；表示厌弃要用“厌恶”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'aa29b907-5038-4975-9c83-47b668cb4b9b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24618, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我爱不吃中国菜。", "corrected_sentence": "我不爱吃中国菜。", "error_description": "错误形式：爱不吃。正确形式：不爱吃。否定词「不」要放在「爱」前面，表示不喜欢吃中国菜。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'aa29b907-5038-4975-9c83-47b668cb4b9b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24618, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我们都爱得这个城市。", "corrected_sentence": "我们都爱这个城市。", "error_description": "错误形式：爱得这个城市。正确形式：爱这个城市。「得」用来引出补语，「爱」后面直接带宾语时不能加「得」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'aa29b907-5038-4975-9c83-47b668cb4b9b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
