INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24620, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "把别人不要的东西拿回来再用。", "primary_collocate": null, "pronunciation": "huí shōu", "ipa": "xweɪ˧˥ ʂoʊ˥", "syllable_count": 2, "sentences": [{"text": "旧报纸可以回收再用。", "target_word": "回收", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我们学校回收旧衣服。", "target_word": "回收", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "工人每天来回收这些空瓶子。", "target_word": "回收", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这家公司专门回收旧手机。", "target_word": "回收", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "用完的塑料瓶请放在这里回收。", "target_word": "回收", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他把旧电脑卖给了回收的人。", "target_word": "回收", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "收废品的人回收了妈妈的旧书，给了她一点钱。", "target_word": "回收", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这些旧东西没有人回收。", "target_word": "回收", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "城市里的旧电池会有人回收吗？", "target_word": "回收", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "回收旧东西对地球很好。", "target_word": "回收", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "回收了", "label": "体标"}, {"form": "回收过", "label": "体标"}, {"form": "回收站", "label": "复合"}], "register": "中性", "sense_fingerprint": "回收：把别人不要的旧东西收回来再利用", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bc7d612e-20ca-4dd1-8228-5889a24a7062') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24620, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "丢弃", "is_correct": false, "explanation": "语义：丢弃之后东西就不能再用了，与后面的“再用”矛盾。"}, {"text": "回收", "is_correct": true, "explanation": "回收指把旧东西收回来再利用，与“可以……再用”相合。"}, {"text": "修理", "is_correct": false, "explanation": "搭配：“修理”多用于机器、器具，不说修理报纸，与“再用”也不搭。"}, {"text": "烧毁", "is_correct": false, "explanation": "语义：烧毁之后东西就没有了，无法再用。"}], "explanations": {"丢弃": "语义：丢弃之后东西就不能再用了，与后面的“再用”矛盾。", "回收": "回收指把旧东西收回来再利用，与“可以……再用”相合。", "修理": "搭配：“修理”多用于机器、器具，不说修理报纸，与“再用”也不搭。", "烧毁": "语义：烧毁之后东西就没有了，无法再用。"}, "sentence_index": 0, "correct_answer": "回收"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他去商店回收了一台新电脑。", "explanation": "这里应该用〈购买〉。回收指把别人不要的旧东西收回来再用，买新电脑要用〈购买〉。"}, {"text": "这家公司回收了一家小工厂。", "explanation": "这里应该用〈收购〉。回收指把别人不要的旧东西收回来再用，买下整家工厂应说〈收购〉。"}, {"text": "我想回收这个月的工资。", "explanation": "这里应该用〈领取〉。回收指收回不要的东西，工资是应得的收入，应说〈领取〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd64ca69b-64e3-4334-9155-6b7ad34fc6c3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24620, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "扔掉", "is_correct": false, "explanation": "语义：把旧书扔掉了，就不会再给妈妈钱，与“给了她一点钱”矛盾。"}, {"text": "回收", "is_correct": true, "explanation": "收废品的人把旧书收回去再利用，并付给妈妈一点钱，与句意相合。"}, {"text": "废弃", "is_correct": false, "explanation": "语域：“废弃”是书面用语，与口语叙述不合；语义上废弃之后也换不到钱。"}, {"text": "种", "is_correct": false, "explanation": "语义：“种”指栽植，不能用于旧书，“妈妈把旧书种了”不成立，与“换了点钱”也无关。"}], "explanations": {"扔掉": "语义：把旧书扔掉了，就不会再给妈妈钱，与“给了她一点钱”矛盾。", "回收": "收废品的人把旧书收回去再利用，并付给妈妈一点钱，与句意相合。", "废弃": "语域：“废弃”是书面用语，与口语叙述不合；语义上废弃之后也换不到钱。", "种": "语义：“种”指栽植，不能用于旧书，“妈妈把旧书种了”不成立，与“换了点钱”也无关。"}, "sentence_index": 6, "correct_answer": "回收"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他回收了一个朋友，把他带回了家。", "explanation": "这里应该用〈接回〉。回收指把别人不要的东西收回来再用，人不能被回收，把朋友接回家应说〈接回〉。"}, {"text": "我回收了一只小狗，它很可爱。", "explanation": "回收用于别人不要的物品，不能用于领养小狗，这里应说〈收养〉。"}, {"text": "我回收了一次跑步，感觉很累。", "explanation": "这里应该用〈锻炼〉。回收指收回不要的具体东西再用，跑步是动作，不能回收，这里应说〈锻炼〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd64ca69b-64e3-4334-9155-6b7ad34fc6c3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24620, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这些旧报纸已经回收完了了。", "corrected_sentence": "这些旧报纸已经回收完了。", "error_description": "“了”重复：“回收完”后只用一个“了”，应说“回收完了”，不能说“回收完了了”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd64ca69b-64e3-4334-9155-6b7ad34fc6c3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24620, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我以前回收了过很多电池。", "corrected_sentence": "我以前回收过很多电池。", "error_description": "体标重复：“了”与“过”不能同时用在同一动词后；表示曾经做过应只说“回收过”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd64ca69b-64e3-4334-9155-6b7ad34fc6c3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
