INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24622, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "一个人替另一个人说话或做事。", "primary_collocate": null, "pronunciation": "dài biǎo", "ipa": "taɪ˥˩ pjɑʊ˨˩˦", "syllable_count": 2, "sentences": [{"text": "他代表全班去开会。", "target_word": "代表", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "我代表公司谢谢大家。", "target_word": "代表", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "王老师代表学校接待客人。", "target_word": "代表", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "小李不能来，我代表他参加比赛。", "target_word": "代表", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "校长代表全校同学发了言。", "target_word": "代表", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "谁来代表我们说几句话？", "target_word": "代表", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "经理今天生病了，我代表他签字。", "target_word": "代表", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "她代表妈妈去看望奶奶。", "target_word": "代表", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我们选他代表班级参加唱歌比赛。", "target_word": "代表", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我代表全家欢迎你来中国。", "target_word": "代表", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "代表了", "label": "完成体"}, {"form": "代表着", "label": "持续体"}, {"form": "代表过", "label": "经历体"}], "register": "中性", "sense_fingerprint": "替别人或集体出面说话、做事", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c158727a-e2ac-46d3-b271-c699b7ec501e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24622, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "代表", "is_correct": true, "explanation": "代表：替全班出面去开会，符合句意。"}, {"text": "参观", "is_correct": false, "explanation": "搭配：“参观”的宾语是场所或展览，不能说“参观全班”。"}, {"text": "容纳", "is_correct": false, "explanation": "语义：“容纳”指能装下，“他”是人，“他容纳全班”说不通。"}, {"text": "参加", "is_correct": false, "explanation": "搭配：“参加”的宾语是活动或组织，不能以“全班”这样的人群作宾语。"}], "explanations": {"代表": "代表：替全班出面去开会，符合句意。", "参观": "搭配：“参观”的宾语是场所或展览，不能说“参观全班”。", "容纳": "语义：“容纳”指能装下，“他”是人，“他容纳全班”说不通。", "参加": "搭配：“参加”的宾语是活动或组织，不能以“全班”这样的人群作宾语。"}, "sentence_index": 0, "correct_answer": "代表"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他一直认真代表自己的职责。", "explanation": "这里应该用〈履行〉。代表指替人出面做事，不能表示履行职责。"}, {"text": "这朵花代表我去参加婚礼。", "explanation": "这里应该用〈替〉。代表指由人替人出面做事，主语须是人，花不能代表人去参加活动。"}, {"text": "他代表了经理的工作。", "explanation": "这里应该用〈接替〉。代表是替人出面做事，不能表示接手别人的职务。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bd75a825-1ba1-4d13-af2f-d6021369ff4b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24622, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "代表", "is_correct": true, "explanation": "代表：经理生病，我替他签字，符合句意。"}, {"text": "照顾", "is_correct": false, "explanation": "搭配：“照顾”的对象是人，后面不能接“签字”这类公务行为。"}, {"text": "探望", "is_correct": false, "explanation": "语义：“探望”是去看望病人，与“签字”的公务行为无关。"}, {"text": "看护", "is_correct": false, "explanation": "语义：“看护”指护理病人，不能指替经理签字。"}], "explanations": {"代表": "代表：经理生病，我替他签字，符合句意。", "照顾": "搭配：“照顾”的对象是人，后面不能接“签字”这类公务行为。", "探望": "语义：“探望”是去看望病人，与“签字”的公务行为无关。", "看护": "语义：“看护”指护理病人，不能指替经理签字。"}, "sentence_index": 6, "correct_answer": "代表"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "妈妈太累了，我代表她洗碗。", "explanation": "这里应该用〈替〉。代表指替别人或集体正式出面说话、做事，家里帮人做家务这类私人小事要用“替”或“帮”。"}, {"text": "这件事的责任我来代表。", "explanation": "这里应该用〈承担〉。代表指替人出面，不能表示承受责任。"}, {"text": "我代表你的成功。", "explanation": "这里应该用〈祝贺〉。代表指替人出面说话做事，不表示表达祝福。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bd75a825-1ba1-4d13-af2f-d6021369ff4b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24622, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我把代表公司参加会议。", "corrected_sentence": "我代表公司参加会议。", "error_description": "错误在“把”字：“代表”是动词，后面直接带宾语，不能放在“把”字结构中，“把代表”不通。应去掉“把”，说“我代表公司参加会议”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bd75a825-1ba1-4d13-af2f-d6021369ff4b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24622, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "她常常被代表我们班出席活动。", "corrected_sentence": "她常常代表我们班出席活动。", "error_description": "错误在“被”字：“代表”是主动动词，表示替人出面，不能用“被”字构成被动句，“被代表”不通。应去掉“被”，说“她常常代表我们班出席活动”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bd75a825-1ba1-4d13-af2f-d6021369ff4b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
