INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24630, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "一种用金属做的罐子，可以装饮料。", "primary_collocate": null, "pronunciation": "yì lā guàn", "ipa": "i˥˩ la˥ kwan˥˩", "syllable_count": 3, "sentences": [{"text": "桌上放着一个空易拉罐。", "target_word": "易拉罐", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他把易拉罐里的饮料倒进杯子里。", "target_word": "易拉罐", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "孩子们在公园里捡易拉罐。", "target_word": "易拉罐", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这个易拉罐有点凉，喝起来很舒服。", "target_word": "易拉罐", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他踩扁了地上的易拉罐。", "target_word": "易拉罐", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "超市里的易拉罐饮料很便宜。", "target_word": "易拉罐", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "老人每天收集易拉罐，卖给回收站。", "target_word": "易拉罐", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我买了一箱易拉罐啤酒。", "target_word": "易拉罐", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "小朋友用易拉罐做了一只小机器人。", "target_word": "易拉罐", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "别把易拉罐扔在路上。", "target_word": "易拉罐", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "个", "label": "量词"}], "register": "中性", "sense_fingerprint": "金属做的、装饮料的罐子", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9bfbe3a8-7aeb-4ee1-8a32-ba6db3e80028') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24630, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "易拉罐", "is_correct": true, "explanation": "正确：句中指桌上空着的金属饮料罐，正是易拉罐。"}, {"text": "石头", "is_correct": false, "explanation": "语义：石头不是饮料罐，空石头是说不通的，与“空的罐子”语境不符。"}, {"text": "钢琴", "is_correct": false, "explanation": "语义：钢琴是大型乐器，不能说桌上放着一个空钢琴。"}, {"text": "信念", "is_correct": false, "explanation": "搭配：“空”多修饰容器或位置，不能说“空信念”。"}], "explanations": {"易拉罐": "正确：句中指桌上空着的金属饮料罐，正是易拉罐。", "石头": "语义：石头不是饮料罐，空石头是说不通的，与“空的罐子”语境不符。", "钢琴": "语义：钢琴是大型乐器，不能说桌上放着一个空钢琴。", "信念": "搭配：“空”多修饰容器或位置，不能说“空信念”。"}, "sentence_index": 0, "correct_answer": "易拉罐"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "晚上他躺在易拉罐里睡觉。", "explanation": "这里应该用〈床〉。易拉罐是小小的金属饮料罐，人不能躺在里面睡觉；睡觉要用床。"}, {"text": "他把易拉罐当成了鞋子，穿在了脚上。", "explanation": "这里应该用〈拖鞋〉。易拉罐是金属罐，不能穿在脚上；穿在脚上的应是拖鞋。"}, {"text": "他用易拉罐煮了一锅粥。", "explanation": "这里应该用〈锅〉。易拉罐是金属饮料罐，不能拿来煮粥；煮粥要用锅。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7c9caf03-da33-4142-a119-fea37774a70e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24630, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "易拉罐", "is_correct": true, "explanation": "正确：句中指老人收集来卖给回收站的金属饮料罐，正是易拉罐。"}, {"text": "星星", "is_correct": false, "explanation": "语义：星星是天体，不能像易拉罐那样收集后卖给回收站。"}, {"text": "时间", "is_correct": false, "explanation": "搭配：“收集”后常接具体物品，不能说“收集时间”，也不能卖给回收站。"}, {"text": "诗篇", "is_correct": false, "explanation": "语域：诗篇是书面、文学性的词，与“收集后卖给回收站”的口语语境不协调。"}], "explanations": {"易拉罐": "正确：句中指老人收集来卖给回收站的金属饮料罐，正是易拉罐。", "星星": "语义：星星是天体，不能像易拉罐那样收集后卖给回收站。", "时间": "搭配：“收集”后常接具体物品，不能说“收集时间”，也不能卖给回收站。", "诗篇": "语域：诗篇是书面、文学性的词，与“收集后卖给回收站”的口语语境不协调。"}, "sentence_index": 6, "correct_answer": "易拉罐"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他用易拉罐写了一封长信。", "explanation": "这里应该用〈信纸〉。易拉罐是金属罐，不能用来写信；写信要用信纸。"}, {"text": "他背着易拉罐去上学。", "explanation": "这里应该用〈书包〉。上学要背书包，不是易拉罐。"}, {"text": "下雨了，他打开易拉罐挡在头上。", "explanation": "这里应该用〈雨伞〉。易拉罐是金属饮料罐，不能用来挡雨；挡雨要用雨伞。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7c9caf03-da33-4142-a119-fea37774a70e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24630, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他把易拉罐摆的很整齐。", "corrected_sentence": "他把易拉罐摆得很整齐。", "error_description": "补语标记错误：“摆”后表示状态的补语应用“得”连接，写成“的”是错误。正确：摆得很整齐；错误：摆的很整齐。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7c9caf03-da33-4142-a119-fea37774a70e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24630, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他把喝完易拉罐丢进了回收箱。", "corrected_sentence": "他把喝完的易拉罐丢进了回收箱。", "error_description": "定语标记错误：“喝完”修饰名词时要加“的”，应说“喝完的易拉罐”，漏掉“的”是错误。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7c9caf03-da33-4142-a119-fea37774a70e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
