INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24632, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7c9caf03-da33-4142-a119-fea37774a70e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24632, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "看了以后能明白，比如看书、看图后知道是什么意思。", "primary_collocate": null, "pronunciation": "kàn de dǒng", "ipa": "kʰan˥˩ tə toŋ˨˩˦", "syllable_count": 3, "sentences": [{"text": "这个故事很短，小朋友都看得懂。", "target_word": "看得懂", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的手势我看得懂，他想让我先走。", "target_word": "看得懂", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这封信是中文写的，你看得懂吗？", "target_word": "看得懂", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这些漫画有图有字，我看得懂。", "target_word": "看得懂", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "题目很难，连老师都不一定看得懂。", "target_word": "看得懂", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "妈妈的菜谱写得很细，新手也看得懂。", "target_word": "看得懂", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她看得懂简单的英文，但是说不好。", "target_word": "看得懂", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个手机的说明书，我自己看得懂。", "target_word": "看得懂", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这张图表有很多数字，你看得懂吗？", "target_word": "看得懂", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他写的中文作文，我基本都看得懂。", "target_word": "看得懂", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "看不懂", "label": "否定"}, {"form": "看懂了", "label": "体标"}], "register": "中性", "sense_fingerprint": "看了之后能明白是什么意思", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9bfbe3a8-7aeb-4ee1-8a32-ba6db3e80028') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24632, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "看得懂", "is_correct": true, "explanation": "正确：故事很短，小朋友能明白其中的意思。"}, {"text": "看不完", "is_correct": false, "explanation": "语义：“很短”说明故事容易读完，与“看不完”矛盾。"}, {"text": "吃得下", "is_correct": false, "explanation": "搭配：“吃得下”用于食物，不能用于故事。"}, {"text": "拿得动", "is_correct": false, "explanation": "搭配：“拿得动”说的是物体的重量，故事不能用拿。"}], "explanations": {"看得懂": "正确：故事很短，小朋友能明白其中的意思。", "看不完": "语义：“很短”说明故事容易读完，与“看不完”矛盾。", "吃得下": "搭配：“吃得下”用于食物，不能用于故事。", "拿得动": "搭配：“拿得动”说的是物体的重量，故事不能用拿。"}, "sentence_index": 0, "correct_answer": "看得懂"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我看得懂这首曲子的温柔。", "explanation": "这里应该用〈感受〉。看得懂用于文字、图画、手势等有含义的内容，曲子的温柔是情感，要用感受。"}, {"text": "黑暗里，我一听就看得懂那是他的脚步声。", "explanation": "这里应该用〈听出〉。看得懂指看了以后明白意思，靠耳朵辨认脚步声是谁要用听出。"}, {"text": "天太黑了，我看得懂远处的树。", "explanation": "这里应该用〈看清〉。这句说的是能不能看见树，不是理解它的含义，要用看清。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7c9caf03-da33-4142-a119-fea37774a70e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24632, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "看得懂", "is_correct": true, "explanation": "正确：她能理解简单的英文，与后面“说不好”形成对比。"}, {"text": "看不懂", "is_correct": false, "explanation": "语义：“简单的英文”说明内容容易懂，与“看不懂”矛盾。"}, {"text": "闻得到", "is_correct": false, "explanation": "搭配：“闻得到”指嗅觉，英文是文字和语言，不能用闻。"}, {"text": "摸得着", "is_correct": false, "explanation": "搭配：“摸得着”指触觉，英文不能用手去摸。"}], "explanations": {"看得懂": "正确：她能理解简单的英文，与后面“说不好”形成对比。", "看不懂": "语义：“简单的英文”说明内容容易懂，与“看不懂”矛盾。", "闻得到": "搭配：“闻得到”指嗅觉，英文是文字和语言，不能用闻。", "摸得着": "搭配：“摸得着”指触觉，英文不能用手去摸。"}, "sentence_index": 6, "correct_answer": "看得懂"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这盆花的香味很浓，我一闻就看得懂是茉莉。", "explanation": "这里应该用〈闻出〉。看得懂指理解文字或语言，花的香味要靠嗅觉，应该用闻出。"}, {"text": "我一看就看得懂这块石头是假的。", "explanation": "这里应该用〈看得出〉。看得懂指理解含义，判断东西真假、看出迹象要用看得出。"}, {"text": "这道菜太咸，我一尝就看得懂。", "explanation": "这里应该用〈尝出〉。看得懂不能表示尝到的味道，味道要用尝出。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7c9caf03-da33-4142-a119-fea37774a70e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24632, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这份说明书的字很小，我戴上眼镜才看得懂着。", "corrected_sentence": "这份说明书的字很小，我戴上眼镜才看得懂。", "error_description": "错误：“看得懂着”。正确：“看得懂”。可能补语“看得懂”是完整结构，后面不能再加动态助词“着”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7c9caf03-da33-4142-a119-fea37774a70e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24632, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这本小说的语言很朴素，我一读就看得懂得。", "corrected_sentence": "这本小说的语言很朴素，我一读就看得懂。", "error_description": "错误：“看得懂得”。正确：“看得懂”。可能补语的“得”只出现一次，“看得懂”后面不能再加“得”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7c9caf03-da33-4142-a119-fea37774a70e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
