INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24634, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "一个人或东西在原地画圆圈。", "primary_collocate": null, "pronunciation": "zhuàn quān", "ipa": "ʈʂwan˥˩ tɕʰyɛn˥", "syllable_count": 2, "sentences": [{"text": "小狗在原地转圈，想咬自己的尾巴。", "target_word": "转圈", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她穿着新裙子，开心地原地转圈。", "target_word": "转圈", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "舞蹈演员在台上转圈，裙子像一朵花。", "target_word": "转圈", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小朋友闭上眼睛，在原地转圈玩。", "target_word": "转圈", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "风很大，地上的落叶在原地转圈。", "target_word": "转圈", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "洗衣机里的衣服一直在转圈。", "target_word": "转圈", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "溜冰的女孩在冰上转圈，大家都看着她。", "target_word": "转圈", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小猫在沙发上转圈，然后躺下睡觉了。", "target_word": "转圈", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他喝多了，站在路边原地转圈。", "target_word": "转圈", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "孩子们张开手臂，在草地上转圈。", "target_word": "转圈", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "转圈儿", "label": "儿化"}], "register": "口语", "sense_fingerprint": "人或物在原地打转，画出圆圈", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9bfbe3a8-7aeb-4ee1-8a32-ba6db3e80028') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24634, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "转圈", "is_correct": true, "explanation": "正确：小狗在原地绕圈，想咬自己的尾巴，符合原地转圈的情景。"}, {"text": "做饭", "is_correct": false, "explanation": "语义：小狗不会做饭，“做饭”与小狗在原地的动作不符。"}, {"text": "读书", "is_correct": false, "explanation": "搭配：“读书”不能用于小狗，动物不读书。"}, {"text": "讲故事", "is_correct": false, "explanation": "搭配：“讲故事”需要会说话的人，不能用于小狗。"}], "explanations": {"转圈": "正确：小狗在原地绕圈，想咬自己的尾巴，符合原地转圈的情景。", "做饭": "语义：小狗不会做饭，“做饭”与小狗在原地的动作不符。", "读书": "搭配：“读书”不能用于小狗，动物不读书。", "讲故事": "搭配：“讲故事”需要会说话的人，不能用于小狗。"}, "sentence_index": 0, "correct_answer": "转圈"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "她听见有人叫她，立刻转圈跑向门口。", "explanation": "这里应该用〈转身〉。转圈指连续绕圈，一次回身要用转身，然后才走向门口。"}, {"text": "我们沿着公路一直转圈，走了十公里。", "explanation": "这里应该用〈直行〉。转圈指在原地绕圈，沿公路走十公里要用直行。"}, {"text": "他病了，只能在床上转圈休息。", "explanation": "这里应该用〈躺〉。转圈指绕圈活动，卧床休息要用躺。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7c9caf03-da33-4142-a119-fea37774a70e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24634, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "转圈", "is_correct": true, "explanation": "正确：女孩在冰上绕圈，大家都看着她，符合溜冰的情景。"}, {"text": "游泳", "is_correct": false, "explanation": "搭配：“游泳”用于水中，女孩是在冰上，不能说在冰上游泳。"}, {"text": "耕地", "is_correct": false, "explanation": "搭配：“耕地”是农业活动，冰上不能耕地。"}, {"text": "躲藏", "is_correct": false, "explanation": "语义：“大家都看着她”说明她是被看着的，与“躲藏”矛盾。"}], "explanations": {"转圈": "正确：女孩在冰上绕圈，大家都看着她，符合溜冰的情景。", "游泳": "搭配：“游泳”用于水中，女孩是在冰上，不能说在冰上游泳。", "耕地": "搭配：“耕地”是农业活动，冰上不能耕地。", "躲藏": "语义：“大家都看着她”说明她是被看着的，与“躲藏”矛盾。"}, "sentence_index": 6, "correct_answer": "转圈"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他转圈奔向学校，一路没停。", "explanation": "这里应该用〈直奔〉。转圈指原地绕圈，去某个地方要用直奔。"}, {"text": "听到老师叫他，他转圈回答了问题。", "explanation": "这里应该用〈站起来〉。转圈指原地绕圈，回答老师问题时应站起来。"}, {"text": "他累了，在椅子上转圈，看着窗外休息。", "explanation": "这里应该用〈坐着〉。转圈是原地绕圈的动作，安静地休息看窗外要用坐着。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7c9caf03-da33-4142-a119-fea37774a70e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24634, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "小猫在窗边转圈着，好像在找什么东西。", "corrected_sentence": "小猫在窗边转着圈，好像在找什么东西。", "error_description": "错误：“转圈着”。正确：“转着圈”。动态助词“着”要紧跟动词“转”，“圈”是动作的宾语，不能把“着”放在“圈”后面。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7c9caf03-da33-4142-a119-fea37774a70e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24634, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他拿到礼物，高兴地在原地转圈地。", "corrected_sentence": "他拿到礼物，高兴地在原地转圈。", "error_description": "错误：“转圈地”。正确：“转圈”。“地”标志状语，用在动词前；“转圈”作谓语，后面不能加“地”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7c9caf03-da33-4142-a119-fea37774a70e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
