INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24636, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "家人一起住的地方。", "primary_collocate": null, "pronunciation": "jiā", "ipa": "tɕja˥", "syllable_count": 1, "sentences": [{"text": "我家就在学校旁边，走路五分钟。", "target_word": "家", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "她的家离学校很远。", "target_word": "家", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "下雨了，我们快回家吧。", "target_word": "家", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他们买了房子，有了自己的家。", "target_word": "家", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "妈妈在家做饭，我在家写作业。", "target_word": "家", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "那个小房子就是他的家。", "target_word": "家", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "我的家不大，但是很温暖。", "target_word": "家", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "晚上他一直待在家，没有出门。", "target_word": "家", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "你的家在哪儿？", "target_word": "家", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "过年时，我要回家看爸妈。", "target_word": "家", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "个", "label": "量词"}, {"form": "家人", "label": "复合"}, {"form": "回家", "label": "复合"}], "register": "中性", "sense_fingerprint": "家：家人共同居住的地方", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '77c37cae-b219-4aee-bb4e-93cb237f46fe') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24636, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "家", "is_correct": true, "explanation": "家（jiā，第一声）：家人一起住的地方，正确答案。"}, {"text": "价", "is_correct": false, "explanation": "价 jià（第四声）与 jiā（第一声）声调不同，意思是价格。"}, {"text": "嫁", "is_correct": false, "explanation": "嫁 jià（第四声）与 jiā（第一声）声调不同，意思是出嫁。"}, {"text": "掐", "is_correct": false, "explanation": "掐 qiā 与 jiā 声母不同（q 送气，j 不送气），意思是用手指按压。"}, {"text": "假", "is_correct": false, "explanation": "假 jiǎ（第三声）与 jiā（第一声）声调不同，意思是虚假。"}], "explanations": {"家": "家（jiā，第一声）：家人一起住的地方，正确答案。", "价": "价 jià（第四声）与 jiā（第一声）声调不同，意思是价格。", "嫁": "嫁 jià（第四声）与 jiā（第一声）声调不同，意思是出嫁。", "掐": "掐 qiā 与 jiā 声母不同（q 送气，j 不送气），意思是用手指按压。", "假": "假 jiǎ（第三声）与 jiā（第一声）声调不同，意思是虚假。"}, "sentence_index": null, "correct_answer": "家"}, "level_3": {"options": [{"text": "家", "is_correct": true, "explanation": "家：家人一起住的地方，“我家就在学校旁边”符合句意。"}, {"text": "国", "is_correct": false, "explanation": "语义：“我国”指国家，国家不可能在学校旁边、走路五分钟。"}, {"text": "校", "is_correct": false, "explanation": "语义：“我校”就是学校，不能说学校在学校旁边。"}, {"text": "班", "is_correct": false, "explanation": "语义：班级在学校里面，不能说“在学校旁边，走路五分钟”。"}], "explanations": {"家": "家：家人一起住的地方，“我家就在学校旁边”符合句意。", "国": "语义：“我国”指国家，国家不可能在学校旁边、走路五分钟。", "校": "语义：“我校”就是学校，不能说学校在学校旁边。", "班": "语义：班级在学校里面，不能说“在学校旁边，走路五分钟”。"}, "sentence_index": 0, "correct_answer": "家"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他们买了一套家，很满意。", "explanation": "这里应该用〈房子〉。“家”指家人共同生活的地方，不能像房子一样用“套”来计量。"}, {"text": "他每天去家上班，很辛苦。", "explanation": "这里应该用〈公司〉。“家”指家人共同生活的地方，不能指工作单位。"}, {"text": "他把家放进口袋里带走了。", "explanation": "这里应该用〈钥匙〉。“家”是家人住的地方，不能放进口袋。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd3ef8427-8705-4e76-a145-d2df3a556326') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24636, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "家", "is_correct": true, "explanation": "家（jiā，第一声）：家人一起住的地方，正确答案。"}, {"text": "江", "is_correct": false, "explanation": "江 jiāng 与 jiā 韵母不同（多了 ng），意思是江河。"}, {"text": "尖", "is_correct": false, "explanation": "尖 jiān 与 jiā 韵母不同（多了 n），意思是尖锐。"}, {"text": "架", "is_correct": false, "explanation": "架 jià（第四声）与 jiā（第一声）声调不同，意思是架子。"}, {"text": "甲", "is_correct": false, "explanation": "甲 jiǎ（第三声）与 jiā（第一声）声调不同，意思是盔甲、指甲等。"}], "explanations": {"家": "家（jiā，第一声）：家人一起住的地方，正确答案。", "江": "江 jiāng 与 jiā 韵母不同（多了 ng），意思是江河。", "尖": "尖 jiān 与 jiā 韵母不同（多了 n），意思是尖锐。", "架": "架 jià（第四声）与 jiā（第一声）声调不同，意思是架子。", "甲": "甲 jiǎ（第三声）与 jiā（第一声）声调不同，意思是盔甲、指甲等。"}, "sentence_index": null, "correct_answer": "家"}, "level_3": {"options": [{"text": "家", "is_correct": true, "explanation": "家：家人一起住的地方，“我的家不大，但是很温暖”符合句意。"}, {"text": "桌", "is_correct": false, "explanation": "语义：桌子不能用“温暖”来形容其居住感受，与句意矛盾。"}, {"text": "作业", "is_correct": false, "explanation": "语义：“作业”是学习任务，不能住人，也不能用“很温暖”形容居住环境，句意不通。"}, {"text": "考试", "is_correct": false, "explanation": "语义：“考试”不是住所，“我的考试不大，但是很温暖”句意不通。"}], "explanations": {"家": "家：家人一起住的地方，“我的家不大，但是很温暖”符合句意。", "桌": "语义：桌子不能用“温暖”来形容其居住感受，与句意矛盾。", "作业": "语义：“作业”是学习任务，不能住人，也不能用“很温暖”形容居住环境，句意不通。", "考试": "语义：“考试”不是住所，“我的考试不大，但是很温暖”句意不通。"}, "sentence_index": 6, "correct_answer": "家"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他很家，经常陪家人。", "explanation": "这里应该用〈顾家〉。“家”是名词，不能用“很”修饰。"}, {"text": "他们有一台家，很温暖。", "explanation": "这里应该用〈个〉。“台”用于机器等，不能用于家。"}, {"text": "他买了一把家，放在客厅。", "explanation": "这里应该用〈个〉。“把”用于有柄的物品，不能用于家。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd3ef8427-8705-4e76-a145-d2df3a556326') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24636, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我们的一台家在三楼。", "corrected_sentence": "我们的家在三楼。", "error_description": "错误形式：“一台家”；正确形式：“我们的家”，去掉“一台”。“台”用于机器等，不能用于家。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd3ef8427-8705-4e76-a145-d2df3a556326') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24636, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我们家回吧。", "corrected_sentence": "我们回家吧。", "error_description": "错误形式：“家回”；正确形式：“回家”。“回家”是动宾结构，“家”应放在“回”后面，不能倒过来。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd3ef8427-8705-4e76-a145-d2df3a556326') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
