INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24638, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "全世界就是地球上所有的地方。", "primary_collocate": null, "pronunciation": "quán shì jiè", "ipa": "tɕʰyɛn˧˥ ʂʐ̩˥˩ tɕjɛ˥˩", "syllable_count": 3, "sentences": [{"text": "全世界的人都喜欢音乐。", "target_word": "全世界", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "我想走遍全世界。", "target_word": "全世界", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "这个电影全世界都知道。", "target_word": "全世界", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "全世界有七十多亿人。", "target_word": "全世界", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "全世界的孩子都爱玩。", "target_word": "全世界", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "中国菜在全世界都很有名。", "target_word": "全世界", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "今天全世界的人都在看这场比赛。", "target_word": "全世界", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他的歌红遍了全世界。", "target_word": "全世界", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "全世界的海都连在一起。", "target_word": "全世界", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "我想把中文介绍给全世界。", "target_word": "全世界", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "地球上所有的地方和人", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a6c53470-eab2-4aaa-a8c7-536b79bbc5b7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24638, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "全世界", "is_correct": true, "explanation": "全世界指地球上所有的地方，和“都”呼应，正好说整个地球的人喜欢音乐。"}, {"text": "石头", "is_correct": false, "explanation": "语义：石头是无生命的东西，不能指一群人，“石头的人”说不通。"}, {"text": "空气", "is_correct": false, "explanation": "语义：空气不是人群，也不是地方，无法和“的人都喜欢音乐”搭配。"}, {"text": "星期天", "is_correct": false, "explanation": "搭配：“星期天”是时间，不能用来修饰“人”，说“星期天的人”不通。"}], "explanations": {"全世界": "全世界指地球上所有的地方，和“都”呼应，正好说整个地球的人喜欢音乐。", "石头": "语义：石头是无生命的东西，不能指一群人，“石头的人”说不通。", "空气": "语义：空气不是人群，也不是地方，无法和“的人都喜欢音乐”搭配。", "星期天": "搭配：“星期天”是时间，不能用来修饰“人”，说“星期天的人”不通。"}, "sentence_index": 0, "correct_answer": "全世界"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我全世界都在北京。", "explanation": "这里应该用〈全家〉。全世界指地球上所有的地方，指一家人的范围要用“全家”。"}, {"text": "全世界同学都在教室里。", "explanation": "这里应该用〈全班〉。全世界指整个地球，只指一个班的同学时要用“全班”。"}, {"text": "全世界师生都在礼堂里。", "explanation": "这里应该用〈全校〉。全世界指地球上所有的地方，指一所学校的师生要用“全校”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'aa29b907-5038-4975-9c83-47b668cb4b9b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24638, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "全世界", "is_correct": true, "explanation": "全世界指地球上所有的地方，和“都”呼应，正好说整个地球的人在看比赛。"}, {"text": "大海", "is_correct": false, "explanation": "搭配：“大海”不能直接修饰“人”，要说“海边的人”，不能说“大海的人”。"}, {"text": "黑板", "is_correct": false, "explanation": "语义：黑板是物品，不能指一群人，“黑板的人”说不通。"}, {"text": "牛奶", "is_correct": false, "explanation": "语义：牛奶是饮料，不指人，句子说“牛奶的人都在看比赛”说不通。"}], "explanations": {"全世界": "全世界指地球上所有的地方，和“都”呼应，正好说整个地球的人在看比赛。", "大海": "搭配：“大海”不能直接修饰“人”，要说“海边的人”，不能说“大海的人”。", "黑板": "语义：黑板是物品，不能指一群人，“黑板的人”说不通。", "牛奶": "语义：牛奶是饮料，不指人，句子说“牛奶的人都在看比赛”说不通。"}, "sentence_index": 6, "correct_answer": "全世界"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他全世界都疼。", "explanation": "这里应该用〈全身〉。全世界指地球上所有的地方，不能用来说身体的范围。"}, {"text": "他一个人把全世界的蛋糕都吃了。", "explanation": "这里应该用〈整个〉。全世界指地球上所有的地方，说一个蛋糕的全部要用“整个蛋糕”。"}, {"text": "这家店全世界营业。", "explanation": "这里应该用〈全天〉。全世界指地点，表示时间要用“全天”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'aa29b907-5038-4975-9c83-47b668cb4b9b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24638, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这个品牌在全世界的都有分店。", "corrected_sentence": "这个品牌在全世界都有分店。", "error_description": "错误形式：全世界的都。正确形式：全世界都。「的」后面必须有名词中心语（如「全世界的人」），这里「的」后面直接接「都」，没有中心语，所以应去掉「的」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'aa29b907-5038-4975-9c83-47b668cb4b9b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24638, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他周游了一个全世界。", "corrected_sentence": "他周游了全世界。", "error_description": "错误形式是在“全世界”前面加了量词“一个”，正确形式是“全世界”。“全世界”指地球上所有的地方，是一个整体，前面不能加量词。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'aa29b907-5038-4975-9c83-47b668cb4b9b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24640, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "糟蹋", "is_correct": true, "explanation": "糟蹋：随便损坏、不好好对待东西，与“爱惜”反义。"}, {"text": "修理", "is_correct": false, "explanation": "修理：使物品恢复正常，与“爱惜”没有反义关系。"}, {"text": "打扫", "is_correct": false, "explanation": "打扫：清理环境，与“爱惜”没有反义关系。"}, {"text": "旅行", "is_correct": false, "explanation": "旅行：出外游览，与“爱惜”没有反义关系。"}], "correct_answer": "糟蹋", "explanations": {"糟蹋": "糟蹋：随便损坏、不好好对待东西，与“爱惜”反义。", "修理": "修理：使物品恢复正常，与“爱惜”没有反义关系。", "打扫": "打扫：清理环境，与“爱惜”没有反义关系。", "旅行": "旅行：出外游览，与“爱惜”没有反义关系。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd3ef8427-8705-4e76-a145-d2df3a556326') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24640, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "糟蹋", "is_correct": true, "explanation": "糟蹋：随便损坏、不好好对待东西，与“爱惜”反义。"}, {"text": "砍伐", "is_correct": false, "explanation": "砍伐：砍倒树木，与“爱惜”没有反义关系。"}, {"text": "测量", "is_correct": false, "explanation": "测量：量取尺寸，与“爱惜”没有反义关系。"}, {"text": "搬运", "is_correct": false, "explanation": "搬运：转移物体的位置，与“爱惜”没有反义关系。"}], "correct_answer": "糟蹋", "explanations": {"糟蹋": "糟蹋：随便损坏、不好好对待东西，与“爱惜”反义。", "砍伐": "砍伐：砍倒树木，与“爱惜”没有反义关系。", "测量": "测量：量取尺寸，与“爱惜”没有反义关系。", "搬运": "搬运：转移物体的位置，与“爱惜”没有反义关系。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd3ef8427-8705-4e76-a145-d2df3a556326') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24640, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "爱惜就是好好保护自己喜欢的东西。", "primary_collocate": null, "pronunciation": "ài xī", "ipa": "ai˥˩ ɕi˥", "syllable_count": 2, "sentences": [{"text": "她很爱惜自己的新裙子。", "target_word": "爱惜", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "哥哥爱惜他的自行车，天天擦。", "target_word": "爱惜", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "小明爱惜每一本漫画书。", "target_word": "爱惜", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "我爱惜这双球鞋，下雨天不穿。", "target_word": "爱惜", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "爷爷爱惜他的老照相机。", "target_word": "爱惜", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "她爱惜着妈妈留下的那条围巾。", "target_word": "爱惜", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他不爱惜玩具，所以很快就坏了。", "target_word": "爱惜", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "你要爱惜朋友送你的礼物。", "target_word": "爱惜", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "妹妹特别爱惜她的小花园。", "target_word": "爱惜", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "弟弟很爱惜他的画笔，每次用完都放好。", "target_word": "爱惜", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "爱惜了", "label": "体标"}, {"form": "爱惜着", "label": "体标"}, {"form": "爱惜过", "label": "体标"}], "register": "中性", "sense_fingerprint": "爱惜：好好保护自己喜欢的东西", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '77c37cae-b219-4aee-bb4e-93cb237f46fe') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24640, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "爱惜", "is_correct": true, "explanation": "爱惜：好好保护、重视，“她很爱惜自己的新裙子”符合句意。"}, {"text": "挥霍", "is_correct": false, "explanation": "搭配：“挥霍”多用于钱财，不用于形容对裙子的态度。"}, {"text": "撕", "is_correct": false, "explanation": "语义：“她很撕自己的新裙子”描述的是破坏行为，与句意相反。"}, {"text": "损坏", "is_correct": false, "explanation": "语义：“损坏自己的新裙子”与“很”和爱惜的态度矛盾。"}], "explanations": {"爱惜": "爱惜：好好保护、重视，“她很爱惜自己的新裙子”符合句意。", "挥霍": "搭配：“挥霍”多用于钱财，不用于形容对裙子的态度。", "撕": "语义：“她很撕自己的新裙子”描述的是破坏行为，与句意相反。", "损坏": "语义：“损坏自己的新裙子”与“很”和爱惜的态度矛盾。"}, "sentence_index": 0, "correct_answer": "爱惜"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他生气地爱惜了椅子。", "explanation": "这里应该用〈踢翻〉。“爱惜”表示重视而不糟蹋，不能用来描述发脾气时的动作。"}, {"text": "他故意爱惜了我的花园。", "explanation": "这里应该用〈踩坏〉。“爱惜”表示重视而不糟蹋，不能用来表示故意破坏。"}, {"text": "警察爱惜了那个小偷。", "explanation": "这里应该用〈逮捕〉。“爱惜”表示重视而不糟蹋，不能用来表示逮捕罪犯的行为。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd3ef8427-8705-4e76-a145-d2df3a556326') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24640, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "爱惜", "is_correct": true, "explanation": "爱惜：重视而不糟蹋，“他不爱惜玩具，所以很快就坏了”中“不爱惜”与句意相符。"}, {"text": "吃", "is_correct": false, "explanation": "语义：“他不吃玩具”与玩具坏掉的因果关系不符。"}, {"text": "煮", "is_correct": false, "explanation": "搭配：玩具不能用“煮”来处理，搭配不当。"}, {"text": "种", "is_correct": false, "explanation": "语义：玩具不能被“种”，与句意矛盾。"}], "explanations": {"爱惜": "爱惜：重视而不糟蹋，“他不爱惜玩具，所以很快就坏了”中“不爱惜”与句意相符。", "吃": "语义：“他不吃玩具”与玩具坏掉的因果关系不符。", "煮": "搭配：玩具不能用“煮”来处理，搭配不当。", "种": "语义：玩具不能被“种”，与句意矛盾。"}, "sentence_index": 6, "correct_answer": "爱惜"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "那个小偷爱惜了我的钱包。", "explanation": "这里应该用〈偷走〉。“爱惜”表示重视而不糟蹋，不能用来描述偷窃行为。"}, {"text": "这场比赛输了，大家都很爱惜。", "explanation": "这里应该用〈惋惜〉。“爱惜”指重视而不糟蹋，不能用来表示对失利的遗憾。"}, {"text": "小狗爱惜了我的拖鞋，上面全是洞。", "explanation": "这里应该用〈咬坏〉。“爱惜”表示好好保护，不能描述把东西咬坏。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd3ef8427-8705-4e76-a145-d2df3a556326') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24640, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我总是爱惜得我的书包。", "corrected_sentence": "我总是爱惜我的书包。", "error_description": "错误形式：“爱惜得我的书包”；正确形式：“爱惜我的书包”。“爱惜”后应直接接宾语，“得”不能插在动词与宾语之间；“爱惜得”只能接程度补语，如“爱惜得很”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd3ef8427-8705-4e76-a145-d2df3a556326') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24640, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "妹妹很爱惜了她的画笔。", "corrected_sentence": "妹妹很爱惜她的画笔。", "error_description": "错误形式：“很爱惜了”；正确形式：“很爱惜”。“很”后面的动词通常不加“了”，应去掉“了”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd3ef8427-8705-4e76-a145-d2df3a556326') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
