INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24648, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "回到过去某个时候。", "primary_collocate": null, "pronunciation": "zhuī sù dào", "ipa": "ʈʂweɪ˥ su˥˩ tɑʊ˥˩", "syllable_count": 3, "sentences": [{"text": "我的记忆可以追溯到三岁的时候。", "target_word": "追溯到", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他们的友谊追溯到小学时代。", "target_word": "追溯到", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这个习惯可以追溯到我小时候。", "target_word": "追溯到", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "说起这件事，要追溯到五年前。", "target_word": "追溯到", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这个村子的名字追溯到很久以前。", "target_word": "追溯到", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "爸爸的回忆追溯到他住在乡下的那些年。", "target_word": "追溯到", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这张桌子可以追溯到上个世纪。", "target_word": "追溯到", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这家公司的历史追溯到一九五零年。", "target_word": "追溯到", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我们的矛盾要追溯到去年的一次旅行。", "target_word": "追溯到", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这道菜的做法追溯到外婆年轻的时候。", "target_word": "追溯到", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "追溯到了", "label": "体标"}], "register": "中性", "sense_fingerprint": "追溯到：记忆、关系或事情的起因回到过去的某个时候", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '78836ff6-43bd-45b4-82eb-9adfdab50fcf') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24648, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "追溯到", "is_correct": true, "explanation": "正确：“我的记忆可以追溯到三岁的时候”表示记忆回到三岁，符合句意。"}, {"text": "预见到", "is_correct": false, "explanation": "语义：“预见”指预先看到未来，与回到过去的记忆语义相反。"}, {"text": "出发到", "is_correct": false, "explanation": "搭配：“出发”指离开某地前往别处，不能与“到三岁的时候”搭配。"}, {"text": "寄托到", "is_correct": false, "explanation": "配价：“寄托”的宾语是希望或感情，不能接时间作补语。"}], "explanations": {"追溯到": "正确：“我的记忆可以追溯到三岁的时候”表示记忆回到三岁，符合句意。", "预见到": "语义：“预见”指预先看到未来，与回到过去的记忆语义相反。", "出发到": "搭配：“出发”指离开某地前往别处，不能与“到三岁的时候”搭配。", "寄托到": "配价：“寄托”的宾语是希望或感情，不能接时间作补语。"}, "sentence_index": 0, "correct_answer": "追溯到"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这条小路追溯到山顶。", "explanation": "这里应该用〈通向〉。追溯到表示回到过去的时间，不能说道路延伸到某个地方。"}, {"text": "研究人员追溯到工程明年完成。", "explanation": "这里应该用〈预计〉。追溯到是回溯过去，不能用来推测未来的完成时间。"}, {"text": "船队终于追溯到了港口。", "explanation": "这里应该用〈抵达〉。追溯到不用于船只或人回到某个空间地点。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f8ff73d8-aa3f-4a7c-8686-6aff4021dffb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24648, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "追溯到", "is_correct": true, "explanation": "正确：“这张桌子可以追溯到上个世纪”表示桌子的历史回到上个世纪，符合句意。"}, {"text": "远眺到", "is_correct": false, "explanation": "搭配：“远眺”指向远处看，不能接“到上个世纪”这样的时间作补语。"}, {"text": "顺延到", "is_correct": false, "explanation": "语义：“顺延”指日期向后推迟，与回溯到过去的时间语义相反。"}, {"text": "放映到", "is_correct": false, "explanation": "配价：“放映”的宾语是影片，不能用于桌子的历史时间。"}], "explanations": {"追溯到": "正确：“这张桌子可以追溯到上个世纪”表示桌子的历史回到上个世纪，符合句意。", "远眺到": "搭配：“远眺”指向远处看，不能接“到上个世纪”这样的时间作补语。", "顺延到": "语义：“顺延”指日期向后推迟，与回溯到过去的时间语义相反。", "放映到": "配价：“放映”的宾语是影片，不能用于桌子的历史时间。"}, "sentence_index": 6, "correct_answer": "追溯到"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "农民追溯到了一群羊。", "explanation": "这里应该用〈饲养〉。追溯到表示回溯过去的源头，不能说对动物进行饲养。"}, {"text": "她拼命地追溯到了前面的那个人。", "explanation": "这里应该用〈追上〉。追溯到表示回到过去的某个时候，不能表示赶上前面正在走的人。"}, {"text": "老师追溯到了我的作业。", "explanation": "这里应该用〈批改〉。追溯到表示回溯到源头，不能表示检查并评分作业。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f8ff73d8-aa3f-4a7c-8686-6aff4021dffb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24648, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我的童年记忆可以追溯到着五岁的时候。", "corrected_sentence": "我的童年记忆可以追溯到五岁的时候。", "error_description": "错误：“到”后多加了“着”，“着”不能接在补语“到”之后表示持续。正确应为“可以追溯到五岁的时候”，“追溯到”直接接时间。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f8ff73d8-aa3f-4a7c-8686-6aff4021dffb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24648, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这首民歌的来历可以追溯到到明朝末年。", "corrected_sentence": "这首民歌的来历可以追溯到明朝末年。", "error_description": "错误：“追溯到”后多加了一个“到”，补语重复，句子不合语法。正确应删去多余的“到”，即“可以追溯到明朝末年”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f8ff73d8-aa3f-4a7c-8686-6aff4021dffb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
