INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24650, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '69f4ea35-59be-4a4b-a754-c6218d71bbb6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24650, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "图案就是画在东西上面的样子，比如衣服上的小花。", "primary_collocate": null, "pronunciation": "tú àn", "ipa": "tʰu˧˥ an˥˩", "syllable_count": 2, "sentences": [{"text": "我的新裙子上有很多小花图案。", "target_word": "图案", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的袜子上是小鱼图案。", "target_word": "图案", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个杯子上的图案是一只猫。", "target_word": "图案", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "窗帘上的图案太花了，我不喜欢。", "target_word": "图案", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "妈妈买了一条有星星图案的围巾。", "target_word": "图案", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "书包上的图案是我最爱的动物。", "target_word": "图案", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "床单上的图案很好看，我想买。", "target_word": "图案", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你的伞上有什么图案？", "target_word": "图案", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这件衣服没有图案，只有一种颜色。", "target_word": "图案", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他在墙上画了一个大图案。", "target_word": "图案", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "个", "label": "量词"}, {"form": "种", "label": "量词"}, {"form": "圖案", "label": "繁体"}], "register": "中性", "sense_fingerprint": "画在衣物、日用品上的样子", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6a1fb72f-7f26-46aa-b253-c34484e0d5e4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24650, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "图案", "is_correct": true, "explanation": "正确：图案指画在衣物上的样子，这里指裙子上的小花图样，符合语境。"}, {"text": "歌曲", "is_correct": false, "explanation": "语义：歌曲是声音作品，不是可以画在裙子上的花样。"}, {"text": "声音", "is_correct": false, "explanation": "搭配：声音无形，不能附着在裙子上，“裙子上有很多小花声音”不成立。"}, {"text": "价格", "is_correct": false, "explanation": "语义：价格是金额，不是可以看见的花样，与“很多小花”的描写不搭。"}], "explanations": {"图案": "正确：图案指画在衣物上的样子，这里指裙子上的小花图样，符合语境。", "歌曲": "语义：歌曲是声音作品，不是可以画在裙子上的花样。", "声音": "搭配：声音无形，不能附着在裙子上，“裙子上有很多小花声音”不成立。", "价格": "语义：价格是金额，不是可以看见的花样，与“很多小花”的描写不搭。"}, "sentence_index": 0, "correct_answer": "图案"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他在舞会上唱了一个很好看的图案。", "explanation": "这里应该用〈歌〉。图案指画在东西上面的样子，不能用来唱；在舞会上唱的是歌。"}, {"text": "他看到这个消息，心里的图案很复杂，久久不能平静。", "explanation": "这里应该用〈心情〉。图案指画在东西上的样子，不指人的心理状态，说心里的感受应用“心情”。"}, {"text": "这首歌的图案很动听。", "explanation": "这里应该用〈旋律〉。图案指画在东西上面的样子，不能用来形容声音；形容歌曲动听应说“旋律”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '69f4ea35-59be-4a4b-a754-c6218d71bbb6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24650, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "图案", "is_correct": true, "explanation": "正确：床单上的图案是可见的花样，“很好看”符合语境。"}, {"text": "味道", "is_correct": false, "explanation": "语义：“好看”形容外观，味道不能用“好看”来形容。"}, {"text": "温度", "is_correct": false, "explanation": "语义：温度是数值，不能用“好看”形容。"}, {"text": "时间", "is_correct": false, "explanation": "搭配：“床单上的时间”不成立，时间不能附着在床单上。"}], "explanations": {"图案": "正确：床单上的图案是可见的花样，“很好看”符合语境。", "味道": "语义：“好看”形容外观，味道不能用“好看”来形容。", "温度": "语义：温度是数值，不能用“好看”形容。", "时间": "搭配：“床单上的时间”不成立，时间不能附着在床单上。"}, "sentence_index": 6, "correct_answer": "图案"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他每天用图案做饭，菜都很好吃。", "explanation": "这里应该用〈食材〉。图案是画在东西上面的样子，不能用来做饭；做饭要用食材。"}, {"text": "墙上挂着一个很长的图案，列出了所有商品的价格。", "explanation": "这里应该用〈价目表〉。图案指画在东西上面的样子，不能用来列出商品价格，列价格要用价目表。"}, {"text": "店门口摆着一个很大的图案，客人可以坐在上面休息。", "explanation": "这里应该用〈长椅〉。长椅供人坐着休息；图案是画在东西上面的样子，不能用来坐。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '69f4ea35-59be-4a4b-a754-c6218d71bbb6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24650, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这条领带上有两本蓝色的图案。", "corrected_sentence": "这条领带上有两个蓝色的图案。", "error_description": "量词错误：“图案”常用“个”或“种”计量，“本”用于书本，不能用来计量图案。正确说法是“两个蓝色的图案”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '69f4ea35-59be-4a4b-a754-c6218d71bbb6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24650, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "妹妹在本子上画了一只小图案。", "corrected_sentence": "妹妹在本子上画了一个小图案。", "error_description": "量词错误：“图案”应该用量词“个”。“只”用于动物，或成对物品中的一个，不能用来计量图案。正确说法是“一个小图案”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '69f4ea35-59be-4a4b-a754-c6218d71bbb6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
