INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24654, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '792dd777-1725-4a90-833e-a1a265eb0b88') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24654, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "设计师是画图、想主意，然后做出新东西的人。", "primary_collocate": null, "pronunciation": "shè jì shī", "ipa": "ʂɤ˥˩ tɕi˥˩ ʂɨ˥", "syllable_count": 3, "sentences": [{"text": "我姐姐是一位有名的设计师。", "target_word": "设计师", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "设计师正在电脑前画图。", "target_word": "设计师", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这座桥是一位年轻设计师设计的。", "target_word": "设计师", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "设计师想了很久，才决定用蓝色。", "target_word": "设计师", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他从小就想当设计师。", "target_word": "设计师", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这件衣服是设计师自己做的。", "target_word": "设计师", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "设计师给我们看了新房子的图。", "target_word": "设计师", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我哥哥在一家公司做设计师。", "target_word": "设计师", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "好的设计师会听客人的想法。", "target_word": "设计师", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那位设计师给我们做了一把新椅子。", "target_word": "设计师", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "位", "label": "量词"}, {"form": "名", "label": "量词"}, {"form": "服装设计师", "label": "复合"}, {"form": "設計師", "label": "繁体"}], "register": "中性", "sense_fingerprint": "从事设计工作的专业人员", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '810ac7fa-1260-4d9e-be13-37017ce45fe6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24654, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "房子", "is_correct": false, "explanation": "搭配：量词“位”只用于人，不说“一位房子”。"}, {"text": "设计师", "is_correct": true, "explanation": "正确：设计师是从事设计工作的人，可以用“一位有名的”修饰。"}, {"text": "石头", "is_correct": false, "explanation": "搭配：“位”只能计人，“一位石头”不能说。"}, {"text": "电脑", "is_correct": false, "explanation": "语义：电脑是机器，不是人，不能作“我姐姐”的职业身份。"}], "explanations": {"房子": "搭配：量词“位”只用于人，不说“一位房子”。", "设计师": "正确：设计师是从事设计工作的人，可以用“一位有名的”修饰。", "石头": "搭配：“位”只能计人，“一位石头”不能说。", "电脑": "语义：电脑是机器，不是人，不能作“我姐姐”的职业身份。"}, "sentence_index": 0, "correct_answer": "设计师"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "设计师在路口指挥交通。", "explanation": "这里应该用〈警察〉。指挥交通是警察的工作，设计师的工作是画图和设计。"}, {"text": "他把设计师放进了冰箱。", "explanation": "这里应该用〈牛奶〉。设计师是人，不能放进冰箱；「牛奶」才是可以放进冰箱的东西。"}, {"text": "我爸爸在设计师工作。", "explanation": "这里应该用〈设计院〉。设计师是职业，不是工作的地方。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '792dd777-1725-4a90-833e-a1a265eb0b88') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24654, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "窗户", "is_correct": false, "explanation": "语义：窗户是建筑部件，不能给人看图，句子不合常理。"}, {"text": "设计师", "is_correct": true, "explanation": "正确：设计师能给人看设计好的图，符合语境。"}, {"text": "小猫", "is_correct": false, "explanation": "语义：小猫不能给人看新房子的图纸，句子不合常理。"}, {"text": "名字", "is_correct": false, "explanation": "配价：“给我们看”需要能动的施事，“名字”不能作施事。"}], "explanations": {"窗户": "语义：窗户是建筑部件，不能给人看图，句子不合常理。", "设计师": "正确：设计师能给人看设计好的图，符合语境。", "小猫": "语义：小猫不能给人看新房子的图纸，句子不合常理。", "名字": "配价：“给我们看”需要能动的施事，“名字”不能作施事。"}, "sentence_index": 6, "correct_answer": "设计师"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "用设计师做了一把椅子。", "explanation": "这里应该用〈木头〉。做椅子要用木头等材料，设计师是人，不能当材料。"}, {"text": "设计师给我们看了病。", "explanation": "这里应该用〈医生〉。看病的是医生，设计师不看病。"}, {"text": "设计师帮我们打了官司。", "explanation": "这里应该用〈律师〉。打官司要找律师，设计师不做这个工作。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '792dd777-1725-4a90-833e-a1a265eb0b88') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24654, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这位很有名设计师住在隔壁。", "corrected_sentence": "这位很有名的设计师住在隔壁。", "error_description": "“很有名”修饰“设计师”时中间要加“的”，应说“很有名的设计师”；漏掉“的”就不自然。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '792dd777-1725-4a90-833e-a1a265eb0b88') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24654, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我们请来了一只设计师。", "corrected_sentence": "我们请来了一位设计师。", "error_description": "“设计师”指人，量词应用“位”或“个”，“只”用于动物等，不能说“一只设计师”；应说“一位设计师”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '792dd777-1725-4a90-833e-a1a265eb0b88') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24656, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "欢送", "is_correct": true, "explanation": "反义：“欢迎”表示迎接来的人，“欢送”表示送别离开的人，二者构成反义。"}, {"text": "学习", "is_correct": false, "explanation": "无关：“学习”与“欢迎”没有反义关系。"}, {"text": "旅行", "is_correct": false, "explanation": "无关：“旅行”与“欢迎”没有反义关系。"}, {"text": "研究", "is_correct": false, "explanation": "无关：“研究”与“欢迎”没有反义关系。"}], "correct_answer": "欢送", "explanations": {"欢送": "反义：“欢迎”表示迎接来的人，“欢送”表示送别离开的人，二者构成反义。", "学习": "无关：“学习”与“欢迎”没有反义关系。", "旅行": "无关：“旅行”与“欢迎”没有反义关系。", "研究": "无关：“研究”与“欢迎”没有反义关系。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bd75a825-1ba1-4d13-af2f-d6021369ff4b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24656, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "欢送", "is_correct": true, "explanation": "反义：“欢迎”表示迎接来的人，“欢送”表示送别离开的人，二者构成反义。"}, {"text": "游泳", "is_correct": false, "explanation": "无关：“游泳”与“欢迎”没有反义关系。"}, {"text": "写作", "is_correct": false, "explanation": "无关：“写作”与“欢迎”没有反义关系。"}, {"text": "唱歌", "is_correct": false, "explanation": "无关：“唱歌”与“欢迎”没有反义关系。"}], "correct_answer": "欢送", "explanations": {"欢送": "反义：“欢迎”表示迎接来的人，“欢送”表示送别离开的人，二者构成反义。", "游泳": "无关：“游泳”与“欢迎”没有反义关系。", "写作": "无关：“写作”与“欢迎”没有反义关系。", "唱歌": "无关：“唱歌”与“欢迎”没有反义关系。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bd75a825-1ba1-4d13-af2f-d6021369ff4b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24656, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "高兴地迎接来到的人，或表示乐于接受某人做某事。", "primary_collocate": null, "pronunciation": "huān yíng", "ipa": "xwan˥ iŋ˧˥", "syllable_count": 2, "sentences": [{"text": "欢迎你来我们学校参观。", "target_word": "欢迎", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们热烈欢迎新同学。", "target_word": "欢迎", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "大家都来机场欢迎他回国。", "target_word": "欢迎", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "欢迎你有空来我家玩。", "target_word": "欢迎", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "欢迎各位来到北京。", "target_word": "欢迎", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们用鲜花欢迎客人。", "target_word": "欢迎", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "妈妈说，欢迎朋友随时来家里吃饭。", "target_word": "欢迎", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师在门口欢迎每一位学生。", "target_word": "欢迎", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "客人一进门，大家就热情地欢迎他们。", "target_word": "欢迎", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们欢迎你加入我们的小组。", "target_word": "欢迎", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "受欢迎", "label": "复合"}, {"form": "欢迎会", "label": "复合"}], "register": "中性", "sense_fingerprint": "动词，高兴地迎接来到的人，或表示乐于接受某人做某事", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c158727a-e2ac-46d3-b271-c699b7ec501e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24656, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "欢迎", "is_correct": true, "explanation": "正确：“欢迎”表示高兴地迎接来的人，与“你来我们学校参观”相符。"}, {"text": "欢送", "is_correct": false, "explanation": "语义：“欢送”指送别离开的人，与“你来我们学校参观”的到来方向相反。"}, {"text": "告别", "is_correct": false, "explanation": "语义：“告别”表示离开，与“你来参观”的语境不符。"}, {"text": "送别", "is_correct": false, "explanation": "搭配：“送别”通常用于送人离开，不与“你来”这样表示到来的内容搭配。"}], "explanations": {"欢迎": "正确：“欢迎”表示高兴地迎接来的人，与“你来我们学校参观”相符。", "欢送": "语义：“欢送”指送别离开的人，与“你来我们学校参观”的到来方向相反。", "告别": "语义：“告别”表示离开，与“你来参观”的语境不符。", "送别": "搭配：“送别”通常用于送人离开，不与“你来”这样表示到来的内容搭配。"}, "sentence_index": 0, "correct_answer": "欢迎"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "大家在车站欢迎他出国。", "explanation": "这里应该用〈欢送〉。“欢送”用于送别离开的人，“欢迎”用于迎接来的人，不能用于送人出国。"}, {"text": "他只能欢迎这种痛苦。", "explanation": "这里应该用〈忍受〉。“忍受”指承受痛苦、不愉快的事；“欢迎”表示乐于接受，与“忍受”的态度正相反。"}, {"text": "欢迎你考上了大学。", "explanation": "这里应该用〈祝贺〉。对别人取得的成绩表示庆贺要用“祝贺”，“欢迎”不能这样用。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bd75a825-1ba1-4d13-af2f-d6021369ff4b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24656, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "欢迎", "is_correct": true, "explanation": "正确：“欢迎”表示乐于接待，与“随时来家里吃饭”的热情语境相符。"}, {"text": "驱赶", "is_correct": false, "explanation": "语义：“驱赶”是赶走，与“随时来家里吃饭”的邀请语气矛盾。"}, {"text": "嫌弃", "is_correct": false, "explanation": "语义：“嫌弃”表示厌恶，与“随时来家里吃饭”的热情邀请不符。"}, {"text": "劝阻", "is_correct": false, "explanation": "搭配：“劝阻”多用于阻止不当行为，不与“随时来家里吃饭”这种邀请搭配。"}], "explanations": {"欢迎": "正确：“欢迎”表示乐于接待，与“随时来家里吃饭”的热情语境相符。", "驱赶": "语义：“驱赶”是赶走，与“随时来家里吃饭”的邀请语气矛盾。", "嫌弃": "语义：“嫌弃”表示厌恶，与“随时来家里吃饭”的热情邀请不符。", "劝阻": "搭配：“劝阻”多用于阻止不当行为，不与“随时来家里吃饭”这种邀请搭配。"}, "sentence_index": 6, "correct_answer": "欢迎"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我们都欢迎了他的错误。", "explanation": "这里应该用〈原谅〉。对别人的过错表示宽恕要用“原谅”，“欢迎”不能用于错误。"}, {"text": "大家都欢迎她的才华。", "explanation": "这里应该用〈欣赏〉。对才能、作品表示赞赏要用“欣赏”，“欢迎”不用于此。"}, {"text": "大家都欢迎这种不良风气。", "explanation": "这里应该用〈抵制〉。“抵制”指反对、不接受，“欢迎”表示乐于接受，意思正好相反。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bd75a825-1ba1-4d13-af2f-d6021369ff4b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24656, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "大家热烈欢迎你去我们城市做客。", "corrected_sentence": "大家热烈欢迎你来我们城市做客。", "error_description": "错误在方向：“欢迎”后面表示到说话人所在地时要用“来”，应说“欢迎你来”，不说“欢迎你去”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bd75a825-1ba1-4d13-af2f-d6021369ff4b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24656, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "去年我们欢迎了过一批新同学。", "corrected_sentence": "去年我们欢迎过一批新同学。", "error_description": "错误在体标：“欢迎”后用“过”表示经历，不能再加“了”，应说“欢迎过”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bd75a825-1ba1-4d13-af2f-d6021369ff4b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
