INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24658, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "做事情的一步一步的顺序。", "primary_collocate": null, "pronunciation": "bù zhòu", "ipa": "pu˥˩ ʈʂoʊ̯˥˩", "syllable_count": 2, "sentences": [{"text": "做这道菜一共有五个步骤。", "target_word": "步骤", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请按照步骤一步一步做。", "target_word": "步骤", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "第一个步骤是先洗手。", "target_word": "步骤", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师给我们讲了实验的步骤。", "target_word": "步骤", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个步骤很简单，你一看就会。", "target_word": "步骤", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你做错了一个步骤，所以手机打不开。", "target_word": "步骤", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "书上写着每个步骤，你照着做就行。", "target_word": "步骤", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "学做饭要先记住每一个步骤。", "target_word": "步骤", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "下一个步骤是把水倒进锅里。", "target_word": "步骤", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他把安装步骤写在纸上了。", "target_word": "步骤", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "个", "label": "量词"}, {"form": "操作步骤", "label": "复合"}, {"form": "实验步骤", "label": "复合"}], "register": "中性", "sense_fingerprint": "步骤：做事情时一步接一步的顺序", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '474535a0-0dad-4240-b06c-55efe2468b5f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24658, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "步骤", "is_correct": true, "explanation": "正确：步骤指做事的一步一步的顺序，与“五个”搭配，表示这道菜的做法环节。"}, {"text": "菜", "is_correct": false, "explanation": "语义：句中说的是做“这道菜”，“一共有五个菜”与这道菜的做法自相矛盾。"}, {"text": "作业", "is_correct": false, "explanation": "语义：“作业”指功课，与做菜的步骤无关，“做这道菜一共有五个作业”说不通。"}, {"text": "电话", "is_correct": false, "explanation": "语义：“电话”与做菜的做法无关，“做这道菜一共有五个电话”说不通。"}], "explanations": {"步骤": "正确：步骤指做事的一步一步的顺序，与“五个”搭配，表示这道菜的做法环节。", "菜": "语义：句中说的是做“这道菜”，“一共有五个菜”与这道菜的做法自相矛盾。", "作业": "语义：“作业”指功课，与做菜的步骤无关，“做这道菜一共有五个作业”说不通。", "电话": "语义：“电话”与做菜的做法无关，“做这道菜一共有五个电话”说不通。"}, "sentence_index": 0, "correct_answer": "步骤"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他走路的步骤很快。", "explanation": "这里应该用〈步伐〉。走路时迈出的脚步要说步伐，步骤指做事的先后顺序。"}, {"text": "这首诗分为三个步骤。", "explanation": "这里应该用〈段落〉。段落是诗文的分段，步骤指做事的先后顺序，诗的划分不说步骤。"}, {"text": "学校每天安排八个步骤。", "explanation": "这里应该用〈课时〉。课时是教学的时间单位，步骤指做事的先后顺序，每天的上课安排不说步骤。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0e47fe9b-3d79-4d9d-abf7-e34753d2a57d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24658, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "步骤", "is_correct": true, "explanation": "正确：步骤是做事的先后顺序，书上写着每个步骤，才能“照着做”。"}, {"text": "答案", "is_correct": false, "explanation": "搭配：答案是问题的结果，不能“照着做”，与句中的做法不搭配。"}, {"text": "味道", "is_correct": false, "explanation": "语义：味道是感觉，不能“照着做”，与“书上写着”的指导语境不合。"}, {"text": "颜色", "is_correct": false, "explanation": "语义：颜色是事物的属性，书上写着每个颜色，你照着做就行，说法不通。"}], "explanations": {"步骤": "正确：步骤是做事的先后顺序，书上写着每个步骤，才能“照着做”。", "答案": "搭配：答案是问题的结果，不能“照着做”，与句中的做法不搭配。", "味道": "语义：味道是感觉，不能“照着做”，与“书上写着”的指导语境不合。", "颜色": "语义：颜色是事物的属性，书上写着每个颜色，你照着做就行，说法不通。"}, "sentence_index": 6, "correct_answer": "步骤"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我最喜欢这首交响曲的第二步骤。", "explanation": "这里应该用〈乐章〉。乐章是交响曲等乐曲的分段，步骤指做事的先后顺序，不用来指乐曲的段落。"}, {"text": "他这学期拿到了十个步骤。", "explanation": "这里应该用〈学分〉。学分是修完课程的计量单位，步骤指做事的先后顺序，不能用来计算修课成果。"}, {"text": "这首歌的步骤很快。", "explanation": "这里应该用〈节奏〉。音乐的快慢要说节奏，步骤不表示快慢。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0e47fe9b-3d79-4d9d-abf7-e34753d2a57d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24658, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "请你先看懂每个的步骤，再动手做。", "corrected_sentence": "请你先看懂每个步骤，再动手做。", "error_description": "结构错误：数量定语“每个”直接修饰名词，中间不加“的”，应说“每个步骤”，不能说“每个的步骤”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0e47fe9b-3d79-4d9d-abf7-e34753d2a57d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24658, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "做这份早餐有三件步骤，很简单。", "corrected_sentence": "做这份早餐有三个步骤，很简单。", "error_description": "量词错误：“步骤”的量词是“个”，不能用“件”。“三件步骤”应改为“三个步骤”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0e47fe9b-3d79-4d9d-abf7-e34753d2a57d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
