INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24662, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "让花草、小河、空气都干干净净，不弄脏它们。", "primary_collocate": null, "pronunciation": "bǎo hù huán jìng", "ipa": "pɑʊ̯˨˩ xu˥˩ xwan˧˥ tɕiŋ˥˩", "syllable_count": 4, "sentences": [{"text": "我们每个人都要保护环境。", "target_word": "保护环境", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "少用塑料袋，就是保护环境。", "target_word": "保护环境", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "老师告诉孩子们要保护环境。", "target_word": "保护环境", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "为了保护环境，我骑自行车上班。", "target_word": "保护环境", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "爷爷一直在山里保护环境。", "target_word": "保护环境", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他们在河边捡垃圾，保护环境。", "target_word": "保护环境", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "保护环境对大家的健康很重要。", "target_word": "保护环境", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "工厂不能随便排脏水，要保护环境。", "target_word": "保护环境", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "小明从小就懂得保护环境。", "target_word": "保护环境", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我们种了很多树来保护环境。", "target_word": "保护环境", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "保护了环境", "label": "体标（了）"}, {"form": "保护过环境", "label": "体标（过）"}, {"form": "保護環境", "label": "繁体"}], "register": "中性", "sense_fingerprint": "保护环境：让自然环境保持干净、不被弄脏", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ffce3848-4e7c-4ec3-885e-673579ba7e56') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24662, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "保护环境", "is_correct": true, "explanation": "正确：“我们每个人都要保护环境”表示人人应爱护自然环境，与句意一致。"}, {"text": "破坏环境", "is_correct": false, "explanation": "语义：“破坏环境”与“每个人都要”的倡导相反。"}, {"text": "保护", "is_correct": false, "explanation": "配价：“保护”需要带宾语，后面要说保护什么，单独使用不完整。"}, {"text": "污染环境", "is_correct": false, "explanation": "语义：“污染环境”与“每个人都要”的号召相反。"}], "explanations": {"保护环境": "正确：“我们每个人都要保护环境”表示人人应爱护自然环境，与句意一致。", "破坏环境": "语义：“破坏环境”与“每个人都要”的倡导相反。", "保护": "配价：“保护”需要带宾语，后面要说保护什么，单独使用不完整。", "污染环境": "语义：“污染环境”与“每个人都要”的号召相反。"}, "sentence_index": 0, "correct_answer": "保护环境"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这位士兵每天都在保护环境，守卫着边疆。", "explanation": "这里应该用〈保卫〉。“保护环境”指让环境干净，守卫边疆要用〈保卫〉。"}, {"text": "奶奶每天在家保护环境，给孙子做饭。", "explanation": "这里应该用〈照顾〉。“保护环境”指让环境干净，不能用来说照看孙子。"}, {"text": "他每天都在保护环境，不敢长时间看书，怕近视。", "explanation": "这里应该用〈保护视力〉。“保护环境”指让环境干净，不能用来说护眼。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ad60c45b-4ca7-40b4-bf0c-f205e95e64b0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24662, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "保护环境", "is_correct": true, "explanation": "正确：“保护环境对大家的健康很重要”符合事实，主语是一个动宾短语。"}, {"text": "污染水源", "is_correct": false, "explanation": "语义：污染水源危害健康，与“很重要”的说法相反。"}, {"text": "保持", "is_correct": false, "explanation": "配价：“保持”后要带宾语，单独作主语时句子不完整。"}, {"text": "乱扔垃圾", "is_correct": false, "explanation": "语义：乱扔垃圾不利于健康，不能说对健康“很重要”。"}], "explanations": {"保护环境": "正确：“保护环境对大家的健康很重要”符合事实，主语是一个动宾短语。", "污染水源": "语义：污染水源危害健康，与“很重要”的说法相反。", "保持": "配价：“保持”后要带宾语，单独作主语时句子不完整。", "乱扔垃圾": "语义：乱扔垃圾不利于健康，不能说对健康“很重要”。"}, "sentence_index": 6, "correct_answer": "保护环境"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他每天保护环境，不让别人看他的日记。", "explanation": "这里应该用〈保护隐私〉。“保护环境”指让环境干净，不能用来说保护隐私。"}, {"text": "博物馆的工作人员每天保护环境，修复古画。", "explanation": "这里应该用〈保护文物〉。“保护环境”指让环境干净，修复古画要说〈保护文物〉。"}, {"text": "警察每天保护环境，看守监狱里的犯人。", "explanation": "这里应该用〈看守〉。“保护环境”指让环境干净，不能用来说看守犯人。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ad60c45b-4ca7-40b4-bf0c-f205e95e64b0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24662, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这个城市每天都在认真保护环境地。", "corrected_sentence": "这个城市每天都在认真保护环境。", "error_description": "多余助词：“保护环境”之后不能加“地”。状语“认真”直接放在动词前即可，应说“认真保护环境”，不能在宾语后加“地”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ad60c45b-4ca7-40b4-bf0c-f205e95e64b0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24662, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我们明天要去公园保护了环境。", "corrected_sentence": "我们明天要去公园保护环境。", "error_description": "体标错误：“明天要去”表示还没发生的事，不能用“了”，应说“我们明天要去公园保护环境。”", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ad60c45b-4ca7-40b4-bf0c-f205e95e64b0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
