INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24664, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "塑料瓶是用来装水或饮料的瓶子，它是用塑料做的。", "primary_collocate": null, "pronunciation": "sù liào píng", "ipa": "su˥˩ li̯ɑu̯˥˩ pʰiŋ˧˥", "syllable_count": 3, "sentences": [{"text": "桌子上有一个塑料瓶。", "target_word": "塑料瓶", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个塑料瓶里有水。", "target_word": "塑料瓶", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他喝完水，把塑料瓶放进了垃圾桶。", "target_word": "塑料瓶", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "塑料瓶很轻，孩子也拿得动。", "target_word": "塑料瓶", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "妈妈用旧塑料瓶种花。", "target_word": "塑料瓶", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "超市里的塑料瓶比玻璃瓶便宜。", "target_word": "塑料瓶", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个塑料瓶不能放进热水里。", "target_word": "塑料瓶", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "别把用过的塑料瓶乱扔。", "target_word": "塑料瓶", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我每天带一个塑料瓶去学校喝水。", "target_word": "塑料瓶", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "塑料瓶掉在地上，水都流出来了。", "target_word": "塑料瓶", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "个", "label": "量词"}, {"form": "塑料瓶盖", "label": "复合"}], "register": "中性", "sense_fingerprint": "用塑料做的、装水或饮料的瓶子", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '60fb9430-b8df-4950-a53e-fc0e3676837a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24664, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "塑料瓶", "is_correct": true, "explanation": "塑料瓶：用塑料做的、装水或饮料的瓶子，符合句中“桌子上”的语境。"}, {"text": "天空", "is_correct": false, "explanation": "语义：“天空”指天上的空间，不能放在桌子上。"}, {"text": "苍穹", "is_correct": false, "explanation": "语域：“苍穹”是书面文学用语，且指天空，与口语句“桌子上有一个”的语域和语义都不合。"}, {"text": "月亮", "is_correct": false, "explanation": "语义：“月亮”在天上，不可能放在桌子上。"}], "explanations": {"塑料瓶": "塑料瓶：用塑料做的、装水或饮料的瓶子，符合句中“桌子上”的语境。", "天空": "语义：“天空”指天上的空间，不能放在桌子上。", "苍穹": "语域：“苍穹”是书面文学用语，且指天空，与口语句“桌子上有一个”的语域和语义都不合。", "月亮": "语义：“月亮”在天上，不可能放在桌子上。"}, "sentence_index": 0, "correct_answer": "塑料瓶"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我每天用塑料瓶烧水。", "explanation": "这里应该用〈水壶〉。塑料瓶不能放在火上或热水中加热，烧水要用水壶。"}, {"text": "超市给我一个塑料瓶装西瓜。", "explanation": "这里应该用〈网兜〉。西瓜太大，塑料瓶装不下，应说“用网兜装西瓜”。"}, {"text": "我买了一根塑料瓶。", "explanation": "这里应该用〈个〉。瓶子的量词用“个”，不用“根”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'af59f68c-12f2-4b76-a7d4-22045b744e01') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24664, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "塑料瓶", "is_correct": true, "explanation": "塑料瓶：用塑料做的、装水或饮料的瓶子，符合句中“放进热水里”的语境。"}, {"text": "冰山", "is_correct": false, "explanation": "语义：“冰山”体积巨大，不可能放进热水里。"}, {"text": "星辰", "is_correct": false, "explanation": "语域：“星辰”是书面语，指星星，且不能放进热水里，与口语句的语域和语义都不合。"}, {"text": "大海", "is_correct": false, "explanation": "语义：“大海”无法放进热水里。"}], "explanations": {"塑料瓶": "塑料瓶：用塑料做的、装水或饮料的瓶子，符合句中“放进热水里”的语境。", "冰山": "语义：“冰山”体积巨大，不可能放进热水里。", "星辰": "语域：“星辰”是书面语，指星星，且不能放进热水里，与口语句的语域和语义都不合。", "大海": "语义：“大海”无法放进热水里。"}, "sentence_index": 6, "correct_answer": "塑料瓶"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他用塑料瓶煮了一锅粥。", "explanation": "这里应该用〈锅〉。塑料瓶不耐高温，不能用来煮东西。"}, {"text": "工人用塑料瓶砌墙。", "explanation": "这里应该用〈砖〉。塑料瓶质轻中空，不能用来砌墙，砌墙要用砖。"}, {"text": "我买了一张塑料瓶。", "explanation": "这里应该用〈个〉。瓶子的量词用“个”，不用“张”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'af59f68c-12f2-4b76-a7d4-22045b744e01') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24664, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这块塑料瓶很轻。", "corrected_sentence": "这个塑料瓶很轻。", "error_description": "量词错误：瓶子的量词用“个”，不用“块”，应说“这个塑料瓶”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'af59f68c-12f2-4b76-a7d4-22045b744e01') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24664, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我买了两塑料瓶。", "corrected_sentence": "我买了两个塑料瓶。", "error_description": "量词缺失：数词“两”后面的名词要带量词，应说“两个塑料瓶”，不能说“两塑料瓶”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'af59f68c-12f2-4b76-a7d4-22045b744e01') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
