INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24666, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "圆圈是像太阳、皮球那样圆圆的形状。", "primary_collocate": null, "pronunciation": "yuán quān", "ipa": "ɥɛn˧˥ tɕʰɥɛn˥", "syllable_count": 2, "sentences": [{"text": "孩子们手拉手围成一个圆圈。", "target_word": "圆圈", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "大家坐成一个圆圈，开始玩游戏。", "target_word": "圆圈", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "小狗在花园里绕着圆圈跑。", "target_word": "圆圈", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "运动员们在操场上排成了一个大圆圈。", "target_word": "圆圈", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "今晚月亮很亮，像一个白色的圆圈。", "target_word": "圆圈", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "石头掉进水里，水面上出现了圆圈。", "target_word": "圆圈", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他吹出的烟变成了一个个圆圈。", "target_word": "圆圈", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "小朋友们站在圆圈中间唱歌。", "target_word": "圆圈", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "老师让我们把椅子摆成一个圆圈。", "target_word": "圆圈", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的眼睛又大又圆，像两个小圆圈。", "target_word": "圆圈", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "个", "label": "量词"}, {"form": "圓圈", "label": "繁体"}], "register": "中性", "sense_fingerprint": "圆圈：人或物围成、排成或呈现出的圆圆的形状", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '78836ff6-43bd-45b4-82eb-9adfdab50fcf') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24666, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "圆圈", "is_correct": true, "explanation": "“圆圈”指人围成的圆圆的形状，与孩子们手拉手围成的情境相符。"}, {"text": "直线", "is_correct": false, "explanation": "语义：“围成”要求形成闭合的形状，直线不能围成图形。"}, {"text": "句子", "is_correct": false, "explanation": "语义：孩子们手拉手无法围成一个句子，句子不是可见的形状。"}, {"text": "围墙", "is_correct": false, "explanation": "搭配：“围墙”是建筑物，“手拉手围成一个围墙”的搭配不当。"}], "explanations": {"圆圈": "“圆圈”指人围成的圆圆的形状，与孩子们手拉手围成的情境相符。", "直线": "语义：“围成”要求形成闭合的形状，直线不能围成图形。", "句子": "语义：孩子们手拉手无法围成一个句子，句子不是可见的形状。", "围墙": "搭配：“围墙”是建筑物，“手拉手围成一个围墙”的搭配不当。"}, "sentence_index": 0, "correct_answer": "圆圈"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "运动员们在操场上排成了一条大圆圈。", "explanation": "这里应该用〈个〉。“圆圈”的量词是“个”，“条”用于细长的东西，不能用来数圆圈。"}, {"text": "运动员们在操场上圆圈了一大片。", "explanation": "这里应该用〈排成〉。“圆圈”是名词，不能直接用作动词。"}, {"text": "运动员们在操场上绕着跑了一只圆圈。", "explanation": "这里应该用〈个〉。“只”多用于动物，不能用来数圆圈。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f8ff73d8-aa3f-4a7c-8686-6aff4021dffb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24666, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "石子", "is_correct": false, "explanation": "语义：烟不会变成石子，石子是固体。"}, {"text": "饼干", "is_correct": false, "explanation": "语义：烟不会变成饼干，饼干是食物。"}, {"text": "字句", "is_correct": false, "explanation": "搭配：“变成一个个字句”搭配不当，烟不会变成文字。"}, {"text": "圆圈", "is_correct": true, "explanation": "“圆圈”指烟圈这类圆圆的形状，与吹出的烟变成一个个圆圈的描写相符。"}], "explanations": {"石子": "语义：烟不会变成石子，石子是固体。", "饼干": "语义：烟不会变成饼干，饼干是食物。", "字句": "搭配：“变成一个个字句”搭配不当，烟不会变成文字。", "圆圈": "“圆圈”指烟圈这类圆圆的形状，与吹出的烟变成一个个圆圈的描写相符。"}, "sentence_index": 6, "correct_answer": "圆圈"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他的眼睛很圆圈。", "explanation": "这里应该用〈圆〉。“圆圈”是名词，不能作形容词谓语。"}, {"text": "他的眼睛像一只大圆圈。", "explanation": "这里应该用〈个〉。“圆圈”的量词是“个”，“只”用于动物，不能用来数圆圈。"}, {"text": "这个箱子是一个圆圈。", "explanation": "这里应该用〈方形〉。箱子是方的，与“圆圈”的圆形相反，不能用“圆圈”来形容。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f8ff73d8-aa3f-4a7c-8686-6aff4021dffb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24666, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "学生们在操场上围成了一条圆圈。", "corrected_sentence": "学生们在操场上围成了一个圆圈。", "error_description": "错误形式：“一条圆圈”。正确形式：“一个圆圈”。“圆圈”的量词用“个”，“条”用于细长的东西。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f8ff73d8-aa3f-4a7c-8686-6aff4021dffb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24666, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "同学们站成了一个圆圈个。", "corrected_sentence": "同学们站成了一个圆圈。", "error_description": "错误形式：“圆圈个”，名词后多加了一个量词“个”。正确形式：“一个圆圈”。数量词只需用一次，“个”已经出现在“一个”中，名词后不能再加。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f8ff73d8-aa3f-4a7c-8686-6aff4021dffb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
