INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24668, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "开始做一件事。", "primary_collocate": null, "pronunciation": "zuò qǐ", "ipa": "tswo˥˩ tɕʰi˨˩˦", "syllable_count": 2, "sentences": [{"text": "想学好中文，要从听和说做起。", "target_word": "做起", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他从小生意做起，慢慢有了大公司。", "target_word": "做起", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "想爱护地球，我们要从小事做起。", "target_word": "做起", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这家店的老板是从工人做起的。", "target_word": "做起", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "做饭很难，你先从简单的菜做起吧。", "target_word": "做起", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "要想身体好，就得从每天走路做起。", "target_word": "做起", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "她想当医生，先从照顾病人做起。", "target_word": "做起", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "学画画可以从画一个苹果做起。", "target_word": "做起", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "改变生活，不如从早睡做起。", "target_word": "做起", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "好习惯要从现在做起。", "target_word": "做起", "complexity_tier": "T1", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "从某件事开始做：从……做起", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a6c53470-eab2-4aaa-a8c7-536b79bbc5b7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24668, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "做起", "is_correct": true, "explanation": "做起表示从某件事开始着手，符合「要从听和说做起」的语境。"}, {"text": "结束", "is_correct": false, "explanation": "语义：「结束」表示终止，与「从……开始」的意思矛盾。"}, {"text": "停下", "is_correct": false, "explanation": "语义：「停下」表示停止进行，不能用来表示从某事开始。"}, {"text": "放弃", "is_correct": false, "explanation": "搭配：「从……放弃」不成立，放弃不能用在「从某事出发」的结构中。"}], "explanations": {"做起": "做起表示从某件事开始着手，符合「要从听和说做起」的语境。", "结束": "语义：「结束」表示终止，与「从……开始」的意思矛盾。", "停下": "语义：「停下」表示停止进行，不能用来表示从某事开始。", "放弃": "搭配：「从……放弃」不成立，放弃不能用在「从某事出发」的结构中。"}, "sentence_index": 0, "correct_answer": "做起"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "会议在下午五点做起。", "explanation": "这里应该用〈开始〉。做起只能用于人动手去做某件事，不能用来说会议这类事件开始。"}, {"text": "雨做起来了。", "explanation": "这里应该用〈下〉。做起只能用于人开始动手做事，不能用来说雨开始下。"}, {"text": "风做起来了，窗户咯吱咯吱地响。", "explanation": "这里应该用〈刮〉。做起只能用于人开始动手做事，不能用来说风刮起来。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'aa29b907-5038-4975-9c83-47b668cb4b9b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24668, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "做起", "is_correct": true, "explanation": "做起表示从某件事开始着手，符合「先从照顾病人做起」的语境。"}, {"text": "忽略", "is_correct": false, "explanation": "语义：忽略表示不加理会，与「从……开始」的意思矛盾。"}, {"text": "逃避", "is_correct": false, "explanation": "语义：逃避表示躲开责任，与「先从某事着手」的语境相反。"}, {"text": "放下", "is_correct": false, "explanation": "搭配：「从……放下」不成立，放下不能用在「从某事出发」的结构中。"}], "explanations": {"做起": "做起表示从某件事开始着手，符合「先从照顾病人做起」的语境。", "忽略": "语义：忽略表示不加理会，与「从……开始」的意思矛盾。", "逃避": "语义：逃避表示躲开责任，与「先从某事着手」的语境相反。", "放下": "搭配：「从……放下」不成立，放下不能用在「从某事出发」的结构中。"}, "sentence_index": 6, "correct_answer": "做起"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他昨天突然做起了感冒。", "explanation": "这里应该用〈得〉。做起表示开始动手做某件事，不能用来说人患上感冒，应说「得了感冒」。"}, {"text": "他突然做起了脾气，把门摔得砰砰响。", "explanation": "这里应该用〈发〉。做起表示开始动手做某件事，不能用来说人发脾气，应说「发脾气」。"}, {"text": "他做起双手，表示投降。", "explanation": "这里应该用〈举起〉。做起表示开始动手做某件事，不表示把双手抬起来。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'aa29b907-5038-4975-9c83-47b668cb4b9b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24668, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "你应该把从基础做起。", "corrected_sentence": "你应该从基础做起。", "error_description": "多加了“把”：“从……做起”中的“从基础”是介词结构，不能放进“把”字句里，应去掉“把”，说“从基础做起”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'aa29b907-5038-4975-9c83-47b668cb4b9b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24668, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "学习弹琴，可以从简单的曲子了做起。", "corrected_sentence": "学习弹琴，可以从简单的曲子做起。", "error_description": "“了”位置错了：“了”不能插在“从……做起”的“曲子”和“做起”之间，应去掉，说“从简单的曲子做起”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'aa29b907-5038-4975-9c83-47b668cb4b9b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
