INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24670, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "用眼睛看，然后知道是什么。", "primary_collocate": null, "pronunciation": "rèn", "ipa": "ʐən˥˩", "syllable_count": 1, "sentences": [{"text": "这个字我不会认，你来读一下。", "target_word": "认", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "天太黑了，我认不清路牌上的字。", "target_word": "认", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他换了发型，我差点认不出来。", "target_word": "认", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "很久没见了，你还认得出我吗？", "target_word": "认", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "照片上有很多人，你能认出哪个是我吗？", "target_word": "认", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他刚来这儿，认不清回家的路。", "target_word": "认", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小孩三岁就会认颜色了。", "target_word": "认", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他刚学中文，还认不了几个汉字。", "target_word": "认", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师教孩子认图上的动物。", "target_word": "认", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这张卡的颜色很特别，一眼就能认出来。", "target_word": "认", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "认了", "label": "体标"}, {"form": "认过", "label": "体标"}, {"form": "认出", "label": "复合"}, {"form": "認", "label": "繁体"}], "register": "中性", "sense_fingerprint": "用眼睛看后辨认出是什么", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6a1fb72f-7f26-46aa-b253-c34484e0d5e4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24670, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "认", "is_correct": true, "explanation": "认 rèn，读第四声，意思是用眼睛辨认。"}, {"text": "人", "is_correct": false, "explanation": "rén 与 rèn 声调不同（第二声与第四声），意思是人。"}, {"text": "忍", "is_correct": false, "explanation": "rěn 与 rèn 声调不同（第三声与第四声），意思是忍耐。"}, {"text": "润", "is_correct": false, "explanation": "rùn 与 rèn 韵母不同（-un 与 -en），意思是滋润。"}], "explanations": {"认": "认 rèn，读第四声，意思是用眼睛辨认。", "人": "rén 与 rèn 声调不同（第二声与第四声），意思是人。", "忍": "rěn 与 rèn 声调不同（第三声与第四声），意思是忍耐。", "润": "rùn 与 rèn 韵母不同（-un 与 -en），意思是滋润。"}, "sentence_index": null, "correct_answer": "认"}, "level_3": {"options": [{"text": "认", "is_correct": true, "explanation": "“认”表示辨认，“这个字我不会认，你来读一下”语境相符。"}, {"text": "画", "is_correct": false, "explanation": "语义：“不画”与“你来读一下”的语境不符，“画”不能用来指字的辨认。"}, {"text": "喝", "is_correct": false, "explanation": "语义：“喝”与“字”无关，句意荒谬。"}, {"text": "买", "is_correct": false, "explanation": "搭配：“买”的对象一般是物品，“买字”不能用于此语境。"}], "explanations": {"认": "“认”表示辨认，“这个字我不会认，你来读一下”语境相符。", "画": "语义：“不画”与“你来读一下”的语境不符，“画”不能用来指字的辨认。", "喝": "语义：“喝”与“字”无关，句意荒谬。", "买": "搭配：“买”的对象一般是物品，“买字”不能用于此语境。"}, "sentence_index": 0, "correct_answer": "认"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这篇文章我认懂了，很有道理。", "explanation": "这里应该用〈看懂〉。“认”表示用眼睛辨认事物是什么，不表示理解文章的意思，理解要说“看懂”。"}, {"text": "我昨晚认了两个小时的电影。", "explanation": "这里应该用〈看〉。“认”表示辨认事物是什么，不表示观看；看电影要说“看”。"}, {"text": "这盘菜我认了三天，才慢慢吃完。", "explanation": "这里应该用〈吃〉。“认”表示辨认事物，不表示吃饭或品尝，吃菜要说“吃”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '69f4ea35-59be-4a4b-a754-c6218d71bbb6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24670, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "认", "is_correct": true, "explanation": "“认”表示辨认，与“小孩三岁就会认颜色”的语境相符。"}, {"text": "穿", "is_correct": false, "explanation": "搭配：“穿”的对象是衣服，“穿颜色”不能说。"}, {"text": "吃", "is_correct": false, "explanation": "语义：“吃颜色”不符合常识，与句意不符。"}, {"text": "挂", "is_correct": false, "explanation": "搭配：“挂”的对象是物品，“挂颜色”不能说。"}], "explanations": {"认": "“认”表示辨认，与“小孩三岁就会认颜色”的语境相符。", "穿": "搭配：“穿”的对象是衣服，“穿颜色”不能说。", "吃": "语义：“吃颜色”不符合常识，与句意不符。", "挂": "搭配：“挂”的对象是物品，“挂颜色”不能说。"}, "sentence_index": 6, "correct_answer": "认"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这瓶酒的颜色很特别，我一眼就认了它的味道。", "explanation": "这里应该用〈闻〉。“认”表示看后辨认，不表示用鼻子闻味道，闻味道要说“闻”。"}, {"text": "这张卡的颜色很特别，我一眼就认了它的价格。", "explanation": "这里应该用〈知道〉。“认”表示辨认具体事物是什么，价格不是可以辨认的实物，应说“知道”它的价格。"}, {"text": "这张卡的颜色很特别，我一眼就认了它的重量。", "explanation": "这里应该用〈称〉。“认”表示看后辨认，不表示测量重量，称重量要说“称”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '69f4ea35-59be-4a4b-a754-c6218d71bbb6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24670, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "昨天在街上，我一眼就认着了他。", "corrected_sentence": "昨天在街上，我一眼就认出了他。", "error_description": "补语用错：表示辨认成功要用结果补语“出”，说“认出了他”；“着”表示持续，不能用在“认”后表示认出的结果。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '69f4ea35-59be-4a4b-a754-c6218d71bbb6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24670, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我一眼就出认了那张照片上的人。", "corrected_sentence": "我一眼就认出了那张照片上的人。", "error_description": "词序错误：“认出”是动补结构，补语“出”必须紧跟“认”，不能说“出认”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '69f4ea35-59be-4a4b-a754-c6218d71bbb6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
