INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24672, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'deebcdfc-2623-4b3b-a262-1127910088b2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24672, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "重要性说的是一个东西有多么重要。", "primary_collocate": null, "pronunciation": "zhòng yào xìng", "ipa": "ʈʂʊŋ˥˩ jɑʊ˥˩ ɕiŋ˥˩", "syllable_count": 3, "sentences": [{"text": "这件事的重要性，你一定要记住。", "target_word": "重要性", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "健康的重要性，每个人都应该明白。", "target_word": "重要性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你们每个人都知道水的重要性。", "target_word": "重要性", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我不懂这个工作的重要性。", "target_word": "重要性", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "妈妈常说吃饭的重要性。", "target_word": "重要性", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "他的话让我看到朋友的重要性。", "target_word": "重要性", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "你能说说这个问题的重要性吗？", "target_word": "重要性", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "每个人都说安全的重要性很大。", "target_word": "重要性", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "请先想一想每件事的重要性。", "target_word": "重要性", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我们要把时间的重要性告诉孩子。", "target_word": "重要性", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "重要性：一个东西有多么重要", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6b6dab98-14d7-4430-bd0f-b102915e1fde') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24672, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "重要性", "is_correct": true, "explanation": "正确：“这件事的重要性”指它的价值，句意是要记住这一点。"}, {"text": "颜色", "is_correct": false, "explanation": "语义：“颜色”指事物的色彩，与“这件事”不搭。"}, {"text": "速度", "is_correct": false, "explanation": "搭配：“速度”说快慢，不能用来要求一件事“一定要记住”。"}, {"text": "形状", "is_correct": false, "explanation": "语义：“形状”指外形，不能指一件事的价值。"}], "explanations": {"重要性": "正确：“这件事的重要性”指它的价值，句意是要记住这一点。", "颜色": "语义：“颜色”指事物的色彩，与“这件事”不搭。", "速度": "搭配：“速度”说快慢，不能用来要求一件事“一定要记住”。", "形状": "语义：“形状”指外形，不能指一件事的价值。"}, "sentence_index": 0, "correct_answer": "重要性"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这次检查的重要性很便宜。", "explanation": "这里应该用〈高〉。“便宜”说价钱，不能用来形容“重要性”；“重要性”说程度，应说“很高”。"}, {"text": "这句话的重要性很深。", "explanation": "这里应该用〈意义〉。“深”形容意义，不形容“重要性”，这句话要说“意义很深”。"}, {"text": "这件礼物的重要性很甜，我很喜欢。", "explanation": "这里应该用〈大〉。“甜”说味道，不能用来形容“重要性”；“重要性”说程度，应说“很大”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'deebcdfc-2623-4b3b-a262-1127910088b2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24672, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "重要性", "is_correct": true, "explanation": "正确：“这个问题的重要性”指它有多重要，符合“说说”的语境。"}, {"text": "体重", "is_correct": false, "explanation": "语义：“体重”指人或动物的重量，不能用于问题。"}, {"text": "味道", "is_correct": false, "explanation": "语义：“味道”指饮食的感受，不能用于问题。"}, {"text": "速度", "is_correct": false, "explanation": "搭配：“速度”说快慢，不能说“这个问题的速度”。"}], "explanations": {"重要性": "正确：“这个问题的重要性”指它有多重要，符合“说说”的语境。", "体重": "语义：“体重”指人或动物的重量，不能用于问题。", "味道": "语义：“味道”指饮食的感受，不能用于问题。", "速度": "搭配：“速度”说快慢，不能说“这个问题的速度”。"}, "sentence_index": 6, "correct_answer": "重要性"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我的弟弟是家里的重要性。", "explanation": "这里不能指人。〈重要性〉是抽象的程度，不能用“是”把人说成它。"}, {"text": "那只狗是我们家的重要性。", "explanation": "这里不能指动物。〈重要性〉是抽象的程度，不能用来指一只狗。"}, {"text": "这辆自行车是我们家的重要性。", "explanation": "这里不能指具体物品。〈重要性〉是抽象的程度，不能用“是”来指一辆自行车。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'deebcdfc-2623-4b3b-a262-1127910088b2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24672, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "水重要性很大，大家都要明白。", "corrected_sentence": "水的重要性很大，大家都要明白。", "error_description": "结构助词错误：“水”与“重要性”之间要用“的”，应说“水的重要性”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'deebcdfc-2623-4b3b-a262-1127910088b2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24672, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这个问题很重要性，你能说说吗？", "corrected_sentence": "这个问题很重要，你能说说吗？", "error_description": "词性错误：“重要性”是名词，不能受“很”修饰，应用形容词“重要”，说“很重要”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'deebcdfc-2623-4b3b-a262-1127910088b2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24674, 1, 'llm_types_A', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0d4c3f44-8c4f-4a9e-a931-44df4946c2a0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24674, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0d4c3f44-8c4f-4a9e-a931-44df4946c2a0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24674, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "告诉别人要小心或者注意。", "primary_collocate": null, "pronunciation": "tí xǐng", "ipa": "tʰi˨˦ ɕiŋ˨˩˦", "syllable_count": 2, "sentences": [{"text": "妈妈提醒我带伞。", "target_word": "提醒", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "请你明天提醒我给他打电话。", "target_word": "提醒", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "手机每天提醒我吃药。", "target_word": "提醒", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "老师提醒大家，明天要考试。", "target_word": "提醒", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "谢谢你提醒我，我差点忘了。", "target_word": "提醒", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他提醒过我，路上要小心。", "target_word": "提醒", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "开会前，请提醒我一下。", "target_word": "提醒", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "闹钟响了，提醒我该起床了。", "target_word": "提醒", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我提醒他别忘了带钥匙。", "target_word": "提醒", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "出门前，爸爸提醒我关好门窗。", "target_word": "提醒", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "提醒了", "label": "完成体"}, {"form": "提醒过", "label": "经验体"}, {"form": "提醒一下", "label": "动量短时"}], "register": "中性", "sense_fingerprint": "对人说话，使其注意某事或不要忘记", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9d72c37e-001c-46ce-9b8e-ae187f9ffc54') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24674, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "提醒", "is_correct": true, "explanation": "正确答案。“提醒”tí xǐng 指让对方注意或不要忘记。"}, {"text": "题型", "is_correct": false, "explanation": "xíng（第二声）与 xǐng（第三声）声调不同，意思是题目的类型。"}, {"text": "体型", "is_correct": false, "explanation": "tǐ 与 tí、xíng 与 xǐng 的声调都不同，意思是身材的样子。"}, {"text": "梯形", "is_correct": false, "explanation": "tī 与 tí、xíng 与 xǐng 的声调都不同，意思是梯形。"}, {"text": "提请", "is_correct": false, "explanation": "qǐng 与 xǐng 声母不同（q 与 x），意思是向上级提出请求。"}], "explanations": {"提醒": "正确答案。“提醒”tí xǐng 指让对方注意或不要忘记。", "题型": "xíng（第二声）与 xǐng（第三声）声调不同，意思是题目的类型。", "体型": "tǐ 与 tí、xíng 与 xǐng 的声调都不同，意思是身材的样子。", "梯形": "tī 与 tí、xíng 与 xǐng 的声调都不同，意思是梯形。", "提请": "qǐng 与 xǐng 声母不同（q 与 x），意思是向上级提出请求。"}, "sentence_index": null, "correct_answer": "提醒"}, "level_3": {"options": [{"text": "提醒", "is_correct": true, "explanation": "“提醒”表示让对方注意，与“妈妈……我带伞”的关切语境相符，是唯一合适的选项。"}, {"text": "品尝", "is_correct": false, "explanation": "配价：“品尝”的宾语是食物，不能接“我带伞”这样的小句。"}, {"text": "忘记", "is_correct": false, "explanation": "语义：“忘记”表示忘掉某事，“妈妈忘记我带伞”与提醒的语境不符。"}, {"text": "发明", "is_correct": false, "explanation": "配价：“发明”的宾语应是被创造出来的事物，不能接“我带伞”这样的小句。"}], "explanations": {"提醒": "“提醒”表示让对方注意，与“妈妈……我带伞”的关切语境相符，是唯一合适的选项。", "品尝": "配价：“品尝”的宾语是食物，不能接“我带伞”这样的小句。", "忘记": "语义：“忘记”表示忘掉某事，“妈妈忘记我带伞”与提醒的语境不符。", "发明": "配价：“发明”的宾语应是被创造出来的事物，不能接“我带伞”这样的小句。"}, "sentence_index": 0, "correct_answer": "提醒"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我提醒他一个秘密。", "explanation": "这里是把对方不知道的事说出来，应该用〈告诉〉。“提醒”是让对方注意或别忘记某事，不带“秘密”这样的新信息作宾语。"}, {"text": "老师提醒我们一个问题，我们都回答了。", "explanation": "这里是提出问题让人回答，应该用〈问〉。“提醒”是让对方注意或别忘记，不用于发问。"}, {"text": "我提醒他生日快乐。", "explanation": "这里是送祝福，应该用〈祝〉。“提醒”是让对方注意某事，不能用来表示祝福。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0d4c3f44-8c4f-4a9e-a931-44df4946c2a0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24674, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "提醒", "is_correct": true, "explanation": "“提醒”表示请对方注意某事，与“开会前，请……我一下”的礼貌请求相符，是唯一合适的选项。"}, {"text": "感谢", "is_correct": false, "explanation": "语义：“感谢”是对他人帮助表示谢意，请别人感谢说话人与语境不符。"}, {"text": "指责", "is_correct": false, "explanation": "语域：“指责”语气严厉，与“请……一下”的礼貌请求不协调。"}, {"text": "威胁", "is_correct": false, "explanation": "语义：“威胁”是以恶果相逼，与“开会前，请……我一下”的请求语境不符。"}], "explanations": {"提醒": "“提醒”表示请对方注意某事，与“开会前，请……我一下”的礼貌请求相符，是唯一合适的选项。", "感谢": "语义：“感谢”是对他人帮助表示谢意，请别人感谢说话人与语境不符。", "指责": "语域：“指责”语气严厉，与“请……一下”的礼貌请求不协调。", "威胁": "语义：“威胁”是以恶果相逼，与“开会前，请……我一下”的请求语境不符。"}, "sentence_index": 6, "correct_answer": "提醒"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "同学们提醒他个子矮。", "explanation": "这里是讥笑对方，应该用〈嘲笑〉。“提醒”是善意地让对方注意，不含讥讽。"}, {"text": "我提醒了他一份礼物。", "explanation": "这里是把东西交给别人，应该用〈送〉。“提醒”不能带“礼物”这样的物品作宾语表示给予。"}, {"text": "他提醒我的眼睛很大。", "explanation": "这里是称赞对方，应该用〈夸〉。“提醒”是让对方注意某事，不含称赞的意思。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0d4c3f44-8c4f-4a9e-a931-44df4946c2a0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24674, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "老师提醒我们一趟。", "corrected_sentence": "老师提醒我们一次。", "error_description": "错误：“提醒我们一趟”，“趟”指往返的行程，提醒的次数应用“次”。正确：“提醒我们一次”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0d4c3f44-8c4f-4a9e-a931-44df4946c2a0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24674, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他提醒我了三次。", "corrected_sentence": "他提醒了我三次。", "error_description": "错误：“了”放在了宾语“我”后面，应紧跟动词，说“提醒了我”。“了”是动词的体标记，不能放在宾语之后。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0d4c3f44-8c4f-4a9e-a931-44df4946c2a0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
