INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24676, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '69f4ea35-59be-4a4b-a754-c6218d71bbb6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24676, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "金属罐是一个用铁或铝做成的圆筒，可以装饮料或食物。", "primary_collocate": null, "pronunciation": "jīn shǔ guàn", "ipa": "tɕin˥˥ ʂu˨˩˦ kuan˥˩", "syllable_count": 3, "sentences": [{"text": "妈妈买了一个金属罐，用来装糖。", "target_word": "金属罐", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "金属罐可以装饮料，也可以装食物。", "target_word": "金属罐", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他把喝完的金属罐压扁了。", "target_word": "金属罐", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "桌子上放着一个红色的金属罐。", "target_word": "金属罐", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个金属罐的盖子打不开了。", "target_word": "金属罐", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "金属罐是用铁或铝做的。", "target_word": "金属罐", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们把金属罐洗干净，再放进回收桶。", "target_word": "金属罐", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "厨房的架子上有三个金属罐。", "target_word": "金属罐", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "金属罐掉在地上，发出很大的声音。", "target_word": "金属罐", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他在金属罐里种了一株小花。", "target_word": "金属罐", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "个", "label": "量词"}, {"form": "金屬罐", "label": "繁体"}], "register": "通用", "sense_fingerprint": "用铁或铝做成的圆筒，用来装饮料或食物", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6a1fb72f-7f26-46aa-b253-c34484e0d5e4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24676, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "金属罐", "is_correct": true, "explanation": "正确：金属罐是可以装东西的容器，能用来装糖。"}, {"text": "手表", "is_correct": false, "explanation": "语义：手表是计时的物件，不能用来装糖，与“用来装糖”冲突。"}, {"text": "台灯", "is_correct": false, "explanation": "搭配：“装”需要容器，台灯不是容器，不能说“用来装糖”。"}, {"text": "玩具", "is_correct": false, "explanation": "语义：玩具用来玩耍，不是用来装糖的器具，与后半句不符。"}], "explanations": {"金属罐": "正确：金属罐是可以装东西的容器，能用来装糖。", "手表": "语义：手表是计时的物件，不能用来装糖，与“用来装糖”冲突。", "台灯": "搭配：“装”需要容器，台灯不是容器，不能说“用来装糖”。", "玩具": "语义：玩具用来玩耍，不是用来装糖的器具，与后半句不符。"}, "sentence_index": 0, "correct_answer": "金属罐"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "妈妈透过金属罐看见了里面的糖。", "explanation": "这里应该用〈玻璃罐〉。玻璃罐透明，能透过它看见里面的东西；金属罐不透明，看不见里面的糖。"}, {"text": "他一口咬碎了金属罐，吞了下去。", "explanation": "这里应该用〈饼干〉。咬碎后吞下的是食物；金属罐是硬质圆筒，咬不碎，也不能吞下。"}, {"text": "水从金属罐里一直流过去。", "explanation": "这里应该用〈金属管〉。金属管两端相通，水能流过；金属罐是封闭的圆筒，水不能从中穿过。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '69f4ea35-59be-4a4b-a754-c6218d71bbb6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24676, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "金属罐", "is_correct": true, "explanation": "正确：金属罐体积小，洗干净后可以放进回收桶。"}, {"text": "冰箱", "is_correct": false, "explanation": "语义：冰箱体积太大，放不进回收桶，与后半句冲突。"}, {"text": "沙发", "is_correct": false, "explanation": "语义：沙发体积太大，即使洗干净也放不进回收桶，与“再放进回收桶”不符。"}, {"text": "书桌", "is_correct": false, "explanation": "搭配：“放进回收桶”要求物品能装进桶中，书桌不能放进回收桶。"}], "explanations": {"金属罐": "正确：金属罐体积小，洗干净后可以放进回收桶。", "冰箱": "语义：冰箱体积太大，放不进回收桶，与后半句冲突。", "沙发": "语义：沙发体积太大，即使洗干净也放不进回收桶，与“再放进回收桶”不符。", "书桌": "搭配：“放进回收桶”要求物品能装进桶中，书桌不能放进回收桶。"}, "sentence_index": 6, "correct_answer": "金属罐"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他骑着金属罐去上学。", "explanation": "这里应该用〈自行车〉。骑的是车；金属罐是装饮料或食物的圆筒，不能骑。"}, {"text": "金属罐把炉子里的烟排到了屋外。", "explanation": "这里应该用〈烟囱〉。烟囱专门排出烟气；金属罐不起排烟的作用。"}, {"text": "这个金属罐是用来接收信件的。", "explanation": "这里应该用〈信箱〉。信箱用来收信；金属罐是装饮料或食物的容器，不能用来收信。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '69f4ea35-59be-4a4b-a754-c6218d71bbb6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24676, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他买了两张金属罐，准备装饮料。", "corrected_sentence": "他买了两个金属罐，准备装饮料。", "error_description": "量词用错：“金属罐”应搭配量词“个”，“张”用于纸张、桌子等扁平物，应说“两个金属罐”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '69f4ea35-59be-4a4b-a754-c6218d71bbb6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24676, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "妈妈把一条金属罐放进了柜子里。", "corrected_sentence": "妈妈把一个金属罐放进了柜子里。", "error_description": "量词用错：金属罐是圆筒形容器，应用“个”；“条”用于细长的物体，不能计量金属罐。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '69f4ea35-59be-4a4b-a754-c6218d71bbb6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
