INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24692, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "事物产生的根源或来历。", "primary_collocate": null, "pronunciation": "qǐ yuán", "ipa": "tɕʰi˨˩˦ ɥɛn˧˥", "syllable_count": 2, "sentences": [{"text": "你知道端午节的起源吗？", "target_word": "起源", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个游戏的起源要追溯到几百年前。", "target_word": "起源", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他喜欢查各种东西的起源。", "target_word": "起源", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我想了解中国功夫的起源。", "target_word": "起源", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这座城市的起源可以追溯到一千年前。", "target_word": "起源", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个姓的起源是什么？大家都很想知道。", "target_word": "起源", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子问我，月饼的起源是什么。", "target_word": "起源", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "每种文化都有自己的起源。", "target_word": "起源", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这本书讲的是语言的起源。", "target_word": "起源", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "要了解一件事，先看它的起源。", "target_word": "起源", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "事物产生的根源或来历", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8c5d266d-7f63-4cac-bf36-2351f9160e06') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24692, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "起源", "is_correct": true, "explanation": "起源（qǐ yuán）指事物发生的源头或开始，是本题的正确答案。"}, {"text": "奇缘", "is_correct": false, "explanation": "qí（第二声）与 qǐ（第三声）声调不同，意思是奇妙的缘分，与起源不同。"}, {"text": "祈愿", "is_correct": false, "explanation": "祈愿（qíyuàn）的两个音节声调都与起源不同，意思是祈祷和希望。"}, {"text": "气源", "is_correct": false, "explanation": "qì（第四声）与 qǐ（第三声）声调不同，意思是气体的来源。"}], "explanations": {"起源": "起源（qǐ yuán）指事物发生的源头或开始，是本题的正确答案。", "奇缘": "qí（第二声）与 qǐ（第三声）声调不同，意思是奇妙的缘分，与起源不同。", "祈愿": "祈愿（qíyuàn）的两个音节声调都与起源不同，意思是祈祷和希望。", "气源": "qì（第四声）与 qǐ（第三声）声调不同，意思是气体的来源。"}, "sentence_index": null, "correct_answer": "起源"}, "level_3": {"options": [{"text": "起源", "is_correct": true, "explanation": "起源指事物最初的发生，能与“端午节的”搭配，并符合“你知道……吗”的问句，填入此处正确。"}, {"text": "身高", "is_correct": false, "explanation": "体貌：“身高”只用于人，不能说“端午节的身高”。"}, {"text": "脾气", "is_correct": false, "explanation": "语义：“脾气”指人的性情，节日没有脾气，句子不通。"}, {"text": "尺寸", "is_correct": false, "explanation": "语义：节日没有尺寸，“端午节的尺寸”无法理解。"}], "explanations": {"起源": "起源指事物最初的发生，能与“端午节的”搭配，并符合“你知道……吗”的问句，填入此处正确。", "身高": "体貌：“身高”只用于人，不能说“端午节的身高”。", "脾气": "语义：“脾气”指人的性情，节日没有脾气，句子不通。", "尺寸": "语义：节日没有尺寸，“端午节的尺寸”无法理解。"}, "sentence_index": 0, "correct_answer": "起源"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "那次登山是我人生中最难忘的起源。", "explanation": "这里应该用〈经历〉。“起源”指事物最初的来源，不指亲身遭遇的事，“最难忘的”应搭配“经历”。"}, {"text": "他每月的起源很稳定。", "explanation": "这里应该用〈收入〉。“每月”和“稳定”描述的是收入，“起源”不能按月计算，也不能说稳定。"}, {"text": "他的辛苦终于换来了好的起源。", "explanation": "这里应该用〈结果〉。“换来”的是收获或结果，“起源”指最开始的阶段，不能用来换取。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3a0a4231-0e50-42c7-9177-91d0248c52a9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24692, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "起源", "is_correct": true, "explanation": "起源指事物最初的来历，“月饼的”后接“是什么”，问的是来历，填入此处正确。"}, {"text": "学历", "is_correct": false, "explanation": "配价：“学历”需要有人作为持有者，不能用于“月饼”。"}, {"text": "体重", "is_correct": false, "explanation": "体貌：“体重”只用于人或动物，不能说“月饼的体重是什么”。"}, {"text": "性格", "is_correct": false, "explanation": "语义：“性格”指人或动物的个性，月饼没有性格，句子不通。"}], "explanations": {"起源": "起源指事物最初的来历，“月饼的”后接“是什么”，问的是来历，填入此处正确。", "学历": "配价：“学历”需要有人作为持有者，不能用于“月饼”。", "体重": "体貌：“体重”只用于人或动物，不能说“月饼的体重是什么”。", "性格": "语义：“性格”指人或动物的个性，月饼没有性格，句子不通。"}, "sentence_index": 6, "correct_answer": "起源"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这件大衣的起源很便宜。", "explanation": "这里应该用〈价格〉。“便宜”描述价格，“起源”指事物的源头，不能说便宜。"}, {"text": "这台冰箱的起源很高。", "explanation": "这里应该用〈高度〉。“很高”说的是物体的高矮，“起源”指事物的源头或开始，不能用来说高矮。"}, {"text": "这个孩子的起源有一米八。", "explanation": "这里应该用〈身高〉。“有一米八”说的是人的身高，“起源”指事物的源头或开始，不能用来说身高。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3a0a4231-0e50-42c7-9177-91d0248c52a9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24692, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这个节日的一把起源可以追溯到古代。", "corrected_sentence": "这个节日的起源可以追溯到古代。", "error_description": "量词错误：“把”用于有柄、可以握持的东西，不能用来数“起源”这样的抽象名词；应说“这个节日的起源”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3a0a4231-0e50-42c7-9177-91d0248c52a9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24692, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这首歌的一张起源和一个雨天有关。", "corrected_sentence": "这首歌的起源和一个雨天有关。", "error_description": "量词错误：“张”用于纸、桌子等有平面的东西，不能用来数“起源”这样的抽象名词；应说“这首歌的起源和一个雨天有关”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3a0a4231-0e50-42c7-9177-91d0248c52a9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
