INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24694, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "可以往回找到来源。", "primary_collocate": null, "pronunciation": "kě zhuī sù", "ipa": "kʰɤ˨˩˦ ʈʂweɪ˥ su˥˩", "syllable_count": 3, "sentences": [{"text": "这家店的牛奶来源清楚，每瓶都可追溯。", "target_word": "可追溯", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "超市里的蔬菜都是可追溯的。", "target_word": "可追溯", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这批药品的生产过程完全可追溯。", "target_word": "可追溯", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这些文件都有日期，所以历史可追溯。", "target_word": "可追溯", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们要让每一件产品都可追溯。", "target_word": "可追溯", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "银行的每笔钱都必须可追溯。", "target_word": "可追溯", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这张照片的来源可追溯，拍摄时间和地点都有记录。", "target_word": "可追溯", "complexity_tier": "T3", "furigana": "zhè zhāng zhào piàn de lái yuán kě zhuī sù, pāi shè shí jiān hé dì diǎn dōu yǒu jì lù.", "sentence_source": "generated"}, {"text": "医院的每份血液记录都是可追溯的。", "target_word": "可追溯", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小明买的大米有二维码，来源可追溯。", "target_word": "可追溯", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这条新闻的消息来源完全可追溯。", "target_word": "可追溯", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "可追溯性", "label": "复合"}, {"form": "不可追溯", "label": "否定"}], "register": "书面", "sense_fingerprint": "产品、记录、资金等的来源或过程能够往回查到", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bf9d64f7-d6db-410b-8410-52799dc0c108') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24694, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "可追溯", "is_correct": true, "explanation": "正确：可追溯指来源或过程能够往回查到，与“来源清楚”相符。"}, {"text": "模糊", "is_correct": false, "explanation": "语义：模糊表示不清楚，与前句“来源清楚”直接矛盾。"}, {"text": "陌生", "is_correct": false, "explanation": "搭配：陌生多形容人或地方，不用来描述瓶子的来源。"}, {"text": "隐秘", "is_correct": false, "explanation": "语义：隐秘表示不公开、难以察觉，与“来源清楚”的语境相反。"}], "explanations": {"可追溯": "正确：可追溯指来源或过程能够往回查到，与“来源清楚”相符。", "模糊": "语义：模糊表示不清楚，与前句“来源清楚”直接矛盾。", "陌生": "搭配：陌生多形容人或地方，不用来描述瓶子的来源。", "隐秘": "语义：隐秘表示不公开、难以察觉，与“来源清楚”的语境相反。"}, "sentence_index": 0, "correct_answer": "可追溯"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这条路的宽度可追溯。", "explanation": "这里应该用〈可测量〉。宽度是可以测量的数值，可追溯指往回找到来源，不适用于此。"}, {"text": "明天的天气可追溯。", "explanation": "这里应该用〈可预报〉。可追溯指往回找到来源，不指还没发生的天气变化。"}, {"text": "今晚的月亮可追溯。", "explanation": "这里应该用〈可欣赏〉。可追溯指能查到来源或过程，不指月亮能否被欣赏。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '99a869e5-d7c6-4cee-bf7b-58b3f659b231') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24694, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "可追溯", "is_correct": true, "explanation": "正确：可追溯指来源能够查到，与“拍摄时间和地点都有记录”相符。"}, {"text": "短暂", "is_correct": false, "explanation": "搭配：短暂多用于时间、生命，不用来描述来源。"}, {"text": "轻盈", "is_correct": false, "explanation": "搭配：轻盈多形容动作、身体，不用来描述来源。"}, {"text": "鲜红", "is_correct": false, "explanation": "体貌：鲜红描写颜色，不能用来形容照片的来源。"}], "explanations": {"可追溯": "正确：可追溯指来源能够查到，与“拍摄时间和地点都有记录”相符。", "短暂": "搭配：短暂多用于时间、生命，不用来描述来源。", "轻盈": "搭配：轻盈多形容动作、身体，不用来描述来源。", "鲜红": "体貌：鲜红描写颜色，不能用来形容照片的来源。"}, "sentence_index": 6, "correct_answer": "可追溯"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这段路很长，可追溯。", "explanation": "这里应该用〈可通行〉。可追溯指能查到来源或过程，不指道路能否供人通过。"}, {"text": "这个孩子很聪明，可追溯。", "explanation": "这里应该用〈可教导〉。可追溯指能查到来源或原因，不用来说人能否被教导。"}, {"text": "这块蛋糕的甜度可追溯。", "explanation": "这里应该用〈可检测〉。甜度是可以检测的指标，可追溯指往回找到来源，不适用于此。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '99a869e5-d7c6-4cee-bf7b-58b3f659b231') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24694, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这批化肥的来源可追溯在厂家。", "corrected_sentence": "这批化肥的来源可追溯到厂家。", "error_description": "错误：指向来源对象时应用“到”，“在”不能接在“可追溯”后。正确形式为“可追溯到厂家”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '99a869e5-d7c6-4cee-bf7b-58b3f659b231') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24694, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这箱牛奶的来源可追溯了到牧场。", "corrected_sentence": "这箱牛奶的来源可追溯到牧场。", "error_description": "错误：“了”插在“可追溯”与补语“到牧场”之间。正确形式为“可追溯到牧场”，“了”不能夹在动词与补语之间。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '99a869e5-d7c6-4cee-bf7b-58b3f659b231') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
