INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24696, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "非常想要得到某样东西或做某件事。", "primary_collocate": null, "pronunciation": "kě wàng", "ipa": "kʰɤ˨˩˦ wɑŋ˥˩", "syllable_count": 2, "sentences": [{"text": "饿了一天，他渴望吃一碗热面。", "target_word": "渴望", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "弟弟渴望有一只小狗。", "target_word": "渴望", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我渴望再见到老朋友。", "target_word": "渴望", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "在外地工作的人，渴望回家过年。", "target_word": "渴望", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她渴望学会游泳，所以天天去练习。", "target_word": "渴望", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他非常渴望拥有一部新手机，但是妈妈不同意。", "target_word": "渴望", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "学生们渴望参加这次比赛。", "target_word": "渴望", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我渴望着周末快点到来。", "target_word": "渴望", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她很渴望一份稳定的工作。", "target_word": "渴望", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小明渴望拿到第一名。", "target_word": "渴望", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "渴望着", "label": "体标"}, {"form": "渴望过", "label": "体标"}], "register": "中性", "sense_fingerprint": "非常想要得到某样东西或做某件事", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8c5d266d-7f63-4cac-bf36-2351f9160e06') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24696, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "修理", "is_correct": false, "explanation": "语义：“修理”是修好器物，不能与“吃一碗热面”搭配。"}, {"text": "打扫", "is_correct": false, "explanation": "搭配：“打扫”的宾语是场地或垃圾，不能接“吃一碗热面”。"}, {"text": "检查", "is_correct": false, "explanation": "语义：“检查”指查看或核对，与“吃一碗热面”的意思不相符。"}, {"text": "渴望", "is_correct": true, "explanation": "正确：渴望表示非常想要得到，这里说饿了一天的人很想吃一碗热面。"}], "explanations": {"修理": "语义：“修理”是修好器物，不能与“吃一碗热面”搭配。", "打扫": "搭配：“打扫”的宾语是场地或垃圾，不能接“吃一碗热面”。", "检查": "语义：“检查”指查看或核对，与“吃一碗热面”的意思不相符。", "渴望": "正确：渴望表示非常想要得到，这里说饿了一天的人很想吃一碗热面。"}, "sentence_index": 0, "correct_answer": "渴望"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "夏天在院子里干活，他渴望极了，直接喝了一大瓶水。", "explanation": "这里应该用〈渴〉。渴望指想得到某样东西，身体缺水要说〈渴〉。"}, {"text": "他很渴望回家，所以一直躲在外面。", "explanation": "这里应该用〈害怕〉。渴望表示想得到，“一直躲在外面”与“渴望回家”矛盾，这里应说〈害怕〉。"}, {"text": "他对黑暗感到渴望，不敢一个人睡。", "explanation": "这里应该用〈恐惧〉。渴望表示想得到，对黑暗的畏惧要说〈恐惧〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3a0a4231-0e50-42c7-9177-91d0248c52a9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24696, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "批评", "is_correct": false, "explanation": "语义：“批评”指指出缺点或错误，不能接“参加这次比赛”作宾语。"}, {"text": "煎", "is_correct": false, "explanation": "搭配：“煎”的宾语应是食物，“参加这次比赛”不能被煎。"}, {"text": "拆", "is_correct": false, "explanation": "语义：“拆”指把组合物分开，与“参加这次比赛”的意思不符。"}, {"text": "渴望", "is_correct": true, "explanation": "正确：渴望表示非常想要做某件事，这里说学生们很想参加这次比赛。"}], "explanations": {"批评": "语义：“批评”指指出缺点或错误，不能接“参加这次比赛”作宾语。", "煎": "搭配：“煎”的宾语应是食物，“参加这次比赛”不能被煎。", "拆": "语义：“拆”指把组合物分开，与“参加这次比赛”的意思不符。", "渴望": "正确：渴望表示非常想要做某件事，这里说学生们很想参加这次比赛。"}, "sentence_index": 6, "correct_answer": "渴望"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他很渴望当初没有努力。", "explanation": "这里应该用〈后悔〉。渴望表示想得到某个目标，对过去的失误要说〈后悔〉。"}, {"text": "她总是渴望责任，从不主动承担。", "explanation": "这里应该用〈逃避〉。渴望是主动追求，躲避责任要说〈逃避〉。"}, {"text": "他总是渴望学习，不愿意开始。", "explanation": "这里应该用〈抗拒〉。渴望是主动想得到，对学习的排斥要说〈抗拒〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3a0a4231-0e50-42c7-9177-91d0248c52a9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24696, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我渴望了吃一顿丰盛的晚饭。", "corrected_sentence": "我渴望吃一顿丰盛的晚饭。", "error_description": "体标错误：“渴望”后不能直接加“了”表示完成，与“想要吃”的未来意思冲突。正确说法：我渴望吃一顿丰盛的晚饭。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3a0a4231-0e50-42c7-9177-91d0248c52a9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24696, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他渴望得早点回家。", "corrected_sentence": "他渴望早点回家。", "error_description": "助词错误：“渴望”后面多加了“得”，应直接接动词或小句。正确说法：他渴望早点回家。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3a0a4231-0e50-42c7-9177-91d0248c52a9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
