INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24698, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "图腾是一个动物或东西，代表一群人。", "primary_collocate": null, "pronunciation": "tú téng", "ipa": "tʰu˧˥ tʰɤŋ˧˥", "syllable_count": 2, "sentences": [{"text": "这个队的图腾是一只老虎。", "target_word": "图腾", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们的图腾是一条龙，代表整个民族。", "target_word": "图腾", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个部落的人都爱他们的图腾。", "target_word": "图腾", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老鹰是这群人的图腾，代表自由。", "target_word": "图腾", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你们家族有自己的图腾吗？", "target_word": "图腾", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "狼是他们的图腾，所以他们不吃狼肉。", "target_word": "图腾", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个村子的图腾是一棵大树。", "target_word": "图腾", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们把熊当作自己的图腾。", "target_word": "图腾", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "看到图腾，我就知道他们是哪个部落的人。", "target_word": "图腾", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子们在墙上画了自己班的图腾。", "target_word": "图腾", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "个", "label": "量词"}, {"form": "圖騰", "label": "繁体"}], "register": "中性", "sense_fingerprint": "代表一群人的动物或东西", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8c5d266d-7f63-4cac-bf36-2351f9160e06') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24698, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "账单", "is_correct": false, "explanation": "语义：“账单”是付款清单，不能代表一群人，与“是一只老虎”也不符。"}, {"text": "成绩", "is_correct": false, "explanation": "搭配：“成绩”不能与“是一只老虎”这类动物名词组成判断句。"}, {"text": "镜子", "is_correct": false, "explanation": "语义：“镜子”是照人的器具，不是代表一群人的标志，与“是一只老虎”也相矛盾。"}, {"text": "图腾", "is_correct": true, "explanation": "正确：图腾指代表一群人的动物或东西，这里说这个队的图腾是老虎。"}], "explanations": {"账单": "语义：“账单”是付款清单，不能代表一群人，与“是一只老虎”也不符。", "成绩": "搭配：“成绩”不能与“是一只老虎”这类动物名词组成判断句。", "镜子": "语义：“镜子”是照人的器具，不是代表一群人的标志，与“是一只老虎”也相矛盾。", "图腾": "正确：图腾指代表一群人的动物或东西，这里说这个队的图腾是老虎。"}, "sentence_index": 0, "correct_answer": "图腾"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "手机屏幕上的图腾很多，我找了半天。", "explanation": "这里应该用〈图标〉。图腾是群体尊奉的象征，手机屏幕上的应用图标要说〈图标〉。"}, {"text": "这家饮料店的菜单上写着各种图腾。", "explanation": "这里应该用〈饮品〉。图腾是群体的标志和象征，菜单上列出的可以喝的东西要说〈饮品〉。"}, {"text": "她每天早上都用这个图腾喝牛奶。", "explanation": "这里应该用〈杯子〉。图腾是群体的象征，不是盛液体的器具，喝牛奶要用〈杯子〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3a0a4231-0e50-42c7-9177-91d0248c52a9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24698, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "课本", "is_correct": false, "explanation": "语义：“课本”是教学用书，不是一棵大树，也不能代表一个村子的标志。"}, {"text": "手套", "is_correct": false, "explanation": "语义：“手套”是戴在手上的东西，不能代表一个村子的人，“村子的手套是一棵大树”说不通。"}, {"text": "病历", "is_correct": false, "explanation": "语义：“病历”是医院的病情记录，与“村子的图腾”毫不相关。"}, {"text": "图腾", "is_correct": true, "explanation": "正确：图腾指代表一群人的动物或东西，这里说村子的图腾是一棵大树。"}], "explanations": {"课本": "语义：“课本”是教学用书，不是一棵大树，也不能代表一个村子的标志。", "手套": "语义：“手套”是戴在手上的东西，不能代表一个村子的人，“村子的手套是一棵大树”说不通。", "病历": "语义：“病历”是医院的病情记录，与“村子的图腾”毫不相关。", "图腾": "正确：图腾指代表一群人的动物或东西，这里说村子的图腾是一棵大树。"}, "sentence_index": 6, "correct_answer": "图腾"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "天冷了，我戴上了新买的图腾。", "explanation": "这里应该用〈帽子〉。图腾是代表一群人的动物或东西，不是戴在头上的衣物。"}, {"text": "我在图腾上看到了明天的天气。", "explanation": "这里应该用〈手机〉。图腾是群体的象征，不能用来查看天气信息。"}, {"text": "医生给我开了一个图腾，让我每天吃三次。", "explanation": "这里应该用〈药方〉。图腾是代表一群人的象征，不是医生开的药。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3a0a4231-0e50-42c7-9177-91d0248c52a9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24698, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我们班有一只图腾，是一只海豚。", "corrected_sentence": "我们班有一个图腾，是一只海豚。", "error_description": "量词错误：“图腾”前应用量词“个”，不能说“一只”（“只”多用于动物）。正确说法：我们班有一个图腾，是一只海豚。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3a0a4231-0e50-42c7-9177-91d0248c52a9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24698, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "每个班的图腾们都挂在墙上。", "corrected_sentence": "每个班的图腾都挂在墙上。", "error_description": "词尾错误：“图腾”是事物，不加“们”；“们”只用于人或拟人的名词。正确说法：每个班的图腾都挂在墙上。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3a0a4231-0e50-42c7-9177-91d0248c52a9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
