INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24700, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "指新事物顺应时代或社会的需要而产生、出现。", "primary_collocate": null, "pronunciation": "yìng yùn ér shēng", "ipa": "iŋ˥˩ yn˥˩ ɚ˧˥ ʂəŋ˥", "syllable_count": 4, "sentences": [{"text": "人们需要又轻又暖的衣服，新式羽绒服应运而生。", "target_word": "应运而生", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "人们想少排队，自助点餐机应运而生。", "target_word": "应运而生", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "随着网购越来越普及，快递驿站应运而生。", "target_word": "应运而生", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "地铁太挤，错峰上班的办法应运而生。", "target_word": "应运而生", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子们爱看书，小小图书角应运而生。", "target_word": "应运而生", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "大家想听歌，这个音乐软件应运而生。", "target_word": "应运而生", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "河水变脏以后，清洁小组应运而生。", "target_word": "应运而生", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "没有地方停车，新的停车楼应运而生。", "target_word": "应运而生", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老年人越来越多，社区养老站应运而生。", "target_word": "应运而生", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "上网学习的人变多，在线辅导班应运而生。", "target_word": "应运而生", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "书面语", "sense_fingerprint": "新事物顺应时代或社会需要而出现", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bf9d64f7-d6db-410b-8410-52799dc0c108') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24700, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "应运而生", "is_correct": true, "explanation": "正确：应运而生指新事物顺应人们的需要而出现，与“人们需要又轻又暖的衣服”相符。"}, {"text": "退役", "is_correct": false, "explanation": "语义：退役指退出现役、停止使用，与新式羽绒服的出现相矛盾。"}, {"text": "消失", "is_correct": false, "explanation": "语义：消失表示不见了，与人们有需要、新事物出现的语境相反。"}, {"text": "倒闭", "is_correct": false, "explanation": "搭配：倒闭用于企业、店铺，不能用来说羽绒服。"}], "explanations": {"应运而生": "正确：应运而生指新事物顺应人们的需要而出现，与“人们需要又轻又暖的衣服”相符。", "退役": "语义：退役指退出现役、停止使用，与新式羽绒服的出现相矛盾。", "消失": "语义：消失表示不见了，与人们有需要、新事物出现的语境相反。", "倒闭": "搭配：倒闭用于企业、店铺，不能用来说羽绒服。"}, "sentence_index": 0, "correct_answer": "应运而生"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我的弟弟去年冬天应运而生。", "explanation": "这里应该用〈出生〉。应运而生指事物顺应社会需要而出现，人的出生不能这样说。"}, {"text": "昨天城里的一场暴雨应运而生。", "explanation": "这里应该用〈发生〉。应运而生指顺应需要而出现的新事物，偶然的天气现象不能这样说。"}, {"text": "这个问题在上个月应运而生。", "explanation": "这里应该用〈出现〉。应运而生强调顺应需要而出现，问题的出现不是应需要而来。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '99a869e5-d7c6-4cee-bf7b-58b3f659b231') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24700, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "应运而生", "is_correct": true, "explanation": "正确：应运而生指事物顺应需要而出现，与“河水变脏”需要清洁小组的语境相符。"}, {"text": "落幕", "is_correct": false, "explanation": "搭配：落幕用于演出、会议等活动结束，不用于说小组出现。"}, {"text": "熄灭", "is_correct": false, "explanation": "搭配：熄灭用于火、灯等，不能用来说清洁小组。"}, {"text": "失传", "is_correct": false, "explanation": "语义：失传指技艺、传统失去传承，与新组建清洁小组的语境相反。"}], "explanations": {"应运而生": "正确：应运而生指事物顺应需要而出现，与“河水变脏”需要清洁小组的语境相符。", "落幕": "搭配：落幕用于演出、会议等活动结束，不用于说小组出现。", "熄灭": "搭配：熄灭用于火、灯等，不能用来说清洁小组。", "失传": "语义：失传指技艺、传统失去传承，与新组建清洁小组的语境相反。"}, "sentence_index": 6, "correct_answer": "应运而生"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "春天在三月应运而生。", "explanation": "这里应该用〈降临〉。应运而生指顺应需要而出现的事物，季节的到来不是应需要而来。"}, {"text": "这场战争在去年应运而生。", "explanation": "这里应该用〈爆发〉。应运而生指顺应需要而出现的新事物，战争的爆发不能用它来描述。"}, {"text": "他在春节应运而生。", "explanation": "这里应该用〈回来〉。应运而生指事物顺应需要而出现，人回到家不能这样说。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '99a869e5-d7c6-4cee-bf7b-58b3f659b231') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24700, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "雨季来临时，新的雨伞很应运而生。", "corrected_sentence": "雨季来临时，新的雨伞应运而生。", "error_description": "错误：在固定四字格“应运而生”前多加了程度副词“很”，四字格不能被程度副词修饰。正确形式为“应运而生”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '99a869e5-d7c6-4cee-bf7b-58b3f659b231') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24700, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "夜里很多人失眠，助眠的软件很应运而生。", "corrected_sentence": "夜里很多人失眠，助眠的软件应运而生。", "error_description": "错误：在固定四字格“应运而生”前多加了程度副词“很”，四字格不能被程度副词修饰。正确形式为“应运而生”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '99a869e5-d7c6-4cee-bf7b-58b3f659b231') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
