INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24706, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "需要马上做。", "primary_collocate": null, "pronunciation": "jí xū", "ipa": "t͡ɕi˧˥ ɕy˥", "syllable_count": 2, "sentences": [{"text": "孩子发烧了，亟需送医院。", "target_word": "亟需", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个问题亟需处理。", "target_word": "亟需", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "河水太脏了，亟需治理。", "target_word": "亟需", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这座桥很旧，亟需修理。", "target_word": "亟需", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公司亏损严重，亟需改变做法。", "target_word": "亟需", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "现在亟需通知所有的人。", "target_word": "亟需", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "房子漏水了，亟需检查。", "target_word": "亟需", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "病人情况不好，亟需抢救。", "target_word": "亟需", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这些规定亟需修改。", "target_word": "亟需", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "食物快没有了，亟需补充。", "target_word": "亟需", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "书面", "sense_fingerprint": "需要马上去做某事", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8c5d266d-7f63-4cac-bf36-2351f9160e06') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24706, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "研究", "is_correct": false, "explanation": "语义：研究是探讨问题，与“孩子发烧”的紧急情况不符，不能接“送医院”。"}, {"text": "亟需", "is_correct": true, "explanation": "亟需：需要马上做，与“孩子发烧了”的紧急情况相符。"}, {"text": "嘲笑", "is_correct": false, "explanation": "语义：嘲笑是讥笑别人，与发烧后送医院的需要不符。"}, {"text": "喜欢", "is_correct": false, "explanation": "搭配：“喜欢”后接的是对象或爱好，不能接“送医院”这种紧急行动。"}], "explanations": {"研究": "语义：研究是探讨问题，与“孩子发烧”的紧急情况不符，不能接“送医院”。", "亟需": "亟需：需要马上做，与“孩子发烧了”的紧急情况相符。", "嘲笑": "语义：嘲笑是讥笑别人，与发烧后送医院的需要不符。", "喜欢": "搭配：“喜欢”后接的是对象或爱好，不能接“送医院”这种紧急行动。"}, "sentence_index": 0, "correct_answer": "亟需"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这个班级每周都亟需打扫。", "explanation": "这里应该用〈需要〉。亟需表示马上要做，每周例行的打扫不用亟需。"}, {"text": "我亟需天气快点暖和。", "explanation": "这里应该用〈希望〉。亟需的对象应是某种需要，不能接表示愿望的“天气快点暖和”。"}, {"text": "我亟需下个月换工作。", "explanation": "这里应该用〈打算〉。亟需强调马上行动，与“下个月”的计划矛盾。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3a0a4231-0e50-42c7-9177-91d0248c52a9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24706, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "庆祝", "is_correct": false, "explanation": "语义：庆祝是为喜事举行活动，与“房子漏水”的情况不符。"}, {"text": "亟需", "is_correct": true, "explanation": "亟需：需要马上做，“房子漏水了，亟需检查”指漏水需要马上检查。"}, {"text": "欣赏", "is_correct": false, "explanation": "搭配：“欣赏”的对象是作品、景色，不能与“检查”搭配。"}, {"text": "戏弄", "is_correct": false, "explanation": "搭配：“戏弄”的对象是人，不能说“戏弄检查”。"}], "explanations": {"庆祝": "语义：庆祝是为喜事举行活动，与“房子漏水”的情况不符。", "亟需": "亟需：需要马上做，“房子漏水了，亟需检查”指漏水需要马上检查。", "欣赏": "搭配：“欣赏”的对象是作品、景色，不能与“检查”搭配。", "戏弄": "搭配：“戏弄”的对象是人，不能说“戏弄检查”。"}, "sentence_index": 6, "correct_answer": "亟需"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "妈妈每天都亟需我的身体。", "explanation": "这里应该用〈关心〉。亟需表示迫切的需要，不表示牵挂和关怀。"}, {"text": "老师亟需我的请求。", "explanation": "这里应该用〈同意〉。亟需表示迫切的需要，不表示答应请求。"}, {"text": "我们亟需每周去一次公园。", "explanation": "这里应该用〈计划〉。亟需强调马上要做，与“每周”的定期安排矛盾。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3a0a4231-0e50-42c7-9177-91d0248c52a9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24706, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这个机器亟需了维护。", "corrected_sentence": "这个机器亟需维护。", "error_description": "“亟需”后不能加“了”；“亟需”表示现在马上需要，不带“了”。应说“这个机器亟需维护”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3a0a4231-0e50-42c7-9177-91d0248c52a9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24706, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这座房子亟需着修理。", "corrected_sentence": "这座房子亟需修理。", "error_description": "体标错误：“亟需”表示需要马上做，不能加“着”表示持续；应说“这座房子亟需修理”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3a0a4231-0e50-42c7-9177-91d0248c52a9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
