INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24708, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "看出，知道是什么。", "primary_collocate": null, "pronunciation": "shí bié", "ipa": "ʂʅ˧˥ pjɛ˧˥", "syllable_count": 2, "sentences": [{"text": "这个手机可以识别我的脸。", "target_word": "识别", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他一眼就识别出了那张假钱。", "target_word": "识别", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小狗能识别主人的声音。", "target_word": "识别", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "机器人识别不了这句方言。", "target_word": "识别", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "医生很快识别出了这种病。", "target_word": "识别", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你会识别真假钱吗？", "target_word": "识别", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个软件能识别图片里的文字。", "target_word": "识别", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子很小就能识别不同的颜色。", "target_word": "识别", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师教我们识别有毒的蘑菇。", "target_word": "识别", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "门口的机器没识别我的指纹。", "target_word": "识别", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "識別", "label": "繁体"}, {"form": "识别率", "label": "复合"}], "register": "中性", "sense_fingerprint": "辨认出事物或人是什么、是谁", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '80ab50cd-4340-49f3-b7d1-188a43322068') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24708, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "识别", "is_correct": true, "explanation": "原句说手机能认出我的脸，“识别”指辨认出事物是什么、是谁，正合适。"}, {"text": "理解", "is_correct": false, "explanation": "语义：“理解”指懂得意思，与“认出脸”的辨认义不符。"}, {"text": "欣赏", "is_correct": false, "explanation": "语义：“欣赏”需要审美感受，手机不会欣赏我的脸。"}, {"text": "同意", "is_correct": false, "explanation": "搭配：“同意”的对象是意见或请求，不能用于“我的脸”。"}], "explanations": {"识别": "原句说手机能认出我的脸，“识别”指辨认出事物是什么、是谁，正合适。", "理解": "语义：“理解”指懂得意思，与“认出脸”的辨认义不符。", "欣赏": "语义：“欣赏”需要审美感受，手机不会欣赏我的脸。", "同意": "搭配：“同意”的对象是意见或请求，不能用于“我的脸”。"}, "sentence_index": 0, "correct_answer": "识别"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我们要识别一下这个计划能不能做。", "explanation": "这里应该用〈评估〉。“识别”是认出眼前的事物是什么，不是判断计划能不能做，那要用“评估”。"}, {"text": "天气预报识别明天会下雨。", "explanation": "这里应该用〈预测〉。“识别”只用于已经存在的事物，不能用于尚未发生的事，预测天气要用“预测”。"}, {"text": "他识别了这个单词的意思。", "explanation": "这里应该用〈理解〉。“识别”是认出眼前的事物是什么，不能用于懂得单词的意思，应说“理解”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6a064b18-cb72-4871-ba51-bc2dd5ad36d0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24708, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "识别", "is_correct": true, "explanation": "原句说软件能认出图片中的文字，“识别”指辨认事物，正合适。"}, {"text": "歌唱", "is_correct": false, "explanation": "搭配：“歌唱”的对象是歌，不能用于“图片里的文字”。"}, {"text": "拥抱", "is_correct": false, "explanation": "语义：“拥抱”需要有形的身体动作，软件不能拥抱文字。"}, {"text": "散步", "is_correct": false, "explanation": "配价：“散步”是不及物动词，后面不能带“图片里的文字”作宾语。"}], "explanations": {"识别": "原句说软件能认出图片中的文字，“识别”指辨认事物，正合适。", "歌唱": "搭配：“歌唱”的对象是歌，不能用于“图片里的文字”。", "拥抱": "语义：“拥抱”需要有形的身体动作，软件不能拥抱文字。", "散步": "配价：“散步”是不及物动词，后面不能带“图片里的文字”作宾语。"}, "sentence_index": 6, "correct_answer": "识别"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我识别了一场精彩的比赛。", "explanation": "这里应该用〈观看〉。“识别”是认出眼前的事物是什么，不表示看比赛的过程，观看比赛要用“观看”。"}, {"text": "我识别明天不下雨。", "explanation": "这里应该用〈希望〉。“识别”不能表示对未来的期盼，盼望事情不发生要用“希望”。"}, {"text": "会议识别了一周。", "explanation": "这里应该用〈推迟〉。“识别”不能表示会议时间的变动，会议改期要用“推迟”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6a064b18-cb72-4871-ba51-bc2dd5ad36d0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24708, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他一眼就识别了出那个骗子。", "corrected_sentence": "他一眼就识别出了那个骗子。", "error_description": "补语位置错误：“出”是结果补语，要紧跟动词，“了”放在“出”后，应说“识别出了”，不能说“识别了出”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6a064b18-cb72-4871-ba51-bc2dd5ad36d0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24708, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "车站的机器没识别了我的身份证。", "corrected_sentence": "车站的机器没识别我的身份证。", "error_description": "“没”否定已发生的动作，“没”和“了”不能同时用在“没识别”中，应去掉“了”，说“没识别”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6a064b18-cb72-4871-ba51-bc2dd5ad36d0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24710, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "减速", "is_correct": true, "explanation": "减速与加速意思相反，指让速度变慢。"}, {"text": "鸣笛", "is_correct": false, "explanation": "鸣笛指按喇叭发出声音，与“加速”没有反义关系。"}, {"text": "前进", "is_correct": false, "explanation": "前进指向前移动，与“加速”没有反义关系。"}, {"text": "旋转", "is_correct": false, "explanation": "旋转指围绕中心转动，与“加速”没有反义关系。"}], "correct_answer": "减速", "explanations": {"减速": "减速与加速意思相反，指让速度变慢。", "鸣笛": "鸣笛指按喇叭发出声音，与“加速”没有反义关系。", "前进": "前进指向前移动，与“加速”没有反义关系。", "旋转": "旋转指围绕中心转动，与“加速”没有反义关系。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6a064b18-cb72-4871-ba51-bc2dd5ad36d0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24710, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "减速", "is_correct": true, "explanation": "减速与加速意思相反，指让速度变慢。"}, {"text": "转弯", "is_correct": false, "explanation": "转弯指改变行进方向，与“加速”没有反义关系。"}, {"text": "滑行", "is_correct": false, "explanation": "滑行指平稳地移动，与“加速”没有反义关系。"}, {"text": "漂浮", "is_correct": false, "explanation": "漂浮指浮在液体或空气中，与“加速”没有反义关系。"}], "correct_answer": "减速", "explanations": {"减速": "减速与加速意思相反，指让速度变慢。", "转弯": "转弯指改变行进方向，与“加速”没有反义关系。", "滑行": "滑行指平稳地移动，与“加速”没有反义关系。", "漂浮": "漂浮指浮在液体或空气中，与“加速”没有反义关系。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6a064b18-cb72-4871-ba51-bc2dd5ad36d0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24710, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "让东西跑得更快。", "primary_collocate": null, "pronunciation": "jiā sù", "ipa": "tɕja˥˥ su˥˩", "syllable_count": 2, "sentences": [{"text": "司机踩油门，汽车开始加速。", "target_word": "加速", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "过了桥，火车慢慢加速。", "target_word": "加速", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "跑到最后一百米，他突然加速。", "target_word": "加速", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "飞机起飞前要先加速。", "target_word": "加速", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "为了赶时间，司机加速了。", "target_word": "加速", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这辆小车起步后加速很快。", "target_word": "加速", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "自行车下坡的时候会自动加速。", "target_word": "加速", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "前面没有车，你可以加速。", "target_word": "加速", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他加速跑向终点。", "target_word": "加速", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "风越来越大，帆船加速前进。", "target_word": "加速", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "加速了", "label": "体标"}, {"form": "加速过", "label": "体标"}, {"form": "加速度", "label": "复合"}], "register": "中性", "sense_fingerprint": "使速度变快", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '80ab50cd-4340-49f3-b7d1-188a43322068') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24710, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "加速", "is_correct": true, "explanation": "正确答案：加速（jiā sù），意思是让速度变快。"}, {"text": "加数", "is_correct": false, "explanation": "shù（第四声）与 sù（第四声）声母不同：sh 与 s，意思是加法中的数。"}, {"text": "家畜", "is_correct": false, "explanation": "chù（第四声）与 sù（第四声）声母不同：ch 与 s，意思是饲养的动物。"}, {"text": "家兔", "is_correct": false, "explanation": "tù（第四声）与 sù（第四声）声母不同：t 与 s，意思是饲养的兔子。"}], "explanations": {"加速": "正确答案：加速（jiā sù），意思是让速度变快。", "加数": "shù（第四声）与 sù（第四声）声母不同：sh 与 s，意思是加法中的数。", "家畜": "chù（第四声）与 sù（第四声）声母不同：ch 与 s，意思是饲养的动物。", "家兔": "tù（第四声）与 sù（第四声）声母不同：t 与 s，意思是饲养的兔子。"}, "sentence_index": null, "correct_answer": "加速"}, "level_3": {"options": [{"text": "加速", "is_correct": true, "explanation": "加速：让速度变快，与“踩油门”的动作一致。"}, {"text": "减速", "is_correct": false, "explanation": "语义：减速与“踩油门”的目的相反，句意说不通。"}, {"text": "哭", "is_correct": false, "explanation": "搭配：“汽车”不能“哭”，搭配不当。"}, {"text": "生锈", "is_correct": false, "explanation": "语义：生锈是慢慢发生的变化，接在“踩油门”之后说不通。"}], "explanations": {"加速": "加速：让速度变快，与“踩油门”的动作一致。", "减速": "语义：减速与“踩油门”的目的相反，句意说不通。", "哭": "搭配：“汽车”不能“哭”，搭配不当。", "生锈": "语义：生锈是慢慢发生的变化，接在“踩油门”之后说不通。"}, "sentence_index": 0, "correct_answer": "加速"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这个月我的体重加速了三公斤。", "explanation": "这里应该用〈增加〉。加速指速度变快，体重的变化要用增加。"}, {"text": "这次考试我的成绩加速了。", "explanation": "这里应该用〈提高〉。加速只用于速度变快，成绩、水平要用提高。"}, {"text": "我的书包加速了。", "explanation": "这里应该用〈变重〉。加速指速度变快，书包变重要用“变重”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6a064b18-cb72-4871-ba51-bc2dd5ad36d0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24710, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "加速", "is_correct": true, "explanation": "加速：下坡时速度自动变快，与“下坡”一致。"}, {"text": "爬坡", "is_correct": false, "explanation": "语义：爬坡是上坡，与“下坡”的情况相反，句意不通。"}, {"text": "上升", "is_correct": false, "explanation": "搭配：“上升”多用于温度、数量，不说自行车上升。"}, {"text": "倒退", "is_correct": false, "explanation": "语义：下坡时自行车不会自动倒退，句意不通。"}], "explanations": {"加速": "加速：下坡时速度自动变快，与“下坡”一致。", "爬坡": "语义：爬坡是上坡，与“下坡”的情况相反，句意不通。", "上升": "搭配：“上升”多用于温度、数量，不说自行车上升。", "倒退": "语义：下坡时自行车不会自动倒退，句意不通。"}, "sentence_index": 6, "correct_answer": "加速"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "两地之间的距离加速了。", "explanation": "这里应该用〈缩短〉。加速指速度变快，距离变短要用缩短。"}, {"text": "这间屋子的面积加速了。", "explanation": "这里应该用〈扩大〉。加速指速度变快，面积变大要用扩大。"}, {"text": "这篇论文的字数加速了。", "explanation": "这里应该用〈减少〉。加速指速度变快，字数变少要用减少。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6a064b18-cb72-4871-ba51-bc2dd5ad36d0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24710, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这辆车突然很加速了。", "corrected_sentence": "这辆车突然加速了。", "error_description": "副词位置错误：“很”是程度副词，一般不直接修饰“加速”这类表示动作变化的动词，应去掉“很”，说“突然加速了”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6a064b18-cb72-4871-ba51-bc2dd5ad36d0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24710, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这辆摩托车刚才加速着。", "corrected_sentence": "这辆摩托车刚才加速了。", "error_description": "体标误用：“刚才”表示动作已经完成，要用“了”，不能用表示持续的“着”，应说“刚才加速了”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6a064b18-cb72-4871-ba51-bc2dd5ad36d0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24712, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "难于", "is_correct": true, "explanation": "正确答案。难于与易于互为反义，都表示做起来难度的高低。"}, {"text": "放弃", "is_correct": false, "explanation": "与“易于”无反义关系，“放弃”表示不再坚持，不涉及难易。"}, {"text": "保留", "is_correct": false, "explanation": "与“易于”无反义关系，“保留”表示留下不动，不涉及难易。"}, {"text": "讨论", "is_correct": false, "explanation": "与“易于”无反义关系，“讨论”表示交流意见，不涉及难易。"}], "correct_answer": "难于", "explanations": {"难于": "正确答案。难于与易于互为反义，都表示做起来难度的高低。", "放弃": "与“易于”无反义关系，“放弃”表示不再坚持，不涉及难易。", "保留": "与“易于”无反义关系，“保留”表示留下不动，不涉及难易。", "讨论": "与“易于”无反义关系，“讨论”表示交流意见，不涉及难易。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '04b0d076-3bc8-4549-b757-b08aa083512e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24712, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "难于", "is_correct": true, "explanation": "正确答案。难于与易于互为反义，都表示做起来难度的高低。"}, {"text": "收集", "is_correct": false, "explanation": "与“易于”无反义关系，“收集”表示聚集起来，不涉及难易。"}, {"text": "拥有", "is_correct": false, "explanation": "与“易于”无反义关系，“拥有”表示占有，不涉及难易。"}, {"text": "观察", "is_correct": false, "explanation": "与“易于”无反义关系，“观察”表示仔细看，不涉及难易。"}], "correct_answer": "难于", "explanations": {"难于": "正确答案。难于与易于互为反义，都表示做起来难度的高低。", "收集": "与“易于”无反义关系，“收集”表示聚集起来，不涉及难易。", "拥有": "与“易于”无反义关系，“拥有”表示占有，不涉及难易。", "观察": "与“易于”无反义关系，“观察”表示仔细看，不涉及难易。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '04b0d076-3bc8-4549-b757-b08aa083512e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24712, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "property", "definition": "很容易，不觉得难。", "primary_collocate": null, "pronunciation": "yì yú", "ipa": "i˥˩ y˧˥", "syllable_count": 2, "sentences": [{"text": "这道题的答案易于找到。", "target_word": "易于", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "他性格开朗，易于相处。", "target_word": "易于", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "这些规则简单，易于记住。", "target_word": "易于", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "干木头易于燃烧，要小心用火。", "target_word": "易于", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这个系统易于操作，一学就会。", "target_word": "易于", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他的话简单清楚，大家易于接受。", "target_word": "易于", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这条山路平坦，易于行走。", "target_word": "易于", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "新词一般易于传播，尤其是在网上。", "target_word": "易于", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这个菜谱步骤很少，易于学会。", "target_word": "易于", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "地图画得很清楚，易于辨认。", "target_word": "易于", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "易於", "label": "繁体"}], "register": "书面语", "sense_fingerprint": "易于+动词：很容易，不觉得难", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '98e0b363-6408-4edb-93ac-1d50e90a7dc1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24712, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "易于", "is_correct": true, "explanation": "正确答案。易于（yì yú）表示很容易、不觉得难。"}, {"text": "意欲", "is_correct": false, "explanation": "第二个音节 yù（第四声）与 yú（第二声）声调不同，意思是“想要”。"}, {"text": "立于", "is_correct": false, "explanation": "lì 与 yì 声母不同，意思是“站立在”。"}, {"text": "一语", "is_correct": false, "explanation": "yī（第一声）与 yì（第四声）声调不同，yǔ 与 yú 声调也不同，意思是“一句话”。"}, {"text": "异域", "is_correct": false, "explanation": "第二个音节 yù（第四声）与 yú（第二声）声调不同，意思是“外国、异乡”。"}], "explanations": {"易于": "正确答案。易于（yì yú）表示很容易、不觉得难。", "意欲": "第二个音节 yù（第四声）与 yú（第二声）声调不同，意思是“想要”。", "立于": "lì 与 yì 声母不同，意思是“站立在”。", "一语": "yī（第一声）与 yì（第四声）声调不同，yǔ 与 yú 声调也不同，意思是“一句话”。", "异域": "第二个音节 yù（第四声）与 yú（第二声）声调不同，意思是“外国、异乡”。"}, "sentence_index": null, "correct_answer": "易于"}, "level_3": {"options": [{"text": "易于", "is_correct": true, "explanation": "正确答案。“答案易于找到”表示答案很容易找到。"}, {"text": "善于", "is_correct": false, "explanation": "搭配：“善于”说人擅长某事，不能说“答案善于找到”。"}, {"text": "勇于", "is_correct": false, "explanation": "搭配：“勇于”表示敢于做某事，不能用来说答案好不好找。"}, {"text": "勤于", "is_correct": false, "explanation": "搭配：“勤于”说人勤奋，不能用来修饰“找到”这一动作。"}], "explanations": {"易于": "正确答案。“答案易于找到”表示答案很容易找到。", "善于": "搭配：“善于”说人擅长某事，不能说“答案善于找到”。", "勇于": "搭配：“勇于”表示敢于做某事，不能用来说答案好不好找。", "勤于": "搭配：“勤于”说人勤奋，不能用来修饰“找到”这一动作。"}, "sentence_index": 0, "correct_answer": "易于"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他易于帮别人搬家，每次都抱怨累得要命。", "explanation": "这里应该用〈乐于〉。易于说事情做起来不费力，说愿意做某事要用乐于；句中“累得要命”与“不费力”矛盾。"}, {"text": "小王易于讲故事，每次都要反复练习。", "explanation": "这里应该用〈善于〉。易于说做起来不费力，与“每次都要反复练习”矛盾；说人擅长某件事要用善于。"}, {"text": "她易于做账，每个月都要反复核对。", "explanation": "这里应该用〈精于〉。易于说做起来不费力，与“每个月都要反复核对”矛盾；说在某方面很内行要用精于。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '04b0d076-3bc8-4549-b757-b08aa083512e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24712, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "易于", "is_correct": true, "explanation": "正确答案。易于（yì yú）表示很容易、不觉得难。"}, {"text": "利于", "is_correct": false, "explanation": "lì 与 yì 声母不同，意思是“有利于”。"}, {"text": "依于", "is_correct": false, "explanation": "yī（第一声）与 yì（第四声）声调不同，意思是“依靠、取决于”。"}, {"text": "抑郁", "is_correct": false, "explanation": "第二个音节 yù（第四声）与 yú（第二声）声调不同，意思是“心情苦闷”。"}], "explanations": {"易于": "正确答案。易于（yì yú）表示很容易、不觉得难。", "利于": "lì 与 yì 声母不同，意思是“有利于”。", "依于": "yī（第一声）与 yì（第四声）声调不同，意思是“依靠、取决于”。", "抑郁": "第二个音节 yù（第四声）与 yú（第二声）声调不同，意思是“心情苦闷”。"}, "sentence_index": null, "correct_answer": "易于"}, "level_3": {"options": [{"text": "易于", "is_correct": true, "explanation": "正确答案。“平坦的山路易于行走”表示走起来不费力。"}, {"text": "难于", "is_correct": false, "explanation": "语义：“平坦”的路应当好走，“难于行走”与前句相矛盾。"}, {"text": "疏于", "is_correct": false, "explanation": "搭配：“疏于”表示疏忽、忽视，不能用来修饰“行走”。"}, {"text": "惯于", "is_correct": false, "explanation": "语义：“惯于行走”说的是人习惯走，与“山路平坦”的说明不相符。"}], "explanations": {"易于": "正确答案。“平坦的山路易于行走”表示走起来不费力。", "难于": "语义：“平坦”的路应当好走，“难于行走”与前句相矛盾。", "疏于": "搭配：“疏于”表示疏忽、忽视，不能用来修饰“行走”。", "惯于": "语义：“惯于行走”说的是人习惯走，与“山路平坦”的说明不相符。"}, "sentence_index": 6, "correct_answer": "易于"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "她易于弹钢琴，每次练琴都要反复练习。", "explanation": "这里应该用〈擅长〉。易于说做起来不费力，与“每次练琴都要反复练习”矛盾；说人在某方面做得好要用擅长。"}, {"text": "我易于早起，每天都要反复按闹钟。", "explanation": "这里应该用〈习惯〉。易于说做起来不费力，与“每天都要反复按闹钟”矛盾；说一个人常做某事要用习惯。"}, {"text": "孩子易于画画，每次画到一半都要歇好久。", "explanation": "这里应该用〈喜欢〉。易于表示做起来不费力，与“每次画到一半都要歇好久”矛盾；表示喜爱某事应用〈喜欢〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '04b0d076-3bc8-4549-b757-b08aa083512e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24712, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这份资料易于了查找，同学们都很方便。", "corrected_sentence": "这份资料易于查找，同学们都很方便。", "error_description": "错误形式：“易于了查找”。正确形式：“易于查找”。易于是后接动词的动词（表示“容易”），后面不能直接加“了”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '04b0d076-3bc8-4549-b757-b08aa083512e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24712, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这张表格被易于填写，老人也能看懂。", "corrected_sentence": "这张表格易于填写，老人也能看懂。", "error_description": "错误形式：“被易于填写”。正确形式：“易于填写”。易于是表示“容易”的动词，不能用在“被”字句里。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '04b0d076-3bc8-4549-b757-b08aa083512e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
