INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24714, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "告诉大家，不让别人不知道。", "primary_collocate": null, "pronunciation": "gōng kāi", "ipa": "kʊŋ˥ kʰaɪ˥", "syllable_count": 2, "sentences": [{"text": "学校明天公开考试成绩。", "target_word": "公开", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公司公开了新产品的价格。", "target_word": "公开", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他不想公开自己的名字。", "target_word": "公开", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "医院把这个消息公开了。", "target_word": "公开", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请你公开这件事的真相。", "target_word": "公开", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师公开了比赛的名单。", "target_word": "公开", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她一直没有公开过自己的年龄。", "target_word": "公开", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "政府公开了去年的数据。", "target_word": "公开", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你为什么要公开我的秘密？", "target_word": "公开", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "经理决定下周公开结果。", "target_word": "公开", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "公开了", "label": "体标"}, {"form": "公开过", "label": "体标"}, {"form": "公开化", "label": "复合"}], "register": "中性", "sense_fingerprint": "公开|把消息、信息告诉大家", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '98e0b363-6408-4edb-93ac-1d50e90a7dc1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24714, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "吃掉", "is_correct": false, "explanation": "语义：“吃掉”与“让大家知道成绩”的意思毫不相关，句意不通。"}, {"text": "烹饪", "is_correct": false, "explanation": "搭配：“烹饪”的对象是食物，不能用于“考试成绩”。"}, {"text": "公开", "is_correct": true, "explanation": "“公开考试成绩”即把成绩告诉大家，与句意相符。"}, {"text": "发射", "is_correct": false, "explanation": "语义：“发射”是射出，与“让大家知道成绩”无关。"}], "explanations": {"吃掉": "语义：“吃掉”与“让大家知道成绩”的意思毫不相关，句意不通。", "烹饪": "搭配：“烹饪”的对象是食物，不能用于“考试成绩”。", "公开": "“公开考试成绩”即把成绩告诉大家，与句意相符。", "发射": "语义：“发射”是射出，与“让大家知道成绩”无关。"}, "sentence_index": 0, "correct_answer": "公开"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这个公园每天公开到晚上十点。", "explanation": "这里应该用〈开放〉。公开指把消息告诉大家，场所对外开放要用“开放”。"}, {"text": "他把钱公开在床底下。", "explanation": "这里应该用〈藏〉。公开是把事情告诉大家，不能表示把东西放在隐秘处。"}, {"text": "他把礼物公开给了老师。", "explanation": "这里应该用〈送〉。公开是把消息告诉大家，把礼物交给别人要用“送”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '04b0d076-3bc8-4549-b757-b08aa083512e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24714, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "种植", "is_correct": false, "explanation": "语义：“种植”是栽培植物，与“年龄”无关。"}, {"text": "修剪", "is_correct": false, "explanation": "语义：“修剪”是剪短枝叶，不能用于“年龄”，句意不通。"}, {"text": "演奏", "is_correct": false, "explanation": "搭配：“演奏”的对象是乐器或乐曲，不能用于“年龄”。"}, {"text": "公开", "is_correct": true, "explanation": "“没有公开过自己的年龄”指没有把年龄告诉别人，与句意相符。"}], "explanations": {"种植": "语义：“种植”是栽培植物，与“年龄”无关。", "修剪": "语义：“修剪”是剪短枝叶，不能用于“年龄”，句意不通。", "演奏": "搭配：“演奏”的对象是乐器或乐曲，不能用于“年龄”。", "公开": "“没有公开过自己的年龄”指没有把年龄告诉别人，与句意相符。"}, "sentence_index": 6, "correct_answer": "公开"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "经理公开了那位员工。", "explanation": "这里应该用〈辞退〉。公开的对象是消息、信息等事项，不能用来指人。"}, {"text": "工人公开了旧楼。", "explanation": "这里应该用〈拆除〉。公开用于消息或事项，不能指建筑物。"}, {"text": "仓库管理员公开了那箱书。", "explanation": "这里应该用〈搬运〉。公开的对象是消息或事项，不能表示搬动一箱东西。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '04b0d076-3bc8-4549-b757-b08aa083512e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24714, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "市政府决定下个月公开了预算报告。", "corrected_sentence": "市政府决定下个月公开预算报告。", "error_description": "错误形式：“下个月公开了”；正确形式：“下个月公开”。将来的时间不能与表示完成的“了”同用。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '04b0d076-3bc8-4549-b757-b08aa083512e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24714, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "老师说明天公开了考试的题目。", "corrected_sentence": "老师说明天公开考试的题目。", "error_description": "错误形式：“明天公开了”；正确形式：“明天公开”。将来的时间（明天）不能与表示完成的“了”同用。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '04b0d076-3bc8-4549-b757-b08aa083512e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
