INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24716, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "平平的面，像桌面、地面那样平平的。", "primary_collocate": null, "pronunciation": "píng miàn", "ipa": "pʰiŋ˧˥ mjɛn˥˩", "syllable_count": 2, "sentences": [{"text": "这块石头的顶部有一个很大的平面，可以放东西。", "target_word": "平面", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "把书放在平面上，不会掉下来。", "target_word": "平面", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "山上很难找到足够大的平面来搭帐篷。", "target_word": "平面", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这张桌子的平面很光滑。", "target_word": "平面", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "杯子要放在平面上才稳。", "target_word": "平面", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "窗台太窄，没有放花盆的平面。", "target_word": "平面", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他把木板磨成一个光滑的平面。", "target_word": "平面", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个盒子底部有一个平面，所以能站稳。", "target_word": "平面", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "厨房里需要一个大平面来切菜。", "target_word": "平面", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我们把垫子铺在那块石板的平面上。", "target_word": "平面", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "块", "label": "量词"}, {"form": "平面图", "label": "复合"}], "register": "中性", "sense_fingerprint": "平面：日常物体上平平的一块面", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '642832d6-af4f-4008-8f4d-ac33a85c01e4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24716, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "平面", "is_correct": true, "explanation": "平面：指石头顶部平平的一块面，可以放东西，与句意相符。"}, {"text": "声音", "is_correct": false, "explanation": "语义：声音不能占有平面，也放不了东西。"}, {"text": "味道", "is_correct": false, "explanation": "语义：味道没有平面可言，“可以放东西”说不通。"}, {"text": "颜色", "is_correct": false, "explanation": "搭配：“很大的”多修饰面积或空间，不修饰颜色。"}], "explanations": {"平面": "平面：指石头顶部平平的一块面，可以放东西，与句意相符。", "声音": "语义：声音不能占有平面，也放不了东西。", "味道": "语义：味道没有平面可言，“可以放东西”说不通。", "颜色": "搭配：“很大的”多修饰面积或空间，不修饰颜色。"}, "sentence_index": 0, "correct_answer": "平面"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这颗鸡蛋的平面很光滑。", "explanation": "这里应该用〈表面〉。平面指平平的面，鸡蛋是椭圆的，没有平面；说外层时用“表面”。"}, {"text": "这个皮球的平面上有很多花纹。", "explanation": "这里应该用〈表面〉。皮球是圆的，没有平平的面，外层要说“表面”。"}, {"text": "这块西瓜的平面很甜。", "explanation": "这里应该用〈果肉〉。平面指平平的面，西瓜是圆的，不能说它的平面很甜。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0250f2ac-1a0a-446f-9ecf-9aba6be4380b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24716, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "平面", "is_correct": true, "explanation": "平面：磨光后木板的表面，指一块平平的面，与句意相符。"}, {"text": "气味", "is_correct": false, "explanation": "语义：木板磨光后得到的是平面，不是气味。"}, {"text": "回声", "is_correct": false, "explanation": "语义：回声是声音的反射，不能被磨成光滑的东西。"}, {"text": "音量", "is_correct": false, "explanation": "搭配：“光滑的”不修饰音量。"}], "explanations": {"平面": "平面：磨光后木板的表面，指一块平平的面，与句意相符。", "气味": "语义：木板磨光后得到的是平面，不是气味。", "回声": "语义：回声是声音的反射，不能被磨成光滑的东西。", "音量": "搭配：“光滑的”不修饰音量。"}, "sentence_index": 6, "correct_answer": "平面"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这颗贝壳的平面很光滑。", "explanation": "这里应该用〈外层〉。平面指平平的面，贝壳是弯曲的，没有平面；说外层时用“外层”。"}, {"text": "他头发的平面很黑。", "explanation": "这里应该用〈颜色〉。头发没有平平的面，说黑要用“颜色”。"}, {"text": "那只小狗的平面很软，很可爱。", "explanation": "这里应该用〈皮毛〉。平面指平平的面，小狗身上没有平面；说毛的柔软要用“皮毛”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0250f2ac-1a0a-446f-9ecf-9aba6be4380b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24716, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "石头顶上有一只平面。", "corrected_sentence": "石头顶上有一块平面。", "error_description": "量词错误：“平面”用“个”或“块”，不能用“只”（“只”用于动物或成对器物中的一个）。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0250f2ac-1a0a-446f-9ecf-9aba6be4380b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24716, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我们在木板上磨出了一扇平面。", "corrected_sentence": "我们在木板上磨出了一块平面。", "error_description": "量词错误：“平面”用“个”或“块”，不能用“扇”（“扇”用于门窗等）。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0250f2ac-1a0a-446f-9ecf-9aba6be4380b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
