INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24722, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "一个东西的尾巴和另一个东西的头连在一起。", "primary_collocate": null, "pronunciation": "shǒu wěi xiāng lián", "ipa": "ʂoʊ̯˨˩ weɪ̯˨˩ ɕjɑŋ˥ ljɛn˧˥", "syllable_count": 4, "sentences": [{"text": "火车的车厢首尾相连。", "target_word": "首尾相连", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "小鸭子们首尾相连，走过了小桥。", "target_word": "首尾相连", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这两条蛇首尾相连，绕成了一个圈。", "target_word": "首尾相连", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小朋友们首尾相连，玩起了火车游戏。", "target_word": "首尾相连", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "工人把两根长管首尾相连地接好。", "target_word": "首尾相连", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "船一只接一只，首尾相连停在河边。", "target_word": "首尾相连", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们把几辆小车首尾相连地接在一起。", "target_word": "首尾相连", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "两条鱼在水里首尾相连地游着。", "target_word": "首尾相连", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请把这些绳子首尾相连，接成一根长绳。", "target_word": "首尾相连", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "长长的卡车队首尾相连，停在路上。", "target_word": "首尾相连", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "首尾相連", "label": "繁体"}], "register": "中性", "sense_fingerprint": "前一个的尾与后一个的头接在一起", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '642832d6-af4f-4008-8f4d-ac33a85c01e4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24722, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "首尾相连", "is_correct": true, "explanation": "正确：车厢一节接一节地连在一起，是这里的动作。"}, {"text": "发芽", "is_correct": false, "explanation": "语义：发芽是植物萌发的现象，车厢不会发芽。"}, {"text": "歌唱", "is_correct": false, "explanation": "语义：歌唱的主体是人或能发声的动物，与车厢无关。"}, {"text": "生长", "is_correct": false, "explanation": "搭配：生长用于生物，不说车厢这类人造物。"}], "explanations": {"首尾相连": "正确：车厢一节接一节地连在一起，是这里的动作。", "发芽": "语义：发芽是植物萌发的现象，车厢不会发芽。", "歌唱": "语义：歌唱的主体是人或能发声的动物，与车厢无关。", "生长": "搭配：生长用于生物，不说车厢这类人造物。"}, "sentence_index": 0, "correct_answer": "首尾相连"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这块木板首尾相连，放在地上。", "explanation": "这里应该用〈平放〉。首尾相连要求两个以上事物头尾相接，一块木板不存在这种接合。"}, {"text": "两条直线在中间首尾相连。", "explanation": "这里应该用〈交叉〉。首尾相连是一端接另一端，不是在中间相交。"}, {"text": "两根绳子在桌上斜着穿过，首尾相连。", "explanation": "这里应该用〈穿插〉。首尾相连指一端接另一端，斜着穿过的绳子并不是头尾相接。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0250f2ac-1a0a-446f-9ecf-9aba6be4380b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24722, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "首尾相连", "is_correct": true, "explanation": "正确：把小车一辆接一辆连在一起，是这里的动作。"}, {"text": "融化", "is_correct": false, "explanation": "语义：融化是固体受热变成液体，车辆不会融化。"}, {"text": "繁殖", "is_correct": false, "explanation": "语义：繁殖是生物产生后代，不用于车辆。"}, {"text": "孵化", "is_correct": false, "explanation": "搭配：孵化用于卵，不说车辆。"}], "explanations": {"首尾相连": "正确：把小车一辆接一辆连在一起，是这里的动作。", "融化": "语义：融化是固体受热变成液体，车辆不会融化。", "繁殖": "语义：繁殖是生物产生后代，不用于车辆。", "孵化": "搭配：孵化用于卵，不说车辆。"}, "sentence_index": 6, "correct_answer": "首尾相连"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这只碗首尾相连，放在桌上。", "explanation": "这里应该用〈摆放〉。首尾相连要求两个以上事物头尾相接，一只碗不能这样说。"}, {"text": "这两个人的眼神首尾相连，互相看着。", "explanation": "这里应该用〈对视〉。首尾相连说的是有形事物的头尾接合，不能用于眼神。"}, {"text": "两根筷子并排首尾相连，放在碗边。", "explanation": "这里应该用〈并排摆放〉。并排是平行放在一起，不是一端接另一端，不能说首尾相连。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0250f2ac-1a0a-446f-9ecf-9aba6be4380b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24722, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "两节车厢首尾相连了一列，停在站台上。", "corrected_sentence": "两节车厢首尾相连成一列，停在站台上。", "error_description": "错误形式「首尾相连了一列」，正确形式「首尾相连成一列」。「成」是结果补语，表示连接后形成的结果，不能用「了」代替。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0250f2ac-1a0a-446f-9ecf-9aba6be4380b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24722, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "几辆车了首尾相连，停在路边。", "corrected_sentence": "几辆车首尾相连，停在路边。", "error_description": "错误形式「了首尾相连」，正确形式「首尾相连」。「了」是体标，不能放在「首尾相连」之前，这里应直接说「首尾相连」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0250f2ac-1a0a-446f-9ecf-9aba6be4380b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
