INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24724, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "赢了", "primary_collocate": null, "pronunciation": "shèng chū", "ipa": "ʂɤŋ˥˩ ʈʂʰu˥", "syllable_count": 2, "sentences": [{"text": "今天的比赛，我们班胜出。", "target_word": "胜出", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他们下棋，最后小明胜出。", "target_word": "胜出", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "哪一队胜出，明天就知道了。", "target_word": "胜出", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "跑步比赛里，小李先到，所以他胜出。", "target_word": "胜出", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我们的队伍在拔河比赛中胜出了。", "target_word": "胜出", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "两个人比谁吃得快，哥哥胜出。", "target_word": "胜出", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这次猜谜比赛，妹妹得分最高，胜出了。", "target_word": "胜出", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他们踢了九十分钟，最后蓝队胜出。", "target_word": "胜出", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "大家都希望自己的队伍能胜出。", "target_word": "胜出", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "乒乓球赛结束了，小刘胜出。", "target_word": "胜出", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "胜出了", "label": "体标"}, {"form": "胜出过", "label": "体标"}, {"form": "勝出", "label": "繁体"}], "register": "书面", "sense_fingerprint": "胜出：比赛中赢了对手", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '642832d6-af4f-4008-8f4d-ac33a85c01e4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24724, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "胜出", "is_correct": true, "explanation": "与听到的读音一致，是正确答案。"}, {"text": "生出", "is_correct": false, "explanation": "shēng（第一声）与 shèng（第四声）声调不同，意思是长出、产生。"}, {"text": "省出", "is_correct": false, "explanation": "shěng（第三声）与 shèng（第四声）声调不同，意思是节省后留下。"}, {"text": "渗出", "is_correct": false, "explanation": "shèn 与 shèng 韵母不同（-n 与 -ng），意思是液体慢慢透出。"}], "explanations": {"胜出": "与听到的读音一致，是正确答案。", "生出": "shēng（第一声）与 shèng（第四声）声调不同，意思是长出、产生。", "省出": "shěng（第三声）与 shèng（第四声）声调不同，意思是节省后留下。", "渗出": "shèn 与 shèng 韵母不同（-n 与 -ng），意思是液体慢慢透出。"}, "sentence_index": null, "correct_answer": "胜出"}, "level_3": {"options": [{"text": "胜出", "is_correct": true, "explanation": "正确：「今天的比赛」中，「我们班」赢了对手。"}, {"text": "出生", "is_correct": false, "explanation": "语义：出生指人或动物降生，班级不能出生，也与比赛无关。"}, {"text": "增长", "is_correct": false, "explanation": "搭配：增长说的是数量，不能用来说班级在比赛中的结果。"}, {"text": "生病", "is_correct": false, "explanation": "语义：生病指身体不适，与比赛的语境不合。"}], "explanations": {"胜出": "正确：「今天的比赛」中，「我们班」赢了对手。", "出生": "语义：出生指人或动物降生，班级不能出生，也与比赛无关。", "增长": "搭配：增长说的是数量，不能用来说班级在比赛中的结果。", "生病": "语义：生病指身体不适，与比赛的语境不合。"}, "sentence_index": 0, "correct_answer": "胜出"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他的病终于胜出了。", "explanation": "这里应该用〈康复〉。胜出指赢了比赛，病情好转不是胜负的结果。"}, {"text": "这次手术顺利胜出了。", "explanation": "这里应该用〈完成〉。胜出指赢了比赛，手术完成不涉及胜负。"}, {"text": "伤口已经胜出了。", "explanation": "这里应该用〈愈合〉。胜出指赢了比赛，伤口愈合不是竞争的结果。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0250f2ac-1a0a-446f-9ecf-9aba6be4380b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24724, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "胜出", "is_correct": true, "explanation": "正确：句中说「得分最高」，所以妹妹是在猜谜比赛中获胜。"}, {"text": "下降", "is_correct": false, "explanation": "语义：下降与「得分最高」矛盾，得分最高不能说下降。"}, {"text": "迷路", "is_correct": false, "explanation": "语义：迷路指找不到方向，与猜谜比赛的得分无关。"}, {"text": "变胖", "is_correct": false, "explanation": "体貌：变胖描写身体外形，与比赛的结果无关。"}], "explanations": {"胜出": "正确：句中说「得分最高」，所以妹妹是在猜谜比赛中获胜。", "下降": "语义：下降与「得分最高」矛盾，得分最高不能说下降。", "迷路": "语义：迷路指找不到方向，与猜谜比赛的得分无关。", "变胖": "体貌：变胖描写身体外形，与比赛的结果无关。"}, "sentence_index": 6, "correct_answer": "胜出"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "河面终于胜出了。", "explanation": "这里应该用〈结冰〉。胜出指赢了比赛，河面结冰不是胜负的结果。"}, {"text": "屋里的灰尘终于胜出了。", "explanation": "这里应该用〈散去〉。胜出指赢了比赛，灰尘散去不涉及胜负。"}, {"text": "天气终于胜出了。", "explanation": "这里应该用〈降温〉。胜出指赢了比赛，气温下降不涉及胜负。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0250f2ac-1a0a-446f-9ecf-9aba6be4380b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
