INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24726, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "变体就是同一个东西不一样的样子。", "primary_collocate": null, "pronunciation": "biàn tǐ", "ipa": "pjɛn˥˩ tʰi˨˩", "syllable_count": 2, "sentences": [{"text": "这个字母有一个特别的变体。", "target_word": "变体", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这道菜是传统做法的变体。", "target_word": "变体", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他画了这只猫的一个变体。", "target_word": "变体", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个游戏有好几种变体。", "target_word": "变体", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这个词有两个变体，意思一样。", "target_word": "变体", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "新的变体看起来和原来不一样。", "target_word": "变体", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这种花有很多颜色的变体。", "target_word": "变体", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师给我们看了这首诗的变体。", "target_word": "变体", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这是同一个故事的另一种变体。", "target_word": "变体", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她做了蛋糕的变体，加了水果。", "target_word": "变体", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "一种变体", "label": "量词"}, {"form": "變體", "label": "繁体"}], "register": "中性", "sense_fingerprint": "同一个东西的另一种样子", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '642832d6-af4f-4008-8f4d-ac33a85c01e4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24726, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "变体", "is_correct": true, "explanation": "“这个字母有一个特别的变体”，指字母的另一种样子，符合句意。"}, {"text": "饭", "is_correct": false, "explanation": "语义：字母的“饭”说不通，饭不是字母的样子。"}, {"text": "口袋", "is_correct": false, "explanation": "语义：字母不能有口袋，句意不通。"}, {"text": "天气", "is_correct": false, "explanation": "语义：字母不会有天气，句意不通。"}], "explanations": {"变体": "“这个字母有一个特别的变体”，指字母的另一种样子，符合句意。", "饭": "语义：字母的“饭”说不通，饭不是字母的样子。", "口袋": "语义：字母不能有口袋，句意不通。", "天气": "语义：字母不会有天气，句意不通。"}, "sentence_index": 0, "correct_answer": "变体"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这座城市的变体很大。", "explanation": "这里应该用〈变化〉。变体指同一事物的另一种样子，不指城市的变动。"}, {"text": "这瓶牛奶放久了变体了。", "explanation": "这里应该用〈变质〉。变体是名词，不能作动词，牛奶坏了要说“变质”。"}, {"text": "这个游戏的规则已经变体了。", "explanation": "这里应该用〈改动〉。变体是名词，指同一事物的另一种样子，不能作动词，规则改动要说“改动”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0250f2ac-1a0a-446f-9ecf-9aba6be4380b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24726, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "变体", "is_correct": true, "explanation": "“这种花有很多颜色的变体”，指花的另一种颜色形态，符合句意。"}, {"text": "雪", "is_correct": false, "explanation": "语义：“颜色的雪”说不通，雪没有这种变异形式。"}, {"text": "雷", "is_correct": false, "explanation": "语义：雷不是花的颜色形态，句意不通。"}, {"text": "考试", "is_correct": false, "explanation": "搭配：“颜色的”修饰的是花的形态，不能接“考试”。"}], "explanations": {"变体": "“这种花有很多颜色的变体”，指花的另一种颜色形态，符合句意。", "雪": "语义：“颜色的雪”说不通，雪没有这种变异形式。", "雷": "语义：雷不是花的颜色形态，句意不通。", "考试": "搭配：“颜色的”修饰的是花的形态，不能接“考试”。"}, "sentence_index": 6, "correct_answer": "变体"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这个塑料杯被晒得变体了。", "explanation": "这里应该用〈变形〉。变体是名词，不能作动词，形状改变要说“变形”。"}, {"text": "他的生活有了很大的变体。", "explanation": "这里应该用〈转变〉。变体指同一事物的另一种样子，不指生活的转变过程。"}, {"text": "这首诗的内容被她变体了。", "explanation": "这里应该用〈改写〉。变体是名词，指同一事物的另一种样子，不能作动词，改写要说“改写”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0250f2ac-1a0a-446f-9ecf-9aba6be4380b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24726, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这个字母有一只特别的变体。", "corrected_sentence": "这个字母有一种特别的变体。", "error_description": "量词错误：“只”不用于变体，应用“种”。正确说法是“一种特别的变体”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0250f2ac-1a0a-446f-9ecf-9aba6be4380b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24726, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这首诗有很多条变体。", "corrected_sentence": "这首诗有很多种变体。", "error_description": "量词错误：“条”用于条状的东西，变体应用“种”。正确说法是“很多种变体”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0250f2ac-1a0a-446f-9ecf-9aba6be4380b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
