INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24734, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "能让人做事、动起来的东西。", "primary_collocate": null, "pronunciation": "néng liàng", "ipa": "nɘŋ˧˥ ljɑŋ˥˩", "syllable_count": 2, "sentences": [{"text": "早饭给了我一天的能量。", "target_word": "能量", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子们有很多能量，一直在跑。", "target_word": "能量", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "太阳给地球带来很多能量。", "target_word": "能量", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "吃完饭后，我觉得身体有了能量。", "target_word": "能量", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "运动太多会用完身体里的能量。", "target_word": "能量", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他每天都充满能量。", "target_word": "能量", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "电是机器的能量，没有电机器就不动。", "target_word": "能量", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我累了，需要吃点东西补充能量。", "target_word": "能量", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她很有能量，跟她在一起我也开心。", "target_word": "能量", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "跑了十公里，我身上一点能量也没有了。", "target_word": "能量", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "一股能量", "label": "量词"}], "register": "中性", "sense_fingerprint": "能量：让人或机器能够活动、做事的力量", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ce010c66-d877-4df7-8147-8f6d54c7cf13') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24734, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "颜色", "is_correct": false, "explanation": "语义：颜色是事物的视觉属性，早饭不能给人一天的颜色。"}, {"text": "能量", "is_correct": true, "explanation": "正确：能量指人的精力和活力，“给了我一天的能量”语义通顺，符合早饭的语境。"}, {"text": "身材", "is_correct": false, "explanation": "体貌：身材指人的体型，早饭不能给人一天的身材。"}, {"text": "味道", "is_correct": false, "explanation": "搭配：“味道”不能作“给”的对象，“一天的味道”不成搭配。"}], "explanations": {"颜色": "语义：颜色是事物的视觉属性，早饭不能给人一天的颜色。", "能量": "正确：能量指人的精力和活力，“给了我一天的能量”语义通顺，符合早饭的语境。", "身材": "体貌：身材指人的体型，早饭不能给人一天的身材。", "味道": "搭配：“味道”不能作“给”的对象，“一天的味道”不成搭配。"}, "sentence_index": 0, "correct_answer": "能量"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这块钢的能量很高，不容易弯。", "explanation": "这里应该用〈硬度〉。描述材料抵抗变形的程度要用硬度，能量指做功的能力或活力，不能用来形容钢的软硬。"}, {"text": "他的翻译能量很强，客人都听懂了。", "explanation": "这里应该用〈能力〉。能量不用来描述技能的强弱，翻译水平要用能力。"}, {"text": "他的能量有一米八，是班里最高的。", "explanation": "这里应该用〈身高〉。人有多高要用身高来说，能量不能用米来计量。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '16782303-5f5e-466a-b0d1-aa2aa443e529') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24734, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "性格", "is_correct": false, "explanation": "语义：性格是人的心理特点，机器没有性格，句子不通。"}, {"text": "能量", "is_correct": true, "explanation": "正确：能量指使机器运转的动力，“机器的能量”语义通顺。"}, {"text": "颜色", "is_correct": false, "explanation": "语义：「颜色」是外观属性，「机器的颜色」与「没有电机器就不动」无关。"}, {"text": "脾气", "is_correct": false, "explanation": "语义：脾气指人的性情，用来形容机器不合逻辑。"}], "explanations": {"性格": "语义：性格是人的心理特点，机器没有性格，句子不通。", "能量": "正确：能量指使机器运转的动力，“机器的能量”语义通顺。", "颜色": "语义：「颜色」是外观属性，「机器的颜色」与「没有电机器就不动」无关。", "脾气": "语义：脾气指人的性情，用来形容机器不合逻辑。"}, "sentence_index": 6, "correct_answer": "能量"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他在晚会上唱起了能量，大家都笑了。", "explanation": "这里应该用〈歌〉。「唱」的对象是歌曲，「能量」不能被唱。"}, {"text": "这间屋子的能量太低了，大家都觉得冷。", "explanation": "这里应该用〈温度〉。屋子冷热要用温度来说，能量不能用来形容空间的冷暖。"}, {"text": "这条河的能量有五公里长。", "explanation": "这里应该用〈长度〉。河有多长要用长度来说，能量不能用公里来计量。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '16782303-5f5e-466a-b0d1-aa2aa443e529') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24734, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "喝完这杯咖啡，我感觉有了一只能量。", "corrected_sentence": "喝完这杯咖啡，我感觉有了一股能量。", "error_description": "量词错误：“一只能量”应为“一股能量”。能量是无形的，应用量词“股”；“只”主要用于动物。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '16782303-5f5e-466a-b0d1-aa2aa443e529') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24734, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我累了，需要吃点东西补充一条能量。", "corrected_sentence": "我累了，需要吃点东西补充一点能量。", "error_description": "量词错误：「一条能量」应为「一点能量」。能量无形，不能用「条」，补充少量能量说「一点」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '16782303-5f5e-466a-b0d1-aa2aa443e529') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
