INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24738, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "这个词语说的是一个手机服务，你可以在很多国家用它打电话。", "primary_collocate": null, "pronunciation": "quán qiú tōng", "ipa": "tɕʰɥɛn˧˥ tɕʰjoʊ˧˥ tʰʊŋ˥", "syllable_count": 3, "sentences": [{"text": "她的手机用全球通，在国外也有信号。", "target_word": "全球通", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我想办全球通，因为我常常出国。", "target_word": "全球通", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "全球通可以在很多国家打电话。", "target_word": "全球通", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他换了全球通，不再担心国外没信号。", "target_word": "全球通", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "全球通贵不贵？", "target_word": "全球通", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "弟弟说全球通比别的手机服务好。", "target_word": "全球通", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "出差的时候，我一直用全球通。", "target_word": "全球通", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我妈妈不会用全球通。", "target_word": "全球通", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "你用的是不是全球通？", "target_word": "全球通", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "在机场，他先问了全球通怎么用。", "target_word": "全球通", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "一种手机服务，在许多国家都可以打电话，适合常出国的人", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3c7f2601-5d41-4e78-8d42-413e02a40644') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24738, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "全球通", "is_correct": true, "explanation": "正确：「全球通」是通信服务，手机用它才会在国外有信号。"}, {"text": "充电宝", "is_correct": false, "explanation": "语义：充电宝只能给手机充电，不提供信号，与「在国外也有信号」矛盾。"}, {"text": "耳机", "is_correct": false, "explanation": "语义：耳机不提供信号，与「在国外也有信号」的说法不符。"}, {"text": "闹钟", "is_correct": false, "explanation": "搭配：「用」后接的应是通信服务，「闹钟」与句中「有信号」搭配不当。"}], "explanations": {"全球通": "正确：「全球通」是通信服务，手机用它才会在国外有信号。", "充电宝": "语义：充电宝只能给手机充电，不提供信号，与「在国外也有信号」矛盾。", "耳机": "语义：耳机不提供信号，与「在国外也有信号」的说法不符。", "闹钟": "搭配：「用」后接的应是通信服务，「闹钟」与句中「有信号」搭配不当。"}, "sentence_index": 0, "correct_answer": "全球通"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "弟弟的全球通很可爱。", "explanation": "这里应该用〈小狗〉。「可爱」形容人或动物，全球通是服务，不能用来形容。"}, {"text": "这次测验的全球通很难。", "explanation": "这里应该用〈试卷〉。全球通是通信服务，不能作为试卷的主语来评价难易。"}, {"text": "我在全球通里看书。", "explanation": "这里应该用〈图书馆〉。全球通是通信服务，不是地点，不能用「在……里」表示看书的场所。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '51d8e2bc-0184-4abe-ade1-561b8f69190c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24738, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "全球通", "is_correct": true, "explanation": "正确：「全球通」是通信服务，出差时一直用它，才能在外地打电话。"}, {"text": "酒店", "is_correct": false, "explanation": "语义：酒店不是通信服务，不能「用」来打电话，与句意不符。"}, {"text": "行李", "is_correct": false, "explanation": "搭配：「用」后接的应是通信服务或工具，「用行李」搭配不当。"}, {"text": "发票", "is_correct": false, "explanation": "语义：发票是报销凭证，不是通信服务，与「一直用」的对象不符。"}], "explanations": {"全球通": "正确：「全球通」是通信服务，出差时一直用它，才能在外地打电话。", "酒店": "语义：酒店不是通信服务，不能「用」来打电话，与句意不符。", "行李": "搭配：「用」后接的应是通信服务或工具，「用行李」搭配不当。", "发票": "语义：发票是报销凭证，不是通信服务，与「一直用」的对象不符。"}, "sentence_index": 6, "correct_answer": "全球通"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他在全球通上班。", "explanation": "这里应该用〈公司〉。「上班」要求工作场所，全球通是通信服务，不是地点。"}, {"text": "这件衣服的全球通很漂亮。", "explanation": "这里应该用〈颜色〉。「很漂亮」评价的是衣服的外观，全球通是服务，不能用来评价衣服。"}, {"text": "我的邻居是一个全球通。", "explanation": "这里应该用〈人〉。全球通是服务，不是人，不能用「是一个」来指称邻居。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '51d8e2bc-0184-4abe-ade1-561b8f69190c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24738, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我在国外过用全球通。", "corrected_sentence": "我在国外用过全球通。", "error_description": "“过”的位置错误：动态助词“过”应紧跟动词，应说“用过”，不能放在动词之前。正确说法是“在国外用过全球通”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '51d8e2bc-0184-4abe-ade1-561b8f69190c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24738, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "出差的时候，他一直用全球通了打电话。", "corrected_sentence": "出差的时候，他一直用全球通打电话。", "error_description": "「了」不能放在「全球通」后面，此处应去掉「了」，改为「一直用全球通打电话」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '51d8e2bc-0184-4abe-ade1-561b8f69190c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
