INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24742, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "把不一样的东西分开。", "primary_collocate": null, "pronunciation": "qū fēn", "ipa": "tɕʰy˥ fən˥", "syllable_count": 2, "sentences": [{"text": "请把红色的和蓝色的区分开。", "target_word": "区分", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子还不会区分左手和右手。", "target_word": "区分", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我分不清它们，你能帮我区分一下吗？", "target_word": "区分", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我们先把垃圾区分开，再扔进桶里。", "target_word": "区分", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "白天和晚上很容易区分。", "target_word": "区分", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "这两只猫太像了，我无法区分。", "target_word": "区分", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "学校用校服的颜色区分年级。", "target_word": "区分", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他能区分各种鸟的叫声。", "target_word": "区分", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "地上的线把两个区域区分开来。", "target_word": "区分", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请区分一下这两个词的用法。", "target_word": "区分", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "區分", "label": "繁体"}, {"form": "区分了", "label": "体标"}, {"form": "区分过", "label": "体标"}, {"form": "区分度", "label": "复合"}], "register": "中性", "sense_fingerprint": "区分|把不一样的东西分开", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '98e0b363-6408-4edb-93ac-1d50e90a7dc1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24742, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "合并", "is_correct": false, "explanation": "语义：“合并”是合在一起，与“请把…分开”的要求相反。"}, {"text": "区分", "is_correct": true, "explanation": "“区分开”即把红色的和蓝色的分开，与句意相符。"}, {"text": "混合", "is_correct": false, "explanation": "语义：“混合”是掺在一起，与“分开”的意思相反。"}, {"text": "粘贴", "is_correct": false, "explanation": "搭配：“粘贴”是把东西粘在一起，不能与“开”搭配成“粘贴开”。"}], "explanations": {"合并": "语义：“合并”是合在一起，与“请把…分开”的要求相反。", "区分": "“区分开”即把红色的和蓝色的分开，与句意相符。", "混合": "语义：“混合”是掺在一起，与“分开”的意思相反。", "粘贴": "搭配：“粘贴”是把东西粘在一起，不能与“开”搭配成“粘贴开”。"}, "sentence_index": 0, "correct_answer": "区分"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "老师区分了每个学生的座位。", "explanation": "这里应该用〈分配〉。区分是把不一样的东西分开，分派座位要用“分配”。"}, {"text": "工人区分了那台旧机器。", "explanation": "这里应该用〈拆解〉。区分要把两种以上不同的东西分开，拆解一台机器要用“拆解”。"}, {"text": "他区分了两个城市的距离。", "explanation": "这里应该用〈测量〉。区分是把不一样的东西分开，量取两地距离要用“测量”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '04b0d076-3bc8-4549-b757-b08aa083512e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24742, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "取消", "is_correct": false, "explanation": "语义：“取消”是撤销，与“用校服的颜色来区分年级”的用途不符。"}, {"text": "安慰", "is_correct": false, "explanation": "搭配：“安慰”的对象是人，不能说“安慰年级”。"}, {"text": "区分", "is_correct": true, "explanation": "“区分”指用颜色辨别不同的年级，与句意相符。"}, {"text": "推迟", "is_correct": false, "explanation": "配价：“推迟”需要时间或事件作对象，“年级”不能被推迟。"}], "explanations": {"取消": "语义：“取消”是撤销，与“用校服的颜色来区分年级”的用途不符。", "安慰": "搭配：“安慰”的对象是人，不能说“安慰年级”。", "区分": "“区分”指用颜色辨别不同的年级，与句意相符。", "推迟": "配价：“推迟”需要时间或事件作对象，“年级”不能被推迟。"}, "sentence_index": 6, "correct_answer": "区分"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "会计把这个月的工资区分给了三名员工。", "explanation": "这里应该用〈发放〉。区分是把不一样的东西分开，把工资交给员工要用“发放”。"}, {"text": "他用胶水把两块木头区分起来。", "explanation": "这里应该用〈粘合〉。区分是把不一样的东西分开，用胶水把两块木头连在一起要用“粘合”。"}, {"text": "两种颜色区分出了一种新的色调。", "explanation": "这里应该用〈混合〉。区分是把不一样的东西分开，两种颜色合成一种新色调要用“混合”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '04b0d076-3bc8-4549-b757-b08aa083512e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24742, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我先把红豆和绿豆区分了开，再分别煮。", "corrected_sentence": "我先把红豆和绿豆区分开，再分别煮。", "error_description": "错误形式：“区分了开”；正确形式：“区分开”。“区分开”是结果补语结构，“了”不能插在“区分”和“开”之间。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '04b0d076-3bc8-4549-b757-b08aa083512e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24742, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这两个小孩长得很像，但妈妈能区分很清楚。", "corrected_sentence": "这两个小孩长得很像，但妈妈能区分得很清楚。", "error_description": "错误形式：“区分很清楚”；正确形式：“区分得很清楚”。“很清楚”作补语时须用“得”与动词相连。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '04b0d076-3bc8-4549-b757-b08aa083512e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
