INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24746, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "abstract", "definition": "两件事有关系。", "primary_collocate": null, "pronunciation": "guān lián", "ipa": "kwan˥˥ ljɛn˧˥", "syllable_count": 2, "sentences": [{"text": "这两件事互相关联。", "target_word": "关联", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这两个问题紧密关联。", "target_word": "关联", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "天气和心情是否关联，很难说。", "target_word": "关联", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个数据与那张表格相互关联。", "target_word": "关联", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的病与饮食习惯关联着。", "target_word": "关联", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这几个词在意思上互相关联。", "target_word": "关联", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "两个案子好像关联，但没有证据。", "target_word": "关联", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "学习成绩和睡觉时间关联吗？", "target_word": "关联", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这些问题彼此关联，要一起解决。", "target_word": "关联", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "价格和质量并不一定关联。", "target_word": "关联", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "关联了", "label": "体标"}, {"form": "关联着", "label": "体标"}, {"form": "关联性", "label": "复合"}, {"form": "關聯", "label": "繁体"}], "register": "书面", "sense_fingerprint": "事物之间互相有联系", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '80ab50cd-4340-49f3-b7d1-188a43322068') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24746, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "关联", "is_correct": true, "explanation": "关联：两件事之间有关系，与“互相”搭配。"}, {"text": "握手", "is_correct": false, "explanation": "语义：事情不能“握手”，句意说不通。"}, {"text": "吃饭", "is_correct": false, "explanation": "搭配：“互相吃饭”搭配不当，“吃饭”的主体是人。"}, {"text": "拥抱", "is_correct": false, "explanation": "语义：事情不能“拥抱”，句意说不通。"}], "explanations": {"关联": "关联：两件事之间有关系，与“互相”搭配。", "握手": "语义：事情不能“握手”，句意说不通。", "吃饭": "搭配：“互相吃饭”搭配不当，“吃饭”的主体是人。", "拥抱": "语义：事情不能“拥抱”，句意说不通。"}, "sentence_index": 0, "correct_answer": "关联"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我在街上关联了老同学，聊了很久。", "explanation": "这里应该用〈遇见〉。关联指事物之间的关系，偶然碰到人要说遇见。"}, {"text": "他每天都关联一本新书，读得很快。", "explanation": "这里应该用〈读〉。关联指事物之间有关系，读书要用“读”。"}, {"text": "他在学校关联了很多朋友。", "explanation": "这里应该用〈结交〉。关联指事物之间的关系，结识朋友要用结交。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6a064b18-cb72-4871-ba51-bc2dd5ad36d0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24746, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "关联", "is_correct": true, "explanation": "关联：两个案子之间可能有关系，与“好像”搭配。"}, {"text": "睡觉", "is_correct": false, "explanation": "语义：案子不会“睡觉”，句意说不通。"}, {"text": "结婚", "is_correct": false, "explanation": "搭配：“结婚”说人，不说案子结婚，搭配不当。"}, {"text": "下雨", "is_correct": false, "explanation": "语义：“下雨”与案子无关，句意说不通。"}], "explanations": {"关联": "关联：两个案子之间可能有关系，与“好像”搭配。", "睡觉": "语义：案子不会“睡觉”，句意说不通。", "结婚": "搭配：“结婚”说人，不说案子结婚，搭配不当。", "下雨": "语义：“下雨”与案子无关，句意说不通。"}, "sentence_index": 6, "correct_answer": "关联"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我们经常关联学习经验。", "explanation": "这里应该用〈交流〉。关联指事物之间有关系，互相交换经验要用交流。"}, {"text": "老师关联我们明天考试的事情。", "explanation": "这里应该用〈通知〉。关联不表示告知，告诉大家消息要用通知。"}, {"text": "我在班会上关联了新来的同学。", "explanation": "这里应该用〈介绍〉。关联指事物之间有关系，向大家引见新同学要用介绍。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6a064b18-cb72-4871-ba51-bc2dd5ad36d0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24746, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这两个部门很互相关联。", "corrected_sentence": "这两个部门互相关联。", "error_description": "副词位置错误：“很”表程度，不能修饰“互相关联”这类表示相互关系的说法，应去掉“很”，说“互相关联”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6a064b18-cb72-4871-ba51-bc2dd5ad36d0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24746, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这两种现象相互关联着了。", "corrected_sentence": "这两种现象相互关联着。", "error_description": "体标错误：“关联着”表示持续的状态，后面不能再加“了”，应去掉“了”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6a064b18-cb72-4871-ba51-bc2dd5ad36d0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
