INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24748, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "说话时用的词。", "primary_collocate": null, "pronunciation": "yòng yǔ", "ipa": "jʊŋ˥˩ y˨˩˦", "syllable_count": 2, "sentences": [{"text": "他在会上的用语很正式。", "target_word": "用语", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "你和朋友聊天，用语可以随便一点。", "target_word": "用语", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "对客人说话，用语要客气。", "target_word": "用语", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这位老师的用语很简单，学生都听得懂。", "target_word": "用语", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "孩子学了不好的用语，妈妈很着急。", "target_word": "用语", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他的用语让大家很生气。", "target_word": "用语", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "外国人常常不懂这些用语。", "target_word": "用语", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "她说话的用语很有意思。", "target_word": "用语", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "请换一个用语，这样说不太好。", "target_word": "用语", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "说话要注意用语。", "target_word": "用语", "complexity_tier": "T1", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "一个人说话时所用的词语，可以评价客气、正式、随便或不好", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3c7f2601-5d41-4e78-8d42-413e02a40644') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24748, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "用语", "is_correct": true, "explanation": "正确：用语 yòng yǔ，指说话时用的词。"}, {"text": "用于", "is_correct": false, "explanation": "yú（第二声）与 yǔ（第三声）声调不同，yòng yú 意思是“用在……上”，不指说话用的词。"}, {"text": "用以", "is_correct": false, "explanation": "yǐ 与 yǔ 韵母不同（i 与 ü），意思是“用来”，表示目的。"}, {"text": "勇于", "is_correct": false, "explanation": "yǒng 与 yòng 声调不同，yú 与 yǔ 声调也不同，意思是“敢于”。"}], "explanations": {"用语": "正确：用语 yòng yǔ，指说话时用的词。", "用于": "yú（第二声）与 yǔ（第三声）声调不同，yòng yú 意思是“用在……上”，不指说话用的词。", "用以": "yǐ 与 yǔ 韵母不同（i 与 ü），意思是“用来”，表示目的。", "勇于": "yǒng 与 yòng 声调不同，yú 与 yǔ 声调也不同，意思是“敢于”。"}, "sentence_index": null, "correct_answer": "用语"}, "level_3": {"options": [{"text": "用语", "is_correct": true, "explanation": "正确：指他在会上说话所用的词语，与“很正式”相合。"}, {"text": "口音", "is_correct": false, "explanation": "搭配：“正式”修饰措辞或文件，不修饰口音，不能说“口音很正式”。"}, {"text": "天气", "is_correct": false, "explanation": "语义：天气指气候，不是说话的方式，不能用来形容会上的表现。"}, {"text": "身材", "is_correct": false, "explanation": "体貌：身材指人的体型，不能用来描述在会上的说话情况。"}], "explanations": {"用语": "正确：指他在会上说话所用的词语，与“很正式”相合。", "口音": "搭配：“正式”修饰措辞或文件，不修饰口音，不能说“口音很正式”。", "天气": "语义：天气指气候，不是说话的方式，不能用来形容会上的表现。", "身材": "体貌：身材指人的体型，不能用来描述在会上的说话情况。"}, "sentence_index": 0, "correct_answer": "用语"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这块石头的用语很重，搬不动。", "explanation": "这里应该用〈重量〉。用语指说话时用的词，不指物体的轻重，不能说“很重”。"}, {"text": "这杯水的用语很高，不能喝。", "explanation": "这里应该用〈温度〉。用语指说话时用的词，不指冷热，不能说“很高”。"}, {"text": "他的用语很大，把窗户都震破了。", "explanation": "这里应该用〈声音〉。用语指说话时用的词，不指声音的大小；句子说用语震破了窗户，不合常理。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '51d8e2bc-0184-4abe-ade1-561b8f69190c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24748, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "用语", "is_correct": true, "explanation": "正确：指外国人听不懂的这些说话用的词。"}, {"text": "价格", "is_correct": false, "explanation": "语义：价格是金额，不是说话时用的词，句中“不懂”的对象不是价格。"}, {"text": "颜色", "is_correct": false, "explanation": "语义：颜色指色彩，与说话用的词无关，句意不通。"}, {"text": "时间", "is_correct": false, "explanation": "搭配：不说“不懂这些时间”，时间不是需要理解的说法。"}], "explanations": {"用语": "正确：指外国人听不懂的这些说话用的词。", "价格": "语义：价格是金额，不是说话时用的词，句中“不懂”的对象不是价格。", "颜色": "语义：颜色指色彩，与说话用的词无关，句意不通。", "时间": "搭配：不说“不懂这些时间”，时间不是需要理解的说法。"}, "sentence_index": 6, "correct_answer": "用语"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "下大雨了，他的用语全湿透了。", "explanation": "这里应该用〈衣服〉。用语指说话时用的词，不会被雨淋湿，被淋湿的是衣服。"}, {"text": "他的用语增加了五公斤。", "explanation": "这里应该用〈体重〉。用语指说话时用的词，不指重量，不能说“增加了五公斤”。"}, {"text": "这种用语能治好感冒。", "explanation": "这里应该用〈药物〉。用语指说话时用的词，不能用来治病，治感冒要用药物。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '51d8e2bc-0184-4abe-ade1-561b8f69190c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24748, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他说话时常用一条粗俗的用语。", "corrected_sentence": "他说话时常用一句粗俗的用语。", "error_description": "量词错误：“用语”是词语，应用“句”，不用“条”（“条”多用于长条形事物）。正确说法是“一句粗俗的用语”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '51d8e2bc-0184-4abe-ade1-561b8f69190c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24748, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他写信时用了一把得体的用语。", "corrected_sentence": "他写信时用了一句得体的用语。", "error_description": "量词错误：“用语”不用“把”（“把”用于有柄的器具），应用“句”。正确说法是“一句得体的用语”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '51d8e2bc-0184-4abe-ade1-561b8f69190c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
