INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24750, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "提出一个想法让大家一起做。", "primary_collocate": null, "pronunciation": "chàng yì", "ipa": "ʈʂʰɑŋ˥˩ i˥˩", "syllable_count": 2, "sentences": [{"text": "班长提出倡议，周末一起去打扫公园。", "target_word": "倡议", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小李的倡议是大家每天走路上班。", "target_word": "倡议", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们都同意他的倡议，明天早上一起跑步。", "target_word": "倡议", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师发出倡议，请大家带旧书来学校。", "target_word": "倡议", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她的倡议很简单：每周一起做一次饭。", "target_word": "倡议", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "邻居们响应了这个倡议，一起种了花。", "target_word": "倡议", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公司里有人提出倡议，请大家少开车。", "target_word": "倡议", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个倡议很好，我愿意参加。", "target_word": "倡议", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "同学们接受了小王的倡议，一起帮助老人。", "target_word": "倡议", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我的倡议是，大家每天喝八杯水。", "target_word": "倡议", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "倡议书", "label": "复合"}, {"form": "倡议者", "label": "复合"}, {"form": "项", "label": "量词"}], "register": "中性", "sense_fingerprint": "日常里提出的、请大家一起参加的想法或做法", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bf9d64f7-d6db-410b-8410-52799dc0c108') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24750, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "倡议", "is_correct": true, "explanation": "倡议：提出一个想法请大家一起做，与“提出”搭配，也与后面“周末一起去打扫公园”相合。"}, {"text": "证据", "is_correct": false, "explanation": "语义：“证据”是用来证明事情的材料，不能指向“周末一起去打扫公园”这样的行动安排。"}, {"text": "疑问", "is_correct": false, "explanation": "语义：“疑问”是对某事不明白而提出的问题，不是请大家一起去做的想法，与“周末一起去打扫公园”不相合。"}, {"text": "问卷", "is_correct": false, "explanation": "搭配：“提出”一般不和“问卷”搭配，问卷通常说“发出”。"}], "explanations": {"倡议": "倡议：提出一个想法请大家一起做，与“提出”搭配，也与后面“周末一起去打扫公园”相合。", "证据": "语义：“证据”是用来证明事情的材料，不能指向“周末一起去打扫公园”这样的行动安排。", "疑问": "语义：“疑问”是对某事不明白而提出的问题，不是请大家一起去做的想法，与“周末一起去打扫公园”不相合。", "问卷": "搭配：“提出”一般不和“问卷”搭配，问卷通常说“发出”。"}, "sentence_index": 0, "correct_answer": "倡议"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "医生倡议我多睡觉。", "explanation": "这里应该用〈建议〉。倡议是向大家提出一起参与的做法，对一个人的劝告要用建议。"}, {"text": "学校倡议暑假从下周五开始。", "explanation": "这里应该用〈宣布〉。倡议是请大家自愿参与的想法，学校确定暑假的开始时间要用宣布。"}, {"text": "老师倡议我早点睡。", "explanation": "这里应该用〈劝告〉。倡议用于向大家提出共同的做法，老师对某个学生的劝告要用劝告。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '99a869e5-d7c6-4cee-bf7b-58b3f659b231') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24750, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "倡议", "is_correct": true, "explanation": "倡议：提出来请大家一起做的想法，与“提出”搭配，也与“请大家少开车”相合。"}, {"text": "拆解", "is_correct": false, "explanation": "搭配：“拆解”是把物体拆开，不能用来指“大家少开车”这样的想法。"}, {"text": "抄袭", "is_correct": false, "explanation": "语义：“抄袭”是照搬他人的作品，与提出少开车的想法意思不通。"}, {"text": "诅咒", "is_correct": false, "explanation": "语域：“诅咒”是强烈的贬义词，用在公司里的普通说法中语域不合，且意思也不通。"}], "explanations": {"倡议": "倡议：提出来请大家一起做的想法，与“提出”搭配，也与“请大家少开车”相合。", "拆解": "搭配：“拆解”是把物体拆开，不能用来指“大家少开车”这样的想法。", "抄袭": "语义：“抄袭”是照搬他人的作品，与提出少开车的想法意思不通。", "诅咒": "语域：“诅咒”是强烈的贬义词，用在公司里的普通说法中语域不合，且意思也不通。"}, "sentence_index": 6, "correct_answer": "倡议"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我倡议你周末和我一起去看电影。", "explanation": "这里应该用〈提议〉。倡议是向大家提出一起参与的想法，只向一个人发出邀请时要用提议。"}, {"text": "校长倡议全体学生在操场集合。", "explanation": "这里应该用〈命令〉。倡议只是请大家自愿参与的想法，不带强制性；要全体立即执行的事要用命令。"}, {"text": "班主任倡议我明天开会。", "explanation": "这里应该用〈通知〉。倡议用于向大家提出想法，班主任告诉学生开会的时间要用通知。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '99a869e5-d7c6-4cee-bf7b-58b3f659b231') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24750, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这是一个很好地倡议，我们都支持。", "corrected_sentence": "这是一个很好的倡议，我们都支持。", "error_description": "“很好”修饰名词“倡议”，应用“的”而不是“地”：应为“很好的倡议”。“地”用于修饰动词。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '99a869e5-d7c6-4cee-bf7b-58b3f659b231') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24750, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "她提出了一只倡议，希望大家少用塑料袋。", "corrected_sentence": "她提出了一项倡议，希望大家少用塑料袋。", "error_description": "量词用错：“只”用于动物、成对的器官等，不能用来数“倡议”；“倡议”是抽象的想法，应用量词“项”，应为“一项倡议”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '99a869e5-d7c6-4cee-bf7b-58b3f659b231') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
