INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24752, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "为别人出的主意，或对做法提出的意见。", "primary_collocate": null, "pronunciation": "jiàn yì", "ipa": "tɕjɛn˥˩ i˥˩", "syllable_count": 2, "sentences": [{"text": "谢谢你的建议。", "target_word": "建议", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "医生给了我一个好建议。", "target_word": "建议", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我想听听老师的建议。", "target_word": "建议", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "他提出了一个很好的建议。", "target_word": "建议", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这个建议很有用，我马上去做。", "target_word": "建议", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "朋友的建议让我不再担心。", "target_word": "建议", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "你有什么建议，请告诉我们。", "target_word": "建议", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他不听大家的建议，一个人走了。", "target_word": "建议", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "妈妈的建议是早点睡觉。", "target_word": "建议", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我接受了你的建议，换了工作。", "target_word": "建议", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "一个建议", "label": "量词"}, {"form": "一条建议", "label": "量词"}, {"form": "建议书", "label": "复合"}], "register": "中性", "sense_fingerprint": "为别人出的主意、做法上的意见", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c158727a-e2ac-46d3-b271-c699b7ec501e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24752, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "建议", "is_correct": true, "explanation": "建议：对方给的意见，与“谢谢你的”搭配自然。"}, {"text": "威胁", "is_correct": false, "explanation": "语义：“威胁”是对人施压或恐吓，与“谢谢”的感激语气矛盾。"}, {"text": "惊讶", "is_correct": false, "explanation": "搭配：“谢谢你的”后接的是可以感谢的事物，“惊讶”是心理状态，不能作感谢的对象。"}, {"text": "错误", "is_correct": false, "explanation": "语义：“错误”是做错的事，不值得感谢，“谢谢你的错误”说不通。"}], "explanations": {"建议": "建议：对方给的意见，与“谢谢你的”搭配自然。", "威胁": "语义：“威胁”是对人施压或恐吓，与“谢谢”的感激语气矛盾。", "惊讶": "搭配：“谢谢你的”后接的是可以感谢的事物，“惊讶”是心理状态，不能作感谢的对象。", "错误": "语义：“错误”是做错的事，不值得感谢，“谢谢你的错误”说不通。"}, "sentence_index": 0, "correct_answer": "建议"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "工人们建议了一座新大桥。", "explanation": "这里应该用〈建造〉。建议指提出做法让人采纳，不能用来说建造大桥，应说“建造一座新大桥”。"}, {"text": "他向朋友建议了一通电话。", "explanation": "这里应该用〈打〉。建议指提出意见，不能与“电话”搭配，打电话要用“打”。"}, {"text": "他把行李建议到车上。", "explanation": "这里应该用〈搬〉。建议是提出做法，不能表示搬运东西，把行李搬到车上要用“搬”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bd75a825-1ba1-4d13-af2f-d6021369ff4b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24752, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "建议", "is_correct": true, "explanation": "建议：“你有什么建议，请告诉我们”，指可以提出的意见，符合句意。"}, {"text": "脚步", "is_correct": false, "explanation": "语义：“脚步”是走路时的动作，不是可以告诉别人的内容。"}, {"text": "建筑", "is_correct": false, "explanation": "语义：“建筑”是实体物件，不能用“告诉”来表达。"}, {"text": "眼泪", "is_correct": false, "explanation": "搭配：“有什么”后接的应是可以拥有或说出的内容，“眼泪”是流出的，不能作为要告诉的对象。"}], "explanations": {"建议": "建议：“你有什么建议，请告诉我们”，指可以提出的意见，符合句意。", "脚步": "语义：“脚步”是走路时的动作，不是可以告诉别人的内容。", "建筑": "语义：“建筑”是实体物件，不能用“告诉”来表达。", "眼泪": "搭配：“有什么”后接的应是可以拥有或说出的内容，“眼泪”是流出的，不能作为要告诉的对象。"}, "sentence_index": 6, "correct_answer": "建议"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这家公司建议了一台新的电脑。", "explanation": "这里应该用〈购买〉。建议指提出做法，不能表示买东西，买电脑要用“购买”。"}, {"text": "他在墙上建议了一幅画。", "explanation": "这里应该用〈挂〉。建议不能表示把画挂起来，挂画要用“挂”。"}, {"text": "他用抹布建议了桌子。", "explanation": "这里应该用〈擦〉。建议指提出意见，不能表示擦拭桌子，擦桌子要用“擦”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bd75a825-1ba1-4d13-af2f-d6021369ff4b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24752, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这是一把很好的建议。", "corrected_sentence": "这是一个很好的建议。", "error_description": "“建议”的量词应用“个”。“把”用于有柄的器具，不能修饰抽象的建议。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bd75a825-1ba1-4d13-af2f-d6021369ff4b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24752, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我很感激你有用建议。", "corrected_sentence": "我很感激你有用的建议。", "error_description": "形容词“有用”修饰名词“建议”时，中间要加“的”，漏掉“的”就不成立，应写作“有用的建议”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bd75a825-1ba1-4d13-af2f-d6021369ff4b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24754, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "旋律", "is_correct": false, "explanation": "无关：旋律指乐音的连续进行，与抽象性不构成反义或近义关系。"}, {"text": "资金", "is_correct": false, "explanation": "无关：资金指用于经营的钱，与抽象性无关。"}, {"text": "具体性", "is_correct": true, "explanation": "反义：具体性指事物可以看见、感受的特点，与抽象性相对。"}, {"text": "区域", "is_correct": false, "explanation": "无关：区域指一定范围的地方，与抽象性无关。"}], "correct_answer": "具体性", "explanations": {"旋律": "无关：旋律指乐音的连续进行，与抽象性不构成反义或近义关系。", "资金": "无关：资金指用于经营的钱，与抽象性无关。", "具体性": "反义：具体性指事物可以看见、感受的特点，与抽象性相对。", "区域": "无关：区域指一定范围的地方，与抽象性无关。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '212e2189-3a9b-4783-aacf-18bf5e476a5c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24754, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "矿石", "is_correct": false, "explanation": "无关：矿石指天然形成的矿物，与抽象性没有反义关系。"}, {"text": "具体性", "is_correct": true, "explanation": "反义：具体性指事物可以看见、感受的特点，与抽象性相对。"}, {"text": "厨房", "is_correct": false, "explanation": "无关：厨房是做饭的地方，与抽象性无关。"}, {"text": "电压", "is_correct": false, "explanation": "无关：电压是电路中的物理量，与抽象性无关。"}], "correct_answer": "具体性", "explanations": {"矿石": "无关：矿石指天然形成的矿物，与抽象性没有反义关系。", "具体性": "反义：具体性指事物可以看见、感受的特点，与抽象性相对。", "厨房": "无关：厨房是做饭的地方，与抽象性无关。", "电压": "无关：电压是电路中的物理量，与抽象性无关。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '212e2189-3a9b-4783-aacf-18bf5e476a5c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24754, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "property", "definition": "事物不依赖具体形象，摸不到、看不到，只能靠想象或思维把握的特点，如‘爱’‘想法’这类概念。", "primary_collocate": null, "pronunciation": "chōu xiàng xìng", "ipa": "ʈʂʰoʊ˥ ɕjɑŋ˥˩ ɕiŋ˥˩", "syllable_count": 3, "sentences": [{"text": "“爱”的抽象性很强，很难用一句话说清楚。", "target_word": "抽象性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小孩子不容易理解想法的抽象性。", "target_word": "抽象性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个词的抽象性，让我很难画出它的样子。", "target_word": "抽象性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师说，爱和自由都有抽象性。", "target_word": "抽象性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "因为有抽象性，我们看不到也摸不到“友情”。", "target_word": "抽象性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们常用图画来降低概念的抽象性。", "target_word": "抽象性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "数字有抽象性，因为你看不到“三”本身。", "target_word": "抽象性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这本书讲了“美”这个概念的抽象性。", "target_word": "抽象性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "朋友说，“时间”的抽象性让人觉得很神奇。", "target_word": "抽象性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "因为“梦想”有抽象性，所以它没有样子。", "target_word": "抽象性", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "抽象性|摸不到看不到、只能想到的东西的特点", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ce3cdbb2-6def-43dc-9a20-b31c9024b160') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24754, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "抽象性", "is_correct": true, "explanation": "正确。“抽象性很强”指爱没有具体形象，所以很难用一句话说清楚。"}, {"text": "透明度", "is_correct": false, "explanation": "语义：透明度指清楚可见，与“很难用一句话说清楚”相矛盾。"}, {"text": "体积", "is_correct": false, "explanation": "语义：体积指物体占的空间，“爱”没有体积，这样说不通。"}, {"text": "硬度", "is_correct": false, "explanation": "搭配：“硬度”多用于材料，不用来形容爱这样的概念。"}], "explanations": {"抽象性": "正确。“抽象性很强”指爱没有具体形象，所以很难用一句话说清楚。", "透明度": "语义：透明度指清楚可见，与“很难用一句话说清楚”相矛盾。", "体积": "语义：体积指物体占的空间，“爱”没有体积，这样说不通。", "硬度": "搭配：“硬度”多用于材料，不用来形容爱这样的概念。"}, "sentence_index": 0, "correct_answer": "抽象性"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这本小册子的抽象性很高，连小学生都能看懂。", "explanation": "这里应该用〈通俗性〉。通俗性指浅显易懂；抽象性指不依赖具体形象，与“连小学生都能看懂”相矛盾。"}, {"text": "这首诗的抽象性很强，读起来很有画面感。", "explanation": "这里应该用〈形象性〉。形象性指能让人看到具体画面；抽象性指不依赖具体形象，与「很有画面感」相矛盾。"}, {"text": "这份说明书的抽象性很强，每一步都配了清楚的图片。", "explanation": "这里应该用〈具体性〉。每一步都有图片说明的是内容具体、看得见，抽象性正好相反。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '212e2189-3a9b-4783-aacf-18bf5e476a5c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24754, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "抽象性", "is_correct": true, "explanation": "正确。因为看不到“三”本身，所以说数字有抽象性。"}, {"text": "颜色", "is_correct": false, "explanation": "语义：颜色是看得见的，与“看不到”相矛盾。"}, {"text": "形状", "is_correct": false, "explanation": "语义：形状也是可以看见的，与句中“看不到”相矛盾。"}, {"text": "气味", "is_correct": false, "explanation": "搭配：“有气味”用于可以闻到的事物，数字不与“气味”搭配。"}], "explanations": {"抽象性": "正确。因为看不到“三”本身，所以说数字有抽象性。", "颜色": "语义：颜色是看得见的，与“看不到”相矛盾。", "形状": "语义：形状也是可以看见的，与句中“看不到”相矛盾。", "气味": "搭配：“有气味”用于可以闻到的事物，数字不与“气味”搭配。"}, "sentence_index": 6, "correct_answer": "抽象性"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这张照片的抽象性很强，观众一眼就能认出里面的人。", "explanation": "这里应该用〈形象性〉。形象性指能让人看到具体样子；照片里的人能被认出，抽象性说的是看不见的特点，说不通。"}, {"text": "这个想法的抽象性很强，大家一听就懂。", "explanation": "这里应该用〈直观性〉。直观性指一看一听就明白；抽象性指不依赖具体形象、不容易把握，与「一听就懂」相矛盾。"}, {"text": "这个故事的抽象性很强，人物和事情都写得清清楚楚。", "explanation": "这里应该用〈具体性〉。人物和事情写得清清楚楚说明内容具体；抽象性指看不到摸不到、只能靠思维把握的特点。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '212e2189-3a9b-4783-aacf-18bf5e476a5c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24754, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这个概念有一片很强的抽象性，学生很难理解。", "corrected_sentence": "这个概念有一种很强的抽象性，学生很难理解。", "error_description": "量词用错：“片”多用于平面的东西，抽象性应用“种”，即“一种很强的抽象性”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '212e2189-3a9b-4783-aacf-18bf5e476a5c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24754, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这个概念的抽象性强很，孩子们很难想象。", "corrected_sentence": "这个概念的抽象性很强，孩子们很难想象。", "error_description": "语序错：程度副词「很」应放在形容词「强」前面，正确说法是「很强」，不能说「强很」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '212e2189-3a9b-4783-aacf-18bf5e476a5c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24756, 1, 'llm_types_A', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '212e2189-3a9b-4783-aacf-18bf5e476a5c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
