INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24756, 1, 'prompt1_core', '{"pos": "副词", "semantic_class": "function", "definition": "说一个事情是真的。", "primary_collocate": null, "pronunciation": "shì shí shàng", "ipa": "ʂɻ̩˥˩ ʂɻ̩˧˥ ʂɑŋ˥˩", "syllable_count": 3, "sentences": [{"text": "我不是开玩笑，事实上我真的要搬家了。", "target_word": "事实上", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他看上去不累，事实上他已经跑了十公里。", "target_word": "事实上", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你可能不信，事实上这是我第一次坐飞机。", "target_word": "事实上", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "事实上，我昨天就把作业做完了。", "target_word": "事实上", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她说她会做饭，事实上她做得很好吃。", "target_word": "事实上", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "很多人觉得汉语很难，事实上汉语没有那么难。", "target_word": "事实上", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他没骗你，事实上他真的赢了比赛。", "target_word": "事实上", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "事实上，这本书我已经看了三遍。", "target_word": "事实上", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "别担心，事实上这个病很容易好。", "target_word": "事实上", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她很少说话，事实上她是个很热情的人。", "target_word": "事实上", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "说话人强调某件事是真的、确实如此", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ce3cdbb2-6def-43dc-9a20-b31c9024b160') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24756, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "事实上", "is_correct": true, "explanation": "正确：「事实上」强调「我真的要搬家」确实如此，与「不是开玩笑」的语气一致。"}, {"text": "明明", "is_correct": false, "explanation": "搭配：「明明」通常与后文的「却」或「还」呼应，这里没有，搭配不当。"}, {"text": "也许", "is_correct": false, "explanation": "语义：「也许」表示推测，与「不是开玩笑」所强调的确定语气相矛盾。"}, {"text": "幸亏", "is_correct": false, "explanation": "语义：「幸亏」表示庆幸避免了不利，句中没有这层意思。"}], "explanations": {"事实上": "正确：「事实上」强调「我真的要搬家」确实如此，与「不是开玩笑」的语气一致。", "明明": "搭配：「明明」通常与后文的「却」或「还」呼应，这里没有，搭配不当。", "也许": "语义：「也许」表示推测，与「不是开玩笑」所强调的确定语气相矛盾。", "幸亏": "语义：「幸亏」表示庆幸避免了不利，句中没有这层意思。"}, "sentence_index": 0, "correct_answer": "事实上"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "事实上，快把窗户关上！", "explanation": "这里应表示〈命令〉，而「事实上」在「说一个事情是真的」的意思下只用来确认事情属实，不能用来直接发出命令。"}, {"text": "事实上，祝你生日快乐！", "explanation": "这里应表示〈祝福〉，而「事实上」只用来说明事情确实如此，不能用于祝福。"}, {"text": "事实上，好的，我马上去。", "explanation": "这里应表示〈应答〉，而「事实上」只用来确认事情是真的，不能用来回应别人。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '212e2189-3a9b-4783-aacf-18bf5e476a5c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24756, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "事实上", "is_correct": true, "explanation": "正确：「事实上」强调「他真的赢了比赛」，与「没骗你」的辩白语气一致。"}, {"text": "或许", "is_correct": false, "explanation": "语义：「或许」表示不确定，与「没骗你」所强调的确定性相矛盾。"}, {"text": "反而", "is_correct": false, "explanation": "搭配：「反而」要求前文有出乎意料的情况作对照，这里没有，搭配不当。"}, {"text": "势必", "is_correct": false, "explanation": "语域：「势必」是书面语，表示必然，与这句口语化的辩白不搭。"}], "explanations": {"事实上": "正确：「事实上」强调「他真的赢了比赛」，与「没骗你」的辩白语气一致。", "或许": "语义：「或许」表示不确定，与「没骗你」所强调的确定性相矛盾。", "反而": "搭配：「反而」要求前文有出乎意料的情况作对照，这里没有，搭配不当。", "势必": "语域：「势必」是书面语，表示必然，与这句口语化的辩白不搭。"}, "sentence_index": 6, "correct_answer": "事实上"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "事实上，对不起，我来晚了。", "explanation": "这里应表示〈道歉〉，而「事实上」只用来确认事情是真的，不能用来开头表示道歉。"}, {"text": "事实上，你要去哪儿？", "explanation": "这里应表示〈询问〉，而「事实上」只用来确认事情是真的，不能引出疑问句。"}, {"text": "事实上，咱们一起去吃饭吧。", "explanation": "这里应表示〈建议〉，而「事实上」只用来确认事情是真的，不能用来提出建议。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '212e2189-3a9b-4783-aacf-18bf5e476a5c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24756, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我本以为今天会下雨，事实上了天气很好。", "corrected_sentence": "我本以为今天会下雨，事实上天气很好。", "error_description": "错误：「事实上」后面多加了「了」，写成「事实上了」。正确：「事实上」是副词，修饰后面的分句，不带「了」，应写成「事实上天气很好」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '212e2189-3a9b-4783-aacf-18bf5e476a5c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24756, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "大家都以为他已经回家了，事实上却他还在公司。", "corrected_sentence": "大家都以为他已经回家了，事实上他却还在公司。", "error_description": "错误：「却」放在了主语「他」前面。正确：「却」应放在主语之后，写成「事实上他却还在公司」；「事实上却他」不成立。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '212e2189-3a9b-4783-aacf-18bf5e476a5c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
