INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24758, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "指人们必须遵守的规则和法律。", "primary_collocate": null, "pronunciation": "fǎ guī", "ipa": "fa˨˩˦ kweɪ˥", "syllable_count": 2, "sentences": [{"text": "开车要遵守交通法规。", "target_word": "法规", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "国家有很多法规，大家都要遵守。", "target_word": "法规", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "公司要按照法规做事。", "target_word": "法规", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "这项新法规明年正式实施。", "target_word": "法规", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家店违反了法规，要交钱。", "target_word": "法规", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "做生意的人要先了解法规。", "target_word": "法规", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "国家制定了新的法规。", "target_word": "法规", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这条法规是为了保护孩子。", "target_word": "法规", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "法规说，不能在这里抽烟。", "target_word": "法规", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "不懂法规的人容易犯错。", "target_word": "法规", "complexity_tier": "T1", "sentence_source": "generated"}], "morphological_forms": [{"form": "法律法规", "label": "复合"}], "register": "正式", "sense_fingerprint": "人们必须遵守的法律和规则", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a6c53470-eab2-4aaa-a8c7-536b79bbc5b7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24758, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "法规", "is_correct": true, "explanation": "法规是人们必须遵守的规则和法律，和“遵守”搭配，正好说开车要遵守的规定。"}, {"text": "地图", "is_correct": false, "explanation": "搭配：“遵守”的对象是规定，地图不是规则，不能说“遵守交通地图”。"}, {"text": "天气", "is_correct": false, "explanation": "语义：天气是自然现象，不是人必须遵守的东西，句子说不通。"}, {"text": "颜色", "is_correct": false, "explanation": "语义：颜色不是规则，说“遵守交通颜色”没有意义。"}], "explanations": {"法规": "法规是人们必须遵守的规则和法律，和“遵守”搭配，正好说开车要遵守的规定。", "地图": "搭配：“遵守”的对象是规定，地图不是规则，不能说“遵守交通地图”。", "天气": "语义：天气是自然现象，不是人必须遵守的东西，句子说不通。", "颜色": "语义：颜色不是规则，说“遵守交通颜色”没有意义。"}, "sentence_index": 0, "correct_answer": "法规"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "早饭的法规很简单，大家一学就会。", "explanation": "这里应该用〈做法〉。法规是法律性的规定，早饭怎么做要说“做法”。"}, {"text": "物体下落有一定的法规。", "explanation": "这里应该用〈规律〉。法规是人制定的法律性规定，自然界中物体下落的规律要说“规律”。"}, {"text": "家里的法规很多，大家都要守。", "explanation": "这里应该用〈规矩〉。法规指国家或机构的正式规定，家里的要求要说“规矩”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'aa29b907-5038-4975-9c83-47b668cb4b9b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24758, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "法规", "is_correct": true, "explanation": "法规是正式的规则和法律，“制定”的对象正是法规，句子说得通。"}, {"text": "蛋糕", "is_correct": false, "explanation": "搭配：“制定”用于计划、规则，不能用于食物，说“制定蛋糕”不通。"}, {"text": "花园", "is_correct": false, "explanation": "搭配：“制定”用于计划、规则，不能用于地方，说“制定花园”不通。"}, {"text": "饭菜", "is_correct": false, "explanation": "语义：饭菜是食物，不是规定，不能被制定。"}], "explanations": {"法规": "法规是正式的规则和法律，“制定”的对象正是法规，句子说得通。", "蛋糕": "搭配：“制定”用于计划、规则，不能用于食物，说“制定蛋糕”不通。", "花园": "搭配：“制定”用于计划、规则，不能用于地方，说“制定花园”不通。", "饭菜": "语义：饭菜是食物，不是规定，不能被制定。"}, "sentence_index": 6, "correct_answer": "法规"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这家工厂的产品法规很高。", "explanation": "这里应该用〈标准〉。法规是法律性的规定，不能用来说质量的高低。"}, {"text": "做饭的法规很简单，每个人都会。", "explanation": "这里应该用〈流程〉。法规是规定，做饭的步骤要说“流程”。"}, {"text": "他有早起的法规，每天六点起床。", "explanation": "这里应该用〈习惯〉。法规是国家或机构的规定，个人的生活习惯要说“习惯”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'aa29b907-5038-4975-9c83-47b668cb4b9b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24758, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "政府发布了一只新法规。", "corrected_sentence": "政府发布了一项新法规。", "error_description": "错误量词是“只”，正确量词是“项”。“只”用于动物，法规要用“项”或“条”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'aa29b907-5038-4975-9c83-47b668cb4b9b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24758, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "违法规会受到处罚。", "corrected_sentence": "违反法规会受到处罚。", "error_description": "错误形式是“违法规”，正确形式是“违反法规”。“违”要和“反”组成“违反”，才能带“法规”作宾语。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'aa29b907-5038-4975-9c83-47b668cb4b9b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24760, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "趋异", "is_correct": true, "explanation": "趋异与趋同构成反义，指原本相同或相近的事物逐渐变得不一样。"}, {"text": "效率", "is_correct": false, "explanation": "“效率”指单位时间内的工作成果，与“趋同”没有反义关系。"}, {"text": "节奏", "is_correct": false, "explanation": "“节奏”指事物有规律的快慢变化，与“趋同”不构成反义。"}, {"text": "规律", "is_correct": false, "explanation": "“规律”指事物内在的必然联系，与“趋同”不构成反义。"}], "correct_answer": "趋异", "explanations": {"趋异": "趋异与趋同构成反义，指原本相同或相近的事物逐渐变得不一样。", "效率": "“效率”指单位时间内的工作成果，与“趋同”没有反义关系。", "节奏": "“节奏”指事物有规律的快慢变化，与“趋同”不构成反义。", "规律": "“规律”指事物内在的必然联系，与“趋同”不构成反义。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '212e2189-3a9b-4783-aacf-18bf5e476a5c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24760, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "趋异", "is_correct": true, "explanation": "趋异与趋同构成反义，指原本相同或相近的事物逐渐变得不一样。"}, {"text": "方向", "is_correct": false, "explanation": "“方向”指事物所朝的位置，与“趋同”不构成反义。"}, {"text": "结构", "is_correct": false, "explanation": "“结构”指各组成部分的组织和排列，与“趋同”不构成反义。"}, {"text": "年龄", "is_correct": false, "explanation": "“年龄”指人已经活过的年数，与“趋同”不构成反义。"}], "correct_answer": "趋异", "explanations": {"趋异": "趋异与趋同构成反义，指原本相同或相近的事物逐渐变得不一样。", "方向": "“方向”指事物所朝的位置，与“趋同”不构成反义。", "结构": "“结构”指各组成部分的组织和排列，与“趋同”不构成反义。", "年龄": "“年龄”指人已经活过的年数，与“趋同”不构成反义。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '212e2189-3a9b-4783-aacf-18bf5e476a5c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24760, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "abstract", "definition": "指不同的事情慢慢变得一样。", "primary_collocate": null, "pronunciation": "qū tóng", "ipa": "tɕʰy˥ tʰʊŋ˧˥", "syllable_count": 2, "sentences": [{"text": "两个城市的样子慢慢趋同了。", "target_word": "趋同", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "住在一起后，孩子和父母的想法慢慢趋同。", "target_word": "趋同", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "时间长了，两个人的口音趋同了。", "target_word": "趋同", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这两家店的菜单越来越趋同。", "target_word": "趋同", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "大家的穿衣风格正在慢慢趋同。", "target_word": "趋同", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们的看法一开始不同，后来趋同了。", "target_word": "趋同", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "年轻人的爱好有趋同的特点。", "target_word": "趋同", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "慢慢地，两种方言的说法趋同了。", "target_word": "趋同", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "两家公司的产品渐渐趋同。", "target_word": "趋同", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这几年，各地学校的做法趋同。", "target_word": "趋同", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "趨同", "label": "繁体"}, {"form": "趋同化", "label": "复合"}, {"form": "趋同性", "label": "复合"}], "register": "中性", "sense_fingerprint": "趋同|不同的事情慢慢变得一样", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ce3cdbb2-6def-43dc-9a20-b31c9024b160') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24760, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "趋同", "is_correct": true, "explanation": "正确：趋同 qū tóng，指不同的事情慢慢变得一样。"}, {"text": "驱动", "is_correct": false, "explanation": "qū dòng 与 qū tóng 第二音节声母（d 与 t）和声调都不同，意思是推动机器或事物运转。"}, {"text": "去痛", "is_correct": false, "explanation": "qù tòng 与 qū tóng 两个音节的声调都不同，意思是减轻疼痛。"}, {"text": "驱虫", "is_correct": false, "explanation": "qū chóng 与 qū tóng 的第二音节声母不同（t 与 ch），意思是杀灭或驱赶害虫。"}], "explanations": {"趋同": "正确：趋同 qū tóng，指不同的事情慢慢变得一样。", "驱动": "qū dòng 与 qū tóng 第二音节声母（d 与 t）和声调都不同，意思是推动机器或事物运转。", "去痛": "qù tòng 与 qū tóng 两个音节的声调都不同，意思是减轻疼痛。", "驱虫": "qū chóng 与 qū tóng 的第二音节声母不同（t 与 ch），意思是杀灭或驱赶害虫。"}, "sentence_index": null, "correct_answer": "趋同"}, "level_3": {"options": [{"text": "趋同", "is_correct": true, "explanation": "正确：“趋同”指不同的事情慢慢变得一样，与“慢慢”和“样子”搭配。"}, {"text": "对立", "is_correct": false, "explanation": "搭配：“对立”指双方或观点相互冲突，不能用来说城市的样子对立。"}, {"text": "发胖", "is_correct": false, "explanation": "体貌：“发胖”只用于人或动物，不能说城市的样子发胖。"}, {"text": "比较", "is_correct": false, "explanation": "配价：“比较”需要被比较的双方，单独说“样子慢慢比较了”，句子不完整。"}], "explanations": {"趋同": "正确：“趋同”指不同的事情慢慢变得一样，与“慢慢”和“样子”搭配。", "对立": "搭配：“对立”指双方或观点相互冲突，不能用来说城市的样子对立。", "发胖": "体貌：“发胖”只用于人或动物，不能说城市的样子发胖。", "比较": "配价：“比较”需要被比较的双方，单独说“样子慢慢比较了”，句子不完整。"}, "sentence_index": 0, "correct_answer": "趋同"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "两家公司的业务越来越趋同，差别却越来越大。", "explanation": "这里应该用〈分化〉。趋同指原本不同的事物慢慢变得一样，与“差别越来越大”矛盾；说差别越来越大要用〈分化〉。"}, {"text": "这件红外套的颜色慢慢趋同了。", "explanation": "这里应该用〈褪色〉。趋同需要两个或以上的事物逐渐变得一样，单件外套的颜色变淡不能说趋同。"}, {"text": "两人的看法一向趋同。", "explanation": "这里应该用〈一致〉。“一向”表示长期保持的状态，趋同指原本不同的事物逐渐变一样，两者矛盾；描述一直相同用〈一致〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '212e2189-3a9b-4783-aacf-18bf5e476a5c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24760, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "趋同", "is_correct": true, "explanation": "正确：“趋同”修饰“特点”，指爱好逐渐变得一致的特点。"}, {"text": "年迈", "is_correct": false, "explanation": "语义：“年迈”指年纪很大，与“年轻人”的说法相矛盾。"}, {"text": "苍老", "is_correct": false, "explanation": "体貌：“苍老”只说人的样貌，不能用来形容爱好的特点。"}, {"text": "退休", "is_correct": false, "explanation": "语义：“退休”指离开工作岗位，与“年轻人”和“爱好”的意思不相符。"}], "explanations": {"趋同": "正确：“趋同”修饰“特点”，指爱好逐渐变得一致的特点。", "年迈": "语义：“年迈”指年纪很大，与“年轻人”的说法相矛盾。", "苍老": "体貌：“苍老”只说人的样貌，不能用来形容爱好的特点。", "退休": "语义：“退休”指离开工作岗位，与“年轻人”和“爱好”的意思不相符。"}, "sentence_index": 6, "correct_answer": "趋同"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这两个班的教材虽然一直相同，却越来越趋同。", "explanation": "这里应该用〈始终一致〉。趋同指原本不同的事物慢慢变一样，已经一直相同的教材不会“越来越趋同”，前后矛盾。"}, {"text": "这只碗的大小趋同了。", "explanation": "这里应该用〈一样〉。趋同需要两个或两个以上的事物慢慢靠近，单独一只碗不能趋同，比较两者相同要用〈一样〉。"}, {"text": "他的想法今天突然趋同了。", "explanation": "这里应该用〈改变〉。趋同需要两个或以上的事物慢慢变得一样，一个人的想法突然变化不能说趋同。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '212e2189-3a9b-4783-aacf-18bf5e476a5c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24760, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这两家店的装修风格逐渐被趋同了。", "corrected_sentence": "这两家店的装修风格逐渐趋同了。", "error_description": "“趋同”是不及物动词，不能用“被”字句表示被动。应去掉“被”，说“风格逐渐趋同了”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '212e2189-3a9b-4783-aacf-18bf5e476a5c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24760, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这几年，各地学校把教学方法逐渐趋同了。", "corrected_sentence": "这几年，各地学校的教学方法逐渐趋同了。", "error_description": "“趋同”是不及物动词，不能用“把”字句处理它的主语，应说“各地学校的教学方法逐渐趋同了”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '212e2189-3a9b-4783-aacf-18bf5e476a5c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24762, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "缩小", "is_correct": true, "explanation": "“缩小”与“扩展”意思相反，指范围、规模变小。"}, {"text": "思考", "is_correct": false, "explanation": "“思考”与“扩展”没有反义关系，指动脑子想问题。"}, {"text": "休息", "is_correct": false, "explanation": "“休息”与“扩展”没有反义关系，指停下来不做事、恢复精力。"}, {"text": "观察", "is_correct": false, "explanation": "“观察”与“扩展”没有反义关系，指仔细看、察看。"}], "correct_answer": "缩小", "explanations": {"缩小": "“缩小”与“扩展”意思相反，指范围、规模变小。", "思考": "“思考”与“扩展”没有反义关系，指动脑子想问题。", "休息": "“休息”与“扩展”没有反义关系，指停下来不做事、恢复精力。", "观察": "“观察”与“扩展”没有反义关系，指仔细看、察看。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '522a0a63-ca91-46af-bf7c-07bce5feac33') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24762, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "收缩", "is_correct": true, "explanation": "“收缩”与“扩展”意思相反，指面积、体积变小。"}, {"text": "游泳", "is_correct": false, "explanation": "“游泳”与“扩展”没有反义关系，指在水中运动。"}, {"text": "回答", "is_correct": false, "explanation": "“回答”与“扩展”没有反义关系，指对问题作出应答。"}, {"text": "赞美", "is_correct": false, "explanation": "“赞美”与“扩展”没有反义关系，指称赞、夸奖。"}], "correct_answer": "收缩", "explanations": {"收缩": "“收缩”与“扩展”意思相反，指面积、体积变小。", "游泳": "“游泳”与“扩展”没有反义关系，指在水中运动。", "回答": "“回答”与“扩展”没有反义关系，指对问题作出应答。", "赞美": "“赞美”与“扩展”没有反义关系，指称赞、夸奖。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '522a0a63-ca91-46af-bf7c-07bce5feac33') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24762, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "让东西变得更大或更多。", "primary_collocate": null, "pronunciation": "kuò zhǎn", "ipa": "kʰuo⁵¹ ʈʂan²¹⁴", "syllable_count": 2, "sentences": [{"text": "学校想扩展这个操场。", "target_word": "扩展", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "公司准备扩展新的市场。", "target_word": "扩展", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们把店扩展了一倍。", "target_word": "扩展", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个城市在向外扩展。", "target_word": "扩展", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我们想扩展一下自己的知识。", "target_word": "扩展", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老板打算扩展生意。", "target_word": "扩展", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "工厂扩展以后，需要更多工人。", "target_word": "扩展", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家公司正在扩展海外业务。", "target_word": "扩展", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "图书馆扩展了，书也多了。", "target_word": "扩展", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "公园的面积还会继续扩展。", "target_word": "扩展", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "扩展了", "label": "体标"}, {"form": "扩展过", "label": "体标"}, {"form": "扩展性", "label": "复合"}, {"form": "擴展", "label": "繁体"}], "register": "中性", "sense_fingerprint": "使范围、规模、面积变大或变多", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '172f7e52-d98b-43ac-869e-8829631459cd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24762, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "吃", "is_correct": false, "explanation": "搭配：“吃”的对象应是食物，不能说“吃这个操场”。"}, {"text": "感谢", "is_correct": false, "explanation": "配价：“感谢”要带感谢的对象（人或帮助），不能直接带“操场”。"}, {"text": "扩展", "is_correct": true, "explanation": "“扩展”指使操场的范围变大，与“学校想……这个操场”的语境相合。"}, {"text": "唱", "is_correct": false, "explanation": "搭配：“唱”的对象是歌曲，不能说“唱这个操场”。"}], "explanations": {"吃": "搭配：“吃”的对象应是食物，不能说“吃这个操场”。", "感谢": "配价：“感谢”要带感谢的对象（人或帮助），不能直接带“操场”。", "扩展": "“扩展”指使操场的范围变大，与“学校想……这个操场”的语境相合。", "唱": "搭配：“唱”的对象是歌曲，不能说“唱这个操场”。"}, "sentence_index": 0, "correct_answer": "扩展"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他的脾气很扩展，大家都有点怕他。", "explanation": "这里应该用〈暴躁〉。扩展指范围、规模的扩大，形容脾气要用“暴躁”之类的词。"}, {"text": "这个孩子很扩展，老师都很喜欢他。", "explanation": "这里应该用〈活泼〉。扩展是动词，指范围、规模变大，不能用来形容孩子的性格。"}, {"text": "这盘菜很扩展，我吃得很香。", "explanation": "这里应该用〈鲜美〉。扩展指范围、规模变大，形容味道要用“鲜美”之类的词。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '522a0a63-ca91-46af-bf7c-07bce5feac33') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24762, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "缩减", "is_correct": false, "explanation": "语义：“缩减”与后半句“需要更多工人”的意思相矛盾，前后不合理。"}, {"text": "扩展", "is_correct": true, "explanation": "“扩展”指工厂规模变大，扩大后才需要更多工人，前后逻辑合理。"}, {"text": "驾驶", "is_correct": false, "explanation": "搭配：“驾驶”的对象是车辆，不能说“工厂驾驶”。"}, {"text": "咳嗽", "is_correct": false, "explanation": "搭配：“咳嗽”是人或动物的动作，工厂不会咳嗽。"}], "explanations": {"缩减": "语义：“缩减”与后半句“需要更多工人”的意思相矛盾，前后不合理。", "扩展": "“扩展”指工厂规模变大，扩大后才需要更多工人，前后逻辑合理。", "驾驶": "搭配：“驾驶”的对象是车辆，不能说“工厂驾驶”。", "咳嗽": "搭配：“咳嗽”是人或动物的动作，工厂不会咳嗽。"}, "sentence_index": 6, "correct_answer": "扩展"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这个人的眼神很扩展，让人感到害怕。", "explanation": "这里应该用〈凶狠〉。扩展指范围、规模变大，形容眼神要用“凶狠”之类的词。"}, {"text": "这件衣服的颜色很扩展，我很喜欢。", "explanation": "这里应该用〈鲜艳〉。扩展指范围、规模变大，形容颜色要用“鲜艳”之类的词。"}, {"text": "这首歌的旋律很扩展，听起来很舒服。", "explanation": "这里应该用〈优美〉。扩展指范围、规模变大，形容旋律要用“优美”之类的词。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '522a0a63-ca91-46af-bf7c-07bce5feac33') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24762, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我们要把厂房扩展更大。", "corrected_sentence": "我们要把厂房扩展得更大。", "error_description": "错误：“扩展更大”缺少补语标记“得”。正确：“扩展得更大”，“得”引出程度补语，说明扩展后的程度，应为“把……扩展得更大”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '522a0a63-ca91-46af-bf7c-07bce5feac33') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24762, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这家公司已经把海外业务扩展。", "corrected_sentence": "这家公司已经把海外业务扩展了。", "error_description": "错误：“把”字句的谓语动词“扩展”后缺少“了”，句子不完整。正确：“把海外业务扩展了”。“把”字句中动词后通常要有“了”或补语等成分。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '522a0a63-ca91-46af-bf7c-07bce5feac33') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
