INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24764, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "包装东西用的东西。", "primary_collocate": null, "pronunciation": "bāo zhuāng wù", "ipa": "paʊ˥ ʈʂwɑŋ˥ u˥˩", "syllable_count": 3, "sentences": [{"text": "这些旧纸箱是很好的包装物。", "target_word": "包装物", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "超市里的塑料袋也是一种包装物。", "target_word": "包装物", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请把用完的包装物放进回收箱。", "target_word": "包装物", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家工厂专门生产食品包装物。", "target_word": "包装物", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "快递的包装物太多，我们要少用一些。", "target_word": "包装物", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "运玻璃杯的时候，要用软的包装物保护它们。", "target_word": "包装物", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他把礼物外面的包装物小心地拆开了。", "target_word": "包装物", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "泡沫是常见的包装物，可以保护电器。", "target_word": "包装物", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这种包装物不会污染环境，可以放心用。", "target_word": "包装物", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "商店用纸做的包装物，代替了塑料袋。", "target_word": "包装物", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "种", "label": "量词"}, {"form": "批", "label": "量词"}], "register": "中性", "sense_fingerprint": "用来包裹、保护商品的材料或物品，如纸箱、塑料袋、泡沫", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ce3cdbb2-6def-43dc-9a20-b31c9024b160') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24764, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "包装物", "is_correct": true, "explanation": "正确：“包装物”指用来包裹、保护商品的材料或物品，纸箱属于这一类。"}, {"text": "歌曲", "is_correct": false, "explanation": "语义：“歌曲”是一首作品，不是用来包裹、保护商品的物品。"}, {"text": "医生", "is_correct": false, "explanation": "语义：“医生”指人，纸箱不能是医生。"}, {"text": "脸", "is_correct": false, "explanation": "体貌：“脸”只指人的面部，不能说纸箱是很好的脸。"}], "explanations": {"包装物": "正确：“包装物”指用来包裹、保护商品的材料或物品，纸箱属于这一类。", "歌曲": "语义：“歌曲”是一首作品，不是用来包裹、保护商品的物品。", "医生": "语义：“医生”指人，纸箱不能是医生。", "脸": "体貌：“脸”只指人的面部，不能说纸箱是很好的脸。"}, "sentence_index": 0, "correct_answer": "包装物"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他骑着包装物去超市。", "explanation": "这里应该用〈自行车〉。包装物是包装东西用的东西，不能用来骑；“骑”的对象应是自行车。"}, {"text": "他每天穿不同的包装物。", "explanation": "这里应该用〈衣服〉。包装物不能穿在身上，“穿”的对象应是衣服。"}, {"text": "他正在包装物礼物。", "explanation": "这里应该用〈包装〉作动词。包装物是名词，指物品，不能用作“包装”这个动作。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '212e2189-3a9b-4783-aacf-18bf5e476a5c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24764, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "包装物", "is_correct": true, "explanation": "正确：“包装物”指包裹礼物的材料，可以把它拆开。"}, {"text": "思想", "is_correct": false, "explanation": "语义：“思想”不是可以包在礼物外面再拆开的东西。"}, {"text": "心情", "is_correct": false, "explanation": "语义：“心情”是情绪，不能包在礼物外面被拆开。"}, {"text": "声音", "is_correct": false, "explanation": "语义：“声音”看不见摸不着，不能包在礼物外面再拆开。"}], "explanations": {"包装物": "正确：“包装物”指包裹礼物的材料，可以把它拆开。", "思想": "语义：“思想”不是可以包在礼物外面再拆开的东西。", "心情": "语义：“心情”是情绪，不能包在礼物外面被拆开。", "声音": "语义：“声音”看不见摸不着，不能包在礼物外面再拆开。"}, "sentence_index": 6, "correct_answer": "包装物"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他是一位很好的包装物。", "explanation": "这里应该用〈朋友〉。包装物指包装商品的材料或容器，不能用来指人。"}, {"text": "我每天喝大量的包装物。", "explanation": "这里应该用〈饮料〉。包装物是装东西的材料或容器，不能用来喝。"}, {"text": "他的包装物很爱笑。", "explanation": "这里应该用〈性格〉。包装物是包装东西用的东西，不会有“爱笑”这样的性格；说人的脾气要用〈性格〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '212e2189-3a9b-4783-aacf-18bf5e476a5c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24764, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这些纸做的的包装物很环保。", "corrected_sentence": "这些纸做的包装物很环保。", "error_description": "错误：「的」重复了一次。正确：「纸做的包装物」只用一个「的」，应写成「这些纸做的包装物很环保」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '212e2189-3a9b-4783-aacf-18bf5e476a5c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24764, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他把包装物堆很整齐。", "corrected_sentence": "他把包装物堆得很整齐。", "error_description": "补语前漏了“得”：“堆”后的补语要用“堆得很整齐”，漏掉“得”就说不通。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '212e2189-3a9b-4783-aacf-18bf5e476a5c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
