INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24766, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "稍微调整一下东西，让它更合适、更好用。", "primary_collocate": null, "pronunciation": "wēi tiáo", "ipa": "weɪ˥ tiɑʊ˧˥", "syllable_count": 2, "sentences": [{"text": "师傅把椅子的高度微调了一下。", "target_word": "微调", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他微调了一下相机的设置。", "target_word": "微调", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请你把电脑屏幕微调一点。", "target_word": "微调", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师微调了投影仪的角度，画面清楚多了。", "target_word": "微调", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我把闹钟的时间微调了一下，现在更准了。", "target_word": "微调", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "厨师微调了汤的味道，更好喝了。", "target_word": "微调", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他微调了自行车的座位，骑起来舒服多了。", "target_word": "微调", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "工人把机器微调后，声音小了。", "target_word": "微调", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "经理微调了会议室的灯光，大家看得更清楚了。", "target_word": "微调", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这把吉他要再微调一下才好用。", "target_word": "微调", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "微调了", "label": "体标"}, {"form": "微调过", "label": "体标"}, {"form": "微調", "label": "繁体"}], "register": "中性", "sense_fingerprint": "微调|动词|稍微调整东西使其更好用", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '05657b60-f4ba-43e6-a05f-48f26d97bd9f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24766, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "微调", "is_correct": true, "explanation": "正确：微调指稍微调整，“把椅子的高度微调了一下”是常见说法。"}, {"text": "擦亮", "is_correct": false, "explanation": "语义：擦亮指让表面变亮，与椅子的高度无关。"}, {"text": "加热", "is_correct": false, "explanation": "语义：加热是提高温度，不能用来说调整椅子的高度。"}, {"text": "缝补", "is_correct": false, "explanation": "搭配：缝补用于衣物或破损处，不说“缝补高度”。"}], "explanations": {"微调": "正确：微调指稍微调整，“把椅子的高度微调了一下”是常见说法。", "擦亮": "语义：擦亮指让表面变亮，与椅子的高度无关。", "加热": "语义：加热是提高温度，不能用来说调整椅子的高度。", "缝补": "搭配：缝补用于衣物或破损处，不说“缝补高度”。"}, "sentence_index": 0, "correct_answer": "微调"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "师傅微调了坏掉的电脑，它又能开机了。", "explanation": "这里应该用〈维修〉。微调是对能用的东西做小幅调整，坏掉的东西要维修。"}, {"text": "店员微调了坏掉的灯泡，屋子又亮了。", "explanation": "这里应该用〈更换〉。坏掉的灯泡要换新的，不能微调。"}, {"text": "工人微调了旧的栅栏，院子变大了。", "explanation": "这里应该用〈拆除〉。微调只做小幅调整，让院子变大要把旧栅栏拆掉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2df51fa8-9f4e-4e02-8622-3dbc11859208') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24766, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "微调", "is_correct": true, "explanation": "正确：微调指稍微调整，“骑起来舒服多了”说明座位经过细微调整后更好用。"}, {"text": "煮熟", "is_correct": false, "explanation": "语义：煮熟用于食物，与自行车座位无关。"}, {"text": "烫平", "is_correct": false, "explanation": "搭配：烫平多用于衣物，不说“烫平座位”。"}, {"text": "冻结", "is_correct": false, "explanation": "语义：冻结会让东西无法活动，与“骑起来舒服多了”矛盾。"}], "explanations": {"微调": "正确：微调指稍微调整，“骑起来舒服多了”说明座位经过细微调整后更好用。", "煮熟": "语义：煮熟用于食物，与自行车座位无关。", "烫平": "搭配：烫平多用于衣物，不说“烫平座位”。", "冻结": "语义：冻结会让东西无法活动，与“骑起来舒服多了”矛盾。"}, "sentence_index": 6, "correct_answer": "微调"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "师傅微调了断裂的铁架，它又能承重了。", "explanation": "这里应该用〈焊接〉。断裂的铁架要焊接，微调不能把断开的部分连起来。"}, {"text": "她微调了沾满油的锅，锅又干净了。", "explanation": "这里应该用〈清洗〉。沾满油的锅要清洗，微调不能去除污垢。"}, {"text": "他微调了生锈的螺丝，换了新的。", "explanation": "这里应该用〈拆卸〉。生锈的螺丝要先拆下来再换，微调不能完成拆卸这个动作。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2df51fa8-9f4e-4e02-8622-3dbc11859208') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24766, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "妈妈已经微调着炉子的火。", "corrected_sentence": "妈妈已经微调了炉子的火。", "error_description": "错误：“着”用错。正确：应用“了”。“已经”表示动作完成，要用“了”，不能用表示持续的“着”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2df51fa8-9f4e-4e02-8622-3dbc11859208') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24766, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他昨天微调着自行车的座位，骑起来舒服多了。", "corrected_sentence": "他昨天微调了自行车的座位，骑起来舒服多了。", "error_description": "错误：“着”表示动作正在持续，与“昨天”指已完成的动作不符。正确：应用完成标记“了”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2df51fa8-9f4e-4e02-8622-3dbc11859208') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
