INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24768, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'aa29b907-5038-4975-9c83-47b668cb4b9b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24768, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "想办法不让不好的事情发生。", "primary_collocate": null, "pronunciation": "bì miǎn", "ipa": "pi˥˩ mjɛn˨˩˦", "syllable_count": 2, "sentences": [{"text": "过马路时要小心，避免出事故。", "target_word": "避免", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "为了避免迟到，我六点就起床了。", "target_word": "避免", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "多检查几遍可以避免错误。", "target_word": "避免", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他说话很小心，想避免吵架。", "target_word": "避免", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "大家都想避免这样的麻烦。", "target_word": "避免", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请你避免在图书馆大声说话。", "target_word": "避免", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "夏天少吃冷的，可以避免肚子疼。", "target_word": "避免", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "提前做好准备，就能避免问题。", "target_word": "避免", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她避免了一次大危险。", "target_word": "避免", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这样做能避免浪费时间。", "target_word": "避免", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "避免了", "label": "体标"}, {"form": "避免过", "label": "体标"}], "register": "中性", "sense_fingerprint": "设法不让不好的事情发生", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a6c53470-eab2-4aaa-a8c7-536b79bbc5b7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24768, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "制造", "is_correct": false, "explanation": "语义：“制造出事故”与“小心”的意思相反，说不通。"}, {"text": "避免", "is_correct": true, "explanation": "正确：“避免”指设法不让不好的事情发生，与“小心”一致。"}, {"text": "引起", "is_correct": false, "explanation": "语义：“引起事故”与句中的“小心”矛盾。"}, {"text": "参加", "is_correct": false, "explanation": "搭配：“参加”的对象是活动，不能说“参加出事故”。"}], "explanations": {"制造": "语义：“制造出事故”与“小心”的意思相反，说不通。", "避免": "正确：“避免”指设法不让不好的事情发生，与“小心”一致。", "引起": "语义：“引起事故”与句中的“小心”矛盾。", "参加": "搭配：“参加”的对象是活动，不能说“参加出事故”。"}, "sentence_index": 0, "correct_answer": "避免"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这次考试他避免了好成绩。", "explanation": "这里应该用〈取得〉。“避免”只用于不好的事情，“好成绩”是好事，应说“取得好成绩”。"}, {"text": "这次比赛我们避免了胜利。", "explanation": "这里应该用〈获得〉。“避免”只用于不好的事情，“胜利”是好事，应说“获得胜利”。"}, {"text": "他看见车就赶紧避免。", "explanation": "这里应该用〈躲开〉。“避免”是及物动词，要带一件要避开的事，不能单独使用。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'aa29b907-5038-4975-9c83-47b668cb4b9b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24768, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "享受", "is_correct": false, "explanation": "语义：没有人会“享受”肚子疼，句子说不通。"}, {"text": "庆祝", "is_correct": false, "explanation": "语义：肚子疼不是值得庆祝的事。"}, {"text": "避免", "is_correct": true, "explanation": "正确：“避免”表示不让肚子疼发生，与“少吃冷的”的目的一致。"}, {"text": "参观", "is_correct": false, "explanation": "搭配：“参观”不能接“肚子疼”这样的状态。"}], "explanations": {"享受": "语义：没有人会“享受”肚子疼，句子说不通。", "庆祝": "语义：肚子疼不是值得庆祝的事。", "避免": "正确：“避免”表示不让肚子疼发生，与“少吃冷的”的目的一致。", "参观": "搭配：“参观”不能接“肚子疼”这样的状态。"}, "sentence_index": 6, "correct_answer": "避免"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "孩子们避免在床下。", "explanation": "这里应该用〈躲藏〉。“避免”只能用于不好的事情，不能说人躲在某处。"}, {"text": "我们这次避免了获奖。", "explanation": "这里应该用〈错过〉。“避免”只用于不好的事情，“获奖”是好事，不能避免。"}, {"text": "妈妈避免我看电视。", "explanation": "这里应该用〈不让〉。“避免”接的是事情，不能直接接人；要说“妈妈不让我看电视”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'aa29b907-5038-4975-9c83-47b668cb4b9b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24768, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "为了不避免误会，我们把话说清楚了。", "corrected_sentence": "为了避免误会，我们把话说清楚了。", "error_description": "多加了“不”：“避免”本身表示不让事情发生，前面不能再加“不”，应说“为了避免误会”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'aa29b907-5038-4975-9c83-47b668cb4b9b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24768, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "小心驾驶，就能避免到事故。", "corrected_sentence": "小心驾驶，就能避免事故。", "error_description": "多加了“到”：“避免”是及物动词，后面直接接宾语“事故”，不能加“到”，应说“避免事故”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'aa29b907-5038-4975-9c83-47b668cb4b9b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
