INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24772, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2df51fa8-9f4e-4e02-8622-3dbc11859208') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24772, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "想到别的东西。", "primary_collocate": null, "pronunciation": "lián xiǎng", "ipa": "lien˧˥ ɕiɑŋ˨˩˦", "syllable_count": 2, "sentences": [{"text": "看见月亮，我联想到了远方的朋友。", "target_word": "联想", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个图案让人联想到一只鸟。", "target_word": "联想", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他一听到雨声，就联想到小时候的家。", "target_word": "联想", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子看到积木，联想出很多好玩的东西。", "target_word": "联想", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "说到夏天，大家会联想到冰淇淋。", "target_word": "联想", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这种味道让我联想到妈妈做的饭。", "target_word": "联想", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "看着这幅画，你能联想到什么？", "target_word": "联想", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老人看到那座桥，联想起过去的事。", "target_word": "联想", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "一看到黄色，她就联想到香蕉。", "target_word": "联想", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "红色的灯让他联想到过年。", "target_word": "联想", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "联想了", "label": "体标"}, {"form": "联想过", "label": "体标"}, {"form": "聯想", "label": "繁体"}], "register": "中性", "sense_fingerprint": "联想|动词|想到别的东西", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '05657b60-f4ba-43e6-a05f-48f26d97bd9f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24772, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "联想", "is_correct": true, "explanation": "“联想”指看到月亮后想到远方的朋友，与句中“看见月亮”的语境相符。"}, {"text": "洗", "is_correct": false, "explanation": "搭配：“洗”的对象是物品，“朋友”不能被洗。"}, {"text": "修理", "is_correct": false, "explanation": "语义：“修理”指修补损坏的东西，朋友不能被修理。"}, {"text": "揣度", "is_correct": false, "explanation": "语域：“揣度”是书面词，后面要接判断性的内容，用在这样的叙述里不协调。"}], "explanations": {"联想": "“联想”指看到月亮后想到远方的朋友，与句中“看见月亮”的语境相符。", "洗": "搭配：“洗”的对象是物品，“朋友”不能被洗。", "修理": "语义：“修理”指修补损坏的东西，朋友不能被修理。", "揣度": "语域：“揣度”是书面词，后面要接判断性的内容，用在这样的叙述里不协调。"}, "sentence_index": 0, "correct_answer": "联想"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "工人用胶水联想了两块木板。", "explanation": "这里应该用〈粘接〉。联想是在头脑中想到别的东西，不能用胶水把木板连在一起；把两块木板粘接在一起要用粘接。"}, {"text": "工人用手推车联想了几箱货物。", "explanation": "这里应该用〈搬运〉。联想是在头脑中想到别的东西，不能用手推车运送货物；把几箱货物运走要用搬运。"}, {"text": "我联想明天的比赛一定能赢。", "explanation": "这里应该用〈推测〉。联想不能用来对将要发生的结果作判断，对将来的情况作推测要用推测。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2df51fa8-9f4e-4e02-8622-3dbc11859208') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24772, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "联想", "is_correct": true, "explanation": "“联想”指由这幅画引出想到的事物，与“看着这幅画”的语境相符。"}, {"text": "品尝", "is_correct": false, "explanation": "搭配：“品尝”的对象是食物或味道，画不能被品尝。"}, {"text": "嗅", "is_correct": false, "explanation": "语义：“嗅”是用鼻子闻气味，句中的语境是看画，无法嗅到。"}, {"text": "思忖", "is_correct": false, "explanation": "语域：“思忖”偏书面，后面要接判断性的内容，用在这样的口语提问里不协调。"}], "explanations": {"联想": "“联想”指由这幅画引出想到的事物，与“看着这幅画”的语境相符。", "品尝": "搭配：“品尝”的对象是食物或味道，画不能被品尝。", "嗅": "语义：“嗅”是用鼻子闻气味，句中的语境是看画，无法嗅到。", "思忖": "语域：“思忖”偏书面，后面要接判断性的内容，用在这样的口语提问里不协调。"}, "sentence_index": 6, "correct_answer": "联想"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "工人们把那座旧桥联想拆掉了。", "explanation": "这里应该用〈拆〉。联想是在头脑中想到别的东西，不能指拆除实物；拆掉旧桥要用拆。"}, {"text": "厨师把那块鱼联想切成了片。", "explanation": "这里应该用〈切〉。联想是在头脑中想到别的东西，不能指切割食物；把鱼切成片要用切。"}, {"text": "我联想明天会下雨。", "explanation": "这里应该用〈估计〉。联想是由眼前事物想到相关事物，对将来的天气作判断要用估计。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2df51fa8-9f4e-4e02-8622-3dbc11859208') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24772, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "一闻到咖啡香，她就联想在了小镇的早晨。", "corrected_sentence": "一闻到咖啡香，她就联想到了小镇的早晨。", "error_description": "错误：“联想在”；正确：“联想到”。“联想”后面要用补语“到”引出想到的事物，不能用“在”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2df51fa8-9f4e-4e02-8622-3dbc11859208') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24772, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "红色的灯让他联想了春节的庆典。", "corrected_sentence": "红色的灯让他联想到了春节的庆典。", "error_description": "错误：“联想了”；正确：“联想到了”。“联想”后面要用补语“到”引出想到的事物，漏掉“到”就不通。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2df51fa8-9f4e-4e02-8622-3dbc11859208') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
