INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24776, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "用数字来表示信息的方法。", "primary_collocate": null, "pronunciation": "shù zì biān mǎ", "ipa": "ʂu˥˩ tsɨ˥˩ pjɛn˥ ma˨˩˦", "syllable_count": 4, "sentences": [{"text": "这种数字编码的方法很简单。", "target_word": "数字编码", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "条形码用的就是一种数字编码。", "target_word": "数字编码", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "用数字编码，一个字可以变成几个数。", "target_word": "数字编码", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "老师教我们用数字编码写秘密信息。", "target_word": "数字编码", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "战争时期，他们用数字编码传送消息。", "target_word": "数字编码", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这个游戏用数字编码表示不同的颜色。", "target_word": "数字编码", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "数字编码的规则要先让大家都知道。", "target_word": "数字编码", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "邮政编码也是数字编码的一种。", "target_word": "数字编码", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我设计了一个简单的数字编码，来表示十种水果。", "target_word": "数字编码", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们用数字编码代替名字，保护大家的隐私。", "target_word": "数字编码", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "数字编码系统", "label": "复合"}, {"form": "數字編碼", "label": "繁体"}], "register": "中性", "sense_fingerprint": "数字编码：用数字表示信息的方法", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '05657b60-f4ba-43e6-a05f-48f26d97bd9f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24776, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "数字编码", "is_correct": true, "explanation": "正确：数字编码是用数字表示信息的方法，“这种……的方法很简单”说得通。"}, {"text": "地震", "is_correct": false, "explanation": "语义：地震是地质现象，不是一种方法，“这种地震的方法”说不通。"}, {"text": "心脏", "is_correct": false, "explanation": "语义：心脏是器官，不能被当作一种方法来描述。"}, {"text": "文物", "is_correct": false, "explanation": "语义：文物是历史遗物，与“方法很简单”的说法不搭。"}], "explanations": {"数字编码": "正确：数字编码是用数字表示信息的方法，“这种……的方法很简单”说得通。", "地震": "语义：地震是地质现象，不是一种方法，“这种地震的方法”说不通。", "心脏": "语义：心脏是器官，不能被当作一种方法来描述。", "文物": "语义：文物是历史遗物，与“方法很简单”的说法不搭。"}, "sentence_index": 0, "correct_answer": "数字编码"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "老师教我们用这只数字编码写秘密信息。", "explanation": "这里应该用〈种〉。“只”用于动物或单件物品，数字编码是方法，应说“这种数字编码”。"}, {"text": "老师教我们用数字编码计算面积。", "explanation": "这里应该用〈公式〉。数字编码是把信息转成数字的方法，不能用来算面积；计算面积要用〈公式〉。"}, {"text": "老师教我们用数字编码放松心情。", "explanation": "这里应该用〈音乐〉。数字编码是用数字表示信息的方法，不能用来放松心情；放松心情要用〈音乐〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2df51fa8-9f4e-4e02-8622-3dbc11859208') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24776, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "数字编码", "is_correct": true, "explanation": "正确：数字编码是一种信息表示方法，“数字编码的规则”指它的使用规则，语境相符。"}, {"text": "感冒", "is_correct": false, "explanation": "搭配：感冒是疾病，没有需要让大家知道的“规则”。"}, {"text": "台风", "is_correct": false, "explanation": "语义：台风是天气现象，不存在需要提前让大家知道的“规则”。"}, {"text": "洪水", "is_correct": false, "explanation": "语义：洪水是自然灾害，“洪水的规则”说不通。"}], "explanations": {"数字编码": "正确：数字编码是一种信息表示方法，“数字编码的规则”指它的使用规则，语境相符。", "感冒": "搭配：感冒是疾病，没有需要让大家知道的“规则”。", "台风": "语义：台风是天气现象，不存在需要提前让大家知道的“规则”。", "洪水": "语义：洪水是自然灾害，“洪水的规则”说不通。"}, "sentence_index": 6, "correct_answer": "数字编码"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "工人们用数字编码修好了桌子。", "explanation": "这里应该用〈工具〉。数字编码是信息的表示方法，不能用来修理桌子；修桌子要用〈工具〉。"}, {"text": "孩子们在台上用数字编码跳了一支舞。", "explanation": "这里应该用〈身体〉。数字编码是用数字表示信息的方法，不能用来跳舞；跳舞要用〈身体〉。"}, {"text": "他用数字编码喝了一杯水。", "explanation": "这里应该用〈杯子〉。数字编码不能盛水；喝水要用〈杯子〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2df51fa8-9f4e-4e02-8622-3dbc11859208') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24776, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他用一只数字编码表示颜色。", "corrected_sentence": "他用一种数字编码表示颜色。", "error_description": "量词错：数字编码应说“一种”，不用“只”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2df51fa8-9f4e-4e02-8622-3dbc11859208') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24776, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他们用一把数字编码代替名字。", "corrected_sentence": "他们用一种数字编码代替名字。", "error_description": "量词错：数字编码应说“一种”，“把”用于有柄的器具，不能用于数字编码。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2df51fa8-9f4e-4e02-8622-3dbc11859208') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
