INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24784, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "用手或东西对着一个地方。", "primary_collocate": null, "pronunciation": "zhǐ xiàng", "ipa": "ʈʂɻ̩˨˩˦ ɕjɑŋ˥˩", "syllable_count": 2, "sentences": [{"text": "小朋友伸手指向天上的月亮。", "target_word": "指向", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他用木棍指向地上的洞。", "target_word": "指向", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "警察伸出手，指向那辆红车。", "target_word": "指向", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "请把手电筒指向门口。", "target_word": "指向", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她指向桌上的苹果，说想吃。", "target_word": "指向", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "门口的牌子指向厕所。", "target_word": "指向", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "老人指向远处，说那就是他的家。", "target_word": "指向", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "风向标指向东边。", "target_word": "指向", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "导游举起小旗，指向前面的山。", "target_word": "指向", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "他把望远镜指向了月亮。", "target_word": "指向", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "指向了", "label": "体标"}, {"form": "指向着", "label": "体标"}, {"form": "指向性", "label": "复合"}], "register": "中性", "sense_fingerprint": "用手或物体对着某个地方", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '08c39e3c-4375-4f78-8873-c3b87ac6f5e8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24784, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "指向", "is_correct": true, "explanation": "指向：zhǐ xiàng，用手或物体对着一个地方。"}, {"text": "志向", "is_correct": false, "explanation": "zhì（第四声）与 zhǐ（第三声）声调不同，志向指人的理想和追求，与指向意思不同。"}, {"text": "纸箱", "is_correct": false, "explanation": "xiāng（第一声）与 xiàng（第四声）声调不同，纸箱指用纸做成的箱子。"}, {"text": "只限", "is_correct": false, "explanation": "xiàn 与 xiàng 韵母不同（-an 与 -ang），只限意思是仅限于。"}], "explanations": {"指向": "指向：zhǐ xiàng，用手或物体对着一个地方。", "志向": "zhì（第四声）与 zhǐ（第三声）声调不同，志向指人的理想和追求，与指向意思不同。", "纸箱": "xiāng（第一声）与 xiàng（第四声）声调不同，纸箱指用纸做成的箱子。", "只限": "xiàn 与 xiàng 韵母不同（-an 与 -ang），只限意思是仅限于。"}, "sentence_index": null, "correct_answer": "指向"}, "level_3": {"options": [{"text": "指向", "is_correct": true, "explanation": "指向：此处表示伸手对着天上的月亮，符合句意。"}, {"text": "擦", "is_correct": false, "explanation": "语义：「擦」指擦拭物体表面，不能用来擦天上的月亮。"}, {"text": "踢", "is_correct": false, "explanation": "语义：「踢」是用脚击打，无法踢到天上的月亮。"}, {"text": "洗", "is_correct": false, "explanation": "搭配：「洗」用于洗涤物品，不能与天上的月亮搭配。"}], "explanations": {"指向": "指向：此处表示伸手对着天上的月亮，符合句意。", "擦": "语义：「擦」指擦拭物体表面，不能用来擦天上的月亮。", "踢": "语义：「踢」是用脚击打，无法踢到天上的月亮。", "洗": "搭配：「洗」用于洗涤物品，不能与天上的月亮搭配。"}, "sentence_index": 0, "correct_answer": "指向"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "老师指向了我的努力。", "explanation": "这里应该用〈表扬〉。表扬是称赞人的努力，指向只表示用手或物体对着某个地方，不能用于努力这类抽象事物。"}, {"text": "警察指向了这起案件。", "explanation": "这里应该用〈调查〉。调查是查明事实，指向只表示用手或东西对着一个地方，不能用于案件。"}, {"text": "他指向了我的道歉。", "explanation": "这里应该用〈接受〉。接受是收下对方的道歉，指向只表示对着某个方向，不能用于道歉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3a006eb5-8ab0-4166-b354-14c01c2e7e95') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24784, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "指向", "is_correct": true, "explanation": "指向：zhǐ xiàng，用手或物体对着一个地方。"}, {"text": "志向", "is_correct": false, "explanation": "zhì（第四声）与 zhǐ（第三声）声调不同，志向指人的理想和追求。"}, {"text": "纸样", "is_correct": false, "explanation": "yàng 与 xiàng 声母不同（y 与 x），纸样指纸制的样板。"}, {"text": "纸线", "is_correct": false, "explanation": "xiàn 与 xiàng 韵母不同（-an 与 -ang），纸线指用纸搓成的线。"}], "explanations": {"指向": "指向：zhǐ xiàng，用手或物体对着一个地方。", "志向": "zhì（第四声）与 zhǐ（第三声）声调不同，志向指人的理想和追求。", "纸样": "yàng 与 xiàng 声母不同（y 与 x），纸样指纸制的样板。", "纸线": "xiàn 与 xiàng 韵母不同（-an 与 -ang），纸线指用纸搓成的线。"}, "sentence_index": null, "correct_answer": "指向"}, "level_3": {"options": [{"text": "指向", "is_correct": true, "explanation": "指向：此处表示老人用手对着远处示意，符合句意。"}, {"text": "拆", "is_correct": false, "explanation": "语义：「拆」指拆除或分解，不能拆掉一个方向。"}, {"text": "搬", "is_correct": false, "explanation": "搭配：「搬」指移动物品，不能搬动远处的方向。"}, {"text": "推", "is_correct": false, "explanation": "语义：「推」指用力使物体移动，不能用来表示指示方向。"}], "explanations": {"指向": "指向：此处表示老人用手对着远处示意，符合句意。", "拆": "语义：「拆」指拆除或分解，不能拆掉一个方向。", "搬": "搭配：「搬」指移动物品，不能搬动远处的方向。", "推": "语义：「推」指用力使物体移动，不能用来表示指示方向。"}, "sentence_index": 6, "correct_answer": "指向"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他指向了我的看法。", "explanation": "这里应该用〈赞同〉。赞同表示同意，指向只表示用手或物体对着某个地方，不能表示同意别人的看法。"}, {"text": "他指向了大家的帮助。", "explanation": "这里应该用〈感谢〉。感谢是对别人的帮助表示谢意，指向只表示用手或物体对着某个地方，不能用于帮助。"}, {"text": "妈妈指向了我的进步。", "explanation": "这里应该用〈夸奖〉。夸奖是称赞别人，指向只表示对着某个地方，不能用来称赞。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3a006eb5-8ab0-4166-b354-14c01c2e7e95') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24784, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我用手向指向那棵大树。", "corrected_sentence": "我用手指向那棵大树。", "error_description": "「指向」本身已经包含方向义，前面不能再加介词「向」。应说「我用手指向那棵大树」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3a006eb5-8ab0-4166-b354-14c01c2e7e95') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24784, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他了指向窗外的鸟群。", "corrected_sentence": "他指向窗外的鸟群。", "error_description": "「了」误放在动词「指向」之前，应删去；删去后「他指向窗外的鸟群」成立。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3a006eb5-8ab0-4166-b354-14c01c2e7e95') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
