INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24788, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "大家一起说想法，找答案。", "primary_collocate": null, "pronunciation": "tàn tǎo", "ipa": "tʰan˥˩ tʰɑʊ̯˨˩˦", "syllable_count": 2, "sentences": [{"text": "我们几个同学一起探讨这道难题。", "target_word": "探讨", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "吃完饭，大家坐下来探讨旅行计划。", "target_word": "探讨", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "小组成员正在探讨怎么做海报。", "target_word": "探讨", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "周末我们想一起探讨一下这个办法。", "target_word": "探讨", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "大家围着桌子探讨明天的活动。", "target_word": "探讨", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我和朋友常常探讨怎样学好汉语。", "target_word": "探讨", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "全家人一起探讨孩子的教育问题。", "target_word": "探讨", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "同事们开会探讨新产品的名字。", "target_word": "探讨", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "各位请先冷静，坐下来共同探讨一下。", "target_word": "探讨", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "同学们在课上探讨这个问题的答案。", "target_word": "探讨", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "探讨了", "label": "体标"}, {"form": "探讨过", "label": "体标"}], "register": "书面", "sense_fingerprint": "大家聚在一起交换想法，共同寻找答案", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '08c39e3c-4375-4f78-8873-c3b87ac6f5e8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24788, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "探讨", "is_correct": true, "explanation": "正确：「探讨」指大家一起交换想法、找答案，与“一起探讨这道难题”相符。"}, {"text": "搬", "is_correct": false, "explanation": "配价：“搬”的宾语应是具体物品，不能搬“难题”。"}, {"text": "擦", "is_correct": false, "explanation": "语义：“擦”是抹去物体表面的动作，不能擦“难题”。"}, {"text": "烤", "is_correct": false, "explanation": "语义：“烤”是用火加热食物，与想法交流的意思不符。"}], "explanations": {"探讨": "正确：「探讨」指大家一起交换想法、找答案，与“一起探讨这道难题”相符。", "搬": "配价：“搬”的宾语应是具体物品，不能搬“难题”。", "擦": "语义：“擦”是抹去物体表面的动作，不能擦“难题”。", "烤": "语义：“烤”是用火加热食物，与想法交流的意思不符。"}, "sentence_index": 0, "correct_answer": "探讨"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他去邻居家探讨钥匙。", "explanation": "这里应该用〈借〉。探讨是大家交换想法，不能用于借还具体的东西。"}, {"text": "我们去探讨一下这家饭馆的菜。", "explanation": "这里应该用〈品尝〉。探讨的对象是想法或办法，不能是菜。"}, {"text": "工人们在海底探讨了一块石头。", "explanation": "这里应该用〈捡〉。探讨是大家交换想法，不能用于捡拾具体的石头。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3a006eb5-8ab0-4166-b354-14c01c2e7e95') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24788, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "探讨", "is_correct": true, "explanation": "正确：「探讨」指大家一起交换想法、找答案，与“一起探讨孩子的教育问题”相符。"}, {"text": "拆", "is_correct": false, "explanation": "配价：“拆”要求具体的宾语，不能拆“教育问题”。"}, {"text": "洗", "is_correct": false, "explanation": "语义：“洗”是清洗东西的动作，与讨论问题不符。"}, {"text": "缝", "is_correct": false, "explanation": "语义：“缝”是用针线连接布料，与交换想法的意思不符。"}], "explanations": {"探讨": "正确：「探讨」指大家一起交换想法、找答案，与“一起探讨孩子的教育问题”相符。", "拆": "配价：“拆”要求具体的宾语，不能拆“教育问题”。", "洗": "语义：“洗”是清洗东西的动作，与讨论问题不符。", "缝": "语义：“缝”是用针线连接布料，与交换想法的意思不符。"}, "sentence_index": 6, "correct_answer": "探讨"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "孩子们围在一起探讨那个小朋友。", "explanation": "这里应该用〈关心〉。探讨的对象是想法或办法，不能是某个人。"}, {"text": "孩子们围在一起探讨这个蛋糕。", "explanation": "这里应该用〈吃〉。探讨的对象是问题或办法，不能是食物。"}, {"text": "孩子们围在一起探讨那把椅子。", "explanation": "这里应该用〈搬〉。探讨不能用于搬动的具体物件。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3a006eb5-8ab0-4166-b354-14c01c2e7e95') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24788, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我们几个朋友一起探讨很热烈。", "corrected_sentence": "我们几个朋友一起探讨得很热烈。", "error_description": "“探讨”后面作程度补语时要用“得”。应说“探讨得很热烈”，漏掉“得”就不通顺。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3a006eb5-8ab0-4166-b354-14c01c2e7e95') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24788, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "大家正在在探讨这个游戏的规则。", "corrected_sentence": "大家正在探讨这个游戏的规则。", "error_description": "“正在”已经表示进行，后面不能再加“在”。应说“大家正在探讨这个游戏的规则”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3a006eb5-8ab0-4166-b354-14c01c2e7e95') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
