INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24790, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "说话或写文章时让表达更好听、更有效的方法。", "primary_collocate": null, "pronunciation": "xiū cí", "ipa": "ɕjoʊ˥ tsʰɨ˧˥", "syllable_count": 2, "sentences": [{"text": "学习修辞可以让文章更生动。", "target_word": "修辞", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他写文章很讲究修辞，大家都爱读。", "target_word": "修辞", "complexity_tier": "T3", "furigana": "tā xiě wénzhāng hěn jiǎngjiu xiūcí, dàjiā dōu ài dú.", "sentence_source": "generated"}, {"text": "写作文时，你可以多用一点修辞。", "target_word": "修辞", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这位作家的修辞很丰富。", "target_word": "修辞", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "排比是一种有力的修辞。", "target_word": "修辞", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "语文课上，老师讲了几种修辞。", "target_word": "修辞", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他说话不讲修辞，但很清楚。", "target_word": "修辞", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这句话的修辞让人印象很深。", "target_word": "修辞", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "新闻稿里的修辞不能太多。", "target_word": "修辞", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "演讲者靠修辞打动了听众。", "target_word": "修辞", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [], "register": "书面", "sense_fingerprint": "修辞：名词，说话写文章时使表达更好听、更有效的方法", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e01db3e0-aba5-44e5-92e3-89627e0736ec') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24790, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "修辞", "is_correct": true, "explanation": "正确答案。修辞是名词，指说话写文章时让表达更好的方法，与“学习”搭配，符合句意。"}, {"text": "食谱", "is_correct": false, "explanation": "语义：食谱指菜谱，学习食谱不能让文章更生动，句意不通。"}, {"text": "账本", "is_correct": false, "explanation": "搭配：“学习账本”与“让文章更生动”没有关系，不是常见搭配。"}, {"text": "汤", "is_correct": false, "explanation": "语义：汤指食物，与文章的生动性无关，句子不成立。"}], "explanations": {"修辞": "正确答案。修辞是名词，指说话写文章时让表达更好的方法，与“学习”搭配，符合句意。", "食谱": "语义：食谱指菜谱，学习食谱不能让文章更生动，句意不通。", "账本": "搭配：“学习账本”与“让文章更生动”没有关系，不是常见搭配。", "汤": "语义：汤指食物，与文章的生动性无关，句子不成立。"}, "sentence_index": 0, "correct_answer": "修辞"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "妈妈用修辞把菜炒得很香。", "explanation": "这里应该用〈调料〉。修辞是说话写文章的表达方法，不能用来炒菜。"}, {"text": "他把头发修辞得很漂亮。", "explanation": "修辞的意思是说话写文章时让表达更好的方法，只用于语言文字，不能用于头发。"}, {"text": "园丁修辞了花枝。", "explanation": "这里应该用〈修剪〉。修辞指说话写文章时的表达方法，不能用来修剪花枝。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ea69a300-08e8-4927-8974-98338482547b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24790, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "修辞", "is_correct": true, "explanation": "正确答案。修辞指让表达更好听、更有效的方法，与“不讲”搭配，并与“但很清楚”形成对比。"}, {"text": "天气", "is_correct": false, "explanation": "搭配：“不讲天气”不是常见搭配，天气与说话的讲究无关。"}, {"text": "鞋子", "is_correct": false, "explanation": "搭配：“不讲鞋子”搭配不当，鞋子与说话的方式无关。"}, {"text": "厨房", "is_correct": false, "explanation": "语义：厨房是场所，不是可以讲究或不讲究的对象，句意不通。"}], "explanations": {"修辞": "正确答案。修辞指让表达更好听、更有效的方法，与“不讲”搭配，并与“但很清楚”形成对比。", "天气": "搭配：“不讲天气”不是常见搭配，天气与说话的讲究无关。", "鞋子": "搭配：“不讲鞋子”搭配不当，鞋子与说话的方式无关。", "厨房": "语义：厨房是场所，不是可以讲究或不讲究的对象，句意不通。"}, "sentence_index": 6, "correct_answer": "修辞"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这双鞋的修辞很合脚。", "explanation": "修辞指说话写文章时的表达方法，不能用来说鞋子合不合脚。"}, {"text": "这台电脑的修辞坏了。", "explanation": "修辞指表达的方法，不是能坏的器物，不能用于电脑。"}, {"text": "他把坏椅子修辞好了。", "explanation": "这里应该用〈修理〉。修辞指说话写文章时的表达方法，不能用来指修理器物。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ea69a300-08e8-4927-8974-98338482547b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24790, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这本书介绍了几本修辞。", "corrected_sentence": "这本书介绍了几种修辞。", "error_description": "错误形式“几本修辞”量词用错了：“本”用于书籍，“修辞”是表达方法，应该用量词“种”。正确形式为“几种修辞”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ea69a300-08e8-4927-8974-98338482547b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24790, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "演讲者用了很修辞，听众很感动。", "corrected_sentence": "演讲者用了修辞，听众很感动。", "error_description": "错误在于名词“修辞”前加了程度副词“很”，名词不能受“很”修饰。正确形式去掉“很”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ea69a300-08e8-4927-8974-98338482547b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
