INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24792, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bd75a825-1ba1-4d13-af2f-d6021369ff4b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24792, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "回头检查自己的言行，总结经验教训。", "primary_collocate": null, "pronunciation": "fǎn sī", "ipa": "fan˨˩˦ sɹ̩˥˥", "syllable_count": 2, "sentences": [{"text": "考试没考好，我在认真反思。", "target_word": "反思", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "你应该好好反思一下。", "target_word": "反思", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "他反思了自己的错误。", "target_word": "反思", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "吵架以后，我们都在反思。", "target_word": "反思", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "老师让我们反思这次比赛。", "target_word": "反思", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "每天睡前，她都会反思自己做的事。", "target_word": "反思", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他反思着这一年的得失。", "target_word": "反思", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "输了比赛，教练带大家一起反思。", "target_word": "反思", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "你不反思，下次还会做错。", "target_word": "反思", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我在日记里反思自己的问题。", "target_word": "反思", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "反思了", "label": "完成体"}, {"form": "反思着", "label": "持续体"}, {"form": "反思过", "label": "经历体"}], "register": "中性", "sense_fingerprint": "回头检查自己的言行并总结教训", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c158727a-e2ac-46d3-b271-c699b7ec501e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24792, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "反思", "is_correct": true, "explanation": "正确：“反思”指回头检查自己的问题，与“考试没考好”的语境相符。"}, {"text": "庆祝", "is_correct": false, "explanation": "语义：考试没考好，不值得庆祝，与语境矛盾。"}, {"text": "忘记", "is_correct": false, "explanation": "配价：“忘记”后面要带所忘的内容，“认真忘记”没有宾语，句意也不通。"}, {"text": "欢呼", "is_correct": false, "explanation": "语义：没考好却欢呼，与语境正好相反。"}], "explanations": {"反思": "正确：“反思”指回头检查自己的问题，与“考试没考好”的语境相符。", "庆祝": "语义：考试没考好，不值得庆祝，与语境矛盾。", "忘记": "配价：“忘记”后面要带所忘的内容，“认真忘记”没有宾语，句意也不通。", "欢呼": "语义：没考好却欢呼，与语境正好相反。"}, "sentence_index": 0, "correct_answer": "反思"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "老师反思了他。", "explanation": "这里应该用〈批评〉。“批评”是指出别人的错误，“反思”只用于自己回头检查，不能指别人。"}, {"text": "他日夜反思远方的家人。", "explanation": "这里应该用〈思念〉。“思念”指想念远方的人，“反思”指自我检查，不能用于想念亲人。"}, {"text": "镜子能反思光线。", "explanation": "这里应该用〈反射〉。光线被镜面送回叫“反射”，“反思”只用于人回顾自己的言行。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bd75a825-1ba1-4d13-af2f-d6021369ff4b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24792, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "反思", "is_correct": true, "explanation": "正确：“反思”指回顾得失、总结经验，与“这一年的得失”相符。"}, {"text": "种植", "is_correct": false, "explanation": "语义：“种植”指栽种植物，不能用于抽象的“得失”，句意不通。"}, {"text": "修剪", "is_correct": false, "explanation": "配价：“修剪”的对象必须是具体的植物或物体，不能带“得失”这类抽象宾语。"}, {"text": "搭建", "is_correct": false, "explanation": "语义：“搭建”指建造具体的结构，不能用于抽象的“得失”。"}], "explanations": {"反思": "正确：“反思”指回顾得失、总结经验，与“这一年的得失”相符。", "种植": "语义：“种植”指栽种植物，不能用于抽象的“得失”，句意不通。", "修剪": "配价：“修剪”的对象必须是具体的植物或物体，不能带“得失”这类抽象宾语。", "搭建": "语义：“搭建”指建造具体的结构，不能用于抽象的“得失”。"}, "sentence_index": 6, "correct_answer": "反思"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他反思了坏掉的自行车。", "explanation": "这里应该用〈修理〉。“修理”指把坏的东西弄好，“反思”只用于人回顾自己的言行，不能用于物品。"}, {"text": "厨房里，妈妈反思了一锅汤。", "explanation": "这里应该用〈熬〉。“熬”指用文火煮，“反思”指回顾自己的言行，不能用于做菜。"}, {"text": "他反思了一封信给朋友。", "explanation": "这里应该用〈写〉。“写”指写信，“反思”指回顾自己的言行，不能表示写信。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bd75a825-1ba1-4d13-af2f-d6021369ff4b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24792, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "比赛失败后，他很反思了自己的问题。", "corrected_sentence": "比赛失败后，他认真反思了自己的问题。", "error_description": "错误在副词：“很”修饰形容词，不修饰动词“反思”，“很反思”不通。应改为“认真”等副词，说“认真反思了自己的问题”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bd75a825-1ba1-4d13-af2f-d6021369ff4b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24792, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我们应该认真得反思自己的错误。", "corrected_sentence": "我们应该认真反思自己的错误。", "error_description": "错误在状语标记：“认真”修饰动词“反思”时直接放在动词前，中间不加“得”；“得”只用于动词或形容词之后的补语，应说“认真反思”，不说“认真得反思”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bd75a825-1ba1-4d13-af2f-d6021369ff4b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
