INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24794, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "做研究、教书的人组成的圈子。", "primary_collocate": null, "pronunciation": "xué shù jiè", "ipa": "ɕɥe˧˥ ʂu˥˩ tɕje˥˩", "syllable_count": 3, "sentences": [{"text": "学术界里的人都喜欢读书和研究。", "target_word": "学术界", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我姐姐是大学老师，生活在学术界。", "target_word": "学术界", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "学术界的人常常忙着写论文。", "target_word": "学术界", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他的父母都在学术界工作。", "target_word": "学术界", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "学术界的朋友都说他很聪明。", "target_word": "学术界", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "学术界的老师和学生常在一起交流。", "target_word": "学术界", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他不喜欢学术界的人际关系。", "target_word": "学术界", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "学术界的人说话常常很认真。", "target_word": "学术界", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "大学教授和研究员都属于学术界。", "target_word": "学术界", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "学术界的圈子不大，大家都认识。", "target_word": "学术界", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "做研究、教书的人所组成的社交圈子", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '08c39e3c-4375-4f78-8873-c3b87ac6f5e8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24794, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "学术界", "is_correct": true, "explanation": "正确：「学术界」指做研究、教书的人组成的圈子，与句中的“读书和研究”相符。"}, {"text": "菜市场", "is_correct": false, "explanation": "语义：「菜市场」是卖菜的场所，不指做研究、教书的人组成的圈子。"}, {"text": "厨房", "is_correct": false, "explanation": "语义：“厨房”是场所，不指做研究、教书的人组成的圈子。"}, {"text": "动物园", "is_correct": false, "explanation": "语义：“动物园”是场所，不指做研究、教书的人组成的圈子。"}], "explanations": {"学术界": "正确：「学术界」指做研究、教书的人组成的圈子，与句中的“读书和研究”相符。", "菜市场": "语义：「菜市场」是卖菜的场所，不指做研究、教书的人组成的圈子。", "厨房": "语义：“厨房”是场所，不指做研究、教书的人组成的圈子。", "动物园": "语义：“动物园”是场所，不指做研究、教书的人组成的圈子。"}, "sentence_index": 0, "correct_answer": "学术界"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这位老师下午去学术界上课。", "explanation": "这里应该用〈大学〉。学术界指做研究、教书的人组成的圈子，不是可以去上课的地方。"}, {"text": "他是一位学术界。", "explanation": "这里应该用〈学者〉。学术界指一个圈子，不能当作一个人来数。"}, {"text": "学术界常常在周末举行。", "explanation": "这里应该用〈学术会议〉。学术界指做研究、教书的人组成的圈子，不是活动，不能作“举行”的主语。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3a006eb5-8ab0-4166-b354-14c01c2e7e95') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24794, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "学术界", "is_correct": true, "explanation": "正确：「学术界」指做研究、教书的人组成的圈子，与“人际关系”的语境相符。"}, {"text": "显微镜", "is_correct": false, "explanation": "语义：“显微镜”是仪器，没有“人际关系”。"}, {"text": "花园", "is_correct": false, "explanation": "语义：“花园”是场所，不是有人际关系的圈子。"}, {"text": "书架", "is_correct": false, "explanation": "语义：「书架」是放书的家具，没有人际关系。"}], "explanations": {"学术界": "正确：「学术界」指做研究、教书的人组成的圈子，与“人际关系”的语境相符。", "显微镜": "语义：“显微镜”是仪器，没有“人际关系”。", "花园": "语义：“花园”是场所，不是有人际关系的圈子。", "书架": "语义：「书架」是放书的家具，没有人际关系。"}, "sentence_index": 6, "correct_answer": "学术界"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "学术界，请您先坐下。", "explanation": "这里应该用〈教授〉作称呼。学术界指领域，不能当作人来称呼。"}, {"text": "这张桌子是用学术界做的。", "explanation": "这里应该用〈木头〉。学术界是领域，不能当作制作桌子的材料。"}, {"text": "我家的厨房在学术界旁边。", "explanation": "这里应该用〈大学〉。学术界是领域，不是有位置的地方，不能说“旁边”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3a006eb5-8ab0-4166-b354-14c01c2e7e95') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24794, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我的同学都学术界工作。", "corrected_sentence": "我的同学都在学术界工作。", "error_description": "“学术界”作处所时前面要加介词“在”。应说“我的同学都在学术界工作”，漏掉“在”就不通顺。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3a006eb5-8ab0-4166-b354-14c01c2e7e95') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24794, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这位学生毕业后想加入了学术界。", "corrected_sentence": "这位学生毕业后想加入学术界。", "error_description": "“想”后面的动词不能带“了”。应说“想加入学术界”，多出的“了”就不通顺。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3a006eb5-8ab0-4166-b354-14c01c2e7e95') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
