INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24796, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "批评者就是指出别人做得不对的地方的人。", "primary_collocate": null, "pronunciation": "pī píng zhě", "ipa": "pʰi˥ pʰiŋ˧˥ ʈʂɤ˨˩˦", "syllable_count": 3, "sentences": [{"text": "我的第一个批评者是我妈妈。", "target_word": "批评者", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "好的批评者会告诉你怎么改。", "target_word": "批评者", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他不怕批评者的意见。", "target_word": "批评者", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这位批评者看了我的画，说颜色太暗。", "target_word": "批评者", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "批评者站起来，说这样做不对。", "target_word": "批评者", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "作为批评者，他总是很直接。", "target_word": "批评者", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "对这篇文章，批评者有不同的看法。", "target_word": "批评者", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她最怕遇到爱挑错的批评者。", "target_word": "批评者", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "球迷是球队最严格的批评者。", "target_word": "批评者", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那位批评者看完电影，一句话也没说。", "target_word": "批评者", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "批评者们", "label": "复数"}, {"form": "批評者", "label": "繁体"}], "register": "中性", "sense_fingerprint": "指出别人做得不对的地方的人", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ef6af6ef-c707-4f59-9d9e-398da924d540') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24796, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "批评者", "is_correct": true, "explanation": "正确：“我的第一个批评者是我妈妈”中，“批评者”指提出批评意见的人，符合语境。"}, {"text": "作品", "is_correct": false, "explanation": "语义：作品是创作成果，不是人，不能“是我妈妈”。"}, {"text": "老虎", "is_correct": false, "explanation": "语义：老虎是动物，不能与“我妈妈”构成“第一个……是”的关系，讲不通。"}, {"text": "卡车", "is_correct": false, "explanation": "语义：卡车是车辆，不能与“我妈妈”构成“第一个……是”的关系，讲不通。"}], "explanations": {"批评者": "正确：“我的第一个批评者是我妈妈”中，“批评者”指提出批评意见的人，符合语境。", "作品": "语义：作品是创作成果，不是人，不能“是我妈妈”。", "老虎": "语义：老虎是动物，不能与“我妈妈”构成“第一个……是”的关系，讲不通。", "卡车": "语义：卡车是车辆，不能与“我妈妈”构成“第一个……是”的关系，讲不通。"}, "sentence_index": 0, "correct_answer": "批评者"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他是我们学校最忠实的批评者，每次比赛都为校队呐喊。", "explanation": "这里应该用〈支持者〉。“批评者”指提出批评的人，不会为校队呐喊；为校队呐喊的人是支持者。"}, {"text": "比赛的批评者吹响了结束的哨声。", "explanation": "这里应该用〈裁判〉。吹哨结束比赛是裁判的职责，“批评者”只提出看法，不负责执法。"}, {"text": "奶奶是我最热情的批评者，总是夸我聪明。", "explanation": "这里应该用〈鼓励者〉。“批评者”重在指出缺点，不会一味夸奖；总是夸我的人应是鼓励者。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '70862c4f-9612-4d02-b2b4-d21b6887d210') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24796, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "批评者", "is_correct": true, "explanation": "正确：“对这篇文章有不同的看法”的主语应是能评价文章的人，“批评者”符合。"}, {"text": "海洋", "is_correct": false, "explanation": "语义：海洋不能对文章提出看法，此处讲不通。"}, {"text": "桌子", "is_correct": false, "explanation": "语义：桌子是家具，不能对文章有看法，与语境不合。"}, {"text": "冰箱", "is_correct": false, "explanation": "语义：冰箱是家电，不能对文章有看法，与语境不合。"}], "explanations": {"批评者": "正确：“对这篇文章有不同的看法”的主语应是能评价文章的人，“批评者”符合。", "海洋": "语义：海洋不能对文章提出看法，此处讲不通。", "桌子": "语义：桌子是家具，不能对文章有看法，与语境不合。", "冰箱": "语义：冰箱是家电，不能对文章有看法，与语境不合。"}, "sentence_index": 6, "correct_answer": "批评者"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这位批评者在舞台上扮演国王，台词背得很熟。", "explanation": "这里应该用〈演员〉。“批评者”指指出别人错误的人，不负责表演；在舞台上扮演角色的是演员。"}, {"text": "这位批评者为病人做了手术，病人恢复得很快。", "explanation": "这里应该用〈医生〉。“批评者”不负责诊治和手术；为病人做手术的是医生。"}, {"text": "这位批评者开车很稳，乘客都觉得很安全。", "explanation": "这里应该用〈司机〉。“批评者”指提出意见的人，不负责驾驶；开车很稳的是司机。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '70862c4f-9612-4d02-b2b4-d21b6887d210') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24796, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他是我的一只严厉的批评者，不会轻易夸我。", "corrected_sentence": "他是我的一位严厉的批评者，不会轻易夸我。", "error_description": "量词错误。“批评者”指人，量词应用“位”或“个”，“只”多用于动物，不能用来修饰人。应说“一位严厉的批评者”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '70862c4f-9612-4d02-b2b4-d21b6887d210') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24796, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "那几只批评者都没有说话。", "corrected_sentence": "那几位批评者都没有说话。", "error_description": "量词错误。“批评者”指人，量词应用“位”，不能用“只”。应说“那几位批评者”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '70862c4f-9612-4d02-b2b4-d21b6887d210') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
