INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24798, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "让一个东西适合另一个东西，比如手机充电器和手机要能插在一起。", "primary_collocate": null, "pronunciation": "shì pèi", "ipa": "ʂɨ˥˩ pʰei̯˥˩", "syllable_count": 2, "sentences": [{"text": "这个充电器能适配我的手机。", "target_word": "适配", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "新手机壳要适配手机的大小。", "target_word": "适配", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这根线不适配这台电脑。", "target_word": "适配", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我买了一个适配所有手机的充电头。", "target_word": "适配", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "店员说这款耳机适配苹果手机。", "target_word": "适配", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请先看看这个插头能不能适配你的插座。", "target_word": "适配", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "新的软件适配了旧电脑。", "target_word": "适配", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这个转接头可以适配不同型号的插座。", "target_word": "适配", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "工程师想办法让新零件适配旧机器。", "target_word": "适配", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个电池适配很多相机。", "target_word": "适配", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "适配器", "label": "复合"}, {"form": "适配性", "label": "复合"}, {"form": "适配了", "label": "体标"}], "register": "中性", "sense_fingerprint": "日常里两个物品大小或接口合适，能配在一起用", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bf9d64f7-d6db-410b-8410-52799dc0c108') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24798, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "适配", "is_correct": true, "explanation": "适配：使充电器和手机能配合使用，符合句意。"}, {"text": "修理", "is_correct": false, "explanation": "语义：“修理”是修好坏掉的东西，充电器不能修理手机。"}, {"text": "观看", "is_correct": false, "explanation": "语义：“观看”是看节目或画面，充电器不能观看手机，句意不通。"}, {"text": "购买", "is_correct": false, "explanation": "配价：“购买”的施事要能付钱，“充电器”不能充当买的一方。"}], "explanations": {"适配": "适配：使充电器和手机能配合使用，符合句意。", "修理": "语义：“修理”是修好坏掉的东西，充电器不能修理手机。", "观看": "语义：“观看”是看节目或画面，充电器不能观看手机，句意不通。", "购买": "配价：“购买”的施事要能付钱，“充电器”不能充当买的一方。"}, "sentence_index": 0, "correct_answer": "适配"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这双鞋和这条裙子很适配。", "explanation": "这里应该用〈匹配〉。适配用于器件之间符合规格、能配合使用，衣物之间的般配要用匹配。"}, {"text": "他很快适配了新的工作。", "explanation": "这里应该用〈适应〉。适配用于器件和系统，人对新工作的适应要用适应。"}, {"text": "这件大衣很适配你。", "explanation": "这里应该用〈合适〉。适配用于器件之间的配合，衣服穿着合不合身要用合适。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '99a869e5-d7c6-4cee-bf7b-58b3f659b231') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24798, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "适配", "is_correct": true, "explanation": "适配：使新软件能在旧电脑上配合运行，符合句意。"}, {"text": "批改", "is_correct": false, "explanation": "搭配：“批改”用于批阅作业或试卷，不能用于软件和电脑，句意不通。"}, {"text": "冲洗", "is_correct": false, "explanation": "语义：“冲洗”是用水冲刷，不能用于软件和电脑。"}, {"text": "喂养", "is_correct": false, "explanation": "搭配：“喂养”用于动物或幼小的生物，不能用于电脑。"}], "explanations": {"适配": "适配：使新软件能在旧电脑上配合运行，符合句意。", "批改": "搭配：“批改”用于批阅作业或试卷，不能用于软件和电脑，句意不通。", "冲洗": "语义：“冲洗”是用水冲刷，不能用于软件和电脑。", "喂养": "搭配：“喂养”用于动物或幼小的生物，不能用于电脑。"}, "sentence_index": 6, "correct_answer": "适配"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这件衬衫和裤子很适配。", "explanation": "这里应该用〈搭配〉。适配指器件之间符合规格、能配合使用，衣服之间的协调要用搭配。"}, {"text": "老板临时适配了明天的行程，把会议提前了。", "explanation": "这里应该用〈调整〉。适配指使设备、系统符合规格或能配合，行程的改动要用调整。"}, {"text": "这两个房间的布置很适配。", "explanation": "这里应该用〈协调〉。适配用于设备、系统的配合，房间布置之间的和谐要用协调。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '99a869e5-d7c6-4cee-bf7b-58b3f659b231') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24798, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这个充电器能很好的适配我的手机。", "corrected_sentence": "这个充电器能很好地适配我的手机。", "error_description": "“很好”修饰动词“适配”，应用“地”而不是“的”：应为“很好地适配”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '99a869e5-d7c6-4cee-bf7b-58b3f659b231') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24798, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这个插头不适配了我家的插座。", "corrected_sentence": "这个插头不适配我家的插座。", "error_description": "否定用“不”时，“适配”后不能加“了”：应为“不适配我家的插座”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '99a869e5-d7c6-4cee-bf7b-58b3f659b231') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
