INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24800, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "美学是研究什么是美丽和艺术的学问。", "primary_collocate": null, "pronunciation": "měi xué", "ipa": "meɪ˨˩˦ ɕɥe˧˥", "syllable_count": 2, "sentences": [{"text": "我在大学选了一门美学课。", "target_word": "美学", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "美学研究什么是美，什么是艺术。", "target_word": "美学", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这位老师专门研究中国古代美学。", "target_word": "美学", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他读过很多关于美学的书。", "target_word": "美学", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "美学可以帮我们看懂一幅画。", "target_word": "美学", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "妹妹对美学很感兴趣，想去学。", "target_word": "美学", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这本美学书写得很清楚，我很喜欢。", "target_word": "美学", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "参加美学讲座以后，我对艺术有了新看法。", "target_word": "美学", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "美学老师带我们去博物馆看画。", "target_word": "美学", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她在大学里教美学，学生都很喜欢她。", "target_word": "美学", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "美學", "label": "繁体"}, {"form": "美学家", "label": "复合"}, {"form": "美学观", "label": "复合"}], "register": "书面", "sense_fingerprint": "研究美和艺术的学科", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f3c9b1ce-420a-4bbc-97dd-366c624344ba') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24800, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "美学", "is_correct": true, "explanation": "正确：“美学”指研究美和艺术的学科，可以作“一门……课”的课程名，与“在大学”相合。"}, {"text": "中学", "is_correct": false, "explanation": "语义：句中有“在大学”，“中学”是另一个教育阶段，大学里不会选中学课程。"}, {"text": "小学", "is_correct": false, "explanation": "语义：“小学”与句中的“大学”冲突，大学不开设小学课程。"}, {"text": "药膏", "is_correct": false, "explanation": "语义：“药膏”是外用药，不能作为大学课程的名称，“一门药膏课”说不通。"}], "explanations": {"美学": "正确：“美学”指研究美和艺术的学科，可以作“一门……课”的课程名，与“在大学”相合。", "中学": "语义：句中有“在大学”，“中学”是另一个教育阶段，大学里不会选中学课程。", "小学": "语义：“小学”与句中的“大学”冲突，大学不开设小学课程。", "药膏": "语义：“药膏”是外用药，不能作为大学课程的名称，“一门药膏课”说不通。"}, "sentence_index": 0, "correct_answer": "美学"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他中午去美学吃饭。", "explanation": "这里应该用〈食堂〉。美学是学科名称，不是地方，不能说去美学吃饭。"}, {"text": "他每天早上去公园练美学，身体很好。", "explanation": "这里应该用〈太极拳〉。美学是研究美和艺术的学科，不是锻炼身体的运动，不能“练美学”。"}, {"text": "我在超市买了一斤美学。", "explanation": "这里应该用〈苹果〉。美学是学科，不是可以买卖、称重的东西。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '65de5bc4-b62f-4ec2-9482-df726991680b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24800, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "美学", "is_correct": true, "explanation": "正确：“这本美学书”指讲美学的书，与“写得很清楚”“我很喜欢”相合。"}, {"text": "冰箱", "is_correct": false, "explanation": "语义：“冰箱”不是书的类别，“这本冰箱书”说不通。"}, {"text": "白菜", "is_correct": false, "explanation": "搭配：“白菜”不能用来修饰“书”表示书的类别，二者不搭配。"}, {"text": "拖鞋", "is_correct": false, "explanation": "语义：“拖鞋”不能作为书的类别，句中“写得很清楚”的书无法是拖鞋。"}], "explanations": {"美学": "正确：“这本美学书”指讲美学的书，与“写得很清楚”“我很喜欢”相合。", "冰箱": "语义：“冰箱”不是书的类别，“这本冰箱书”说不通。", "白菜": "搭配：“白菜”不能用来修饰“书”表示书的类别，二者不搭配。", "拖鞋": "语义：“拖鞋”不能作为书的类别，句中“写得很清楚”的书无法是拖鞋。"}, "sentence_index": 6, "correct_answer": "美学"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他很爱吃美学。", "explanation": "这里应该用〈饭〉。美学是学科，不能吃，“爱吃”的对象应是食物。"}, {"text": "这件美学很贵，是在商店买的。", "explanation": "这里应该用〈衣服〉。美学是学科，不是商店里买的物品。"}, {"text": "这位美学很有名。", "explanation": "这里应该用〈美学家〉。“美学”指学科，不能指人；指研究美学的人要说“美学家”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '65de5bc4-b62f-4ec2-9482-df726991680b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24800, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他在大学选修了一张美学。", "corrected_sentence": "他在大学选修了一门美学。", "error_description": "量词错误：“张”用于平面的东西，不能用来数学科名称，应说“选修了一门美学”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '65de5bc4-b62f-4ec2-9482-df726991680b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24800, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我学了过美学，知道一些基本概念。", "corrected_sentence": "我学过美学，知道一些基本概念。", "error_description": "体标错误：“了”和“过”不能同时用在动词“学”后，应说“学过”，表示曾经学过美学。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '65de5bc4-b62f-4ec2-9482-df726991680b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
