INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24802, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "效力指人、文件、规定等对别人或事情所起的约束作用。", "primary_collocate": null, "pronunciation": "xiào lì", "ipa": "ɕjaʊ˥˩ li˥˩", "syllable_count": 2, "sentences": [{"text": "这份合同已经有法律效力了。", "target_word": "效力", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这张优惠券过期了，已经失去效力了。", "target_word": "效力", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "领导的决定在我们公司很有效力。", "target_word": "效力", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "父母的话对孩子还有效力。", "target_word": "效力", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "没有签字的文件没有效力。", "target_word": "效力", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个规定对所有人都有效力。", "target_word": "效力", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这种证明在国外没有效力。", "target_word": "效力", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "警察的命令对每个人都有效力。", "target_word": "效力", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "口头说的话没有法律效力。", "target_word": "效力", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这份通知的效力到月底为止。", "target_word": "效力", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "法律效力", "label": "复合"}], "register": "中性", "sense_fingerprint": "人、文件、规定等对别人或事情起的约束作用", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ef6af6ef-c707-4f59-9d9e-398da924d540') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24802, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "效力", "is_correct": true, "explanation": "效力指人或事物对别人或事情起的约束作用，即正确答案。"}, {"text": "效率", "is_correct": false, "explanation": "lǜ（第四声）与 lì（第四声）韵母不同（ü 与 i），意思是效率。"}, {"text": "效益", "is_correct": false, "explanation": "yì 与 lì 声母不同（零声母与 l），意思是效益。"}, {"text": "小利", "is_correct": false, "explanation": "xiǎo（第三声）与 xiào（第四声）声调不同，意思是小利。"}], "explanations": {"效力": "效力指人或事物对别人或事情起的约束作用，即正确答案。", "效率": "lǜ（第四声）与 lì（第四声）韵母不同（ü 与 i），意思是效率。", "效益": "yì 与 lì 声母不同（零声母与 l），意思是效益。", "小利": "xiǎo（第三声）与 xiào（第四声）声调不同，意思是小利。"}, "sentence_index": null, "correct_answer": "效力"}, "level_3": {"options": [{"text": "效力", "is_correct": true, "explanation": "效力指约束作用，“法律”后接“效力”构成固定说法，与合同相符。"}, {"text": "颜色", "is_correct": false, "explanation": "语义：颜色与合同的法律约束无关，不能说“有法律颜色”。"}, {"text": "数量", "is_correct": false, "explanation": "搭配：“有法律……”后面要接“效力”这类词，“数量”不能这样用。"}, {"text": "体重", "is_correct": false, "explanation": "语义：体重指人或物的重量，与合同的法律约束无关。"}], "explanations": {"效力": "效力指约束作用，“法律”后接“效力”构成固定说法，与合同相符。", "颜色": "语义：颜色与合同的法律约束无关，不能说“有法律颜色”。", "数量": "搭配：“有法律……”后面要接“效力”这类词，“数量”不能这样用。", "体重": "语义：体重指人或物的重量，与合同的法律约束无关。"}, "sentence_index": 0, "correct_answer": "效力"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这位老教授很有效力，一口气讲了三个小时。", "explanation": "这里应该用〈精力〉。精力指人的体力与精神，效力指约束作用，不能用来形容讲课的劲头。"}, {"text": "他的效力很大，一个人就能把箱子扛起来。", "explanation": "这里应该用〈力量〉。力量指人或物的力气与能量，用于体力；效力指事物的约束作用，不能用来说人的体力。"}, {"text": "这位法官的效力很大，一顿能吃五碗饭。", "explanation": "这里应该用〈食量〉。食量指吃饭的分量，效力指约束作用，不能用来说吃饭多少。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '70862c4f-9612-4d02-b2b4-d21b6887d210') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24802, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "效力", "is_correct": true, "explanation": "效力指人或事物对别人或事情起的约束作用，即正确答案。"}, {"text": "下力", "is_correct": false, "explanation": "xià 与 xiào 韵母不同（ia 与 iao），意思是下力（用力气）。"}, {"text": "小吏", "is_correct": false, "explanation": "xiǎo（第三声）与 xiào（第四声）声调不同，意思是小吏。"}, {"text": "小利", "is_correct": false, "explanation": "xiǎo（第三声）与 xiào（第四声）声调不同，意思是小利。"}], "explanations": {"效力": "效力指人或事物对别人或事情起的约束作用，即正确答案。", "下力": "xià 与 xiào 韵母不同（ia 与 iao），意思是下力（用力气）。", "小吏": "xiǎo（第三声）与 xiào（第四声）声调不同，意思是小吏。", "小利": "xiǎo（第三声）与 xiào（第四声）声调不同，意思是小利。"}, "sentence_index": null, "correct_answer": "效力"}, "level_3": {"options": [{"text": "效力", "is_correct": true, "explanation": "效力指证明的约束作用，“没有”后接“效力”，与句意相符。"}, {"text": "外貌", "is_correct": false, "explanation": "语义：“外貌”指人或物的样子，不能用来说证明在国外的作用。"}, {"text": "身高", "is_correct": false, "explanation": "语义：身高指人的身长，与证明在国外是否有约束力无关。"}, {"text": "体积", "is_correct": false, "explanation": "语义：体积指物体占的空间，与证明的作用无关。"}], "explanations": {"效力": "效力指证明的约束作用，“没有”后接“效力”，与句意相符。", "外貌": "语义：“外貌”指人或物的样子，不能用来说证明在国外的作用。", "身高": "语义：身高指人的身长，与证明在国外是否有约束力无关。", "体积": "语义：体积指物体占的空间，与证明的作用无关。"}, "sentence_index": 6, "correct_answer": "效力"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这个部门的效力很高，文件两天就能处理完。", "explanation": "这里应该用〈效率〉。效率指单位时间内的工作量，形容部门办事快慢；效力指约束作用，不说办事速度。"}, {"text": "这场雨的效力很大，地面都湿透了。", "explanation": "这里应该用〈雨量〉。效力指约束作用，不能用来形容雨的大小，应说雨量。"}, {"text": "他跑了一整天，身上的效力都用光了。", "explanation": "这里应该用〈体力〉。体力指身体的力量，用于人；效力指事物的约束作用，不能用来说人的体力。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '70862c4f-9612-4d02-b2b4-d21b6887d210') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24802, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这份通知的法律效力很甜，大家都要遵守。", "corrected_sentence": "这份通知的法律效力很大，大家都要遵守。", "error_description": "形容词搭配错误：“效力”说“大”或“强”，不说“甜”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '70862c4f-9612-4d02-b2b4-d21b6887d210') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24802, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这项规定从下个月开始生产效力。", "corrected_sentence": "这项规定从下个月开始产生效力。", "error_description": "动词搭配错误：“效力”说“产生效力”或“生效”，不能说“生产效力”；“生产”指制造东西。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '70862c4f-9612-4d02-b2b4-d21b6887d210') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
