INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24804, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "世界上很多国家都同意的一些做法或规则。", "primary_collocate": null, "pronunciation": "guó jì guàn lì", "ipa": "kwo˧˥ tɕi˥˩ kwan˥˩ li˥˩", "syllable_count": 4, "sentences": [{"text": "很多国家都按国际惯例办事。", "target_word": "国际惯例", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这是国际惯例，大家都要遵守。", "target_word": "国际惯例", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们的合同符合国际惯例。", "target_word": "国际惯例", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "学会国际惯例，出国做生意更方便。", "target_word": "国际惯例", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个做法不是国际惯例，所以外国朋友不懂。", "target_word": "国际惯例", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "国际惯例告诉我们，船在海上要先救人。", "target_word": "国际惯例", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "不了解国际惯例，做生意就容易出问题。", "target_word": "国际惯例", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师给我们讲了几个国际惯例。", "target_word": "国际惯例", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "国际惯例不是法律，但是很多国家都遵守。", "target_word": "国际惯例", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公司按照国际惯例，把价格写在合同上。", "target_word": "国际惯例", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "个", "label": "量词"}], "register": "正式", "sense_fingerprint": "世界上很多国家都认可并照着做的做法或规则", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ce3cdbb2-6def-43dc-9a20-b31c9024b160') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24804, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "国际惯例", "is_correct": true, "explanation": "正确：「国际惯例」是世界上多数国家认同的做法，与「很多国家都按……办事」相符。"}, {"text": "菜谱", "is_correct": false, "explanation": "语义：「菜谱」是做菜的方法，不是国家之间办事的规则，句子说不通。"}, {"text": "童话", "is_correct": false, "explanation": "语义：「童话」是虚构的故事，不是可以用来办事的规则，句子说不通。"}, {"text": "土话", "is_correct": false, "explanation": "语域：「土话」是地方口语，与「国际」这种正式的语境不符。"}], "explanations": {"国际惯例": "正确：「国际惯例」是世界上多数国家认同的做法，与「很多国家都按……办事」相符。", "菜谱": "语义：「菜谱」是做菜的方法，不是国家之间办事的规则，句子说不通。", "童话": "语义：「童话」是虚构的故事，不是可以用来办事的规则，句子说不通。", "土话": "语域：「土话」是地方口语，与「国际」这种正式的语境不符。"}, "sentence_index": 0, "correct_answer": "国际惯例"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我们家的国际惯例是每周五包饺子。", "explanation": "这里应该用〈家规〉或〈习惯〉。国际惯例指世界上很多国家认可的做法，只属于一家人的习惯不能这样说。"}, {"text": "这个产品的电压要符合国际惯例才能出口。", "explanation": "这里应该用〈国际标准〉。惯例指世界上很多国家认可的做法，电压等技术指标要用标准。"}, {"text": "水往低处流是国际惯例。", "explanation": "这里应该用〈规律〉。惯例是人们在交往中逐渐形成的做法，水往低处流是自然规律，不属于惯例。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '212e2189-3a9b-4783-aacf-18bf5e476a5c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24804, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "国际惯例", "is_correct": true, "explanation": "正确：「不了解国际惯例」指不了解国家间通行的做法，与「做生意就容易出问题」相符。"}, {"text": "古诗", "is_correct": false, "explanation": "语义：「古诗」与做生意的规则无关，句子不通。"}, {"text": "脚步", "is_correct": false, "explanation": "搭配：「了解」后接的是知识、情况或人，「脚步」不能作它的宾语。"}, {"text": "童谣", "is_correct": false, "explanation": "语义：「童谣」是儿歌，与做生意要遵守的规则无关。"}], "explanations": {"国际惯例": "正确：「不了解国际惯例」指不了解国家间通行的做法，与「做生意就容易出问题」相符。", "古诗": "语义：「古诗」与做生意的规则无关，句子不通。", "脚步": "搭配：「了解」后接的是知识、情况或人，「脚步」不能作它的宾语。", "童谣": "语义：「童谣」是儿歌，与做生意要遵守的规则无关。"}, "sentence_index": 6, "correct_answer": "国际惯例"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "只有我们学校知道的这个做法，是国际惯例。", "explanation": "这里应该用〈校内惯例〉。国际惯例须是世界上很多国家都认可的做法，只在一所学校内部通行的做法不能这样称呼。"}, {"text": "这个组织制定了国际惯例，各国都要照着做。", "explanation": "这里应该用〈国际准则〉。惯例是各国在交往中逐渐形成的，不是由某个组织制定的。"}, {"text": "两国签订了国际惯例，规定了边境的界线。", "explanation": "这里应该用〈国际条约〉。惯例是长期形成的做法，不是书面条约，不能签订。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '212e2189-3a9b-4783-aacf-18bf5e476a5c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24804, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "很多国家都认可的这只国际惯例很实用。", "corrected_sentence": "很多国家都认可的这项国际惯例很实用。", "error_description": "量词错误：「国际惯例」应搭配量词「项」，不能用「只」（「只」多用于动物等）。正确：「很多国家都认可的这项国际惯例很实用」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '212e2189-3a9b-4783-aacf-18bf5e476a5c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24804, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "很多国家都做这些国际惯例。", "corrected_sentence": "很多国家都遵守这些国际惯例。", "error_description": "错误：「做」不能带「惯例」作宾语。正确：「国际惯例」应与「遵守」搭配，说「遵守国际惯例」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '212e2189-3a9b-4783-aacf-18bf5e476a5c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
