INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24808, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "别的东西挡住了，让人看不见。", "primary_collocate": null, "pronunciation": "zhē bì", "ipa": "ʈʂɤ˥ pi˥˩", "syllable_count": 2, "sentences": [{"text": "前面的大卡车遮蔽了我的视线。", "target_word": "遮蔽", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "一块大石头遮蔽了后面的小房子。", "target_word": "遮蔽", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "树叶遮蔽着窗户，屋里看不到外面。", "target_word": "遮蔽", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "讲台上的花遮蔽了老师的脸。", "target_word": "遮蔽", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "墙太高，遮蔽了外面的风景。", "target_word": "遮蔽", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他把帽子压得很低，遮蔽了半张脸。", "target_word": "遮蔽", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "大雾遮蔽了对面的楼，我只看到一片白。", "target_word": "遮蔽", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "浓烟遮蔽了房子，消防员看不清火在哪。", "target_word": "遮蔽", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "那块布遮蔽了桌上的东西，没人知道是什么。", "target_word": "遮蔽", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "新建的大楼遮蔽了我家的阳台。", "target_word": "遮蔽", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "遮蔽了", "label": "完成体"}, {"form": "遮蔽着", "label": "持续体"}], "register": "书面语", "sense_fingerprint": "一样东西挡在前面，使人看不见后面的事物（具体遮挡）", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e01db3e0-aba5-44e5-92e3-89627e0736ec') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24808, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "遮蔽", "is_correct": true, "explanation": "遮蔽：挡住前方，使视线看不到后面，与“视线”相合。"}, {"text": "照亮", "is_correct": false, "explanation": "语义：“照亮”指使明亮，与“看不见”的语境相反。"}, {"text": "修补", "is_correct": false, "explanation": "搭配：“修补”针对破损之物，不能用于“视线”。"}, {"text": "清扫", "is_correct": false, "explanation": "搭配：“清扫”指清除脏物，不能用于大卡车对视线的作用。"}], "explanations": {"遮蔽": "遮蔽：挡住前方，使视线看不到后面，与“视线”相合。", "照亮": "语义：“照亮”指使明亮，与“看不见”的语境相反。", "修补": "搭配：“修补”针对破损之物，不能用于“视线”。", "清扫": "搭配：“清扫”指清除脏物，不能用于大卡车对视线的作用。"}, "sentence_index": 0, "correct_answer": "遮蔽"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他用双手遮蔽了耳朵，不想听见吵闹。", "explanation": "这里应该用〈捂住〉。遮蔽多指挡住视线或光线，不用于耳朵等感官。"}, {"text": "工人们把那棵旧树遮蔽掉了。", "explanation": "这里应该用〈砍掉〉。遮蔽是挡住视线，不能表示把树木除去。"}, {"text": "他想把这本书遮蔽回书架上。", "explanation": "这里应该用〈放〉。遮蔽是挡住，不能表示把东西送回原处。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ea69a300-08e8-4927-8974-98338482547b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24808, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "遮蔽", "is_correct": true, "explanation": "遮蔽：挡住视线，使人看不清对面的楼，与“只看到一片白”相合。"}, {"text": "点亮", "is_correct": false, "explanation": "语义：“点亮”指使明亮，与“只看到一片白”的语境不符。"}, {"text": "擦拭", "is_correct": false, "explanation": "搭配：“擦拭”针对脏污的表面，不能用于“大雾”。"}, {"text": "搬走", "is_correct": false, "explanation": "语义：“搬走”指移开物体，与“对面的楼仍在、只看到白雾”的语境相反。"}], "explanations": {"遮蔽": "遮蔽：挡住视线，使人看不清对面的楼，与“只看到一片白”相合。", "点亮": "语义：“点亮”指使明亮，与“只看到一片白”的语境不符。", "擦拭": "搭配：“擦拭”针对脏污的表面，不能用于“大雾”。", "搬走": "语义：“搬走”指移开物体，与“对面的楼仍在、只看到白雾”的语境相反。"}, "sentence_index": 6, "correct_answer": "遮蔽"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "新装的路灯遮蔽了整条街道。", "explanation": "这里应该用〈照亮〉。遮蔽是挡住视线，路灯的作用是照亮，不能说遮蔽。"}, {"text": "孩子们在教室里遮蔽课文。", "explanation": "这里应该用〈背诵〉。遮蔽是挡住视线，不能用于朗读或背诵文字。"}, {"text": "医生给病人遮蔽体温。", "explanation": "这里应该用〈测量〉。遮蔽是挡住视线，不能用于测定体温。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ea69a300-08e8-4927-8974-98338482547b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24808, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "云层遮蔽地了整片树林。", "corrected_sentence": "云层遮蔽了整片树林。", "error_description": "错误：“遮蔽地了”。正确：“遮蔽了”。“地”是状语标记，不能插在动词与“了”之间。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ea69a300-08e8-4927-8974-98338482547b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24808, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "夜色遮蔽了住远处的山峰。", "corrected_sentence": "夜色遮蔽住了远处的山峰。", "error_description": "错误：“遮蔽了住”。正确：“遮蔽住了”。“住”是补语，应紧接动词，“了”放在补语之后。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ea69a300-08e8-4927-8974-98338482547b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
