INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24810, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "塑料是一种可以做成很多玩具和杯子的材料。", "primary_collocate": null, "pronunciation": "sù liào", "ipa": "su˥˩ ljau˥˩", "syllable_count": 2, "sentences": [{"text": "这个杯子是塑料的。", "target_word": "塑料", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "孩子的玩具都是塑料做的。", "target_word": "塑料", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "水杯是塑料的，掉在地上不会碎。", "target_word": "塑料", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "塑料很轻，也不容易坏。", "target_word": "塑料", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "超市的袋子是塑料，不是纸。", "target_word": "塑料", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "塑料不能放进火里烧。", "target_word": "塑料", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这把椅子是塑料做的，不太重。", "target_word": "塑料", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我用塑料做了一个小盒子。", "target_word": "塑料", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "海里有很多塑料，对鱼不好。", "target_word": "塑料", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他把用过的塑料放进了回收箱。", "target_word": "塑料", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "塑料袋", "label": "复合词"}, {"form": "塑料瓶", "label": "复合词"}, {"form": "塑料杯", "label": "复合词"}], "register": "中性", "sense_fingerprint": "塑料：用来做玩具、杯子、袋子的人造材料", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bc7d612e-20ca-4dd1-8228-5889a24a7062') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24810, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "空气", "is_correct": false, "explanation": "语义：杯子不能用空气做成，与“是……的”所表示的材料义不合。"}, {"text": "塑料", "is_correct": true, "explanation": "塑料是可以做杯子的材料，与“这个杯子是……的”相合。"}, {"text": "声音", "is_correct": false, "explanation": "搭配：“是……的”后接材料名词，“声音”不能作杯子的材料。"}, {"text": "云", "is_correct": false, "explanation": "语义：云是天上的水汽，不能用来制作杯子。"}], "explanations": {"空气": "语义：杯子不能用空气做成，与“是……的”所表示的材料义不合。", "塑料": "塑料是可以做杯子的材料，与“这个杯子是……的”相合。", "声音": "搭配：“是……的”后接材料名词，“声音”不能作杯子的材料。", "云": "语义：云是天上的水汽，不能用来制作杯子。"}, "sentence_index": 0, "correct_answer": "塑料"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我和一块塑料握了手。", "explanation": "这里应该用〈朋友〉。塑料是材料，不是人，不能和它握手，应说〈和朋友握手〉。"}, {"text": "我今天喝了一杯塑料。", "explanation": "塑料是制作物品的材料，不能喝，这里应该说〈喝了一杯水〉。"}, {"text": "我的塑料很可爱，每天陪我玩。", "explanation": "塑料指材料，不能指会陪人玩的东西，这里应该说〈玩具〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd64ca69b-64e3-4334-9155-6b7ad34fc6c3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24810, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "水", "is_correct": false, "explanation": "语义：水是液体，不能做成椅子，与“是……做的”不合。"}, {"text": "塑料", "is_correct": true, "explanation": "塑料比较轻，与“这把椅子是……做的，不太重”相合。"}, {"text": "石头", "is_correct": false, "explanation": "语义：石头很重，与“不太重”矛盾。"}, {"text": "牛奶", "is_correct": false, "explanation": "搭配：“是……做的”要接材料，“牛奶”不能用来做椅子。"}], "explanations": {"水": "语义：水是液体，不能做成椅子，与“是……做的”不合。", "塑料": "塑料比较轻，与“这把椅子是……做的，不太重”相合。", "石头": "语义：石头很重，与“不太重”矛盾。", "牛奶": "搭配：“是……做的”要接材料，“牛奶”不能用来做椅子。"}, "sentence_index": 6, "correct_answer": "塑料"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他在塑料里面睡了一个晚上。", "explanation": "塑料是材料，不能作睡觉的场所，这里应该说〈睡在帐篷里〉。"}, {"text": "妈妈把塑料请进了房间。", "explanation": "「请」只用于请人，塑料是材料，不能被请进房间，这里应说〈搬进了房间〉。"}, {"text": "我用塑料写了一封信。", "explanation": "写字要用纸和笔，塑料不能用来写字，这里应该说〈用纸写〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd64ca69b-64e3-4334-9155-6b7ad34fc6c3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24810, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他在路边捡到一只塑料。", "corrected_sentence": "他在路边捡到一块塑料。", "error_description": "量词误用：「只」用于动物或成对器物中的一件，塑料作为材料应说「一块」或「片」，应改为「一块塑料」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd64ca69b-64e3-4334-9155-6b7ad34fc6c3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24810, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他买了一块很轻塑料。", "corrected_sentence": "他买了一块很轻的塑料。", "error_description": "「很轻」修饰名词「塑料」时要加「的」，应说「很轻的塑料」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd64ca69b-64e3-4334-9155-6b7ad34fc6c3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24812, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "隐藏", "is_correct": true, "explanation": "正确：“隐藏”与“呈现”表示的显露相对，是这一义项的反义词。"}, {"text": "购买", "is_correct": false, "explanation": "与“呈现”无反义关系：“购买”指花钱买东西，与显露样子无关。"}, {"text": "保持", "is_correct": false, "explanation": "与“呈现”无反义关系：“保持”指维持原状，与显露样子不构成相对。"}, {"text": "讨论", "is_correct": false, "explanation": "与“呈现”无反义关系：“讨论”指交换意见，与显露样子无关。"}], "correct_answer": "隐藏", "explanations": {"隐藏": "正确：“隐藏”与“呈现”表示的显露相对，是这一义项的反义词。", "购买": "与“呈现”无反义关系：“购买”指花钱买东西，与显露样子无关。", "保持": "与“呈现”无反义关系：“保持”指维持原状，与显露样子不构成相对。", "讨论": "与“呈现”无反义关系：“讨论”指交换意见，与显露样子无关。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5b3042e5-b35f-462e-9b42-3d0f42ef5c59') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24812, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "隐藏", "is_correct": true, "explanation": "正确：“隐藏”与“呈现”表示的显露相对，是这一义项的反义词。"}, {"text": "生长", "is_correct": false, "explanation": "与“呈现”无反义关系：“生长”指生物逐渐长大，与显露样子无关。"}, {"text": "决定", "is_correct": false, "explanation": "与“呈现”无反义关系：“决定”指作出选择或结论，与显露样子无关。"}, {"text": "跳跃", "is_correct": false, "explanation": "与“呈现”无反义关系：“跳跃”指身体向上或向前跃起，与显露样子无关。"}], "correct_answer": "隐藏", "explanations": {"隐藏": "正确：“隐藏”与“呈现”表示的显露相对，是这一义项的反义词。", "生长": "与“呈现”无反义关系：“生长”指生物逐渐长大，与显露样子无关。", "决定": "与“呈现”无反义关系：“决定”指作出选择或结论，与显露样子无关。", "跳跃": "与“呈现”无反义关系：“跳跃”指身体向上或向前跃起，与显露样子无关。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5b3042e5-b35f-462e-9b42-3d0f42ef5c59') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24812, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "呈现就是东西出现在我们面前，让我们看到。", "primary_collocate": null, "pronunciation": "chéng xiàn", "ipa": "ʈʂʰɤŋ˧˥ ɕjɛn˥˩", "syllable_count": 2, "sentences": [{"text": "雨后，天空呈现出美丽的颜色。", "target_word": "呈现", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "打开门，一片绿色呈现在我们眼前。", "target_word": "呈现", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "春天到了，田野呈现出一片绿色。", "target_word": "呈现", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "太阳出来后，山上呈现出金黄色。", "target_word": "呈现", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他的脸上呈现出高兴的表情。", "target_word": "呈现", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "下雪以后，大地呈现出一片白色。", "target_word": "呈现", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "夜晚的城市呈现着另一种美。", "target_word": "呈现", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "走进山谷，一片美丽的景色呈现在眼前。", "target_word": "呈现", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "湖水在阳光下呈现出蓝色。", "target_word": "呈现", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "秋天的树叶呈现出红色和黄色。", "target_word": "呈现", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "呈现出", "label": "趋向补语形式"}, {"form": "呈现了", "label": "体标：完成"}, {"form": "呈现着", "label": "体标：持续"}], "register": "书面", "sense_fingerprint": "事物的颜色、景象、样子显现出来，被人看到", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '35c41e43-d819-4200-99d8-f4259434702f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24812, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "呈现", "is_correct": true, "explanation": "正确答案：呈现（chéng xiàn），表示显露出样子，被人看到。"}, {"text": "长线", "is_correct": false, "explanation": "cháng 与 chéng 韵母不同（ang 与 eng），“长线”指长的线，也比喻长期的项目或投资。"}, {"text": "成像", "is_correct": false, "explanation": "xiàng 与 xiàn 韵尾不同（ng 与 n），意思是形成图像。"}, {"text": "成仙", "is_correct": false, "explanation": "xiān 与 xiàn 只有声调不同（第一声与第四声），意思是修行得道成为神仙。"}, {"text": "成见", "is_correct": false, "explanation": "jiàn 与 xiàn 声母不同（j 与 x），意思是对人或事预先形成的看法。"}], "explanations": {"呈现": "正确答案：呈现（chéng xiàn），表示显露出样子，被人看到。", "长线": "cháng 与 chéng 韵母不同（ang 与 eng），“长线”指长的线，也比喻长期的项目或投资。", "成像": "xiàng 与 xiàn 韵尾不同（ng 与 n），意思是形成图像。", "成仙": "xiān 与 xiàn 只有声调不同（第一声与第四声），意思是修行得道成为神仙。", "成见": "jiàn 与 xiàn 声母不同（j 与 x），意思是对人或事预先形成的看法。"}, "sentence_index": null, "correct_answer": "呈现"}, "level_3": {"options": [{"text": "呈现", "is_correct": true, "explanation": "正确：“呈现出”表示显露出颜色和景象，与“天空”和“美丽的颜色”相合。"}, {"text": "喷射", "is_correct": false, "explanation": "语义：“喷射”指猛烈地向外射出，与雨后柔和的天色不合。"}, {"text": "喷涂", "is_correct": false, "explanation": "配价：“喷涂”要求有人用工具涂抹的施事，天空不能喷涂颜色。"}, {"text": "吐露", "is_correct": false, "explanation": "搭配：“吐露”多接言语、心事，不能与“颜色”搭配。"}], "explanations": {"呈现": "正确：“呈现出”表示显露出颜色和景象，与“天空”和“美丽的颜色”相合。", "喷射": "语义：“喷射”指猛烈地向外射出，与雨后柔和的天色不合。", "喷涂": "配价：“喷涂”要求有人用工具涂抹的施事，天空不能喷涂颜色。", "吐露": "搭配：“吐露”多接言语、心事，不能与“颜色”搭配。"}, "sentence_index": 0, "correct_answer": "呈现"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他在超市呈现了两斤苹果。", "explanation": "这里应该用〈买〉。“呈现”指显露出样子，不表示买东西；买东西要说“买”。"}, {"text": "他在比赛中呈现了冠军。", "explanation": "这里应该用〈获得〉。“呈现”不表示取得荣誉，赢得冠军要用“获得”或“夺得”。"}, {"text": "他每天呈现三个小时的作业。", "explanation": "这里应该用〈完成〉。“呈现”指显露出样子，不表示做完某项任务；做作业应说“完成”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5b3042e5-b35f-462e-9b42-3d0f42ef5c59') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24812, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "呈现", "is_correct": true, "explanation": "正确：“呈现着”表示持续显露出另一种美，与“夜晚的城市”相合。"}, {"text": "挑动", "is_correct": false, "explanation": "语义：“挑动”指撩拨情绪或引起纷争，与“另一种美”的描述不合。"}, {"text": "咆哮", "is_correct": false, "explanation": "语义：“咆哮”指猛兽或人愤怒时大声吼叫，与“美”的描述不合。"}, {"text": "叫嚷", "is_correct": false, "explanation": "搭配：“叫嚷”的主语须是能发声的人，“城市”不能叫嚷。"}], "explanations": {"呈现": "正确：“呈现着”表示持续显露出另一种美，与“夜晚的城市”相合。", "挑动": "语义：“挑动”指撩拨情绪或引起纷争，与“另一种美”的描述不合。", "咆哮": "语义：“咆哮”指猛兽或人愤怒时大声吼叫，与“美”的描述不合。", "叫嚷": "搭配：“叫嚷”的主语须是能发声的人，“城市”不能叫嚷。"}, "sentence_index": 6, "correct_answer": "呈现"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "池塘的水呈现了冰。", "explanation": "这里应该用〈变成〉。“呈现”表示显露出样子，不能表示事物变成另一种东西。"}, {"text": "我们呈现了讨论。", "explanation": "这里应该用〈进行〉。“呈现”不接“讨论”这类动作性活动，应说“进行讨论”。"}, {"text": "这件事呈现了大家的注意。", "explanation": "这里应该用〈引起〉。“呈现”不表示引发某种关注，应说“引起大家的注意”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5b3042e5-b35f-462e-9b42-3d0f42ef5c59') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24812, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "傍晚，天边呈现在橘红色。", "corrected_sentence": "傍晚，天边呈现出橘红色。", "error_description": "错误：“呈现在”后接颜色不合，应为“呈现出”。“呈现在”指显露于某处（如呈现在眼前），后面不接表示样子的颜色，此处应用趋向补语“出”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5b3042e5-b35f-462e-9b42-3d0f42ef5c59') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24812, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "湖面呈现进银色的光。", "corrected_sentence": "湖面呈现出银色的光。", "error_description": "错误：趋向补语用错了方向。“呈现”指显露出来，应用“出”，不能用“进”。应为“湖面呈现出银色的光”，不能说“湖面呈现进银色的光”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5b3042e5-b35f-462e-9b42-3d0f42ef5c59') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24814, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "复杂化", "is_correct": true, "explanation": "复杂化指使事物变得复杂，与“简化”意思相反。"}, {"text": "保存", "is_correct": false, "explanation": "保存指留存不丢失，与“简化”没有反义关系。"}, {"text": "研究", "is_correct": false, "explanation": "研究指深入探讨，与“简化”没有反义关系。"}, {"text": "唱歌", "is_correct": false, "explanation": "唱歌指用声音表达歌曲，与“简化”没有反义关系。"}], "correct_answer": "复杂化", "explanations": {"复杂化": "复杂化指使事物变得复杂，与“简化”意思相反。", "保存": "保存指留存不丢失，与“简化”没有反义关系。", "研究": "研究指深入探讨，与“简化”没有反义关系。", "唱歌": "唱歌指用声音表达歌曲，与“简化”没有反义关系。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '70862c4f-9612-4d02-b2b4-d21b6887d210') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
