INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24814, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "让事情变得更容易做或更少。", "primary_collocate": null, "pronunciation": "jiǎn huà", "ipa": "tɕjɛn˨˩˦ xwa˥˩", "syllable_count": 2, "sentences": [{"text": "新软件简化了我们的日常工作。", "target_word": "简化", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "网上办事简化了很多步骤。", "target_word": "简化", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个新规定简化了申请的方法。", "target_word": "简化", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我想简化一下早上的准备。", "target_word": "简化", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他把做饭的步骤简化了。", "target_word": "简化", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "用手机付钱简化了买东西的过程。", "target_word": "简化", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公司简化了开会的程序。", "target_word": "简化", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请简化这些步骤，大家会省不少时间。", "target_word": "简化", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他把每天的计划简化了。", "target_word": "简化", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "地铁卡简化了坐车的方法。", "target_word": "简化", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "简化了", "label": "体标"}, {"form": "简化过", "label": "体标"}, {"form": "簡化", "label": "繁体"}], "register": "中性", "sense_fingerprint": "让做事的步骤、手续变少变容易", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ef6af6ef-c707-4f59-9d9e-398da924d540') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24814, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "简化", "is_correct": true, "explanation": "简化指让事情变简单、变少，“我们的日常工作”是它的对象，符合句意。"}, {"text": "打扫", "is_correct": false, "explanation": "搭配：“打扫”指清除脏物，不能用于工作。"}, {"text": "冷却", "is_correct": false, "explanation": "语义：“冷却”指温度降低，与工作的变化无关。"}, {"text": "擦亮", "is_correct": false, "explanation": "语义：“擦亮”指使物体发亮，与“日常工作”不相关。"}], "explanations": {"简化": "简化指让事情变简单、变少，“我们的日常工作”是它的对象，符合句意。", "打扫": "搭配：“打扫”指清除脏物，不能用于工作。", "冷却": "语义：“冷却”指温度降低，与工作的变化无关。", "擦亮": "语义：“擦亮”指使物体发亮，与“日常工作”不相关。"}, "sentence_index": 0, "correct_answer": "简化"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我想简化一下工作的压力。", "explanation": "这里应该用〈减轻〉。减轻指使负担变轻，用于压力、负担；简化指让事情变简单，不能用于压力的减轻。"}, {"text": "这个方法能简化工作效率。", "explanation": "这里应该用〈提高〉。提高指使水平变高，用于效率、质量；简化指让事情变简单，不能用于效率的提升。"}, {"text": "这个办法能简化学习的速度。", "explanation": "这里应该用〈加快〉。加快指使速度变快，用于速度、进程；简化指把复杂的事变简单，不能用于速度的快慢。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '70862c4f-9612-4d02-b2b4-d21b6887d210') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24814, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "简化", "is_correct": true, "explanation": "简化指让做事的程序变少变容易，“开会的程序”是它的对象，符合句意。"}, {"text": "测量", "is_correct": false, "explanation": "语义：“测量”指量长短大小，与程序的变化无关。"}, {"text": "裁剪", "is_correct": false, "explanation": "搭配：“裁剪”用于布料、纸张等，不能用于程序。"}, {"text": "融化", "is_correct": false, "explanation": "搭配：“融化”指固体遇热变成液体，不能用于程序。"}], "explanations": {"简化": "简化指让做事的程序变少变容易，“开会的程序”是它的对象，符合句意。", "测量": "语义：“测量”指量长短大小，与程序的变化无关。", "裁剪": "搭配：“裁剪”用于布料、纸张等，不能用于程序。", "融化": "搭配：“融化”指固体遇热变成液体，不能用于程序。"}, "sentence_index": 6, "correct_answer": "简化"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这条新路简化了上班的时间。", "explanation": "这里应该用〈缩短〉。缩短指使时间变少，用于时间、距离；简化指让事情变简单，不说“简化时间”。"}, {"text": "妈妈简化了客厅的桌子。", "explanation": "这里应该用〈整理〉。整理指把东西弄整齐，用于物品；简化指让事情变简单，不说“简化桌子”。"}, {"text": "他每天锻炼，简化了身体的素质。", "explanation": "这里应该用〈增强〉。增强指使力量、素质变强，用于身体、能力；简化指让事情变简单，不说“简化素质”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '70862c4f-9612-4d02-b2b4-d21b6887d210') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24814, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这个程序很简化了我们的购物过程。", "corrected_sentence": "这个程序简化了我们的购物过程。", "error_description": "“简化”是动词，前面不能加程度副词“很”；应说“简化了”，不说“很简化了”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '70862c4f-9612-4d02-b2b4-d21b6887d210') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24814, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "公司去年简化着开会的流程。", "corrected_sentence": "公司去年简化了开会的流程。", "error_description": "体标错误：“去年”说的是已经完成的事，“简化”后面要用“了”，不能用表示持续的“着”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '70862c4f-9612-4d02-b2b4-d21b6887d210') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24816, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "理论", "is_correct": true, "explanation": "正确：“理论”与“实际”相对，“联系生活实际”中二者形成对立。"}, {"text": "花园", "is_correct": false, "explanation": "无反义关系：花园是场所，与“实际”没有对立关系。"}, {"text": "篮球", "is_correct": false, "explanation": "无反义关系：篮球是运动器材，与“实际”的真实情况义不构成对立。"}, {"text": "石头", "is_correct": false, "explanation": "无反义关系：石头是具体物品，与“实际”没有对立关系。"}], "correct_answer": "理论", "explanations": {"理论": "正确：“理论”与“实际”相对，“联系生活实际”中二者形成对立。", "花园": "无反义关系：花园是场所，与“实际”没有对立关系。", "篮球": "无反义关系：篮球是运动器材，与“实际”的真实情况义不构成对立。", "石头": "无反义关系：石头是具体物品，与“实际”没有对立关系。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '70862c4f-9612-4d02-b2b4-d21b6887d210') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24816, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "理想", "is_correct": true, "explanation": "正确：“理想”与“实际”相对，“报告里写的和实际差得很远”指报告内容与真实情况不一致。"}, {"text": "钥匙", "is_correct": false, "explanation": "无反义关系：钥匙是日常物品，与“实际”没有对立关系。"}, {"text": "雨伞", "is_correct": false, "explanation": "无反义关系：雨伞是日常用品，与“实际”的真实情况义不构成对立。"}, {"text": "牛奶", "is_correct": false, "explanation": "无反义关系：牛奶是饮品，与“实际”没有对立关系。"}], "correct_answer": "理想", "explanations": {"理想": "正确：“理想”与“实际”相对，“报告里写的和实际差得很远”指报告内容与真实情况不一致。", "钥匙": "无反义关系：钥匙是日常物品，与“实际”没有对立关系。", "雨伞": "无反义关系：雨伞是日常用品，与“实际”的真实情况义不构成对立。", "牛奶": "无反义关系：牛奶是饮品，与“实际”没有对立关系。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '70862c4f-9612-4d02-b2b4-d21b6887d210') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24816, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "实际就是真实的情况。", "primary_collocate": null, "pronunciation": "shí jì", "ipa": "ʂʅ˧˥ tɕi˥˩", "syllable_count": 2, "sentences": [{"text": "书上说得很好，可是实际很不同。", "target_word": "实际", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请你面对实际，不要再骗我了。", "target_word": "实际", "complexity_tier": "T3", "furigana": "qǐng nǐ miànduì shíjì, bú yào zài piàn wǒ le.", "sentence_source": "generated"}, {"text": "他的话离实际太远了。", "target_word": "实际", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "学习汉语要联系生活实际。", "target_word": "实际", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个说法脱离实际，我们都不相信。", "target_word": "实际", "complexity_tier": "T3", "furigana": "zhè ge shuōfǎ tuōlí shíjì, wǒmen dōu bù xiāngxìn.", "sentence_source": "generated"}, {"text": "这个计划没有结合工厂的生产实际。", "target_word": "实际", "complexity_tier": "T3", "furigana": "zhè ge jìhuà méiyǒu jiéhé gōngchǎng de shēngchǎn shíjì.", "sentence_source": "generated"}, {"text": "这个想法听起来不错，却不合实际。", "target_word": "实际", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我想先从实际出发，再做决定。", "target_word": "实际", "complexity_tier": "T3", "furigana": "wǒ xiǎng xiān cóng shíjì chūfā, zài zuò juédìng.", "sentence_source": "generated"}, {"text": "他总是不顾实际，乱花钱。", "target_word": "实际", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "报告里写的和实际差得很远。", "target_word": "实际", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "實際", "label": "繁体"}], "register": "中性", "sense_fingerprint": "名词：真实的情况（联系实际、不合实际）", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ef6af6ef-c707-4f59-9d9e-398da924d540') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24816, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "实际", "is_correct": true, "explanation": "正确：shí jì，指真实的情况。"}, {"text": "事迹", "is_correct": false, "explanation": "shì（第四声）与 shí（第二声）声调不同，意思是事迹。"}, {"text": "十几", "is_correct": false, "explanation": "shí jǐ（第三声）与 shí jì（第四声）声调不同，意思是十几。"}, {"text": "时机", "is_correct": false, "explanation": "shí jī（第一声）与 shí jì（第四声）声调不同，意思是时机。"}], "explanations": {"实际": "正确：shí jì，指真实的情况。", "事迹": "shì（第四声）与 shí（第二声）声调不同，意思是事迹。", "十几": "shí jǐ（第三声）与 shí jì（第四声）声调不同，意思是十几。", "时机": "shí jī（第一声）与 shí jì（第四声）声调不同，意思是时机。"}, "sentence_index": null, "correct_answer": "实际"}, "level_3": {"options": [{"text": "实际", "is_correct": true, "explanation": "正确：“可是实际很不同”中，“实际”指真实情况，与“书上说得很好”形成对比。"}, {"text": "血型", "is_correct": false, "explanation": "语义：血型是固定的类别，“很不同”与“书上说得很好”的对比讲不通。"}, {"text": "性别", "is_correct": false, "explanation": "语义：性别是固定的身份特征，与“书上说得很好”没有对比关系，句子说不通。"}, {"text": "指纹", "is_correct": false, "explanation": "语义：指纹是人人各异的固定特征，与“书上说得很好”的对比讲不通。"}], "explanations": {"实际": "正确：“可是实际很不同”中，“实际”指真实情况，与“书上说得很好”形成对比。", "血型": "语义：血型是固定的类别，“很不同”与“书上说得很好”的对比讲不通。", "性别": "语义：性别是固定的身份特征，与“书上说得很好”没有对比关系，句子说不通。", "指纹": "语义：指纹是人人各异的固定特征，与“书上说得很好”的对比讲不通。"}, "sentence_index": 0, "correct_answer": "实际"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这首歌的实际很动听，大家都喜欢听。", "explanation": "这里应该用〈旋律〉。“旋律”指乐曲的音高变化，形容歌曲动听要用“旋律”；“实际”指真实情况，不能这样用。"}, {"text": "这是一个很有趣的实际，大家都愿意参加。", "explanation": "这里应该用〈游戏〉。“游戏”指供人娱乐的活动；“实际”指真实情况，不能用来指一种活动。"}, {"text": "电视里播出了比赛实际，观众很兴奋。", "explanation": "这里应该用〈实况〉。“比赛实况”指现场的真实情况，“比赛实际”不能这样说。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '70862c4f-9612-4d02-b2b4-d21b6887d210') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24816, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "实际", "is_correct": true, "explanation": "正确：shí jì，指真实的情况。"}, {"text": "世纪", "is_correct": false, "explanation": "shì（第四声）与 shí（第二声）声调不同，意思是世纪。"}, {"text": "十级", "is_correct": false, "explanation": "shí jí（第二声）与 shí jì（第四声）声调不同，意思是十级。"}, {"text": "时机", "is_correct": false, "explanation": "shí jī（第一声）与 shí jì（第四声）声调不同，意思是时机。"}], "explanations": {"实际": "正确：shí jì，指真实的情况。", "世纪": "shì（第四声）与 shí（第二声）声调不同，意思是世纪。", "十级": "shí jí（第二声）与 shí jì（第四声）声调不同，意思是十级。", "时机": "shí jī（第一声）与 shí jì（第四声）声调不同，意思是时机。"}, "sentence_index": null, "correct_answer": "实际"}, "level_3": {"options": [{"text": "实际", "is_correct": true, "explanation": "正确：“不合实际”指与真实情况不相符，符合语境。"}, {"text": "海浪", "is_correct": false, "explanation": "语义：“不合”要接标准或情况，海浪不能作为“不合”的对象，讲不通。"}, {"text": "玩具", "is_correct": false, "explanation": "语义：玩具不能用来衡量想法，“却不合玩具”讲不通。"}, {"text": "体重", "is_correct": false, "explanation": "语义：体重是身体的重量，不能用来衡量想法，“却不合体重”讲不通。"}], "explanations": {"实际": "正确：“不合实际”指与真实情况不相符，符合语境。", "海浪": "语义：“不合”要接标准或情况，海浪不能作为“不合”的对象，讲不通。", "玩具": "语义：玩具不能用来衡量想法，“却不合玩具”讲不通。", "体重": "语义：体重是身体的重量，不能用来衡量想法，“却不合体重”讲不通。"}, "sentence_index": 6, "correct_answer": "实际"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "博物馆里陈列着很多珍贵的实际，吸引了不少游客。", "explanation": "这里应该用〈实物〉。“实物”指真实存在的具体物品，“实际”指真实情况，不能指陈列的物品。"}, {"text": "他在医院实际，每天跟着老师查房。", "explanation": "这里应该用〈实习〉。“实习”是动词，指在实际工作中学习；“实际”不能表示这个动作。"}, {"text": "他是个实际家，做事从不空谈。", "explanation": "这里应该用〈实干家〉。“实干家”指踏实做事的人；“实际家”不是词，“实际”不能组成这个词。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '70862c4f-9612-4d02-b2b4-d21b6887d210') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24816, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他的计划从实际太远，没法执行。", "corrected_sentence": "他的计划离实际太远，没法执行。", "error_description": "介词错误：“离实际太远”表示与实际相差很远，应用“离”。“从实际太远”讲不通，“从”不能用于表示距离。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '70862c4f-9612-4d02-b2b4-d21b6887d210') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24816, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我们应该实际出发，制定可行的计划。", "corrected_sentence": "我们应该从实际出发，制定可行的计划。", "error_description": "漏掉介词“从”。“从实际出发”是固定说法，“从”表示以什么为依据，不能省略。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '70862c4f-9612-4d02-b2b4-d21b6887d210') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
