INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24818, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "废料就是没用的东西。", "primary_collocate": null, "pronunciation": "fèi liào", "ipa": "fei˥˩ liɑʊ˥˩", "syllable_count": 2, "sentences": [{"text": "地上都是废料，快打扫一下。", "target_word": "废料", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他把家里的废料都扔了。", "target_word": "废料", "complexity_tier": "T3", "furigana": "tā bǎ jiālǐ de fèiliào dōu rēng le", "sentence_source": "generated"}, {"text": "别把好东西当成废料。", "target_word": "废料", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这堆废料没有什么用处。", "target_word": "废料", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "屋后有一堆废料，没人管。", "target_word": "废料", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "妈妈说这些废料不要放在家里。", "target_word": "废料", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子用废料做了一辆小汽车。", "target_word": "废料", "complexity_tier": "T3", "furigana": "háizi yòng fèiliào zuò le yí liàng xiǎo qìchē", "sentence_source": "generated"}, {"text": "垃圾车来把门口的废料拉走了。", "target_word": "废料", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "车间里的废料越来越多。", "target_word": "废料", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这些废料已经不能再用了。", "target_word": "废料", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "廢料", "label": "繁体"}], "register": "中性", "sense_fingerprint": "名词：没有用的东西（一堆废料、扔掉废料）", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ef6af6ef-c707-4f59-9d9e-398da924d540') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24818, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "废料", "is_correct": true, "explanation": "“废料”指没有用的东西，地上堆着的废料需要打扫，符合句子的语境。"}, {"text": "音乐", "is_correct": false, "explanation": "搭配：“地上都是”不能与“音乐”搭配，音乐不能铺在地上。"}, {"text": "钢琴", "is_correct": false, "explanation": "语义：钢琴是大型乐器，不会散落在地上需要打扫，句子说不通。"}, {"text": "时间", "is_correct": false, "explanation": "语义：时间不能“地上都是”，这个说法没有意义。"}], "explanations": {"废料": "“废料”指没有用的东西，地上堆着的废料需要打扫，符合句子的语境。", "音乐": "搭配：“地上都是”不能与“音乐”搭配，音乐不能铺在地上。", "钢琴": "语义：钢琴是大型乐器，不会散落在地上需要打扫，句子说不通。", "时间": "语义：时间不能“地上都是”，这个说法没有意义。"}, "sentence_index": 0, "correct_answer": "废料"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这个老相框是家里的废料，很珍贵。", "explanation": "这里应该用〈宝贝〉。废料指没有用的东西，珍贵的东西要用宝贝。"}, {"text": "这把新锤子是很好用的废料，修东西全靠它。", "explanation": "这里应该用〈工具〉。废料指没有用的东西，好用、能修东西的锤子要叫工具。"}, {"text": "他的知识是人生的废料，帮助了很多人。", "explanation": "这里应该用〈财富〉。废料指没有用的东西，对人有帮助的东西要用财富。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '70862c4f-9612-4d02-b2b4-d21b6887d210') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24818, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "废料", "is_correct": true, "explanation": "“废料”可以用来做东西，符合“孩子用……做了一辆小汽车”的语境。"}, {"text": "空气", "is_correct": false, "explanation": "语义：空气是无形的气体，不能用来做成汽车，句子说不通。"}, {"text": "歌曲", "is_correct": false, "explanation": "语义：歌曲不是实物，不能用来做成汽车。"}, {"text": "眼泪", "is_correct": false, "explanation": "语义：眼泪不能用来做汽车，句子的意思说不通。"}], "explanations": {"废料": "“废料”可以用来做东西，符合“孩子用……做了一辆小汽车”的语境。", "空气": "语义：空气是无形的气体，不能用来做成汽车，句子说不通。", "歌曲": "语义：歌曲不是实物，不能用来做成汽车。", "眼泪": "语义：眼泪不能用来做汽车，句子的意思说不通。"}, "sentence_index": 6, "correct_answer": "废料"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这种废料很有效，吃了就好了。", "explanation": "这里应该用〈药〉。废料没有用处，不能说有效、吃了能治病，这些话只用于药。"}, {"text": "这件废料还很新，可以穿。", "explanation": "这里应该用〈衣服〉。废料没有用途，不能说还很新、可以穿，这些话只用于衣服。"}, {"text": "这个废料很重要，要好好保存。", "explanation": "这里应该用〈文件〉。废料没有用处，不能说很重要、要好好保存，这些话只用于文件。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '70862c4f-9612-4d02-b2b4-d21b6887d210') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24818, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这些废料的要尽快搬走。", "corrected_sentence": "这些废料要尽快搬走。", "error_description": "多余的“的”：“废料”后面不能直接加“的”接谓语，应去掉“的”，说“这些废料要尽快搬走”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '70862c4f-9612-4d02-b2b4-d21b6887d210') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24818, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "门口那辆废料没人要了。", "corrected_sentence": "门口那堆废料没人要了。", "error_description": "量词错误：“辆”用于车，“废料”的量词要用“堆”。应说“那堆废料”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '70862c4f-9612-4d02-b2b4-d21b6887d210') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
