INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24820, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "一个人心里想要得到什么，或者希望事情变成什么样子。", "primary_collocate": null, "pronunciation": "sù qiú", "ipa": "su˥˩ tɕʰioʊ˧˥", "syllable_count": 2, "sentences": [{"text": "孩子的诉求很简单，就是想早点回家。", "target_word": "诉求", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她心里的诉求，从来没有对人说过。", "target_word": "诉求", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的诉求只有一个：多睡一会儿。", "target_word": "诉求", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我想知道你真正的诉求是什么。", "target_word": "诉求", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小明的诉求是想要一只小狗。", "target_word": "诉求", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "妈妈听懂了孩子的诉求。", "target_word": "诉求", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老人没有太多诉求，只想平安。", "target_word": "诉求", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "每个人的诉求都不一样。", "target_word": "诉求", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他不好意思说出自己的诉求。", "target_word": "诉求", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "朋友问我，对这份工作有什么诉求。", "target_word": "诉求", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "个", "label": "量词"}], "register": "书面", "sense_fingerprint": "诉求|名词|个人心里想要的东西", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ba8c8f5f-fc8f-4d44-9255-da7efb81def0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24820, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "诉求", "is_correct": true, "explanation": "诉求：孩子想要的东西，与“很简单，就是想早点回家”搭配，句意通顺。"}, {"text": "饭量", "is_correct": false, "explanation": "语义：“饭量”指吃饭的数量，不是孩子想要的东西，句意不通。"}, {"text": "身高", "is_correct": false, "explanation": "语义：“身高”是身体特征，不能作为“想要”的对象。"}, {"text": "年龄", "is_correct": false, "explanation": "语义：“年龄”是岁数，不能与“很简单，就是想早点回家”搭配。"}], "explanations": {"诉求": "诉求：孩子想要的东西，与“很简单，就是想早点回家”搭配，句意通顺。", "饭量": "语义：“饭量”指吃饭的数量，不是孩子想要的东西，句意不通。", "身高": "语义：“身高”是身体特征，不能作为“想要”的对象。", "年龄": "语义：“年龄”是岁数，不能与“很简单，就是想早点回家”搭配。"}, "sentence_index": 0, "correct_answer": "诉求"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "警察提取到了清晰的诉求。", "explanation": "这里应该用〈指纹〉。诉求指人心里想要得到的东西，不是可以提取的实物痕迹。"}, {"text": "这次实验的诉求是正确的。", "explanation": "这里应该用〈结论〉。诉求指想要得到的东西，不指实验得出的判断。"}, {"text": "他心里有一把诉求。", "explanation": "量词不对。诉求是抽象名词，不用“把”，应说“一个诉求”或“一项诉求”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3a384423-1ab5-4cce-9e02-76eae3132d8a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24820, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "诉求", "is_correct": true, "explanation": "诉求：老人想要的东西或希望，与“没有太多”搭配，句意通顺。"}, {"text": "颜色", "is_correct": false, "explanation": "语义：“颜色”不是老人的需求，“没有太多颜色，只想平安”句意不通。"}, {"text": "体温", "is_correct": false, "explanation": "语义：“体温”是身体的温度，不能作为“没有太多”的对象，句意不通。"}, {"text": "字体", "is_correct": false, "explanation": "搭配：“没有太多”一般搭配可以拥有或计量的事物，“字体”不能这样说。"}], "explanations": {"诉求": "诉求：老人想要的东西或希望，与“没有太多”搭配，句意通顺。", "颜色": "语义：“颜色”不是老人的需求，“没有太多颜色，只想平安”句意不通。", "体温": "语义：“体温”是身体的温度，不能作为“没有太多”的对象，句意不通。", "字体": "搭配：“没有太多”一般搭配可以拥有或计量的事物，“字体”不能这样说。"}, "sentence_index": 6, "correct_answer": "诉求"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这份工作的诉求很好。", "explanation": "这里应该用〈条件〉。诉求指人想要得到的东西，不用来描述工作本身的待遇和环境。"}, {"text": "公司有严格的诉求。", "explanation": "这里应该用〈规定〉。诉求指人心里想要的东西，不指单位制定的制度。"}, {"text": "他写了一首诉求。", "explanation": "量词不对。诉求是抽象名词，不用“首”，“首”用于诗歌、歌曲；应说“一个诉求”或“一项诉求”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3a384423-1ab5-4cce-9e02-76eae3132d8a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24820, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这张诉求很明确。", "corrected_sentence": "这项诉求很明确。", "error_description": "量词错误：“诉求”应该用量词“项”，“张”用于纸张、桌子等平面的东西，不能修饰“诉求”。正确说法是“这项诉求”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3a384423-1ab5-4cce-9e02-76eae3132d8a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24820, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他听懂着朋友的诉求。", "corrected_sentence": "他听懂了朋友的诉求。", "error_description": "动态助词错误：“听懂”表示瞬间完成的结果，完成义要用“了”，说“听懂了朋友的诉求”；“着”表示持续状态，与“听懂”不合，“听懂着”是错误。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3a384423-1ab5-4cce-9e02-76eae3132d8a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24822, 1, 'llm_types_A', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '70862c4f-9612-4d02-b2b4-d21b6887d210') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24822, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '70862c4f-9612-4d02-b2b4-d21b6887d210') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24822, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "利用率就是看一样东西被用了多少次。", "primary_collocate": null, "pronunciation": "lì yòng lǜ", "ipa": "li˥˩ yʊŋ˥˩ ly˥˩", "syllable_count": 3, "sentences": [{"text": "这把雨伞的利用率很低，一年只用两次。", "target_word": "利用率", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "健身房的利用率不高，很少有人去。", "target_word": "利用率", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "买东西以前先估计一下它的利用率。", "target_word": "利用率", "complexity_tier": "T3", "furigana": "mǎi dōngxi yǐqián xiān gūjì yíxià tā de lìyònglǜ", "sentence_source": "generated"}, {"text": "这辆自行车每天都骑，利用率很高。", "target_word": "利用率", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "图书馆的书利用率高不高，要看借出的次数。", "target_word": "利用率", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公园里的椅子利用率很高，总是有人坐。", "target_word": "利用率", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师说这台电脑的利用率太低了。", "target_word": "利用率", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他买了很多衣服，但利用率很低。", "target_word": "利用率", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "一样东西用得越多，利用率就越高。", "target_word": "利用率", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这间房子一年住不到一个月，利用率太低。", "target_word": "利用率", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "名词：一样东西被使用的频繁程度（利用率高、利用率低）", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ef6af6ef-c707-4f59-9d9e-398da924d540') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24822, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "利用率", "is_correct": true, "explanation": "“利用率”指东西被用得多少，“一年只用两次”正好说明利用率低。"}, {"text": "颜色", "is_correct": false, "explanation": "搭配：“颜色”不能说“很低”，雨伞的颜色没有高低之分。"}, {"text": "体重", "is_correct": false, "explanation": "语义：“一年只用两次”说的是使用次数，跟体重轻重无关，句子说不通。"}, {"text": "音量", "is_correct": false, "explanation": "语义：雨伞没有音量，“这把雨伞的音量很低”说不通。"}], "explanations": {"利用率": "“利用率”指东西被用得多少，“一年只用两次”正好说明利用率低。", "颜色": "搭配：“颜色”不能说“很低”，雨伞的颜色没有高低之分。", "体重": "语义：“一年只用两次”说的是使用次数，跟体重轻重无关，句子说不通。", "音量": "语义：雨伞没有音量，“这把雨伞的音量很低”说不通。"}, "sentence_index": 0, "correct_answer": "利用率"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他跑步的利用率很快，三分钟就跑到了终点。", "explanation": "这里应该用〈速度〉。利用率指东西被用了多少，人跑得快慢要用速度。"}, {"text": "他的利用率很高，身高有一米八。", "explanation": "这里应该用〈个子〉。利用率只用于东西的使用情况，人长得高要说“个子很高”。"}, {"text": "他去年的利用率很高，赚了很多钱。", "explanation": "这里应该用〈收入〉。利用率指东西被使用的频繁程度，赚钱的多少要用收入。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '70862c4f-9612-4d02-b2b4-d21b6887d210') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24822, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "利用率", "is_correct": true, "explanation": "“利用率”可以说高或低，这里说“太低了”，符合句子的意思。"}, {"text": "身高", "is_correct": false, "explanation": "语义：“身高”只用于人或动物的身长，不用来形容电脑，“太低了”说不通。"}, {"text": "味道", "is_correct": false, "explanation": "语义：电脑没有味道，“味道太低了”不能用来描述电脑。"}, {"text": "名字", "is_correct": false, "explanation": "搭配：“名字”不能说“太低”，电脑的名字没有高低之分。"}], "explanations": {"利用率": "“利用率”可以说高或低，这里说“太低了”，符合句子的意思。", "身高": "语义：“身高”只用于人或动物的身长，不用来形容电脑，“太低了”说不通。", "味道": "语义：电脑没有味道，“味道太低了”不能用来描述电脑。", "名字": "搭配：“名字”不能说“太低”，电脑的名字没有高低之分。"}, "sentence_index": 6, "correct_answer": "利用率"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这杯水的利用率很烫，你先别喝。", "explanation": "这里应该用〈温度〉。利用率指东西被用得多少，水的冷热要用温度。"}, {"text": "这位老人的利用率很大，已经八十岁了。", "explanation": "这里应该用〈年龄〉。利用率只说东西的使用情况，人的岁数要用年龄。"}, {"text": "这块布的利用率很红，很漂亮。", "explanation": "这里应该用〈颜色〉。利用率说的是东西被使用的多少，不能用来说颜色。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '70862c4f-9612-4d02-b2b4-d21b6887d210') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24822, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这辆电动车的利用率高很，每天都用。", "corrected_sentence": "这辆电动车的利用率很高，每天都用。", "error_description": "语序错误：程度副词“很”要放在“高”的前面，应说“利用率很高”，不能说“利用率高很”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '70862c4f-9612-4d02-b2b4-d21b6887d210') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24822, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "她买了很多鞋，可是利用率了很低。", "corrected_sentence": "她买了很多鞋，可是利用率很低。", "error_description": "了的位置错误：“利用率”后面不能加“了”，“了”是动态助词，不能用在这里。应直接说“可是利用率很低”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '70862c4f-9612-4d02-b2b4-d21b6887d210') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
