INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24824, 1, 'prompt1_core', '{"pos": "副词", "semantic_class": "function", "definition": "表示正好、刚刚的意思。", "primary_collocate": null, "pronunciation": "qià", "ipa": "tɕʰja˥˩", "syllable_count": 1, "sentences": [{"text": "我刚想出门，朋友恰来了。", "target_word": "恰", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我口袋里的钱恰够买这本书。", "target_word": "恰", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的话恰说到了我心里。", "target_word": "恰", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "两个人恰同时开口。", "target_word": "恰", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她来的那天，恰是我的生日。", "target_word": "恰", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "今天的天气恰不冷不热。", "target_word": "恰", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "妈妈做的菜，咸淡恰合我的口味。", "target_word": "恰", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他说得恰与我想的一样。", "target_word": "恰", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我到家时，雨恰下起来了。", "target_word": "恰", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这支笔恰是我丢的那一支。", "target_word": "恰", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "恰好", "label": "复合"}, {"form": "恰巧", "label": "复合"}], "register": "书面", "sense_fingerprint": "恰|副词|正好、刚刚", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ba8c8f5f-fc8f-4d44-9255-da7efb81def0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24824, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "恰", "is_correct": true, "explanation": "恰：听到的是 qià（第四声），意思是正好、刚刚。"}, {"text": "下", "is_correct": false, "explanation": "xià（第四声）与 qià 声母不同（x 与 q），意思是下面。"}, {"text": "卡", "is_correct": false, "explanation": "qiǎ（第三声）与 qià 只有声调不同，意思是卡住。"}, {"text": "掐", "is_correct": false, "explanation": "qiā（第一声）与 qià 只有声调不同，意思是用手指按压。"}, {"text": "嫁", "is_correct": false, "explanation": "jià（第四声）与 qià 声母不同（j 与 q），意思是出嫁。"}], "explanations": {"恰": "恰：听到的是 qià（第四声），意思是正好、刚刚。", "下": "xià（第四声）与 qià 声母不同（x 与 q），意思是下面。", "卡": "qiǎ（第三声）与 qià 只有声调不同，意思是卡住。", "掐": "qiā（第一声）与 qià 只有声调不同，意思是用手指按压。", "嫁": "jià（第四声）与 qià 声母不同（j 与 q），意思是出嫁。"}, "sentence_index": null, "correct_answer": "恰"}, "level_3": {"options": [{"text": "恰", "is_correct": true, "explanation": "恰：副词，表示正好、刚刚，此处说朋友正好在我刚要出门时来了。"}, {"text": "很", "is_correct": false, "explanation": "搭配：「很」修饰形容词，不能修饰「来了」这样的动作结构。"}, {"text": "挺", "is_correct": false, "explanation": "语域：「挺」是口语口吻，与这句书面语的语域不合。"}, {"text": "将", "is_correct": false, "explanation": "体貌：「将」表示将来，与「我刚想出门」所述的已发生情境不合。"}], "explanations": {"恰": "恰：副词，表示正好、刚刚，此处说朋友正好在我刚要出门时来了。", "很": "搭配：「很」修饰形容词，不能修饰「来了」这样的动作结构。", "挺": "语域：「挺」是口语口吻，与这句书面语的语域不合。", "将": "体貌：「将」表示将来，与「我刚想出门」所述的已发生情境不合。"}, "sentence_index": 0, "correct_answer": "恰"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "你恰别去那儿！", "explanation": "这里应该用〈可〉。恰表示正好、刚好，不用于加强劝阻语气；“你可别去那儿”才对。"}, {"text": "这个房间恰很大。", "explanation": "这里应该用〈很〉。恰表示正好，不表示程度高；“这个房间很大”才对。"}, {"text": "他恰以为你不来了。", "explanation": "这里应该用〈还〉。恰表示正好，不表示出乎意料；“他还以为你不来了”才对。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3a384423-1ab5-4cce-9e02-76eae3132d8a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24824, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "恰", "is_correct": true, "explanation": "恰：听到的是 qià（第四声），意思是正好、刚刚。"}, {"text": "价", "is_correct": false, "explanation": "jià（第四声）与 qià 声母不同（j 与 q），意思是价格。"}, {"text": "夏", "is_correct": false, "explanation": "xià（第四声）与 qià 声母不同（x 与 q），意思是夏天。"}, {"text": "侠", "is_correct": false, "explanation": "xiá（第二声）与 qià 声母、声调都不同，意思是侠客。"}], "explanations": {"恰": "恰：听到的是 qià（第四声），意思是正好、刚刚。", "价": "jià（第四声）与 qià 声母不同（j 与 q），意思是价格。", "夏": "xià（第四声）与 qià 声母不同（x 与 q），意思是夏天。", "侠": "xiá（第二声）与 qià 声母、声调都不同，意思是侠客。"}, "sentence_index": null, "correct_answer": "恰"}, "level_3": {"options": [{"text": "恰", "is_correct": true, "explanation": "恰：副词，表示正好、恰好，此处说咸淡正好合我的口味。"}, {"text": "从", "is_correct": false, "explanation": "语法：「从」是介词，后面要接处所或时间，不能直接修饰「合」。"}, {"text": "被", "is_correct": false, "explanation": "语法：「被」表示被动，「咸淡被合我的口味」不成句。"}, {"text": "忽然", "is_correct": false, "explanation": "语义：「忽然」表示突然，与「咸淡合我的口味」这一稳定的评价不合。"}], "explanations": {"恰": "恰：副词，表示正好、恰好，此处说咸淡正好合我的口味。", "从": "语法：「从」是介词，后面要接处所或时间，不能直接修饰「合」。", "被": "语法：「被」表示被动，「咸淡被合我的口味」不成句。", "忽然": "语义：「忽然」表示突然，与「咸淡合我的口味」这一稳定的评价不合。"}, "sentence_index": 6, "correct_answer": "恰"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他恰常常迟到。", "explanation": "这里应该用〈经常〉。恰表示正好、刚好，不表示次数多；“他经常迟到”才对。"}, {"text": "他没帮忙，恰添了乱。", "explanation": "这里应该用〈反而〉。恰不表示与预期相反的结果；“他没帮忙，反而添了乱”才对。"}, {"text": "这道题恰难，我做不出来。", "explanation": "这里应该用〈太〉。恰表示正好，不表示程度过高；“这道题太难，我做不出来”才对。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3a384423-1ab5-4cce-9e02-76eae3132d8a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24824, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这支笔够恰用。", "corrected_sentence": "这支笔恰够用。", "error_description": "“恰”是副词，应放在“够”之前修饰，说“恰够用”；“够恰用”把“恰”放在“够”后面，位置错误。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3a384423-1ab5-4cce-9e02-76eae3132d8a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24824, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这套衣服合恰身。", "corrected_sentence": "这套衣服恰合身。", "error_description": "“恰”是副词，应放在“合”之前修饰，说“恰合身”；“合恰身”把“恰”放在“合”与“身”之间，位置错误。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3a384423-1ab5-4cce-9e02-76eae3132d8a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
